INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'Penerimaan Mahasiswa Baru', 'Pendaftaran', 'Bagaimana cara mendaftar di UPITRA?', '<p>Pendaftaran mahasiswa baru UPITRA dilakukan melalui sistem <strong>Penerimaan Mahasiswa Baru (PMB)</strong> secara online yang sudah terintegrasi dan mudah diakses.</p><p>Langkah pendaftaran:</p><ul><li><p>🌐 Akses laman resmi PMB: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://pmb.upitra.ac.id/\">https://pmb.upitra.ac.id/</a></p></li><li><p>📝 Buat akun dan isi formulir pendaftaran secara lengkap</p></li><li><p>📄 Lengkapi data diri serta dokumen yang dibutuhkan</p></li><li><p>💳 Ikuti proses verifikasi dan pembayaran pendaftaran (jika diperlukan)</p></li><li><p>🎓 Ikuti tahapan seleksi hingga pengumuman hasil penerimaan</p></li></ul><p>Seluruh proses dirancang agar calon mahasiswa dapat mendaftar secara lebih cepat, transparan, dan fleksibel dari mana saja.</p>', '[\"cara daftar upitra\",\"pmb upitra\",\"pendaftaran mahasiswa baru\",\"daftar kuliah upitra\",\"registrasi online\",\"join upitra\",\"seleksi masuk upitra\",\"daftar pmb\",\"form pendaftaran upitra\",\"cara masuk upitra\"]', 'Aktif', 1, 1, '2026-04-16 20:11:29', '2026-07-06 21:25:03'),
(2, 'Penerimaan Mahasiswa Baru', 'Pendaftaran', 'Kapan jadwal pendaftaran mahasiswa baru UPITRA dibuka?', '', '\"[\\\"jadwal pmb\\\",\\\"jadwal pendaftaran\\\",\\\"kapan daftar\\\",\\\"gelombang pendaftaran\\\"]\"', 'Kosong', 1, 2, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(3, 'Penerimaan Mahasiswa Baru', 'Pendaftaran', 'Berapa biaya pendaftaran di UPITRA?', '', '\"[\\\"biaya daftar\\\",\\\"biaya pendaftaran\\\",\\\"harga daftar\\\",\\\"uang pendaftaran\\\"]\"', 'Kosong', 1, 3, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(4, 'Penerimaan Mahasiswa Baru', 'Persyaratan', 'Apa saja persyaratan dokumen untuk mendaftar di UPITRA?', 'Persyaratan dokumen: 1. Formulir pendaftaran 2. Rapor kelas X-XII 3. KTP/KK 4. Akta kelahiran 5. Pas foto. Info: https://pmb.upitra.ac.id', '\"[\\\"syarat daftar\\\",\\\"persyaratan dokumen\\\",\\\"dokumen pendaftaran\\\",\\\"berkas pendaftaran\\\"]\"', 'Aktif', 1, 4, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(5, 'Penerimaan Mahasiswa Baru', 'Persyaratan', 'Apakah ada tes masuk di UPITRA?', '', '\"[\\\"tes masuk\\\",\\\"seleksi masuk\\\",\\\"ujian masuk\\\",\\\"tes penerimaan\\\"]\"', 'Kosong', 1, 5, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(6, 'Penerimaan Mahasiswa Baru', 'Persyaratan', 'Apakah lulusan SMK bisa mendaftar di UPITRA?', '', '\"[\\\"smk bisa daftar\\\",\\\"lulusan smk\\\",\\\"smk masuk upitra\\\"]\"', 'Kosong', 1, 6, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(7, 'Penerimaan Mahasiswa Baru', 'Beasiswa', 'Apa saja beasiswa yang tersedia di UPITRA?', '<h2>Beasiswa yang Tersedia di UPITRA</h2><p>Universitas Pignatelli Triputra (UPITRA) menyediakan beberapa jalur beasiswa bagi mahasiswa:</p><ul><li><p><strong>Beasiswa KIP-Kuliah (KIP-K):</strong> Bantuan pendidikan dari pemerintah untuk mahasiswa berprestasi yang memiliki keterbatasan ekonomi.</p></li><li><p><strong>Beasiswa Keluarga UPITRA:</strong> Potongan biaya kuliah khusus bagi calon mahasiswa yang memiliki hubungan keluarga dengan sivitas akademika atau yayasan.</p></li><li><p><strong>Beasiswa UPITRA Untuk Indonesia (UII):</strong> Program beasiswa prestasi untuk putra-putri terbaik bangsa.</p></li><li><p><strong>Beasiswa Mitra UPITRA:</strong> Beasiswa kerja sama dengan berbagai perusahaan mitra dan institusi eksternal.</p></li></ul><blockquote><p><strong>Informasi Lebih Lanjut &amp; Pendaftaran:</strong> Silakan kunjungi portal resmi PMB di <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.upitra.ac.id\">pmb.upitra.ac.id</a>.</p></blockquote><p></p>', '[\"beasiswa\",\"kip kuliah\",\"kip-k\",\"beasiswa keluarga\",\"beasiswa uii\",\"beasiswa mitra\",\"keringanan kuliah\",\"cara daftar beasiswa\",\"syarat beasiswa\",\"beasiswa upitra\",\"kuliah gratis\",\"bantuan biaya\",\"info pmb beasiswa\",\"beasiswa kip kuliah\",\"kip-k upitra\",\"beasiswa yayasan\",\"kuliah gratis sampai lulus\"]', 'Aktif', 1, 7, '2026-04-16 20:11:29', '2026-07-01 01:04:55'),
(8, 'Penerimaan Mahasiswa Baru', 'Beasiswa', 'Bagaimana cara mendapatkan beasiswa di UPITRA?', '', '\"[\\\"cara dapat beasiswa\\\",\\\"syarat beasiswa\\\",\\\"daftar beasiswa upitra\\\",\\\"beasiswa prestasi\\\"]\"', 'Kosong', 1, 8, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(9, 'Penerimaan Mahasiswa Baru', 'Beasiswa', 'Apakah ada beasiswa penuh di UPITRA?', '', '\"[\\\"beasiswa penuh\\\",\\\"beasiswa 100 persen\\\",\\\"gratis kuliah upitra\\\",\\\"beasiswa full\\\"]\"', 'Kosong', 1, 9, '2026-04-16 20:11:29', '2026-04-16 20:11:29'),
(10, 'Biaya Kuliah', 'SPP', 'Berapa biaya kuliah per semester di UPITRA?', '<p>Biaya kuliah di UPITRA berbeda untuk setiap program studi dan jalur penerimaan mahasiswa.</p><p>Untuk memperoleh informasi biaya kuliah, biaya pendaftaran, serta skema pembayaran terbaru, silakan mengakses PMB UPITRA melalui:</p><p>🌐 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://pmb.upitra.ac.id\">https://pmb.upitra.ac.id</a></p><p>atau hubungi Admission UPITRA:</p><p>📞 0811-290-7500</p>', '[\"biaya kuliah\",\"uang kulaih\",\"spp\",\"ukt\",\"harga kuliah\",\"biaya semester\",\"berapa biaya kuliah\",\"tarif kuliah\",\"biaya pendidikan\"]', 'Aktif', 1, 10, '2026-04-16 20:11:29', '2026-07-06 21:26:23'),
(12, 'Biaya Kuliah', 'SPP', 'Bagaimana cara pembayaran SPP di UPITRA?', '<p>Pembayaran SPP atau Uang Kuliah Semesteran (UKS) di UPITRA dapat dilakukan secara praktis melalui metode berikut:</p><ol><li><p><strong>Melalui Virtual Account (VA):</strong> Mahasiswa dapat melihat nomor VA masing-masing di akun SIAKAD, kemudian melakukan pembayaran via transfer bank (ATM, Mobile Banking, atau Internet Banking). Status pembayaran akan otomatis ter-update di sistem setelah transaksi sukses.</p></li><li><p><strong>Metode Alternatif:</strong> Jika terdapat kendala pada sistem VA, informasi mengenai nomor rekening resmi institusi atau loket pembayaran tunai di kampus dapat dikonfirmasi langsung ke Biro Keuangan.</p></li></ol><p><em>Catatan: Selalu simpan bukti transfer atau struk pembayaran Anda sebagai arsip jika sewaktu-waktu diperlukan untuk verifikasi manual.</em></p>', '[\"cara bayar spp\",\"pembayaran uks\",\"transfer spp upitra\",\"cara bayar kuliah\",\"nomer rekneing upitra\",\"panduan bayar spp\",\"va bank upitra\"]', 'Aktif', 1, 12, '2026-04-16 20:11:29', '2026-06-23 21:20:29'),
(17, 'Akademik', 'KRS', 'Bagaimana cara mengisi KRS di UPITRA?', '<p style=\"text-align: justify;\">Pengisian Kartu Rencana Studi (KRS) dilakukan secara online dengan langkah berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Akses Portal:</strong> Buka portal mahasiswa di <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id/\">Portal Mahasiswa.</a></p></li><li><p style=\"text-align: justify;\"><strong>Login:</strong> Masuk menggunakan akun dan <em>password</em> mahasiswa Anda.</p></li><li><p style=\"text-align: justify;\"><strong>Pilih Menu:</strong> Masuk ke menu <strong>KRS</strong> atau <strong>Isi KRS</strong>.</p></li><li><p style=\"text-align: justify;\"><strong>Pilih Mata Kuliah:</strong> Pilih mata kuliah yang akan diambil pada semester berjalan sesuai arahan Dosen Pembimbing Akademik (PA), lalu simpan.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"kartu rencana studi\",\"isi krs\",\"pengisian krs\",\"daftar mata kuliah\",\"ambil mata kuliah\",\"registrasi mata kuliah\",\"pilih mata kuliah\",\"susun jadwal kuliah\",\"cara ambil krs\",\"bimbingan krs\",\"revisi krs\",\"krsan\",\"pilih matkul\",\"cara input krs\",\"langkah mengisi krs\",\"panduan siakad\"]', 'Aktif', 1, 17, '2026-04-16 20:11:29', '2026-06-24 20:13:44'),
(20, 'Akademik', 'IPK', 'Berapa IPK minimum untuk lulus di UPITRA?', '<p style=\"text-align: justify;\">Syarat Indeks Prestasi Kumulatif (IPK) minimum untuk kelulusan dan wisuda di UPITRA adalah <strong>2.00</strong>. Selain IPK minimum, mahasiswa juga wajib memastikan telah memenuhi jumlah SKS minimum sesuai kurikulum program studi, tidak memiliki nilai E, serta memenuhi batas maksimal nilai D yang diizinkan oleh prodi masing-masing.</p>', '[\"ipk minimum\",\"ip kelulusan\",\"syarat ipk lulus\",\"minimal ipk wisuda\",\"standar lulus upitra\",\"ipk paling rendah\",\"ipk lulus\"]', 'Aktif', 1, 20, '2026-04-16 20:11:29', '2026-06-24 20:13:56'),
(25, 'Program Studi', 'Umum', 'Program Studi Apa Saja yang Tersedia di UPITRA?', '<p>UPITRA memiliki program studi yang berada di beberapa fakultas, antara lain:</p><p>Fakultas Sains &amp; Teknologi</p><p>• Informatika</p><p>• Sistem Informasi</p><p>• Software Engineering</p><p>Fakultas Ekonomika &amp; Bisnis</p><p>• Akuntansi</p><p>• Manajemen</p><p>Fakultas Sosial &amp; Humaniora</p><p>• Pariwisata</p><p>• Bahasa Inggris</p><p>Fakultas Kesehatan</p><p>• Fisioterapi</p><p>• Keselamatan dan Kesehatan Kerja (K3)</p>', '[\"program studi\",\"jurusan\",\"prodi\",\"daftar prodi\",\"jurusan upitra\",\"program studi upitra\"]', 'Aktif', 1, 25, '2026-04-16 20:11:30', '2026-06-02 01:42:46'),
(26, 'Program Studi', 'FST', 'Apa keunggulan Prodi Sistem Informasi UPITRA?', '<p>Prodi Sistem Informasi UPITRA menggabungkan kompetensi <strong>teknologi informasi</strong> dan <strong>strategi bisnis</strong> untuk menghasilkan lulusan yang mampu merancang solusi digital bagi organisasi. Mahasiswa akan menguasai analisis bisnis, transformasi digital, serta manajemen sistem informasi yang relevan dengan kebutuhan industri saat ini, sehingga siap berkarir sebagai profesional IT yang adaptif.</p>', '[\"prodi sistem informasi\",\"jurusan sistem informasi\",\"keunggulan sistem informasi\",\"kuliah prodi si\",\"kurikulum prodi sistem informasi\",\"prodi si upitra\",\"jurusan si\"]', 'Aktif', 1, 26, '2026-04-16 20:11:30', '2026-07-01 01:02:36'),
(27, 'Program Studi', 'FST', 'Apa keunggulan Prodi Software Engineering UPITRA?', '<p>Program Studi Software Engineering UPITRA berfokus pada pengembangan perangkat lunak modern melalui pendekatan project-based learning dan praktik industri. Mahasiswa mempelajari software development, software architecture, DevOps, quality assurance, hingga pengelolaan proyek perangkat lunak sesuai standar industri global.</p>', '[\"software engineering\",\"rekayasa perangkat lunak\",\"prodi software engineering\",\"keunggulan software engineering\"]', 'Aktif', 1, 27, '2026-04-16 20:11:30', '2026-06-02 01:53:30'),
(28, 'Program Studi', 'FST', 'Apa keunggulan Prodi Informatika UPITRA?', '<p>Program Studi Informatika UPITRA membekali mahasiswa dengan kompetensi di bidang pemrograman, kecerdasan buatan (Artificial Intelligence), data science, pengembangan aplikasi, dan teknologi digital. Mahasiswa juga mendapatkan pengalaman pembelajaran berbasis proyek, dukungan teknologi modern, serta kesempatan mengikuti Immersion Program yang terhubung dengan dunia industri.</p>', '[\"informatika\",\"prodi informatika\",\"jurusan informatika\",\"keunggulan informatika\",\"informatika upitra\"]', 'Aktif', 1, 28, '2026-04-16 20:11:30', '2026-06-02 01:48:43'),
(29, 'Program Studi', 'FEB', 'Apa keunggulan Prodi Akuntansi UPITRA?', '<p>Program Studi Akuntansi UPITRA membekali mahasiswa dengan kompetensi di bidang akuntansi keuangan, audit, perpajakan, sistem informasi akuntansi, dan pengelolaan keuangan berbasis teknologi.</p>', '[\"akuntansi\",\"prodi akuntansi\",\"jurusan akuntansi\",\"keunggulan akuntansi\"]', 'Aktif', 1, 29, '2026-04-16 20:11:30', '2026-06-02 01:57:33'),
(30, 'Program Studi', 'FEB,Manajemen', 'Apa keunggulan Prodi Manajemen UPITRA?', '<p>Prodi Manajemen UPITRA memiliki kurikulum berbasis industri yang fokus pada pengembangan kemampuan manajerial, bisnis digital, kewirausahaan, dan kepemimpinan. Mahasiswa juga mendapatkan kesempatan magang, project industri, serta pembelajaran praktis yang mendukung kesiapan kerja di dunia bisnis modern.</p>', '[\"keunggulan Manajemen UPITRA\",\"Prodi Manajemen UPITRA\",\"jurusan Manajemen UPITRA\",\"kuliah manajemen Surakarta\",\"kampus bisnis UPITRA\",\"prospek kerja manajemen UPITRA\"]', 'Aktif', 1, 30, '2026-04-16 20:11:30', '2026-05-28 22:58:19'),
(31, 'Program Studi', 'Akreditasi', 'Apa akreditasi program studi di UPITRA?', '<p>Seluruh program studi di UPITRA telah terakreditasi oleh BAN-PT. Saat ini, program studi <strong>Sistem Informasi</strong> berstatus <strong>Sangat Baik</strong>, <strong>Akuntansi</strong> berstatus <strong>Baik Sekali</strong>, serta <strong>Manajemen, Informatika, dan Software Engineering</strong> berstatus <strong>Baik</strong>. Adapun untuk program studi baru seperti <strong>Pariwisata, BKI, Fisioterapi, dan K3</strong> saat ini sedang dalam proses pemenuhan akreditasi minimum.</p>', '[\"akreditasi upitra\",\"status ban-pt\",\"apakah upitra terakreditasi\",\"peringkat kampus\"]', 'Aktif', 1, 31, '2026-04-16 20:11:30', '2026-07-01 01:09:28'),
(32, 'Program Studi', 'FST', 'Apa prospek karir lulusan Sistem Informasi UPITRA?', '<p>Lulusan Sistem Informasi dapat berkarier sebagai Business Analyst, System Analyst, IT Consultant, Project Manager, ERP Specialist, Digital Transformation Specialist, maupun posisi strategis yang menghubungkan kebutuhan bisnis dan teknologi.</p>', '[\"karir sistem informasi\",\"lulusan sistem informasi\",\"kerja sistem informasi\",\"prospek kerja sistem informasi\"]', 'Aktif', 1, 32, '2026-04-16 20:11:30', '2026-06-02 01:51:16'),
(33, 'Program Studi', 'FST', 'Apa prospek karir lulusan Software Engineering UPITRA?', '<p>Lulusan Software Engineering dapat berkarier sebagai Software Engineer, Full Stack Developer, Mobile Developer, DevOps Engineer, QA Engineer, Software Architect, maupun Product Engineer di berbagai industri digital.</p>', '[\"karir software engineering\",\"lulusan software engineering\",\"kerja software engineering\",\"prospek kerja software engineering\"]', 'Aktif', 1, 33, '2026-04-16 20:11:30', '2026-06-02 01:54:33'),
(34, 'Program Studi', 'FEB', 'Apa prospek karir lulusan Akuntansi UPITRA?', '<p>Lulusan Akuntansi dapat berkarier sebagai Auditor, Akuntan, Tax Consultant, Financial Analyst, Internal Auditor, Accounting Staff, maupun profesional di bidang keuangan dan perpajakan.</p>', '[\"karir akuntansi\",\"lulusan akuntansi\",\"kerja akuntansi\",\"prospek kerja akuntansi\"]', 'Aktif', 1, 34, '2026-04-16 20:11:30', '2026-06-02 01:59:31'),
(35, 'Immersion Program', 'Informasi', 'Apa itu Immersion Program di UPITRA?', '<p>Immersion Program adalah program pembelajaran berbasis pengalaman yang menjadi bagian dari kurikulum UPITRA. Melalui program ini, mahasiswa mendapatkan kesempatan belajar langsung di dunia industri, institusi pendidikan, atau lingkungan profesional untuk mengembangkan kompetensi, pengalaman kerja, dan wawasan global.</p>', '[\"immersion program upitra\",\"apa itu immersion upitra\",\"program magang upitra\",\"internship upitra\",\"mbkm upitra\",\"pengalaman industri mahasiswa upitra\",\"smart immersion upitra\"]', 'Aktif', 1, 35, '2026-04-16 20:11:30', '2026-06-01 23:49:42'),
(37, 'Immersion Program', 'Umum', 'Siapa saja yang dapat mengikuti Immersion Program UPITRA?', '<p>Immersion Program UPITRA dapat diikuti oleh mahasiswa aktif Universitas Pignatelli Triputra yang telah memenuhi persyaratan akademik sesuai ketentuan program studi. Umumnya, mahasiswa yang memasuki tahap akhir pembelajaran (setelah menyelesaikan sejumlah SKS tertentu) berkesempatan mengikuti program ini sebagai bagian dari implementasi kurikulum 3+1.</p><p>Kelayakan peserta ditentukan oleh program studi berdasarkan capaian akademik, kesiapan kompetensi, serta kebutuhan penempatan pada mitra industri atau program yang tersedia.</p>', '[\"peserta immersion program upitra\",\"syarat immersion upitra\",\"siapa yang bisa ikut immersion upitra\"]', 'Aktif', 1, 37, '2026-04-16 20:11:30', '2026-05-28 23:52:05'),
(38, 'Immersion Program', 'Umum', 'Bagaimana cara mendaftar Immersion Program?', '<p>Pendaftaran Immersion Program UPITRA dilakukan secara terstruktur melalui program studi dan sistem yang ditentukan oleh universitas. Mahasiswa yang memenuhi syarat akan mendapatkan informasi resmi terkait pembukaan pendaftaran, kemudian melakukan pengisian data dan seleksi sesuai ketentuan (termasuk kesiapan akademik dan kompetensi).</p><p>Proses pendaftaran biasanya meliputi verifikasi oleh program studi, penentuan penempatan mitra industri, serta briefing atau pembekalan sebelum pelaksanaan program. Seluruh informasi dan mekanisme teknis mengikuti pengumuman resmi dari kampus melalui kanal akademik dan program Immersion UPITRA.</p>', '[\"cara daftar immersion upitra\",\"pendaftaran immersion program\",\"seleksi immersion upitra\",\"registrasi program industri upitra\"]', 'Aktif', 1, 38, '2026-04-16 20:11:30', '2026-05-28 23:53:29'),
(39, 'Fasilitas & Layanan', 'Fasilitas Kampus', 'Apa saja fasilitas yang tersedia di kampus UPITRA?', '<p>UPITRA menyediakan berbagai fasilitas untuk mendukung pembelajaran dan pengembangan mahasiswa, antara lain:</p><p>• Ruang kelas modern</p><p>• Laboratorium komputer dan praktikum</p><p>• WiFi kampus</p><p>• Perpustakaan Digital (SIPER)</p><p>• Portal Akademik</p><p>• E-Learning UNITY</p><p>• Career Center (UCC)</p><p>• Ruang kegiatan mahasiswa</p><p>Fasilitas terus dikembangkan untuk mendukung pembelajaran berbasis teknologi dan kebutuhan industri.</p>', '[\"fasilitas kampus\",\"sarana kampus\",\"fasilitas upitra\",\"infrastruktur kampus\",\"gedung kampus\",\"laboratorium\",\"ruang kelas\",\"fasilitas mahasiswa\"]', 'Aktif', 1, 39, '2026-04-16 20:11:30', '2026-06-01 20:50:01'),
(42, 'Fasilitas & Layanan', 'Portal Akademik', 'Bagaimana cara login portal akademik mahasiswa?', '<p>Mahasiswa UPITRA dapat mengakses <strong>Portal Akademik</strong> melalui laman resmi berikut:<br>🌐 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id\">https://mhs.upitra.ac.id</a></p><p>Langkah login:</p><ul><li><p>Masukkan <strong>NIM (Nomor Induk Mahasiswa)</strong> sebagai username</p></li><li><p>Masukkan <strong>password</strong> yang diberikan saat proses registrasi atau aktivasi akun</p></li><li><p>Klik tombol <strong>Login</strong> untuk masuk ke dashboard akademik</p></li></ul><p>Melalui portal ini, mahasiswa dapat mengakses layanan seperti KRS, jadwal kuliah, nilai, dan informasi akademik lainnya.</p>', '[\"portal akademik\",\"cara login portal akademik mahasiswa\",\"siakad\",\"login siakad\",\"akun mahasiswa\",\"portal mahasiswa\",\"akses akademik\",\"mhs upitra\"]', 'Aktif', 1, 42, '2026-04-16 20:11:30', '2026-06-01 20:51:40'),
(45, 'Lainnya', 'Transportasi', 'Bagaimana akses transportasi ke kampus UPITRA?', '<p>Akses menuju kampus <strong>Universitas Pignatelli Triputra (UPITRA)</strong> relatif mudah dijangkau karena berada di lokasi strategis di Kota Surakarta.</p><p>Alamat kampus:<br>📍 Jl. Duwet Raya No. I, Karangasem, Laweyan, Kota Surakarta, Jawa Tengah 57145</p><p>Pilihan akses transportasi yang dapat digunakan:</p><ul><li><p>🚗 <strong>Kendaraan pribadi</strong> (mobil dan motor) melalui jalur utama Kota Surakarta</p></li><li><p>🚕 <strong>Transportasi online</strong> seperti ojek dan taksi online</p></li><li><p>🚌 <strong>Transportasi umum kota</strong> yang melewati atau mendekati kawasan Laweyan</p></li><li><p>🚉 <strong>Akses dari stasiun dan terminal</strong> di Kota Solo, dilanjutkan perjalanan darat ±15–30 menit ke kampus</p></li></ul><p>Kampus UPITRA juga memiliki akses jalan yang terhubung dengan pusat kota sehingga mudah dijangkau dari berbagai arah.</p>', '[\"transportasi upitra\",\"akses kampus upitra\",\"cara ke upitra\",\"lokasi upitra\",\"alamat kampus upitra\",\"rute ke upitra\",\"kampus laweyan\",\"cara ke kampus\",\"stasiun ke upitra\",\"terminal ke upitra\",\"transportasi solo\"]', 'Aktif', 1, 45, '2026-04-16 20:11:30', '2026-06-01 20:51:55'),
(46, 'Kemahasiswaan', 'Organisasi', 'Apa saja organisasi mahasiswa di UPITRA?', 'Organisasi mahasiswa UPITRA: BEM (Badan Eksekutif Mahasiswa), HIMA (Himpunan Mahasiswa per Prodi), UKM (Unit Kegiatan Mahasiswa) di bidang olahraga, seni, teknologi, dan kewirausahaan.', '\"[\\\"organisasi mahasiswa\\\",\\\"bem upitra\\\",\\\"hima upitra\\\",\\\"ukm upitra\\\",\\\"ormawa\\\"]\"', 'Aktif', 1, 46, '2026-04-16 20:11:30', '2026-04-16 20:11:30'),
(47, 'Kemahasiswaan', 'Organisasi', 'Bagaimana cara bergabung dengan UKM di UPITRA?', '', '\"[\\\"daftar ukm\\\",\\\"bergabung ukm\\\",\\\"cara masuk ukm\\\",\\\"ukm apa saja\\\"]\"', 'Kosong', 1, 47, '2026-04-16 20:11:30', '2026-04-16 20:11:30'),
(48, 'Kemahasiswaan', 'Prestasi', 'Apa saja prestasi mahasiswa UPITRA?', 'Mahasiswa UPITRA aktif berprestasi di tingkat nasional dan internasional, termasuk PSM Genta Dikara yang meraih Bronze Medal di Saint Angela International Choir Festival 2026.', '\"[\\\"prestasi mahasiswa\\\",\\\"penghargaan mahasiswa\\\",\\\"juara kompetisi\\\",\\\"prestasi upitra\\\"]\"', 'Aktif', 1, 48, '2026-04-16 20:11:30', '2026-04-16 20:11:30'),
(49, 'Kemahasiswaan', 'Beasiswa Prestasi', 'Bagaimana cara mendapatkan beasiswa prestasi mahasiswa?', '', '\"[\\\"beasiswa prestasi mahasiswa\\\",\\\"beasiswa aktif\\\",\\\"beasiswa ipk tinggi\\\"]\"', 'Kosong', 1, 49, '2026-04-16 20:11:30', '2026-04-16 20:11:30'),
(51, 'Karir & Alumni', 'Career Center', 'Bagaimana cara mengakses lowongan kerja di UPITRA?', '<p>Mahasiswa dan alumni dapat mengakses informasi lowongan kerja melalui UPITRA Career Center (UCC) yang menyediakan berbagai informasi peluang karier dari perusahaan mitra dan jaringan industri UPITRA.</p>', '[\"lowongan kerja\",\"cari kerja\",\"job vacancy\",\"pekerjaan alumni\",\"info loker\",\"peluang kerja\",\"rekrutmen alumni\"]', 'Aktif', 1, 51, '2026-04-16 20:11:30', '2026-06-02 00:09:56'),
(52, 'Karir & Alumni', 'Tracer Study', 'Apa itu tracer study dan bagaimana cara mengisinya?', 'Tracer Study adalah survei karir alumni. Isi di: https://tracer.upitra.ac.id. Membantu UPITRA meningkatkan kualitas pendidikan.', '\"[\\\"tracer study\\\",\\\"survei alumni\\\",\\\"tracer upitra\\\",\\\"alumni upitra\\\"]\"', 'Aktif', 1, 52, '2026-04-16 20:11:30', '2026-04-16 20:11:30'),
(54, 'Profil Universitas', 'Umum', 'Apa visi Universitas Pignatelli Triputra?', '<p>Visi Universitas Pignatelli Triputra (UPITRA) adalah menjadi universitas unggul yang menghasilkan lulusan berkarakter, profesional, inovatif, dan siap bersaing di tingkat nasional maupun global.</p>', '[\"visi misi universitas\",\"tujuan upitra\",\"target kampus\"]', 'Aktif', 1, 54, '2026-04-16 20:11:30', '2026-07-01 01:10:38'),
(55, 'Profil Universitas', 'Umum', 'Kapan Universitas Pignatelli Triputra didirikan?', '<p>Universitas Pignatelli Triputra (UPITRA) resmi didirikan pada tanggal <strong>13 Juli 2022</strong> berdasarkan <strong>SK Pendirian No. 511/E/O/2022</strong>. Kehadiran UPITRA merupakan wujud sinergi strategis antara Yayasan Pignatelli dan Triputra Group dalam berkomitmen menyelenggarakan pendidikan tinggi berkualitas yang relevan dengan perkembangan industri global.</p>', '[\"kapan upitra didirikan\",\"sejarah upitra\",\"umur kampus upitra\",\"pendiri pignatelli\"]', 'Aktif', 1, 55, '2026-04-16 20:11:30', '2026-07-01 01:11:42'),
(56, 'Profil Universitas', 'Pimpinan', 'Siapa Rektor Universitas Pignatelli Triputra?', '<p>Dr. Fr. Ninik Yudianti, M.Acc., QIA., CSRA merupakan Rektor UPITRA (Universitas Pignatelli Triputra) yang aktif dalam pengembangan pendidikan tinggi dan pembangunan kampus berkelanjutan. Beliau memiliki latar belakang di bidang manajemen, akuntansi, dan tata kelola organisasi. Selain aktif di dunia akademik, beliau juga terlibat dalam pengembangan kualitas pendidikan, kepemimpinan institusi, dan pengelolaan organisasi pendidikan. </p>', '[\"Dr Fr Ninik Yudianti\",\"Ninik Yudianti\",\"Romo Ninik\",\"Rektor UPITRA\",\"Rektor Universitas Pignatelli Triputra\",\"Pimpinan UPITRA\",\"Dr. Fr. Ninik Yudianti M.Acc QIA CSRA\",\"ninik yudianti upitra\",\"rektor upitra\",\"siapa rektor\",\"rektor\"]', 'Aktif', 1, 56, '2026-04-16 20:11:30', '2026-06-03 18:55:28'),
(57, 'Profil Universitas', 'Pimpinan', 'Siapa Wakil Rektor Bidang Akademik UPITRA?', '<p>Wakil Rektor Bidang Akademik UPITRA (Universitas Pignatelli Triputra) dijabat oleh Neil Semuel Rupidara, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>., Ph.D. Beliau merupakan akademisi dan praktisi pendidikan tinggi yang memiliki pengalaman luas di bidang manajemen dan pengembangan organisasi. Sebelum bergabung di UPITRA, beliau pernah menjabat sebagai Rektor Universitas Kristen Satya Wacana (UKSW) periode 2017–2022. Keahlian beliau meliputi Human Resource Management, Strategic HRM, International HRM, dan Organization Studies. </p>', '[\"Neil Semuel Rupidara\",\"Neil Rupidara\",\"Pak Neil\",\"Wakil Rektor Akademik\",\"Wakil Rektor 1\",\"WR 1 UPITRA\",\"Wakil Rektor Bidang Akademik UPITRA\",\"Pimpinan UPITRA\",\"Neil Semuel Rupidara S.E. M.Sc. Ph.D\",\"Akademisi UPITRA\",\"wakil rektor 1\",\"wr 1\",\"WR 1\",\"wakil rektor bidang akademik\"]', 'Aktif', 1, 57, '2026-04-16 20:11:30', '2026-06-03 18:56:12'),
(58, 'Profil Universitas', 'Lokasi', 'Dimana lokasi kampus UPITRA?', '<p>Kampus Universitas Pignatelli Triputra berlokasi di <strong>Jl. Duwet No. 1, Karangasem, Laweyan, Surakarta 57145, Jawa Tengah</strong>. Lokasinya strategis dan mudah diakses menggunakan kendaraan pribadi maupun transportasi umum di area Kota Surakarta.</p><p>📍 Google Maps: <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://maps.app.goo.gl/ZTVrpyX76bh9GDFg6?utm_source=chatgpt.com\">Lokasi Kampus UPITRA</a></p>', '[\"lokasi UPITRA\",\"alamat UPITRA\",\"kampus UPITRA dimana\",\"lokasi kampus\",\"alamat kampus\",\"letak UPITRA\",\"universitas pignatelli triputra lokasi\",\"UPITRA solo\",\"maps UPITRA\",\"google maps UPITRA\",\"rute ke UPITRA\",\"menuju UPITRA\",\"akses kampus UPITRA\",\"alamat universitas\",\"lokasi universitas\",\"kampus di mana\",\"share lokasi UPITRA\",\"titik lokasi kampus\",\"alamat lengkap UPITRA\",\"lokasi universitas pignatelli triputra\"]', 'Aktif', 1, 58, '2026-04-16 20:11:30', '2026-05-28 21:25:38'),
(59, 'Profil Universitas', 'Kontak', 'Bagaimana cara menghubungi UPITRA?', '<p>Untuk informasi dan layanan akademik, Anda dapat menghubungi Universitas Pignatelli Triputra melalui:</p><p>📞 Telp/WhatsApp: <strong>0811-290-7500</strong><br>✉️ Email: <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:admission@upitra.ac.id\"><strong>admission@upitra.ac.id</strong></a><br>🌐 Website Resmi: <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://upitra.ac.id?utm_source=chatgpt.com\">UPITRA Official Website</a></p><p>🕘 Jam layanan administrasi: <strong>Senin–Jumat, pukul 08.00–16.00 WIB</strong>.<br>Tim UPITRA siap membantu informasi pendaftaran, akademik, fasilitas kampus, hingga konsultasi program studi.</p>', '[\"kontak UPITRA\",\"hubungi UPITRA\",\"nomor whatsapp UPITRA\",\"WA UPITRA\",\"telepon UPITRA\",\"email UPITRA\",\"customer service UPITRA\",\"admin UPITRA\",\"call center UPITRA\",\"layanan informasi UPITRA\",\"cara menghubungi kampus\",\"jam layanan UPITRA\",\"kontak admission UPITRA\",\"pusat informasi UPITRA\"]', 'Aktif', 1, 59, '2026-04-16 20:11:30', '2026-05-28 21:28:03'),
(63, 'Teknologi & Sistem', 'Umum', 'Apa saja sistem informasi yang digunakan di UPITRA?', '<p>Untuk mendukung kegiatan akademik dan administrasi yang efisien, UPITRA memanfaatkan ekosistem digital terintegrasi. Layanan utama kami meliputi <strong>Portal Akademik Mahasiswa</strong> (administrasi perkuliahan), <strong>UNITY</strong> (platform pembelajaran mandiri/LMS), <strong>SIPER</strong> (perpustakaan digital), <strong>Sistem PMB Online</strong>, serta <strong>Career Center</strong> untuk persiapan karir alumni.</p>', '[\"sistem kampus\",\"platform digital\",\"aplikasi kampus\",\"teknologi kampus\",\"sistem upitra\",\"siakad upitra\",\"sistem informasi akademik\",\"aplikasi unity\",\"login siper\",\"portal mahasiswa\"]', 'Aktif', 1, 63, '2026-04-16 20:11:30', '2026-07-01 00:58:30'),
(64, 'Teknologi & Sistem', 'Umum', 'Apakah mahasiswa mendapatkan email kampus?', '<p>Ya, mahasiswa UPITRA dapat memperoleh <strong>email resmi kampus</strong> yang digunakan untuk kebutuhan akademik seperti akses sistem pembelajaran, komunikasi resmi, dan layanan digital kampus.</p><p>Untuk informasi atau permintaan aktivasi email kampus, silakan menghubungi:<br>📧 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:admission@upitra.ac.id\"><strong>admission@upitra.ac.id</strong></a></p>', '[\"email kampus\",\"email mahasiswa\",\"akun email upitra\",\"student email\",\"surel mahasiswa\"]', 'Aktif', 1, 64, '2026-04-16 20:11:30', '2026-06-02 01:15:58'),
(65, 'Riset & Publikasi', 'Jurnal', 'APAKAH UPITRA MEMILIKI JURNAL ILMIAH?', '<p>UPITRA mendukung publikasi ilmiah melalui berbagai media publikasi akademik. Informasi mengenai jurnal yang dikelola dapat diperoleh melalui website resmi UPITRA atau LPPM.</p>', '[\"jurnal upitra\",\"apakah ada jurnal\",\"publikasi ilmiah\",\"e-journal upitra\",\"akses jurnal kampus\",\"jurnal ilmiah\",\"journal\"]', 'Aktif', 1, 65, '2026-04-16 20:11:30', '2026-06-02 01:34:33'),
(66, 'Riset & Publikasi', 'LPPM', 'APA ITU LPPM UPITRA?', '<p>LPPM (Lembaga Penelitian dan Pengabdian kepada Masyarakat) merupakan unit di UPITRA yang mengelola kegiatan penelitian, publikasi ilmiah, pengabdian masyarakat, serta pengembangan inovasi dosen dan mahasiswa.</p>', '[\"lppm\",\"lppm upitra\",\"apa itu lppm\",\"pengabdian masyarakat\",\"tridharma perguruan tinggi\",\"ketua lppm upitra\",\"ketua lppm\",\"lembaga penelitian\",\"pusat penelitian\",\"penelitian dan pengabdian\"]', 'Aktif', 1, 66, '2026-04-16 20:11:30', '2026-06-02 01:30:24'),
(135, 'Lainnya', 'Triputra', 'Apa itu Triputra Group?', '<p>Triputra Group adalah perusahaan induk (holding company) di Indonesia yang memiliki portofolio bisnis terdiversifikasi di berbagai sektor strategis, termasuk agribisnis, manufaktur, pertambangan, logistik, dan layanan bisnis. Sejak didirikan, Triputra Group berfokus pada pembangunan bisnis berkelanjutan melalui tata kelola perusahaan yang baik (good corporate governance), penguatan kapabilitas sumber daya manusia, serta pengembangan organisasi yang adaptif dan berdaya saing tinggi.</p><p>Selain aktivitas bisnis, Triputra Group juga berperan dalam pengembangan ekosistem pendidikan dan penguatan link and match antara dunia industri dan dunia akademik melalui berbagai inisiatif pengembangan talenta. Hal ini dilakukan untuk memastikan kesiapan lulusan dalam menghadapi kebutuhan kompetensi di dunia kerja yang terus berkembang.</p>', '[\"Triputra Group\",\"apa itu Triputra\",\"perusahaan Triputra\",\"TP Rachmat\",\"Triputra pendidikan\",\"holding company Indonesia\"]', 'Aktif', 0, 3, '2026-05-25 20:33:56', '2026-05-29 01:20:57'),
(136, 'Lainnya', 'TEN', 'Siapa Yohanes Tan?', '<p>Yohanes Tan merupakan Chief Executive Officer (CEO) Triputra Edukasi Nusantara (TEN), entitas yang berperan dalam pengembangan ekosistem pendidikan di lingkungan UPITRA (Universitas Pignatelli Triputra). Dalam perannya, beliau berfokus pada penguatan kolaborasi antara dunia pendidikan tinggi dan industri melalui pengembangan program berbasis kebutuhan kompetensi kerja, peningkatan kualitas pembelajaran, serta penguatan kemitraan strategis. Kontribusinya diarahkan pada pembangunan model pendidikan yang relevan dengan kebutuhan dunia kerja dan transformasi institusi pendidikan yang adaptif terhadap perubahan industri.</p>', '[\"Yohanes Tan\",\"Pak Yohanes\",\"CEO TEN\",\"CEO Triputra Edukasi Nusantara\",\"Pimpinan TEN\",\"Industry Driven Education\",\"Yohanes Tan TEN\",\"pak yo\",\"pak yohanes\",\"siapa pemilik ten\"]', 'Aktif', 0, 0, '2026-05-26 00:08:43', '2026-06-03 19:06:06'),
(145, 'Fasilitas & Layanan', 'Perpustakaan', 'Apakah UPITRA memiliki perpustakaan digital?', '<p>Ya, UPITRA memiliki <strong>perpustakaan digital</strong> yang dapat diakses oleh mahasiswa dan sivitas akademika untuk mendukung kegiatan pembelajaran, penelitian, dan pengembangan ilmu pengetahuan.</p><p>Perpustakaan digital UPITRA menyediakan berbagai koleksi referensi akademik yang dapat diakses secara online melalui sistem <strong>SIPER (Sistem Informasi Perpustakaan)</strong>.</p><p>Akses perpustakaan digital dapat dilakukan melalui:<br>🌐 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://siper.upitra.ac.id\">https://siper.upitra.ac.id</a></p>', '[\"perpustakaan digital\",\"library upitra\",\"siper upitra\",\"perpustakaan online\",\"perpustakaan mahasiswa\",\"perpustakaan\",\"library\",\"siper\",\"ebook\",\"referensi digital\",\"buku online\"]', 'Aktif', 0, 0, '2026-05-26 00:58:43', '2026-06-01 21:49:18'),
(146, 'Fasilitas & Layanan', 'E-Learning', 'Bagaimana cara mengakses e-learning di UPITRA?', '<p>Mahasiswa UPITRA dapat mengakses sistem e-learning melalui platform <strong>UNITY (Learning Management System)</strong> yang digunakan untuk mendukung proses pembelajaran daring, pengumpulan tugas, dan akses materi kuliah.</p><p>Langkah akses e-learning UPITRA:</p><ul><li><p>Buka laman resmi: 🌐 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://unity.upitra.ac.id\">https://unity.upitra.ac.id</a></p></li><li><p>Login menggunakan akun mahasiswa yang telah diberikan oleh kampus</p></li><li><p>Pilih mata kuliah yang sedang diambil</p></li><li><p>Akses materi, tugas, dan aktivitas pembelajaran sesuai kelas masing-masing</p></li></ul><p>Platform UNITY digunakan untuk memastikan proses pembelajaran tetap berjalan efektif, terstruktur, dan dapat diakses secara fleksibel oleh mahasiswa.</p>', '[\"unity upitra\",\"cara akses e-learning\",\"login unity\",\"lms upitra\",\"learning management system\",\"learning management system UPITRA\",\"platform pembelajaran\",\"akses unity upitra\"]', 'Aktif', 0, 0, '2026-05-26 00:59:44', '2026-05-29 01:49:22'),
(147, 'Fasilitas & Layanan', 'Career Center', 'Apakah UPITRA memiliki layanan Career Center?', '<p>Ya, UPITRA memiliki layanan <strong>Career Center (UCC – UPITRA Career Center)</strong> yang berfungsi membantu mahasiswa dan alumni dalam pengembangan karier serta akses informasi dunia kerja.</p><p>Melalui UCC, mahasiswa dapat memperoleh informasi seperti:</p><ul><li><p>Lowongan kerja dan magang</p></li><li><p>Pengembangan kompetensi dan pelatihan karier</p></li><li><p>Program rekrutmen dari mitra industri</p></li><li><p>Konseling dan persiapan memasuki dunia kerja</p></li></ul><p>Layanan Career Center UPITRA dapat diakses melalui:<br>🌐 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://ucc.upitra.ac.id\">https://ucc.upitra.ac.id</a></p>', '[\"career center\",\"ucc\",\"pengembangan karir\",\"konseling karir\",\"career counseling\"]', 'Aktif', 0, 0, '2026-05-26 01:04:15', '2026-06-01 20:04:50'),
(148, 'Teknologi & Sistem', 'Layanan Online', 'Apakah semua layanan akademik UPITRA dapat diakses secara online?', '<p>Sebagian besar layanan akademik UPITRA telah tersedia secara digital untuk memudahkan mahasiswa dalam proses perkuliahan dan administrasi. Sistem ini mendukung pembelajaran yang lebih fleksibel, cepat, dan terintegrasi.</p><p>Layanan yang dapat diakses secara online meliputi:</p><ul><li><p>📚 <strong>Portal Akademik</strong> (KRS, jadwal, nilai) – <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id\">https://mhs.upitra.ac.id</a></p></li><li><p>🎓 <strong>E-Learning UNITY</strong> (materi, tugas, kelas online) – <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://unity.upitra.ac.id\">https://unity.upitra.ac.id</a></p></li><li><p>📖 <strong>Perpustakaan Digital SIPER</strong> – <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://siper.upitra.ac.id\">https://siper.upitra.ac.id</a></p></li><li><p>💼 <strong>Career Center UCC</strong> – <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://ucc.upitra.ac.id\">https://ucc.upitra.ac.id</a></p></li></ul><p>Namun, beberapa layanan tertentu seperti administrasi fisik atau layanan khusus tetap dapat memerlukan proses offline sesuai kebutuhan.</p>', '[\"layanan akademik UPITRA dapat diakses secara online\",\"layanan online upitra\",\"kemudahan layanan online\",\"layanan online\",\"akses online\",\"sistem online\",\"layanan digital\"]', 'Aktif', 0, 0, '2026-05-26 01:05:06', '2026-06-02 01:21:35'),
(150, 'Program Studi', 'FST,Sistem Informasi', 'Siapa Mawar Hardiyanti, S.Kom, M.Kom?', '<p>Mawar Hardiyanti, S.Kom, M.Kom merupakan dosen sekaligus Kaprodi Sistem Informasi di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Sistem Informasi Enterprise dan Artificial Intelligence. Pendidikan S1 ditempuh di STMIK Sinar Nusantara dan S2 di Universitas Islam Indonesia. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:mawar@upitra.ac.id\">mawar@upitra.ac.id</a></p>', '[\"Kaprodi SI UPITRA\",\"Kaprodi Sistem Informasi\",\"Mawar\",\"Bu Mawar\",\"Mawar Hardiyanti, S.Kom., M.Kom.\",\"Kaprodi SI\",\"Mawar Hardiyanti\"]', 'Aktif', 0, 50, '2026-05-26 02:19:12', '2026-06-01 20:25:10'),
(152, 'Program Studi', 'FST,Sistem Informasi', 'Siapa Benedictus Herry Suharto, S.T., M.T.?', '<p>Benedictus Herry Suharto, S.T., M.T merupakan dosen tetap Program Studi Sistem Informasi di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Internet of Things (IoT), Artificial Intelligence, dan Robotika. Pendidikan S1 dan S2 ditempuh di Universitas Gadjah Mada pada bidang Teknik Elektro. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:bherrys@upitra.ac.id\">bherrys@upitra.ac.id</a></p>', '[\"Benedictus Herry Suharto\",\"Herry Suharto\",\"Pak Herry\",\"Benedictus Herry Suharto S.T. M.T\"]', 'Aktif', 0, 63, '2026-05-26 02:23:42', '2026-06-01 20:25:19'),
(153, 'Program Studi', 'FST,Sistem Informasi', 'Siapa Maria Karmelia Fajarlestari, S.Kom, M.Kom?', '<p>Maria Karmelia Fajarlestari, S.Kom, M.Kom merupakan dosen tetap Program Studi Sistem Informasi di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Sistem Informasi Enterprise dan Sistem Penjadwalan. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Atma Jaya Yogyakarta. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:mariakarmelia@upitra.ac.id\">mariakarmelia@upitra.ac.id</a></p>', '[\"Maria Karmelia Fajarlestari\",\"Maria Karmelia\",\"Karmel\",\"Bu Karmel\",\"Maria Karmelia Fajarlestari S.Kom M.Kom\"]', 'Aktif', 0, 0, '2026-05-26 02:25:01', '2026-05-28 23:24:32'),
(154, 'Program Studi', 'FST,Sistem Informasi', 'Siapa Yeremia Victor Rondonuwu, S.Kom, M.M.?', '<p>eremia Victor Rondonuwu, S.Kom, M.M merupakan dosen tetap Program Studi Sistem Informasi di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Web Development, UI/UX, Information System, dan IS Management. Pendidikan S1 ditempuh di STMIK Asia Malang dan S2 di Universitas Merdeka Malang. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:yeremiavictor@upitra.ac.id\">yeremiavictor@upitra.ac.id</a></p>', '[\"Yeremia Victor Rondonuwu\",\"Yeremia\",\"Victor Rondonuwu\",\"Pak Yeremia\"]', 'Aktif', 0, 0, '2026-05-26 02:26:15', '2026-05-28 23:24:39'),
(155, 'Program Studi', 'FST,Sistem Informasi', 'Siapa Imanuel Zega, S.Kom, M.Kom?', '<p>Imanuel Zega, S.Kom, M.Kom merupakan dosen tetap Program Studi Sistem Informasi di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Cryptography, Algorithm, Decision Support System, dan Data Science. Pendidikan S1 ditempuh di STMIK Triguna Dharma dan S2 di Universitas Sumatera Utara. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:nuelzega@upitra.ac.id\">nuelzega@upitra.ac.id</a></p>', '[\"Imanuel Zega\",\"Imanuel\",\"Zega\",\"Pak Imanuel\",\"Imanuel Zega S.Kom M.Kom\",\"imanuel zega\",\"zega\",\"pak imanuel\",\"pak zega\",\"imanuel zega s.kom m.kom\",\"imanuel\"]', 'Aktif', 0, 0, '2026-05-26 02:27:23', '2026-06-08 01:51:49'),
(156, 'Program Studi', 'Rekomendasi Prodi', 'Rekomendasi program studi dengan prospek kerja dan peluang karir terbaik ?', '<p>Pilih program studi (prodi) yang paling sesuai dengan minat dan tujuan karier masa depan Anda/putra-putri Anda:</p><h3>🚀 1. Karir Teknologi &amp; Global (Gaji Tinggi &amp; Peluang Global)</h3><ul><li><p><strong>Software Engineering (RPL):</strong> Paling dicari industri, fokus bikin software, peluang kerja global sangat tinggi.</p></li><li><p><strong>Sistem Informasi:</strong> Gabungan teknologi &amp; bisnis digital untuk transformasi industri.</p></li><li><p><strong>Informatika:</strong> Fondasi kuat untuk ahli AI (<em>Artificial Intelligence</em>), <em>Data Science</em>, dan teknologi masa depan.</p></li></ul><h3>💼 2. Karir Bisnis &amp; Keuangan (Stabil &amp; Leadership Track)</h3><ul><li><p><strong>Akuntansi:</strong> Karir stabil dan pasti, jalur menjadi Akuntan Profesional (CA).</p></li><li><p><strong>Manajemen:</strong> Sangat fleksibel untuk semua industri, fokus pada kepemimpinan &amp; bisnis.</p></li></ul><h3>🌐 3. Karir Bahasa, Pariwisata &amp; Hospitality (Global Communication)</h3><ul><li><p><strong>Bahasa Inggris:</strong> Menguasai komunikasi internasional untuk karier global di bidang edukasi, korporat multinasional, translator, hingga <em>content creator</em>.</p></li><li><p><strong>Pariwisata:</strong> Industri yang terus berkembang dengan peluang kerja internasional luas di sektor <em>hospitality</em> dan destinasi global.</p></li></ul><h3>🏥 4. Karir Kesehatan &amp; Keselamatan (Sektor Esensial)</h3><ul><li><p><strong>Fisioterapi:</strong> Profesi medis terukur dengan permintaan kerja yang stabil.</p></li><li><p><strong>K3 (Kesehatan &amp; Keselamatan Kerja):</strong> Profesi wajib yang sangat dibutuhkan di industri manufaktur dan pabrik.</p></li></ul><p><strong>Rekomendasi Terbaik (Peluang Kerja &amp; Gaji Tertinggi):</strong> Pilih <strong>Software Engineering (RPL)</strong> atau <strong>Sistem Informasi</strong>. Industri teknologi berkembang pesat dan menawarkan peluang kerja global (bisa kerja <em>remote</em> untuk perusahaan luar negeri).</p><p>Mau konsultasi lebih lanjut atau langsung mendaftar? Hubungi kami di: <br>📞 <strong>WhatsApp:</strong> 0811-290-7500 📧 <strong>Email:</strong> <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:admission@upitra.ac.id\">admission@upitra.ac.id</a></p>', '[\"rekomendasi prodi\",\"prodi terbaik\",\"rekomendasi untuk anak\",\"jurusan yang bagus\",\"untuk anak saya\",\"gaji tinggi\",\"masa depan bagus\",\"prospek kerja\",\"jurusan terbaik di upitra\",\"prodi paling diminati\",\"bingung pilih jurusan\"]', 'Aktif', 0, 35, '2026-05-26 23:48:47', '2026-07-01 01:08:04'),
(157, 'Program Studi', 'Pemilihan Prodi,Karir Global', 'Kalau ingin memiliki karir global sebaiknya memilih prodi apa?', '<p>Untuk karir global, berikut rekomendasi prodi UPITRA:</p><p>🌍 <strong>PRODI UNTUK KARIR GLOBAL:</strong></p><p>1️⃣ <strong>Software Engineering (paling direkomendasikan)</strong></p><ul><li><p>Sangat dibutuhkan di industri teknologi global</p></li><li><p>Peluang kerja luar negeri tinggi</p></li><li><p>Fokus pada praktik &amp; industri</p></li><li><p>Ada <em>Immersion Program</em> dengan partner industri</p></li></ul><p>2️⃣ <strong>Sistem Informasi</strong></p><ul><li><p>Cocok untuk digital transformation</p></li><li><p>Dibutuhkan di perusahaan multinasional</p></li><li><p>Kombinasi bisnis dan teknologi</p></li></ul><p>3️⃣ <strong>Informatika</strong></p><ul><li><p>Dasar kuat untuk AI, data, dan software</p></li><li><p>Banyak peluang di tech company global</p></li></ul><p>4️⃣ <strong>Manajemen</strong></p><ul><li><p>Karir di perusahaan multinasional</p></li><li><p>Fokus leadership dan bisnis global</p></li></ul><p>🎓 <strong>Keunggulan UPITRA:</strong></p><ul><li><p>Kurikulum berbasis industri (OBE)</p></li><li><p><em>Immersion Program</em> di dunia kerja</p></li><li><p>Proyek nyata untuk portofolio</p></li><li><p>Peluang networking industri</p></li></ul><p>📌 Kesimpulan:<br>Software Engineering adalah pilihan paling kuat untuk karir global, diikuti Sistem Informasi dan Informatika.</p>', '[\"karir global\",\"prospek kerja internasional\",\"global industry\",\"peluang kerja global\"]', 'Aktif', 0, 35, '2026-05-27 19:33:10', '2026-05-29 01:09:45'),
(158, 'Program Studi', 'FST,Software Engineering', 'Siapa Wisnu Wendanto, S.Kom, M.Kom?', '<p>Wisnu Wendanto, S.Kom, M.Kom merupakan dosen tetap Program Studi Software Engineering di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Selain sebagai dosen, beliau juga menjabat sebagai Kepala Biro IT UPITRA. Beliau memiliki keahlian di bidang Software Architecture, DevOps, Mobile Programming, dan Web Programming. Pendidikan S1 ditempuh di STMIK AUB Surakarta dan S2 di Universitas Diponegoro. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:wisnuwendanto@upitra.ac.id\">wisnuwendanto@upitra.ac.id</a></p>', '[\"Wisnu Wendanto\",\"Wisnu\",\"Pak Wisnu\",\"Kepala Biro IT\",\"Kepala IT UPITRA\",\"Biro IT UPITRA\",\"Wisnu Wendanto S.Kom M.Kom\",\"siapa pak wisnu itu\",\"siapa pak wisnu\",\"pak wisnu\"]', 'Aktif', 0, 0, '2026-05-27 19:57:44', '2026-07-07 20:19:09'),
(159, 'Program Studi', 'FST,Software Engineering', 'Siapa Moyo Hady Poernomo, S.Kom, M.Kom?', '<p>Moyo Hady Poernomo, S.Kom, M.Kom merupakan dosen tetap Program Studi Software Engineering di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Rekayasa Perangkat Lunak, Basisdata, Teknologi Informasi, dan Media Digital. Pendidikan S1 ditempuh di STIKI Malang dan S2 di STMIK Amikom. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:moyo@upitra.ac.id\">moyo@upitra.ac.id</a></p>', '[\"Moyo Hady Poernomo\",\"Moyo\",\"Pak Moyo\",\"Moyo Hady Poernomo S.Kom M.Kom\"]', 'Aktif', 0, 0, '2026-05-27 19:59:36', '2026-05-28 23:24:58'),
(160, 'Program Studi', 'FST,Software Engineering', 'Siapa Aldian Umbu Tamu Ama, S.Si, M.Cs?', '<p>Aldian Umbu Tamu Ama, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Si\">S.Si</a>, M.Cs merupakan dosen tetap Program Studi Software Engineering di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Information System, Computer Vision, Object Detection, dan Machine Learning. Pendidikan S1 dan S2 ditempuh di Universitas Kristen Satya Wacana. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:aldianumbu@upitra.ac.id\">aldianumbu@upitra.ac.id</a></p>', '[\"Aldian Umbu Tamu Ama\",\"Aldian\",\"Pak Aldian\",\"Aldian Umbu Tamu Ama S.Si M.Cs\"]', 'Aktif', 0, 0, '2026-05-27 20:01:29', '2026-05-28 23:25:07'),
(161, 'Program Studi', 'FST,Software Engineering', 'Siapa Said Hirzi Hadi, S.Kom, M.Eng?', '<p>Said Hirzi Hadi, S.Kom, M.Eng merupakan dosen tetap Program Studi Software Engineering di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Virtual Reality, Augmented Reality, dan Game Development. Pendidikan S1 ditempuh di Universitas Islam Indonesia dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:hirzihadi@upitra.ac.id\">hirzihadi@upitra.ac.id</a></p>', '[\"Said Hirzi Hadi\",\"Hirzi Hadi\",\"Pak Hirzi\",\"Said Hirz\",\"Said Hirzi Hadi S.Kom M.Eng\",\"Dosen Game Development\",\"Dosen VR\",\"Dosen AR\"]', 'Aktif', 0, 0, '2026-05-27 20:04:31', '2026-05-28 23:25:13'),
(162, 'Program Studi', 'FST,Informatika,Software Engginering', 'Siapa Tutus Praningki, S.Kom, M.Kom?', '<p>Tutus Praningki, S.Kom, M.Kom merupakan dosen sekaligus Kaprodi Software Engineering di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Basisdata, Data Mining, dan Machine Learning. Pendidikan S1 ditempuh di Sekolah Tinggi Teknologi Cahaya Surya dan S2 di Universitas Amikom Yogyakarta. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:praningki@upitra.ac.id\">praningki@upitra.ac.id</a></p>', '[\"Tutus Praningki\",\"Tutus\",\"Pak Tutus\",\"Kaprodi Software Engineering\",\"Kaprodi SE\",\"Tutus Praningki S.Kom M.Kom\"]', 'Aktif', 0, 0, '2026-05-27 20:06:32', '2026-05-28 23:25:19');
INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(163, 'Program Studi', 'FST,Informatika', 'Siapa Endang Anggiratih, S.T., M.Cs?', '<p>Endang Anggiratih, S.T., M.Cs merupakan dosen sekaligus Kaprodi Informatika di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Deep Learning, Machine Learning, Data Mining, dan Big Data. Pendidikan S1 ditempuh di Universitas Pembangunan Nasional Veteran dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:endangratih@upitra.ac.id\">endangratih@upitra.ac.id</a></p>', '[\"Endang Anggiratih\",\"Ratih\",\"Bu Ratih\",\"Kaprodi Informatika\",\"Kaprodi Teknik Informatika\",\"Endang Anggiratih S.T. M.Cs\",\"ratih\",\"bu ratih\"]', 'Aktif', 0, 0, '2026-05-27 20:08:59', '2026-07-12 21:42:27'),
(164, 'Program Studi', 'FST,Informatika', 'Siapa Bagas Dwi Yulianto, S.Kom, M.Kom?', '<p>Bagas Dwi Yulianto, S.Kom, M.Kom merupakan dosen tetap Program Studi Informatika di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Cryptography, Data Hiding, Cyber Security, Artificial Intelligence, dan Green Computing. Pendidikan S1 dan S2 ditempuh di Universitas Dian Nuswantoro. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:bagas.yulianto@upitra.ac.id\">bagas.yulianto@upitra.ac.id</a></p>', '[\"Bagas Dwi Yulianto\",\"Bagas\",\"Pak Bagas\",\"Dwi Yulianto S.Kom M.Kom\",\"Kepala Laboratorium UPITRA\",\"Dosen Cyber Security\",\"bagas\"]', 'Aktif', 0, 0, '2026-05-27 20:11:24', '2026-06-09 19:11:10'),
(165, 'Program Studi', 'FST,Informatika', 'Siapa Very Dwi Setiawan, S.T., M.Sc?', '<p>Very Dwi Setiawan, S.T., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a> merupakan dosen tetap Program Studi Informatika di Fakultas Sains &amp; Teknologi UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Natural Language Processing, Machine Learning, dan Data Science. Pendidikan S1 ditempuh di Universitas Islam Negeri Sultan Syarif Kasim Riau dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:verydwisetiawan@upitra.ac.id\">verydwisetiawan@upitra.ac.id</a></p>', '[\"Very Dwi Setiawan\",\"Very\",\"Pak Very\",\"Very Dwi Setiawan S.T. M.Sc\",\"Dosen NLP\"]', 'Aktif', 0, 0, '2026-05-27 20:13:03', '2026-05-28 23:25:41'),
(166, 'Program Studi', 'FSH,Pariwisata', 'Siapa Oktavianus I Wayan Semuel, S.E., M.M?', '<p>Oktavianus I Wayan Semuel, S.E., M.M merupakan dosen sekaligus Kaprodi Pariwisata di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Perhotelan, Hospitality, dan Manajemen Bisnis Pariwisata. Pendidikan S1 ditempuh di Universitas Dhyana Pura dan S2 di Universitas Pendidikan Nasional. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:okta@upitra.ac.id\">okta@upitra.ac.id</a></p>', '[\"Oktavianus I Wayan Semuel\",\"Oktavianus\",\"Okta\",\"Pak Okta\",\"Kaprodi Pariwisata\",\"Oktavianus I Wayan Semuel S.E. M.M\",\"Dosen Manajemen Bisnis Pariwisata\"]', 'Aktif', 0, 0, '2026-05-27 20:19:05', '2026-05-28 23:25:51'),
(167, 'Program Studi', 'FSH,Pariwisata', 'Siapa Dr. RR. Erna Sadiarti Budiningtyas, S.Sos., M.Sc.?', '<p>Dr. RR. Erna Sadiarti Budiningtyas, S.Sos., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a> merupakan Dekan Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Cultural Heritage Tourism, Pariwisata Budaya, dan Ekowisata. Pendidikan S1, S2, dan S3 ditempuh di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:erna_budiningtyas@upitra.ac.id\">erna_budiningtyas@upitra.ac.id</a></p>', '[\"Erna Sadiarti Budiningtyas\",\"RR Erna Sadiarti Budiningtyas\",\"Dr Erna\",\"Bu Erna\",\"Dekan Fakultas Sosial dan Humaniora\",\"Dekan FSH\",\"Dr. RR. Erna Sadiarti Budiningtyas S.Sos. M.Sc\"]', 'Aktif', 0, 0, '2026-05-27 20:23:49', '2026-05-28 23:26:02'),
(168, 'Program Studi', 'FSH,Pariwisata', 'Siapa Wahyu Setiawan, S.M., M.Sc.?', '<p>Wahyu Setiawan, S.M., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a> merupakan dosen tetap Program Studi Pariwisata di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Perhotelan, Manajemen Bisnis Pariwisata, Revenue Management, dan Event Management. Pendidikan S1 ditempuh di Universitas Kristen Duta Wacana dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:wahyu_setiawan@upitra.ac.id\">wahyu_setiawan@upitra.ac.id</a></p>', '[\"Wahyu Setiawan\",\"Wahyu\",\"Pak Wahyu\",\"Wahyu Setiawan S.M. M.Sc\"]', 'Aktif', 0, 0, '2026-05-27 20:25:44', '2026-05-28 23:26:14'),
(169, 'Program Studi', 'FSH,Pariwisata', 'Siapa Albert Josua Putera Maliogha, S.Si.-Teol., MTS.?', '<p>Albert Josua Putera Maliogha, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Si\">S.Si</a>.-Teol., MTS merupakan dosen tetap Program Studi Pariwisata di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Anthropology of Religion dan Urban Religion Studies. Pendidikan S1 ditempuh di Universitas Kristen Satya Wacana dan S2 di Boston University. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:maliogha@upitra.ac.id\">maliogha@upitra.ac.id</a></p>', '[\"Albert Josua Putera Maliogha\",\"Albert Maliogha\",\"Maliogha\",\"Pak Albert\",\"Albert Josua Putera Maliogha S.Si.-Teol. MTS\",\"Anthropology of Religion\",\"Antropologi Agama\"]', 'Aktif', 0, 0, '2026-05-27 20:32:57', '2026-05-28 23:26:24'),
(170, 'Program Studi', 'FSH,Pariwisata', 'Siapa Fendy Kurniawan, S.Tr.Par., M.Par.?', '<p>Fendy Kurniawan, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Tr\">S.Tr</a>.Par., M.Par merupakan dosen tetap Program Studi Pariwisata di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki pengalaman lebih dari 12 tahun di industri hospitality, khususnya di bidang Food and Beverage. Beliau juga memiliki sertifikasi kompetensi Food and Beverage Product dan Food and Beverage Service serta berpengalaman dalam operasional pelayanan hospitality dan customer service. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:fendywawan@upitra.ac.id\">fendywawan@upitra.ac.id</a></p>', '[\"Fendy Kurniawan\",\"Fendy\",\"Pak Fendy\",\"Fendy Kurniawan S.Tr.Par. M.Par\"]', 'Aktif', 0, 0, '2026-05-27 20:37:16', '2026-05-28 23:26:34'),
(171, 'Program Studi', 'FEB,Akuntansi', 'Siapa Hirawresti Langen Apsari, S.E., M.Ak?', '<p>Hirawresti Langen Apsari, S.E., M.Ak merupakan dosen sekaligus Kaprodi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Forensik dan Akuntansi Keuangan. Pendidikan S1 ditempuh di Universitas Jember dan S2 di Universitas Diponegoro. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:hirawrestila@upitra.ac.id\">hirawrestila@upitra.ac.id</a></p>', '[\"Hirawresti Langen Apsari\",\"Hirawresti\",\"Bu Hira\",\"Kaprodi Akuntansi\",\"Hirawresti Langen Apsari S.E. M.Ak\",\"Forensic Accounting\"]', 'Aktif', 0, 0, '2026-05-27 20:40:34', '2026-05-28 23:26:40'),
(172, 'Program Studi', 'FEB,Akuntansi', 'Siapa Heru Suwasono, S.E., M.Sc?', '<p>Heru Suwasono, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a> merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Keuangan dan Audit Internal. Pendidikan S1 ditempuh di Sekolah Tinggi Ilmu Ekonomi Widya Wiwaha dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:herusuwasono@upitra.ac.id\">herusuwasono@upitra.ac.id</a></p>', '[\"Heru Suwasono\",\"Heru\",\"Pak Heru\",\"Heru Suwasono S.E. M.Sc\"]', 'Aktif', 0, 0, '2026-05-27 20:42:27', '2026-05-28 23:26:46'),
(173, 'Program Studi', 'FEB,Akuntansi', 'Siapa Vitalis Ari Widiyaningsih, S.E., M.Si?', '<p>Vitalis Ari Widiyaningsih, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a> merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Financial Accounting, Akuntansi Manajemen, dan Analisis Laporan Keuangan. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Sebelas Maret. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:vitalis_ari@upitra.ac.id\">vitalis_ari@upitra.ac.id</a></p>', '[\"Vitalis Ari Widiyaningsih\",\"Vitalis\",\"Bu Vitalis\",\"Vitalis Ari Widiyaningsih S.E. M.Si\"]', 'Aktif', 0, 0, '2026-05-27 20:50:38', '2026-05-28 23:26:51'),
(174, 'Program Studi', 'FEB,Akuntansi', 'Siapa Remon Gunanta, S.Pd, M.Si?', '<p>Remon Gunanta, S.Pd, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a> merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Accounting dan Sistem Informasi Akuntansi. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Sekolah Tinggi Ilmu Ekonomi YKPN. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:remon@upitra.ac.id\">remon@upitra.ac.id</a></p>', '[\"Remon Gunanta\",\"Remon\",\"Pak Remon\",\"Remon Gunanta S.Pd M.Si\"]', 'Aktif', 0, 0, '2026-05-27 20:52:29', '2026-05-28 23:26:57'),
(175, 'Program Studi', 'FEB,Akuntansi', 'Siapa Gisilowati Dian Purnamasari, S.E., M.Si?', '<p>Gisilowati Dian Purnamasari, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a> merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Forensik, Audit Internal, dan Corporate Governance. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Diponegoro. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:gisil@upitra.ac.id\">gisil@upitra.ac.id</a></p>', '[\"Gisilowati Dian Purnamasari\",\"Gisilowati\",\"Bu Gisilowati\",\"Bu Gisil\",\"Gisilowati Dian Purnamasari S.E. M.Si\"]', 'Aktif', 0, 0, '2026-05-27 20:54:47', '2026-05-28 23:27:07'),
(176, 'Program Studi', 'FEB,Akuntansi', 'Siapa Dr. Ir. Dwi Poetra Sedjati, M.M.?', '<p>Dr. Ir. Dwi Poetra Sedjati, M.M merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Strategik dan Akuntansi Manajemen. Pendidikan S1 ditempuh di Universitas Brawijaya, S2 di Institut Keuangan-Perbankan dan Informatika Asia Perbanas, serta S3 di Universitas Trisakti. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:dwi_poetra@upitra.ac.id\">dwi_poetra@upitra.ac.id</a></p>', '[\"Dwi Poetra Sedjati\",\"Dr Dwi Poetra\",\"Pak Dwi\",\"Dr. Ir. Dwi Poetra Sedjati M.M\",\"Strategic Management\"]', 'Aktif', 0, 0, '2026-05-27 20:56:50', '2026-05-28 23:27:13'),
(177, 'Program Studi', 'FEB,Akuntansi', 'Siapa Titik Dwiyani, S.E., M.M.?', '<p>Titik Dwiyani, S.E., M.M merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Keuangan, Akuntansi Manajemen, dan Analisis Laporan Keuangan. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Sekolah Tinggi Ilmu Ekonomi Adi Unggul Bhirawa. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:titik_dwiyani@upitra.ac.id\">titik_dwiyani@upitra.ac.id</a></p>', '[\"Titik Dwiyani\",\"Bu Titik\",\"Titik Dwiyani S.E. M.M\",\"Titik\"]', 'Aktif', 0, 0, '2026-05-27 20:58:31', '2026-05-28 23:27:19'),
(178, 'Program Studi', 'FEB,Akuntansi', 'Siapa Dewi Kartikasari, S.E., M.M., M.Ak?', '<p>Dewi Kartikasari, S.E., M.M., M.Ak merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Keuangan, Akuntansi Manajemen, dan Sustainability Reporting. Pendidikan S1 ditempuh di Universitas Sanata Dharma, S2 Manajemen di STIE Adi Unggul Bhirawa, dan S2 Akuntansi di Universitas Muhammadiyah Surakarta. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:dewi_kartikasari@upitra.ac.id\">dewi_kartikasari@upitra.ac.id</a></p>', '[\"Dewi Kartikasari\",\"Dewi\",\"Bu Dewi\",\"Dewi Kartikasari S.E. M.M. M.Ak\"]', 'Aktif', 0, 0, '2026-05-27 21:08:34', '2026-05-28 23:27:25'),
(179, 'Program Studi', 'FEB,Akuntansi', 'Siapa Maria Rosa Kumala Dewi, S.E., M.Ak?', '<p>Maria Rosa Kumala Dewi, S.E., M.Ak merupakan dosen tetap Program Studi Akuntansi di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Akuntansi Keuangan, Sistem Informasi Akuntansi, dan Perpajakan. Pendidikan S1 dan S2 ditempuh di Sekolah Tinggi Ilmu Ekonomi YKPN. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:mariarosa@upitra.ac.id\">mariarosa@upitra.ac.id</a></p>', '[\"Maria Rosa Kumala Dewi\",\"Maria Rosa\",\"Bu Rosa\",\"Maria Rosa Kumala Dewi S.E. M.Ak\"]', 'Aktif', 0, 0, '2026-05-27 21:10:17', '2026-05-28 23:27:30'),
(182, 'Akademik', 'Maksimal sks', 'Berapa batas maksimal pengambilan SKS per semester?', '<p style=\"text-align: justify;\">Beban SKS maksimal yang dapat diambil mahasiswa program Sarjana (S1) UPITRA pada semester reguler adalah <strong>24 SKS</strong>, sedangkan untuk program Semester Pendek (SP) adalah maksimal <strong>9 SKS</strong>. Pengambilan jumlah SKS ini bergantung pada perolehan Indeks Prestasi Semester (IPS) Anda pada semester sebelumnya (misal: IPS &gt; 3.00 untuk mengambil 24 SKS).</p>', '[\"SKS semester reguler\",\"batas SKS maksimal\",\"beban studi maksimal\",\"SKS maksimal semester normal\"]', 'Aktif', 0, 0, '2026-05-28 18:23:30', '2026-06-24 20:12:59'),
(185, 'Akademik', 'Jadwal Kuliah', 'Bagaimana cara melihat jadwal kuliah?', '<p style=\"text-align: justify;\">Jadwal kuliah dapat dilihat secara real-time melalui <strong>Sistem Informasi Akademik (SIAKAD)</strong> resmi UPITRA.</p><p style=\"text-align: justify;\"><strong>Cara mengeceknya:</strong></p><ol><li><p style=\"text-align: justify;\">Buka portal mahasiswa di <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id/\">Portal Mahasiswa</a></p></li><li><p style=\"text-align: justify;\">Login menggunakan akun mahasiswa aktif Anda.</p></li><li><p style=\"text-align: justify;\">Pilih menu <strong>Jadwal Kuliah</strong> atau <strong>Aktivitas Akademik</strong> untuk melihat detail hari, jam, ruang kelas, dan mata kuliah.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"jadwal kuliah upitra\",\"portal akademik upitra\",\"sistem informasi akademik upitra\",\"jadwal kuliah\",\"cek jadwal\",\"lihat jadwal\",\"siakad upitra\",\"jadwal hari ini\",\"masuk jam berapa\",\"ruang kelas\",\"jadwal siakad\",\"jam kuliah\",\"jadwal reguler\",\"cek ruangan kuliah\",\"hari kuliah\"]', 'Aktif', 0, 0, '2026-05-28 18:24:22', '2026-06-24 20:13:10'),
(189, 'Akademik', 'Pindah Kelas', 'Apakah mahasiswa bisa pindah kelas di UPITRA?', '<p style=\"text-align: justify;\"><strong>Ya, mahasiswa dapat mengajukan perpindahan kelas</strong> dengan ketentuan sebagai berikut:</p><ul><li><p style=\"text-align: justify;\">🎓 <strong>Syarat:</strong> Masih dalam satu program studi (prodi) yang sama dan memenuhi ketentuan akademik.</p></li><li><p style=\"text-align: justify;\">📝 <strong>Prosedur:</strong> Mengajukan permohonan melalui persetujuan <strong>Dosen Pembimbing Akademik (PA)</strong> dan <strong>Ketua Prodi</strong>.</p></li><li><p style=\"text-align: justify;\">📊 <strong>Pertimbangan:</strong> Persetujuan bergantung pada kapasitas kuota kelas baru dan kesesuaian jadwal kuliah.</p></li></ul><p style=\"text-align: justify;\">Perubahan kelas yang disetujui akan langsung diperbarui secara otomatis di sistem akademik resmi (SIAKAD)</p>', '[\"pindah kelas kuliah\",\"ganti jadwal kelas\",\"pindah paralel\",\"pindah ruang kuliah\"]', 'Aktif', 0, 0, '2026-05-28 18:25:46', '2026-06-24 20:13:26'),
(190, 'Kemahasiswaan', 'Keaktifan', 'Bagaimana prosedur pengajuan surat aktif kuliah di UPITRA?', '<p>Pengajuan surat aktif kuliah di Universitas Pignatelli Triputra dilakukan melalui bagian administrasi akademik atau unit layanan kemahasiswaan sesuai prosedur yang berlaku. Mahasiswa mengajukan permohonan dengan melengkapi data identitas dan keperluan surat, kemudian diproses secara administratif oleh pihak kampus. Setelah diverifikasi, surat aktif kuliah akan diterbitkan secara resmi dan dapat digunakan untuk keperluan akademik maupun non-akademik seperti beasiswa atau administrasi eksternal.</p>', '[\"surat aktif kuliah upitra\",\"cara buat surat aktif kuliah\",\"pengajuan surat mahasiswa upitra\"]', 'Aktif', 0, 0, '2026-05-28 18:26:04', '2026-05-28 23:43:20'),
(192, 'Program Studi', 'Konsentrasi,Informatika', 'Apa saja konsentrasi atau peminatan di jurusan Informatika?', '<p>Program Studi <strong>S1 Informatika UPITRA</strong> memiliki tiga konsentrasi utama:</p><ul><li><p>🤖 Artificial Intelligence (AI)</p></li><li><p>💻 Application Programming</p></li><li><p>📊 Data Analytics</p></li></ul><p>Mahasiswa dapat memilih konsentrasi sesuai minat dan rencana karier di bidang teknologi informasi.</p>', '[\"konsentrasi informatika\",\"peminatan informatika\",\"konsentrasi s1 informatika\",\"peminatan s1 informatika\",\"bidang konsentrasi informatika\",\"spesialisasi informatika\",\"konsentrasi prodi informatika\",\"peminatan prodi informatika\",\"informatika ada peminatan apa saja\",\"informatika ada konsentrasi apa saja\",\"jurusan informatika fokusnya apa\",\"belajar apa di informatika\",\"pilihan peminatan informatika\",\"konsentrasi di informatika upitra\",\"peminatan informatika upitra\",\"informatika upitra ada apa saja\",\"jalur peminatan informatika\",\"bidang yang dipelajari informatika\",\"informatika ada ai tidak\",\"ada data analytics di informatika\",\"ada application programming di informatika\",\"peminatan ai\",\"peminatan data analytics\",\"peminatan programming\"]', 'Aktif', 0, 0, '2026-05-28 18:26:48', '2026-06-04 20:25:59'),
