(242, 'Program Studi', 'FSH,Bahasa Inggirs', 'Siapa Tan Michael Chandra, S.S., M.Hum.?', '<p>Tan Michael Chandra, S.S., M.Hum merupakan dosen sekaligus Kaprodi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang English Literature and Culture, Pop Culture, dan English Test Preparation. Pendidikan S1 dan S2 ditempuh di Universitas Sanata Dharma. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:michael.chandra@upitra.ac.id\">michael.chandra@upitra.ac.id</a></p>', '[\"Tan Michael Chandra\",\"Michael Chandra\",\"Michael\",\"Pak Michael\",\"Kaprodi Bahasa Inggris\",\"Tan Michael Chandra S.S. M.Hum\",\"Dosen English Test Preparation\",\"siapa sih nama ketua prodi S1 Bahasa Inggris\"]', 'Aktif', 0, 0, '2026-05-28 20:22:04', '2026-06-01 20:23:06'),
(243, 'Program Studi', 'FSH,Bahasa Inggris', 'Siapa Yulia Milka Nugraheni, S.S., M.A.?', '<p>Yulia Milka Nugraheni, S.S., M.A merupakan dosen tetap Program Studi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Applied Linguistics dan Translation. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Gadjah Mada. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:yuliamilka@upitra.ac.id\">yuliamilka@upitra.ac.id</a></p>', '[\"Yulia Milka Nugraheni\",\"Yulia Milka\",\"Bu Yulia\",\"Yulia Milka Nugraheni S.S. M.A\"]', 'Aktif', 0, 0, '2026-05-28 20:23:53', '2026-06-01 20:23:14'),
(244, 'Program Studi', 'FSH,Bahasa Inggris', 'Siapa Vinsensius Galuh Kusuma, S.Pd., M.Pd.?', '<p>Vinsensius Galuh Kusuma, S.Pd., M.Pd merupakan dosen tetap Program Studi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Technological Pedagogical and Content Knowledge (TPACK), Information and Communication Technology (ICT), dan Computer-Assisted Language Learning (CALL). Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Negeri Yogyakarta. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:vinsensiusgaluhkusuma@upitra.ac.id\">vinsensiusgaluhkusuma@upitra.ac.id</a></p>', '[\"Vinsensius Galuh Kusuma\",\"Galuh Kusuma\",\"Pak Galuh\",\"Vinsensius Galuh Kusuma S.Pd. M.Pd\"]', 'Aktif', 0, 0, '2026-05-28 20:25:44', '2026-06-01 20:23:27'),
(245, 'Program Studi', 'FSH,Bahasa Inggris', 'Siapa Sangaji Yudhi Pratama, S.Pd., M.Pd.?', '<p>Sangaji Yudhi Pratama, S.Pd., M.Pd merupakan dosen tetap Program Studi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang TEFL, Applied Linguistic, dan Technology-Enhanced Learning. Pendidikan S1 ditempuh di Universitas Sultan Ageng Tirtayasa dan S2 di Universitas Sebelas Maret. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:sangajiyudhi10@gmail.com\">sangajiyudhi10@gmail.com</a></p>', '[\"Sangaji Yudhi Pratama\",\"Sangaji\",\"Yudhi Pratama\",\"Pak Yudhi\",\"Sangaji Yudhi Pratama S.Pd. M.Pd\"]', 'Aktif', 0, 0, '2026-05-28 20:27:40', '2026-06-01 20:23:39'),
(246, 'Program Studi', 'FSH,Bahasa Inggris', 'Siapa Nanda Pambudi, S.Pd., M.Pd.?', '<p>Nanda Pambudi, S.Pd., M.Pd merupakan dosen tetap Program Studi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang English for Specific Purposes (ESP) dan TESOL. Pendidikan S1 ditempuh di Universitas Islam Negeri Walisongo Semarang, S2 di Universitas Negeri Yogyakarta, dan S3 di Universiti Pendidikan Sultan Idris Malaysia. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:nanda_pambudi@upitra.ac.id\">nanda_pambudi@upitra.ac.id</a></p>', '[\"Nanda Pambudi\",\"Nanda\",\"Pak Nanda\",\"Nanda Pambudi S.Pd. M.Pd\"]', 'Aktif', 0, 0, '2026-05-28 20:29:21', '2026-06-01 20:23:47'),
(247, 'Program Studi', 'FSH,Bahasa Inggris', 'Siapa Fitria Yuliani, S.Pd., M.Pd.?', '<p>Fitria Yuliani, S.Pd., M.Pd merupakan dosen tetap Program Studi Bahasa Inggris di Fakultas Sosial &amp; Humaniora UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Applied Linguistics. Pendidikan S1 ditempuh di Universitas Terbuka dan S2 di bidang Pendidikan Bahasa Inggris. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:fitria_yuliani@upitra.ac.id\">fitria_yuliani@upitra.ac.id</a></p>', '[\"Fitria Yuliani\",\"Fitria\",\"Bu Fitria\",\"Fitria Yuliani S.Pd. M.Pd\"]', 'Aktif', 0, 0, '2026-05-28 20:30:53', '2026-06-01 20:23:56'),
(248, 'Program Studi', 'FEB,Manajemen', 'Siapa Agustinus Kismet N. J., S.E., MBA?', '<p>Agustinus Kismet N. J., S.E., MBA merupakan dosen sekaligus Kaprodi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Strategi Bisnis, Manajemen Operasional, dan Manajemen Keuangan. Pendidikan S1 ditempuh di Sekolah Tinggi Ilmu Ekonomi Kesatuan dan S2 di Universitas Gadjah Mada pada bidang Business Administration. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:kismet@upitra.ac.id\">kismet@upitra.ac.id</a></p>', '[\"Agustinus Kismet\",\"Kismet\",\"Pak Kismet\",\"Kaprodi Manajemen\",\"Agustinus Kismet N. J. S.E. MBA\"]', 'Aktif', 0, 0, '2026-05-28 20:48:21', '2026-06-01 20:24:06'),
(250, 'Program Studi', 'FEB,Manajemen', 'Siapa Dr. Alfa Santoso B. P., S.E., M.M.?', '<p>Dr. Alfa Santoso B. P., S.E., M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen, Manajemen SDM, Organizational Behavior, dan Leadership. Pendidikan S1 ditempuh di Universitas Kristen Duta Wacana, S2 di Universitas Atma Jaya Yogyakarta, dan S3 di Universitas Kristen Satya Wacana. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:alfasbp@upitra.ac.id\">alfasbp@upitra.ac.id </a></p>', '[\"Alfa Santoso\",\"Dr Alfa Santoso\",\"Pak Alfa\",\"Dr. Alfa Santoso B. P. S.E. M.M\"]', 'Aktif', 0, 0, '2026-05-28 20:52:12', '2026-06-01 20:24:14'),
(251, 'Program Studi', 'FEB,Manajemen', 'Siapa Dr. Endang Purwaningsih, S.E., M.M.?', '<p>Dr. Endang Purwaningsih, S.E., M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Pemasaran, Manajemen Keuangan, dan Investasi. Pendidikan S1 ditempuh di STIE Jaya Negara, S2 di Universitas Atma Jaya Yogyakarta, dan S3 di STIE Indonesia pada bidang Ilmu Manajemen. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:endang_purwaningsih@upitra.ac.id\">endang_purwaningsih@upitra.ac.id</a></p>', '[\"Endang Purwaningsih\",\"Dr Endang Purwaningsih\",\"Bu Endang\",\"Dr. Endang Purwaningsih S.E. M.M\"]', 'Aktif', 0, 0, '2026-05-28 20:53:39', '2026-06-01 20:24:21'),
(252, 'Program Studi', 'FEB,Manajemen', 'Siapa Tjong Budisantoso, S.E., MBA, Ph.D?', '<p>Tjong Budisantoso, S.E., MBA, Ph.D merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Branding, Retailing, dan Marketing. Pendidikan S1 ditempuh di Universitas Atma Jaya Yogyakarta, S2 di Monash University, dan S3 di The University of Notre Dame Australia. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:tjong@upitra.ac.id\">tjong@upitra.ac.id</a></p>', '[\"Tjong Budisantoso\",\"Pak Tjong\",\"Tjong Budisantoso S.E. MBA Ph.D\"]', 'Aktif', 0, 0, '2026-05-28 20:55:11', '2026-06-01 20:24:31'),
(253, 'Program Studi', 'FEB,Manajemen', 'Siapa Margareta Ernanda Rahardani, S.M., M.M.?', '<p>Margareta Ernanda Rahardani, S.M., M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Pemasaran dan Perilaku Konsumen. Pendidikan S1 dan S2 ditempuh di Universitas Katolik Soegijapranata.  <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:reta.ernanda@upitra.ac.id\">reta.ernanda@upitra.ac.id</a></p>', '[\"Margareta Ernanda Rahardani\",\"Margareta\",\"Ernanda Rahardani\",\"Bu Reta\",\"Margareta Ernanda Rahardani S.M. M.M\"]', 'Aktif', 0, 0, '2026-05-28 20:57:05', '2026-06-01 20:24:40'),
(254, 'Program Studi', 'FEB,Manajemen', 'Siapa Yenni Maria Sridarta, S.E., M.M.?', '<p>Yenni Maria Sridarta, S.E., M.M merupakan dosen tetap Program Studi Manajemen sekaligus Dekan Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Keuangan, Manajemen Operasional, dan Manajemen SDM. Pendidikan S1 ditempuh di Universitas Sanata Dharma dan S2 di Universitas Atma Jaya Yogyakarta. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:yenni_maria@upitra.ac.id\">yenni_maria@upitra.ac.id</a></p>', '[\"Yenni Maria Sridarta\",\"Yenni Maria\",\"Bu Yenni\",\"Dekan FEB\",\"Dekan Fakultas Ekonomi dan Bisnis\",\"Yenni Maria Sridarta S.E. M.M\"]', 'Aktif', 0, 0, '2026-05-28 21:00:18', '2026-06-01 20:24:47'),
(255, 'Program Studi', 'FEB,Manajemen', 'Siapa Vincentia Indah Puspita Sari, S.E., M.M.?', '<p>Vincentia Indah Puspita Sari, S.E., M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Pemasaran, Perilaku Konsumen, dan Strategi Bisnis. Pendidikan S1 dan S2 ditempuh di Sekolah Tinggi Ilmu Ekonomi YKPN. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:vincentia_indah@upitra.ac.id\">vincentia_indah@upitra.ac.id </a></p>', '[\"Vincentia Indah Puspita Sari\",\"Vincentia\",\"Indah Puspita\",\"Bu Vincentia\",\"Vincentia Indah Puspita Sari S.E. M.M\"]', 'Aktif', 0, 0, '2026-05-28 21:02:08', '2026-06-01 20:24:54'),
(256, 'Program Studi', 'FEB,Manajemen', 'Siapa Yusup Hari Subagya, S.E., M.M.?', '<p>Yusup Hari Subagya, S.E., M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Keuangan dan Kewirausahaan. Pendidikan S1 ditempuh di STIE Atma Bhakti dan S2 di Universitas Slamet Riyadi. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:yusup@upitra.ac.id\">yusup@upitra.ac.id</a></p>', '[\"Yusup Hari Subagya\",\"Yusup Hari Subagya S.E. M.M.\",\"profil Yusup Hari Subagya\",\"biodata Yusup Hari Subagya\",\"dosen Yusup Hari Subagya\",\"informasi Yusup Hari Subagya\",\"data dosen Yusup Hari Subagya\",\"profil dosen Yusup Hari Subagya\",\"Yusup Hari Subagya UPITRA\",\"dosen manajemen Yusup Hari Subagya\",\"siapa Yusup Hari Subagya\",\"siapa pak Yusup Hari Subagya\",\"siapa bapak Yusup Hari Subagya\",\"Yusup Hari Subagya itu siapa\",\"Yusup Hari Subagya dosen apa\",\"pak Yusup mengajar di prodi apa\",\"Yusup Hari Subagya mengajar apa\",\"Yusup Hari Subagya dari fakultas apa\",\"profil pak Yusup\",\"informasi pak Yusup\",\"biodata pak Yusup Hari Subagya\",\"dosen Yusup Hari Subagya siapa\",\"pak Yusup di manajemen ya\",\"Yusup Hari Subagya mengajar di mana\"]', 'Aktif', 0, 0, '2026-05-28 21:03:24', '2026-06-08 02:00:47'),
(257, 'Program Studi', 'FEB,Manajemen', 'Siapa Dra. Margaretha Prihatiningsih, M.M.?', '<p>Dra. Margaretha Prihatiningsih, M.M merupakan dosen tetap Program Studi Manajemen di Fakultas Ekonomi &amp; Bisnis UPITRA (Universitas Pignatelli Triputra). Beliau memiliki keahlian di bidang Manajemen Keuangan, Manajemen SDM, dan Manajemen Pemasaran. Pendidikan S1 ditempuh di Universitas Surakarta dan S2 di Universitas Sebelas Maret. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:margareta_pri@upitra.ac.id\">margareta_pri@upitra.ac.id</a></p>', '[\"Dra. Margaretha Prihatiningsih\",\"Margaretha Prihatiningsih\",\"Dra. Margaretha Prihatiningsih M.M.\",\"Margaretha Prihatiningsih M.M.\",\"profil Margaretha Prihatiningsih\",\"biodata Margaretha Prihatiningsih\",\"dosen Margaretha Prihatiningsih\",\"informasi Margaretha Prihatiningsih\",\"data dosen Margaretha Prihatiningsih\",\"Margaretha Prihatiningsih UPITRA\",\"dosen manajemen Margaretha Prihatiningsih\",\"siapa Margaretha Prihatiningsih\",\"siapa Dra. Margaretha Prihatiningsih\",\"siapa ibu Margaretha Prihatiningsih\",\"Margaretha Prihatiningsih itu siapa\",\"Bu Margaretha dosen apa\",\"Margaretha Prihatiningsih mengajar apa\",\"Margaretha Prihatiningsih dari fakultas apa\",\"profil Bu Margaretha\",\"informasi Bu Margaretha\",\"dosen Margaretha Prihatiningsih siapa\",\"Bu Margaretha mengajar di prodi apa\",\"Margaretha Prihatiningsih mengajar di mana\"]', 'Aktif', 0, 0, '2026-05-28 21:04:53', '2026-06-08 02:04:40'),
(258, 'Profil Universitas', 'Pimpinan', 'Siapa Wakil Rektor Bidang Sumber Daya dan Keuangan UPITRA?', '<p>Johannes Christianto Hartono, S.Pd merupakan Wakil Rektor II UPITRA (Universitas Pignatelli Triputra) yang membidangi Sumber Daya dan Keuangan. Beliau berperan dalam pengelolaan administrasi, sumber daya manusia, keuangan, serta pengembangan tata kelola institusi di lingkungan UPITRA. Informasi jabatan beliau tercantum dalam struktur pimpinan Universitas Pignatelli Triputra. </p>', '[\"Johannes Christianto Hartono\",\"Johannes Hartono\",\"Pak Johannes\",\"Wakil Rektor 2\",\"WR 2 UPITRA\",\"Wakil Rektor Bidang Sumber Daya dan Keuangan\",\"Pimpinan UPITRA\",\"Johannes Christianto Hartono S.Pd\",\"wr2\",\"wr 2\",\"wakil rektor 2\",\"WR2\",\"WR 2\",\"siapa pak chris\"]', 'Aktif', 0, 0, '2026-05-28 21:14:55', '2026-06-03 18:57:04'),
(259, 'Profil Universitas', 'Pimpinan', 'Siapa Wakil Rektor Bidang Kemahasiswaan dan Kerjasama UPITRA ?', '<p>Thomas Ambar Prihastomo, S.S., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a> merupakan Wakil Rektor III Bidang Kemahasiswaan dan Kerjasama UPITRA (Universitas Pignatelli Triputra). Beliau berperan dalam pengembangan kegiatan kemahasiswaan, kerja sama institusi, promosi kampus, dan penguatan relasi dengan dunia industri maupun sekolah mitra. Selain menjabat sebagai pimpinan universitas, beliau juga aktif dalam berbagai kegiatan akademik dan pengembangan karakter mahasiswa di lingkungan UPITRA. </p>', '[\"Thomas Ambar Prihastomo\",\"Thomas Ambar\",\"Pak Thomas\",\"Wakil Rektor 3\",\"WR 3 UPITRA\",\"Wakil Rektor Bidang Kemahasiswaan dan Kerjasama\",\"Wakil Rektor III UPITRA\",\"Thomas Ambar Prihastomo S.S. M.Sc\",\"wr3\",\"wr 3\",\"wakil rektor 3\",\"WR3\",\"WR 3\"]', 'Aktif', 0, 0, '2026-05-28 21:18:04', '2026-06-03 18:57:28'),
(260, 'Profil Universitas', 'Informasi', 'Apa itu Universitas Pignatelli Triputra?', '<p>Universitas Pignatelli Triputra (UPITRA) adalah universitas swasta di Surakarta yang berfokus pada pendidikan berbasis “Link and Match” dengan dunia industri. UPITRA memiliki berbagai program studi unggulan dan berkomitmen mencetak lulusan yang kompeten, inovatif, berintegritas, dan siap kerja di tingkat global.</p>', '[\"apa itu UPITRA\",\"Universitas Pignatelli Triputra\",\"tentang UPITRA\",\"kampus UPITRA\",\"universitas swasta Surakarta\",\"link and match UPITRA\",\"kampus industri UPITRA\"]', 'Aktif', 0, 0, '2026-05-28 21:30:51', '2026-05-28 22:53:57'),
(261, 'Profil Universitas', 'Pendiri', 'Siapa pendiri Universitas Pignatelli Triputra?', '<p>Universitas Pignatelli Triputra (UPITRA) didirikan dan dikelola oleh Yayasan Santo Yosef Maria Pignatelli Surakarta, dengan dukungan dan kolaborasi dari Triputra Group dalam pengembangan pendidikan dan koneksi industri.</p>', '[\"pendiri UPITRA\",\"founder Universitas Pignatelli Triputra\",\"yayasan UPITRA\",\"sejarah UPITRA\",\"Yayasan Pignatelli Surakarta\"]', 'Aktif', 0, 0, '2026-05-28 21:31:09', '2026-05-28 22:52:11'),
(263, 'Profil Universitas', 'Informasi', 'Apa saja fakultas di UPITRA?', '<p>Universitas Pignatelli Triputra (UPITRA) memiliki beberapa fakultas, yaitu Fakultas Sains &amp; Teknologi, Fakultas Ekonomika &amp; Bisnis, Fakultas Sosial &amp; Humaniora, dan Fakultas Kesehatan. Setiap fakultas memiliki program studi yang dirancang sesuai kebutuhan industri dan perkembangan global.</p>', '[\"fakultas UPITRA\",\"fakultas di Universitas Pignatelli Triputra\"]', 'Aktif', 0, 0, '2026-05-28 21:31:38', '2026-05-28 22:55:50'),
(265, 'Profil Universitas', 'Umum', 'Apa keunggulan UPITRA?', '<p>UPITRA memiliki berbagai keunggulan, antara lain:</p><p>• Kurikulum yang relevan dengan kebutuhan industri</p><p>• Immersion Program sebagai pengalaman belajar langsung</p><p>• Dukungan teknologi pembelajaran modern</p><p>• Jaringan kerja sama dengan berbagai mitra industri</p><p>• Fokus pada pengembangan karakter, kepemimpinan, dan kompetensi profesional</p>', '[\"keunggulan upitra\",\"kelebihan upitra\",\"mengapa memilih upitra\",\"alasan memilih upitra\"]', 'Aktif', 0, 0, '2026-05-28 21:32:08', '2026-06-02 02:12:04'),
(267, 'Profil Universitas', 'Umum', 'Apakah UPITRA terhubung dengan Triputra Group?', '<p>UPITRA merupakan bagian dari ekosistem pendidikan yang didukung oleh Triputra. Keterhubungan ini memperkuat kolaborasi dengan dunia industri serta mendukung pengembangan pengalaman belajar yang relevan dengan kebutuhan profesional.</p>', '[\"hubungan triputra\",\"upitra dan triputra\",\"pemilik upitra\"]', 'Aktif', 0, 0, '2026-05-28 21:32:31', '2026-06-02 02:14:23'),
(272, 'Profil Universitas', 'Umum', 'Apa yang membedakan UPITRA dengan kampus lain?', '<p>UPITRA mengintegrasikan pendidikan akademik, pengalaman industri melalui Immersion Program, pengembangan karakter, serta dukungan ekosistem Triputra untuk mempersiapkan lulusan yang siap menghadapi dunia profesional dan perubahan global.</p>', '[\"beda upitra\",\"keunikan upitra\",\"ciri khas upitra\",\"apa yang membedakan upitra\"]', 'Aktif', 0, 0, '2026-05-28 21:33:43', '2026-06-02 02:13:35');
INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(274, 'Program Studi', 'Informasi', 'Apa saja program studi yang tersedia di kampus ini?', '<p>UPITRA memiliki berbagai program studi yang terbagi dalam beberapa fakultas, yaitu:</p><ol><li><p>Fakultas Sains &amp; Teknologi<br>(Informatika, Sistem Informasi, Software Engineering)</p></li><li><p>Fakultas Ekonomika &amp; Bisnis<br>(Akuntansi, Manajemen)</p></li><li><p>Fakultas Sosial &amp; Humaniora<br>(Pariwisata, Bahasa Inggris)</p></li><li><p>Fakultas Kesehatan<br>(Fisioterapi, Keselamatan dan Kesehatan Kerja/K3)</p></li></ol><p></p>', '[\"program studi UPITRA\",\"prodi UPITRA\",\"jurusan UPITRA\"]', 'Aktif', 0, 0, '2026-05-28 23:07:28', '2026-05-28 23:07:28'),
(276, 'Immersion Program', 'Umum', 'Apa saja kegiatan dalam Immersion Program UPITRA?', '<p>Kegiatan Immersion Program dapat mencakup magang industri, proyek profesional, observasi lapangan, pelatihan, studi kasus, kolaborasi dengan mitra industri, hingga pengembangan kompetensi sesuai bidang studi mahasiswa.</p>', '[\"kegiatan immersion upitra\",\"aktivitas immersion program\",\"project based learning upitra\",\"kegiatan immersion\",\"aktivitas immersion\",\"isi program immersion\",\"apa yang dilakukan saat immersion\"]', 'Aktif', 0, 0, '2026-05-28 23:56:48', '2026-06-01 23:56:16'),
(277, 'Immersion Program', 'Umum', 'Apakah Immersion Program UPITRA dilakukan di luar negeri?', '<p>UPITRA memiliki peluang kerja sama dengan berbagai mitra, termasuk program yang dapat memberikan pengalaman internasional sesuai ketersediaan dan ketentuan yang berlaku.</p>', '[\"immersion luar negeri upitra\",\"program internasional upitra\",\"magang luar negeri upitra\",\"immersion luar negeri\",\"international immersion\",\"overseas immersion\",\"program luar negeri\"]', 'Aktif', 0, 0, '2026-05-28 23:57:52', '2026-06-02 00:02:49'),
(278, 'Immersion Program', 'Umum', 'Berapa lama durasi Immersion Program UPITRA?', '<p>Durasi Immersion Program dapat berbeda sesuai program dan mitra yang terlibat. Informasi pelaksanaan akan diinformasikan kepada mahasiswa sesuai ketentuan akademik yang berlaku.</p>', '[\"durasi immersion upitra\",\"lama immersion program\",\"durasi immersion\",\"berapa lama immersion\",\"jangka waktu immersion\",\"lama program immersion\"]', 'Aktif', 0, 0, '2026-05-28 23:58:53', '2026-06-01 23:55:26'),
(279, 'Immersion Program', 'Umum', 'Apakah peserta mendapatkan sertifikat pada Immersion Program UPITRA?', '<p>Peserta Immersion Program dapat memperoleh sertifikat atau dokumen pengakuan sesuai jenis kegiatan dan ketentuan dari penyelenggara maupun mitra program.</p>', '[\"sertifikat immersion upitra\",\"sertifikat magang upitra\",\"bukti kelulusan immersion program\",\"sertifikat immersion\",\"certificate immersion\",\"bukti ikut immersion\"]', 'Aktif', 0, 0, '2026-05-29 00:00:03', '2026-06-01 23:59:05'),
(280, 'Immersion Program', 'Umum', 'Apakah ada biaya mengikuti Immersion Program UPITRA?', '<p>Immersion Program UPITRA umumnya merupakan bagian dari implementasi kurikulum 3+1, sehingga tidak diperlakukan sebagai program tambahan berbayar terpisah. Namun, ketentuan biaya dapat mengikuti kebijakan akademik universitas dan program studi, terutama jika terdapat kebutuhan khusus terkait penempatan, mobilitas, atau aktivitas tertentu selama program berlangsung. Untuk informasi yang paling akurat, mahasiswa disarankan merujuk pada pengumuman resmi dari program studi atau unit terkait sebelum pelaksanaan.</p>', '[\"biaya immersion upitra\",\"gratis immersion program upitra\",\"biaya magang upitra\"]', 'Aktif', 0, 0, '2026-05-29 00:01:32', '2026-05-29 01:52:04'),
(282, 'Immersion Program', 'Umum', 'Apakah ada pendampingan selama Immersion Program UPITRA berlangsung?', '<p>Mahasiswa akan mendapatkan pendampingan sesuai mekanisme program, baik dari dosen pembimbing maupun pihak mitra tempat pelaksanaan Immersion Program.</p>', '[\"pendampingan immersion upitra\",\"mentor industri upitra\",\"bimbingan magang upitra\",\"monitoring mahasiswa immersion\",\"mentor immersion\",\"pembimbing immersion\",\"dosen pembimbing immersion\",\"pendamping immersion\"]', 'Aktif', 0, 0, '2026-05-29 00:03:58', '2026-06-02 00:03:43'),
(283, 'Immersion Program', 'Umum', 'Apakah mahasiswa mendapatkan konversi SKS dari Immersion Program UPITRA?', '<p>Ya. Aktivitas Immersion Program dapat dikonversi menjadi SKS sesuai kebijakan akademik dan capaian pembelajaran yang ditetapkan oleh program studi.</p>', '[\"konversi sks immersion upitra\",\"credit transfer immersion program\",\"konversi sks\",\"sks immersion\",\"nilai immersion\",\"pengakuan sks\"]', 'Aktif', 0, 0, '2026-05-29 00:06:09', '2026-06-01 23:57:12'),
(286, 'Lainnya', 'TEN', 'Apa itu Triputra Edukasi Nusantara?', '<p>Triputra Edukasi Nusantara (TEN) adalah entitas yang berfokus pada pengembangan ekosistem pendidikan yang terintegrasi dengan kebutuhan industri di lingkungan Triputra Group. TEN berperan dalam membangun sinergi antara dunia pendidikan tinggi dan dunia kerja melalui penguatan kurikulum berbasis kompetensi, program pengembangan talenta, serta kolaborasi strategis dengan institusi pendidikan.</p><p>Dalam implementasinya, Triputra Edukasi Nusantara mendorong terciptanya model pembelajaran yang relevan dengan kebutuhan industri, dengan tujuan meningkatkan kesiapan lulusan dalam menghadapi dinamika dunia kerja. Fokus utamanya mencakup pengembangan kompetensi, pengalaman berbasis praktik, serta penguatan karakter dan profesionalisme mahasiswa. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://triputraedu.com/\">https://triputraedu.com/</a></p>', '[\"Triputra Edukasi Nusantara\",\"Triputra Edukasi Nusantara TEN\",\"TEN\",\"pendidikan Triputra\",\"ekosistem pendidikan Triputra\",\"Triputra Group education\",\"TEN Indonesia\"]', 'Aktif', 0, 0, '2026-05-29 01:23:35', '2026-05-29 01:23:35'),
(287, 'Akademik', 'Sistem Perkuliahan', 'Sistem apa yang digunakan UPITRA dalam pembelajarannya ?', '<p style=\"text-align: justify;\">Ya, UPITRA menerapkan pendekatan <strong>Outcome-Based Education (OBE)</strong> dalam proses pembelajarannya. Sistem ini berfokus pada <strong>capaian pembelajaran (<em>learning outcomes</em>)</strong>, sehingga mahasiswa tidak hanya mendapatkan teori, tetapi juga kompetensi, keterampilan praktis, dan karakter yang selaras dengan kebutuhan industri global. Kurikulum ini dirancang khusus untuk mencetak lulusan yang siap kerja dan adaptif di dunia profesional.</p>', '[\"obe\",\"outcome based education\",\"kurikulum obe\",\"sistem kuliah\",\"metode pembelajaran\",\"sistem pembelajaran\",\"kurikulum upitra\",\"model belajar\",\"siap kerja\",\"capaian pembelajaran\",\"kompetensi lulusan\"]', 'Aktif', 0, 0, '2026-06-01 20:27:41', '2026-06-24 20:07:51'),
(288, 'Teknologi & Sistem', 'Unity', 'Apa itu UNITY?', '<p>UNITY adalah Learning Management System (LMS) UPITRA yang digunakan untuk mendukung pembelajaran digital. Melalui UNITY, mahasiswa dapat mengakses materi kuliah, tugas, diskusi kelas, kuis, dan berbagai aktivitas pembelajaran secara online.</p>', '[\"unity\",\"learning management system\",\"lms\",\"platform belajar\",\"apa itu unity\",\"lms upitra\",\"platform pembelajaran\"]', 'Aktif', 0, 0, '2026-06-01 20:29:04', '2026-06-02 01:01:48'),
(289, 'Akademik', 'KHS', 'Bagaimana cara mengunduh KHS?', '<h3 style=\"text-align: justify;\">Cara Mengunduh KHS Mahasiswa UPITRA</h3><ol><li><p style=\"text-align: justify;\"><strong>Akses Portal:</strong> Buka <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://mhs.upitra.ac.id\">Portal Akademik Mahasiswa</a><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id\">.</a></p></li><li><p style=\"text-align: justify;\"><strong>Login:</strong> Masuk menggunakan <strong>NIM</strong> dan <strong>password</strong> Anda.</p></li><li><p style=\"text-align: justify;\"><strong>Pilih Menu:</strong> Masuk ke menu <strong>KHS</strong> atau <strong>Hasil Studi</strong>, lalu pilih semester yang diinginkan.</p></li><li><p style=\"text-align: justify;\"><strong>Unduh:</strong> Klik tombol <strong>Unduh / Cetak / Download PDF</strong> untuk menyimpan file ke perangkat.</p></li></ol><p style=\"text-align: justify;\">💡 <strong>Butuh Bantuan?</strong> &gt; Jika mengalami kendala login atau akses, silakan hubungi bagian akademik/admisi melalui WhatsApp atau email</p><p style=\"text-align: justify;\">📞 <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://www.google.com/search?q=https://wa.me/628112907500\">0811-290-7500</a>  </p><p style=\"text-align: justify;\">📧 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:admission@upitra.ac.id\">admission@upitra.ac.id</a>.</p><p style=\"text-align: justify;\"></p>', '[\"KHS\",\"Kartu Hasil Studi\",\"Nilai Kuliah\",\"Nilai Semester\",\"Hasil Studi\",\"Download KHS\",\"Cetak KHS\",\"Lihat KHS\",\"Melihat Nilai\",\"Unduh Nilai\",\"Error login portal\",\"Portal mhs\",\"Link portal akademik\"]', 'Aktif', 0, 0, '2026-06-01 20:32:54', '2026-06-24 20:08:26'),
(290, 'Akademik', 'Lama studi', 'Berapa lama masa studi di UPITRA?', '<p style=\"text-align: justify;\">Masa studi program Sarjana (S1) di UPITRA normalnya adalah <strong>8 semester (sekitar 4 tahun)</strong>. Pembelajaran menggunakan kurikulum <strong>Outcome-Based Education (OBE)</strong> dengan konsep <strong>3+1</strong> (3 tahun belajar di kampus dan 1 tahun program pengalaman industri/luar kampus). Durasi kelulusan akhir tetap bergantung pada jumlah SKS yang diambil dan capaian akademik masing-masing mahasiswa.</p>', '[\"masa studi\",\"lama kuliah\",\"berapa tahun kuliah\",\"durasi kuliah\",\"waktu lulus\",\"masa pendidikan\",\"3+1\",\"program 3+1\",\"kuliah industri\",\"magang perkuliahan\",\"batas semester\",\"maksimal kuliah\",\"kapan lulus\",\"do upitra\"]', 'Aktif', 0, 0, '2026-06-01 20:35:21', '2026-06-24 20:08:35'),
(291, 'Akademik', 'Sistem Penilaian', 'Bagaimana sistem penilaian di UPITRA?', '<p style=\"text-align: justify;\">UPITRA menerapkan sistem penilaian berbasis <strong>Outcome-Based Education (OBE)</strong> yang berfokus pada pencapaian kompetensi dan capaian pembelajaran mahasiswa, bukan hanya nilai ujian.</p><p style=\"text-align: justify;\"><strong>Komponen penilaian meliputi:</strong></p><ul><li><p style=\"text-align: justify;\">📝 Tugas (individu/kelompok) &amp; partisipasi kelas</p></li><li><p style=\"text-align: justify;\">🎯 Kuis, presentasi, &amp; proyek pembelajaran</p></li><li><p style=\"text-align: justify;\">📚 Ujian Tengah Semester (UTS) &amp; Ujian Akhir Semester (UAS)</p></li><li><p style=\"text-align: justify;\">💼 Praktikum atau proyek berbasis industri (sesuai mata kuliah)</p></li></ul><p style=\"text-align: justify;\">Nilai akhir dapat dilihat secara transparan melalui <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://mhs.upitra.ac.id\">Portal Akademik Mahasiswa</a><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://mhs.upitra.ac.id\">.</a></p>', '[\"sistem penilaian\",\"penilaian mahasiswa\",\"komponen nilai\",\"bobot nilai\",\"uts uas\",\"tugas kuliah\",\"remidi\",\"lihat nilai\",\"cek nilai\",\"ipk\",\"ips\",\"transkrip nilai\"]', 'Aktif', 0, 0, '2026-06-01 20:36:42', '2026-06-24 20:08:45'),
(292, 'Akademik', 'Dosen Pembimbing', 'Apakah mahasiswa mendapatkan dosen pembimbing akademik?', '<p style=\"text-align: justify;\">Ya, setiap mahasiswa UPITRA akan mendapatkan <strong>Dosen Pembimbing Akademik (PA)</strong> yang mendampingi selama masa studi.</p><p style=\"text-align: justify;\"><strong>Peran utama Dosen PA meliputi:</strong></p><p style=\"text-align: justify;\">🎓 Mengarahkan perencanaan studi dan pengambilan mata kuliah.</p><p style=\"text-align: justify;\">📝 Membantu konsultasi akademik dan pengisian KRS/BRS.</p><p style=\"text-align: justify;\">📊 Memantau perkembangan nilai dan kehadiran mahasiswa.</p><p style=\"text-align: justify;\">💡 Memberikan solusi atas kendala akademik agar lulus tepat waktu.</p><p style=\"text-align: justify;\">Mahasiswa dapat berkomunikasi dengan dosen PA masing-masing sesuai mekanisme yang berlaku di program studi.</p><p style=\"text-align: justify;\"></p>', '[\"dosen PA\",\"pembimbing akademik\",\"dosen wali\",\"konsultasi KRS\",\"bimbingan akademik\",\"curhat kuliah\",\"masalah nilai\",\"tanya krs\",\"susah kuliah\",\"bimbingan krs\",\"dosen pa upitra\",\"pembimbing\",\"Dosen PA\",\"fungsi PA\",\"tugas PA\"]', 'Aktif', 0, 0, '2026-06-01 20:38:14', '2026-06-24 20:08:53'),
(293, 'Biaya Kuliah', 'Pendaftaran', 'Berapa biaya pendaftaran di UPITRA?', '<p style=\"text-align: justify;\">Biaya pendaftaran mahasiswa baru di UPITRA bervariasi bergantung pada jalur masuk dan gelombang pendaftaran yang dipilih.</p><p style=\"text-align: justify;\">Informasi lengkap mengenai nominal tarif dan tata cara pembayaran terbaru dapat diakses melalui portal resmi atau kontak admisi berikut:</p><ul><li><p style=\"text-align: justify;\">🌐 <strong>Portal PMB:</strong> <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.upitra.ac.id\">pmb.upitra.ac.id</a></p></li><li><p style=\"text-align: justify;\">📞 <strong>WhatsApp Admission:</strong> 0811-290-7500</p></li></ul><p style=\"text-align: justify;\"></p>', '[\"biaya pendaftaran\",\"uang pendaftaran\",\"daftar berapa\",\"registrasi pmb\",\"biaya formulir\",\"harga formulir\",\"biaya pmb\",\"bayar pendaftaran\",\"beli formulir\",\"biaya tes masuk\",\"tarif pendaftaran\"]', 'Aktif', 0, 0, '2026-06-01 20:43:13', '2026-06-24 20:15:51'),
(294, 'Biaya Kuliah', 'Cicilan pembayaran', 'Apakah biaya kuliah dapat dibayar secara cicilan?', '<p style=\"text-align: justify;\"><strong>Ya, UPITRA menyediakan skema pembayaran kuliah secara cicilan/bertahap</strong> yang dapat disesuaikan dengan ketentuan berlaku pada setiap periode penerimaan mahasiswa baru.</p><p style=\"text-align: justify;\">Untuk informasi lebih rinci mengenai prosedur, jumlah angsuran, atau skema pembayaran yang tersedia, silakan langsung menghubungi tim Admission UPITRA melalui:</p><ul><li><p style=\"text-align: justify;\">📞 <strong>WhatsApp Admission:</strong> 0811-290-7500</p></li></ul><p style=\"text-align: justify;\"></p>', '[\"cicilan kuliah\",\"angsuran kuliah\",\"bayar bertahap\",\"cicil spp\",\"pembayaran bertahap\",\"bayar kuliah per bulan\",\"bisa dicicil tidak\",\"keringan bayar\",\"skema cicilan\",\"tenggat cicilan\",\"Apakah pembayaran Uang Kuliah Tunggal (UKT) di UPITRA bisa dicicil, dan bagaimana prosedurnya?\"]', 'Aktif', 0, 0, '2026-06-01 20:44:27', '2026-06-24 20:15:58'),
(295, 'Biaya Kuliah', 'Potongan', 'Apakah tersedia potongan biaya kuliah?', '<p style=\"text-align: justify;\"><strong>Ya, UPITRA secara berkala menyediakan program beasiswa dan potongan biaya pendidikan</strong> sesuai dengan kebijakan yang berlaku.</p><p style=\"text-align: justify;\">Informasi terbaru mengenai syarat, jenis beasiswa, dan kuota potongan biaya dapat Anda lihat langsung melalui portal resmi PMB atau dengan menghubungi tim admisi kampuse resmi.</p>', '[\"diskon kuliah\",\"potongan biaya\",\"promo kuliah\",\"keringanan biaya\",\"pengurangan biaya\",\"beasiswa upitra\",\"potongan spp\",\"diskon pmb\",\"potongan pangkal\",\"beasiswa prestasi\"]', 'Aktif', 0, 0, '2026-06-01 20:45:30', '2026-06-24 20:16:05'),
(296, 'Fasilitas & Layanan', 'Laboratorium', 'Apakah UPITRA memiliki laboratorium?', '<p>Ya. UPITRA menyediakan laboratorium sesuai kebutuhan program studi untuk mendukung kegiatan praktikum, riset, dan pengembangan keterampilan mahasiswa.</p>', '[\"laboratorium\",\"lab komputer\",\"lab praktikum\",\"fasilitas lab\"]', 'Aktif', 0, 0, '2026-06-01 22:04:38', '2026-06-01 22:04:38'),
(297, 'Fasilitas & Layanan', 'Lahan Parkir', 'Apakah tersedia area parkir?', '<p>Ya, UPITRA menyediakan <strong>area parkir</strong> untuk mendukung kenyamanan mahasiswa, dosen, tenaga kependidikan, dan tamu kampus yang menggunakan kendaraan pribadi.</p><p>Area parkir tersedia untuk:</p><ul><li><p>🏍️ Sepeda motor</p></li><li><p>🚗 Mobil</p></li><li><p>👥 Tamu dan pengunjung kampus</p></li></ul><p>Fasilitas parkir dirancang untuk mendukung aktivitas perkuliahan dan kegiatan kampus sehari-hari sehingga civitas akademika dapat mengakses kampus dengan lebih nyaman.</p>', '[\"tempat parkir\",\"lahan parkir\",\"parkir motor\",\"parkir mobil\",\"parkir\"]', 'Aktif', 0, 0, '2026-06-01 22:06:42', '2026-06-01 22:06:42'),
(298, 'Fasilitas & Layanan', 'Organisasi Mahasiswa', 'Apakah tersedia ruang organisasi mahasiswa?', '<p>Ya, UPITRA menyediakan fasilitas yang mendukung kegiatan organisasi dan pengembangan mahasiswa, termasuk <strong>ruang atau area kegiatan kemahasiswaan</strong> yang dapat digunakan untuk koordinasi, diskusi, rapat, dan pelaksanaan program organisasi mahasiswa.</p><p>Fasilitas ini mendukung berbagai kegiatan kemahasiswaan, seperti:</p><ul><li><p>👥 Organisasi mahasiswa dan himpunan program studi</p></li><li><p>🎯 Unit Kegiatan Mahasiswa (UKM)</p></li><li><p>🤝 Kegiatan kepemimpinan dan pengembangan soft skills</p></li><li><p>📋 Rapat, diskusi, dan perencanaan program kerja</p></li></ul><p>UPITRA mendorong mahasiswa untuk aktif berorganisasi sebagai bagian dari pengembangan karakter, kepemimpinan, dan pengalaman di luar kegiatan akademik.</p>', '[\"sekretariat ukm\",\"ruang organisasi\",\"ruang mahasiswa\",\"fasilitasi organisasi\",\"ukm\"]', 'Aktif', 0, 0, '2026-06-01 22:08:09', '2026-06-01 22:08:09'),
(299, 'Fasilitas & Layanan', 'Layanan', 'Apakah UPITRA memiliki ruang kelas modern?', '<p>Ya, UPITRA menyediakan <strong>ruang kelas modern</strong> yang dirancang untuk mendukung proses pembelajaran yang nyaman, interaktif, dan efektif.</p><p>Ruang kelas dilengkapi dengan fasilitas penunjang pembelajaran yang mendukung kegiatan akademik, seperti:</p><ul><li><p>🎓 Lingkungan belajar yang nyaman dan kondusif</p></li><li><p>📺 Perangkat presentasi untuk mendukung proses belajar mengajar</p></li><li><p>🌐 Akses internet dan teknologi pembelajaran digital</p></li><li><p>💡 Fasilitas yang mendukung metode pembelajaran kolaboratif dan interaktif</p></li></ul><p>Ruang kelas modern ini merupakan bagian dari komitmen UPITRA dalam menyediakan lingkungan belajar yang relevan dengan perkembangan teknologi dan kebutuhan pendidikan masa kini.</p>', '[\"ruang kelas\",\"ruang kelas modern\",\"kelas modern\",\"smart classroom\"]', 'Aktif', 0, 0, '2026-06-01 22:09:23', '2026-06-04 20:48:01'),
(300, 'Fasilitas & Layanan', 'Layanan', 'Apakah tersedia layanan bantuan IT?', '<p>Ya, UPITRA menyediakan <strong>layanan bantuan IT (IT Support)</strong> untuk membantu mahasiswa dan sivitas akademika dalam mengatasi kendala teknis yang berkaitan dengan sistem dan layanan digital kampus.</p><p>Layanan bantuan IT dapat membantu berbagai kebutuhan, seperti:</p><ul><li><p>💻 Kendala akses Portal Akademik (SIAKAD)</p></li><li><p>🎓 Masalah login atau penggunaan E-Learning UNITY</p></li><li><p>📖 Akses Perpustakaan Digital SIPER</p></li><li><p>💼 Kendala pada Career Center UCC</p></li><li><p>📧 Aktivasi atau akses akun dan email kampus</p></li><li><p>🌐 Permasalahan terkait layanan teknologi informasi kampus</p></li></ul><p>Jika mengalami kendala teknis, mahasiswa dapat menghubungi bagian terkait atau layanan resmi kampus untuk mendapatkan bantuan lebih lanjut.</p><p>📞 0811-290-7500<br>📧 <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"mailto:admission@upitra.ac.id\">admission@upitra.ac.id</a></p>', '[\"it support\",\"bantuan it\",\"helpdesk it\",\"masalah akun\",\"dukungan system\",\"portal akademik eror\",\"reset password\",\"unity error\",\"siper error\",\"ucc error\",\"layanan kampus\",\"layanan teknologi kampus\",\"portal akademik error\"]', 'Aktif', 0, 0, '2026-06-01 22:12:16', '2026-06-01 22:12:16'),
(301, 'Fasilitas & Layanan', 'Area Belajar', 'Apakah tersedia ruang diskusi atau area belajar mahasiswa?', '<p>Ya, UPITRA menyediakan <strong>ruang diskusi dan area belajar</strong> yang dapat digunakan mahasiswa untuk belajar mandiri, diskusi kelompok, mengerjakan tugas, dan berkolaborasi dalam kegiatan akademik.</p>', '[\"ruang diskusi\",\"area belajar\",\"study area\",\"belajar kelompok\",\"ruang belajar\",\"tempat belajar\"]', 'Aktif', 0, 0, '2026-06-01 23:47:50', '2026-06-01 23:47:50'),
(302, 'Immersion Program', 'Umum', 'Apa manfaat Immersion Program?', '<p>Melalui Immersion Program, mahasiswa dapat memperoleh pengalaman kerja nyata, memperluas jaringan profesional, meningkatkan keterampilan praktis, memahami budaya kerja industri, serta memperkuat portofolio dan kesiapan karier setelah lulus.</p>', '[\"manfaat immersion\",\"keuntungan immersion\",\"benefit immersion\",\"nilai tambah immersion\"]', 'Aktif', 0, 0, '2026-06-01 23:53:30', '2026-06-01 23:53:30'),
(303, 'Immersion Program', 'Umum', 'Kapan Immersion Program Dilaksanakan?', '<p>Immersion Program dilaksanakan sesuai kurikulum dan jadwal akademik yang ditetapkan UPITRA. Informasi pelaksanaan akan diumumkan kepada mahasiswa pada periode yang telah ditentukan.</p>', '[\"kapan immersion\",\"jadwal immersion\",\"semester immersion\",\"pelaksanaan immersion\"]', 'Aktif', 0, 0, '2026-06-02 00:00:00', '2026-06-02 00:00:00'),
(304, 'Immersion Program', 'Umum', 'Di Mana Immersion Program Dilaksanakan?', '<p>Immersion Program dapat dilaksanakan pada perusahaan, institusi, organisasi, maupun mitra yang bekerja sama dengan UPITRA, baik di dalam maupun luar negeri sesuai program yang tersedia.</p>', '[\"lokasi immersion\",\"tempat immersion\",\"dimana immersion\",\"pelaksanaan immersion dimana\"]', 'Aktif', 0, 0, '2026-06-02 00:00:57', '2026-06-02 00:00:57'),
(305, 'Immersion Program', 'Umum', 'Apakah Semua Mahasiswa Mendapat Tempat Immersion?', '<p>UPITRA berupaya menyediakan kesempatan Immersion Program bagi mahasiswa melalui jaringan mitra yang dimiliki. Penempatan dilakukan sesuai ketentuan dan ketersediaan program yang berlaku.</p>', '[\"penempatan immersion\",\"tempat immersion mahasiswa\",\"jaminan immersion\",\"lokasi immersion mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:01:51', '2026-06-02 00:01:51'),
(306, 'Immersion Program', 'Umum', 'Apa Perbedaan Immersion Program dan Magang?', '<p>Magang merupakan salah satu bentuk kegiatan yang dapat dilakukan dalam Immersion Program. Namun Immersion Program memiliki cakupan yang lebih luas karena dapat mencakup proyek industri, studi lapangan, kolaborasi profesional, pelatihan, maupun pengalaman pembelajaran lainnya.</p>', '[\"beda immersion dan magang\",\"immersion vs magang\",\"perbandingan immersion\",\"magang atau immersion\"]', 'Aktif', 0, 0, '2026-06-02 00:04:41', '2026-06-02 00:04:41'),
(307, 'Karir & Alumni', NULL, 'Apa itu UPITRA Career Center (UCC)?', '<p>UPITRA Career Center (UCC) adalah layanan pengembangan karier yang membantu mahasiswa dan alumni mempersiapkan diri memasuki dunia kerja melalui informasi lowongan kerja, pelatihan karier, pengembangan kompetensi, dan jejaring profesional.</p>', '[\"ucc\",\"career center\",\"upitra career center\",\"pusat karir\",\"layanan karir\",\"pengembangan karir\"]', 'Aktif', 0, 0, '2026-06-02 00:08:42', '2026-06-02 00:08:42'),
(308, 'Karir & Alumni', 'Umum', 'Apakah UPITRA membantu penyaluran kerja alumni?', '<p>UPITRA mendukung kesiapan karier mahasiswa dan alumni melalui Career Center, jaringan mitra industri, program Immersion, serta berbagai kegiatan pengembangan profesional yang membantu meningkatkan peluang kerja lulusan.</p>', '[\"penyaluran kerja\",\"bantuan kerja \\\\\",\"mencari pekerjaan\",\"job placement\",\"penempatan kerja alumni\"]', 'Aktif', 0, 0, '2026-06-02 00:11:44', '2026-06-02 00:11:44'),
(309, 'Karir & Alumni', 'Umum', 'Alumni UPITRA bekerja di mana saja?', '<p>Lulusan UPITRA memiliki peluang berkarier di berbagai sektor industri sesuai bidang keilmuan masing-masing. Informasi alumni dan perjalanan karier lulusan dapat diperoleh melalui Career Center maupun kanal resmi UPITRA.</p>', '[\"alumni kerja dimana\",\"lulusan kerja dimana\",\"karir alumni\",\"tempat kerja alumni\",\"profil alumni\"]', 'Aktif', 0, 0, '2026-06-02 00:13:12', '2026-06-02 00:13:12'),
(310, 'Karir & Alumni', NULL, 'Apakah UPITRA menyediakan pelatihan karier?', '<p>Ya. UPITRA secara berkala menyelenggarakan kegiatan pengembangan karier seperti pelatihan, seminar, workshop, dan pembekalan profesional untuk membantu mahasiswa mempersiapkan diri menghadapi dunia kerja.</p>', '[\"pelatihan karir\",\"career training\",\"career development\",\"persiapan kerja\",\"pengembangan karir\"]', 'Aktif', 0, 0, '2026-06-02 00:14:48', '2026-06-02 00:14:48'),
(311, 'Karir & Alumni', 'Umum', 'Apakah UPITRA membantu pembuatan CV dan persiapan interview?', '<p>Melalui berbagai program pengembangan karier, mahasiswa dapat memperoleh pembekalan terkait penyusunan CV, teknik wawancara kerja, personal branding, dan keterampilan profesional lainnya.</p>', '[\"curriculum vitae\",\"interview kerja\",\"cv\",\"simulasi interview\",\"persiapan wawancara\"]', 'Aktif', 0, 0, '2026-06-02 00:15:50', '2026-06-02 00:15:50'),
(312, 'Karir & Alumni', NULL, 'Apakah UPITRA mengadakan job fair?', '<p>UPITRA dapat menyelenggarakan kegiatan karier seperti job fair, seminar industri, dan rekrutmen bersama mitra sesuai program dan kerja sama yang berjalan.</p>', '[\"job fair\",\"career fair\",\"bursa kerja\",\"rekrutmen kampus\"]', 'Aktif', 0, 0, '2026-06-02 00:19:17', '2026-06-02 00:19:17'),
(313, 'Karir & Alumni', 'Umum', 'Apakah alumni masih dapat menggunakan layanan Career Center?', '<p>Ya. Career Center UPITRA dirancang untuk mendukung mahasiswa maupun alumni dalam pengembangan karier dan akses informasi profesional.</p>', '[\"alumni career center\",\"layanan alumni\",\"ucc alumni\",\"akses career center alumni\"]', 'Aktif', 0, 0, '2026-06-02 00:20:15', '2026-06-02 00:20:15'),
(315, 'Karir & Alumni', 'Umum', 'Apa manfaat menjadi bagian dari jaringan alumni UPITRA?', '<p>Jaringan alumni memberikan kesempatan untuk memperluas relasi profesional, berbagi informasi karier, memperoleh peluang kolaborasi, serta mendukung pengembangan karier jangka panjang.</p>', '[\"manfaat alumni\",\"keuntungan alumni\",\"jaringan alumni\",\"komunitas lulusan\"]', 'Aktif', 0, 0, '2026-06-02 00:22:01', '2026-06-04 19:49:10'),
(316, 'Karir & Alumni', NULL, 'Berapa persen lulusan UPITRA yang bekerja setelah lulus?', NULL, '[]', 'Kosong', 0, 0, '2026-06-02 00:22:38', '2026-06-02 00:22:38'),
(317, 'Karir & Alumni', 'Umum', 'Berapa lama rata-rata alumni mendapatkan pekerjaan?', NULL, '[]', 'Kosong', 0, 0, '2026-06-02 00:22:56', '2026-06-02 00:22:56'),
(318, 'Kemahasiswaan', 'Umum', 'Apakah UPITRA memiliki organisasi mahasiswa?', '<p>Ya. UPITRA memiliki berbagai organisasi mahasiswa sebagai wadah pengembangan kepemimpinan, kreativitas, kolaborasi, dan pengembangan diri mahasiswa di luar kegiatan akademik.</p>', '[\"organisasi mahasiswa\",\"ormawa\",\"organisasi kampus\",\"organisasi di upitra\",\"organisasi mahasiswa upitra\"]', 'Aktif', 0, 0, '2026-06-02 00:25:27', '2026-06-02 00:25:27'),
(319, 'Kemahasiswaan', NULL, 'Apakah UPITRA memiliki BEM?', '<p>Ya. Mahasiswa dapat berpartisipasi dalam Badan Eksekutif Mahasiswa (BEM) sebagai sarana pengembangan kepemimpinan, organisasi, dan kontribusi terhadap kehidupan kampus.</p>', '[\"bem\",\"badan eksekutif mahasiswa\",\"organisasi bem\",\"bem upitra\"]', 'Kosong', 0, 0, '2026-06-02 00:26:54', '2026-06-02 00:26:54'),
(320, 'Kemahasiswaan', 'Umum', 'Apakah UPITRA memiliki Himpunan Mahasiswa Program Studi?', '<p>Ya. Setiap program studi dapat memiliki himpunan mahasiswa yang menjadi wadah pengembangan minat, kegiatan akademik, dan kolaborasi antar mahasiswa dalam bidang keilmuan yang sama.</p>', '[\"himpunan mahasiswa\",\"hima\",\"organisasi prodi\",\"himpunan prodi\"]', 'Aktif', 0, 0, '2026-06-02 00:27:54', '2026-06-04 19:49:49'),
(321, 'Kemahasiswaan', 'Umum', 'Apakah UPITRA memiliki Unit Kegiatan Mahasiswa (UKM)?', '<p>Ya. UPITRA menyediakan berbagai Unit Kegiatan Mahasiswa (UKM) sebagai sarana pengembangan minat, bakat, olahraga, seni, sosial, dan bidang lainnya sesuai kebutuhan mahasiswa.</p>', '[\"unit kegiatan mahasiswa\",\"ukm\",\"komunitas mahasiswa\",\"kegiatan mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:29:19', '2026-06-04 19:49:54'),
(322, 'Kemahasiswaan', 'Umum', 'Bagaimana cara bergabung dengan organisasi mahasiswa?', '<p>Mahasiswa dapat bergabung dengan organisasi atau UKM melalui proses rekrutmen yang diumumkan oleh masing-masing organisasi pada awal periode kegiatan atau melalui bagian kemahasiswaan.</p>', '[\"gabung organisasi\",\"daftar ukm\",\"ikut organisasi\",\"cara masuk bem\",\"cara masuk ukm\",\"cara masuk hima\"]', 'Aktif', 0, 0, '2026-06-02 00:30:25', '2026-06-04 19:49:59'),
(323, 'Kemahasiswaan', 'Umum', 'Apakah mahasiswa didorong mengikuti kompetisi?', '<p>Ya. UPITRA mendukung mahasiswa untuk mengikuti berbagai kompetisi akademik maupun non-akademik sebagai bagian dari pengembangan kompetensi dan prestasi mahasiswa.</p>', '[\"kompetisi mahasiswa\",\"lomba mahasiswa\",\"ikut lomba\",\"prestasi mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:31:09', '2026-06-04 19:50:04'),
(324, 'Kemahasiswaan', 'Umum', 'Apakah UPITRA memberikan dukungan untuk lomba mahasiswa?', '<p>UPITRA mendukung partisipasi mahasiswa dalam berbagai kompetisi melalui pembinaan, pendampingan, dan dukungan sesuai kebijakan yang berlaku.</p>', '[\"dukungan lomba\",\"bantuan lomba\",\"kompetisi mahasiswa\",\"fasilitas lomba\"]', 'Aktif', 0, 0, '2026-06-02 00:32:04', '2026-06-04 19:50:08'),
(325, 'Kemahasiswaan', 'Umum', 'Apakah ada program pengembangan kepemimpinan mahasiswa?', '<p>Ya. UPITRA menyelenggarakan berbagai kegiatan pengembangan kepemimpinan dan soft skills untuk membantu mahasiswa menjadi individu yang profesional dan berkarakter.</p>', '[\"kepemimpinan\",\"leadership\",\"pelatihan kepemimpinan\",\"pengembangan leadership\"]', 'Aktif', 0, 0, '2026-06-02 00:33:00', '2026-06-04 19:50:12'),
(326, 'Kemahasiswaan', NULL, 'Apakah mahasiswa dapat mengikuti kegiatan sosial atau pengabdian masyarakat?', '<p>Ya. Mahasiswa memiliki kesempatan mengikuti berbagai kegiatan sosial, pengabdian kepada masyarakat, dan program kolaboratif yang mendukung pengembangan karakter serta kepedulian sosial.</p>', '[\"pengabdian masyarakat\",\"kegiatan sosial\",\"volunteer\",\"bakti sosial\"]', 'Aktif', 0, 0, '2026-06-02 00:33:46', '2026-06-04 19:50:17'),
(327, 'Kemahasiswaan', 'Umum', 'Apakah tersedia layanan konseling mahasiswa?', '<p>UPITRA berkomitmen mendukung perkembangan mahasiswa melalui berbagai layanan pendampingan dan pembinaan sesuai kebutuhan akademik maupun pengembangan diri.</p>', '[\"konseling mahasiswa\",\"layanan konseling\",\"bimbingan mahasiswa\",\"konsultasi mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:35:02', '2026-06-04 19:50:20'),
(328, 'Kemahasiswaan', NULL, 'Apakah mahasiswa bisa mengadakan kegiatan atau acara kampus?', '<p>Ya. Mahasiswa dapat menyelenggarakan berbagai kegiatan akademik maupun non-akademik melalui organisasi mahasiswa dan mekanisme yang berlaku di lingkungan kampus.</p>', '[\"buat acara\",\"event mahasiswa\",\"kegiatan kampus\",\"program mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:36:01', '2026-06-04 19:50:25'),
(329, 'Kemahasiswaan', 'Umum', 'Apakah ada program mahasiswa berprestasi?', NULL, '[\"mahasiswa berprestasi\",\"mawapres\",\"prestasi mahasiswa\"]', 'Kosong', 0, 0, '2026-06-02 00:38:19', '2026-06-02 00:38:19'),
(330, 'Kemahasiswaan', 'Umum', 'Bagaimana cara mengajukan kegiatan mahasiswa?', NULL, '[\"proposal kegiatan\",\"izin kegiatan\",\"pengajuan acara\"]', 'Kosong', 0, 0, '2026-06-02 00:38:52', '2026-06-02 00:38:52'),
(331, 'Kemahasiswaan', 'Umum', 'Apakah mahasiswa dapat menjadi relawan kegiatan kampus?', NULL, '[\"kewirausahaan mahasiswa\",\"entrepreneur mahasiswa\",\"startup mahasiswa\",\"bisnis mahasiswa\"]', 'Kosong', 0, 0, '2026-06-02 00:39:39', '2026-06-02 00:39:39'),
(332, 'Kemahasiswaan', NULL, 'Apakah mahasiswa mendapatkan pelatihan soft skills?', NULL, '[\"soft skill\",\"pengembangan diri\",\"communication skill\",\"public speaking\"]', 'Kosong', 0, 0, '2026-06-02 00:40:37', '2026-06-02 00:40:37'),
(333, 'Kemahasiswaan', NULL, 'Apakah mahasiswa memiliki kesempatan berkolaborasi dengan industri?', NULL, '[\"kolaborasi industri\",\"proyek industri\",\"kerjasama industri mahasiswa\"]', 'Kosong', 0, 0, '2026-06-02 00:41:09', '2026-06-02 00:41:09'),
(334, 'Kerjasama', NULL, 'APAKAH UPITRA MEMILIKI KERJASAMA DENGAN INDUSTRI?', '<p>Ya. UPITRA menjalin kerja sama dengan berbagai mitra industri untuk mendukung pembelajaran, pengembangan kompetensi mahasiswa, Immersion Program, riset terapan, dan pengembangan karier lulusan.</p>', '[\"kerjasama industri\",\"mitra industri\",\"partner industri\",\"industri mitra\",\"hubungan industri\",\"kerjasama perusahaan\"]', 'Aktif', 0, 0, '2026-06-02 00:45:58', '2026-06-02 00:45:58'),
(335, 'Kerjasama', NULL, 'APAKAH UPITRA MEMILIKI KERJASAMA INTERNASIONAL?', '<p>Ya. UPITRA mengembangkan kerja sama dengan berbagai institusi dan mitra internasional untuk mendukung pertukaran pengetahuan, pengembangan akademik, serta peluang pengalaman global bagi mahasiswa dan dosen.</p>', '[\"kerjasama internasional\",\"international partnership\",\"mitra internasional\",\"kerjasama luar negeri\",\"global partnership\"]', 'Aktif', 0, 0, '2026-06-02 00:47:00', '2026-06-02 00:47:00'),
(336, 'Kerjasama', NULL, 'APA MANFAAT KERJASAMA BAGI MAHASISWA?', '<p>Kerja sama yang dimiliki UPITRA membuka peluang bagi mahasiswa untuk memperoleh pengalaman industri, kegiatan pembelajaran berbasis praktik, Immersion Program, pengembangan kompetensi, serta akses ke berbagai peluang karier dan jejaring profesional.</p>', '[\"manfaat kerjasama\",\"keuntungan kerjasama\",\"dampak kerjasama\",\"kerjasama untuk mahasiswa\"]', 'Aktif', 0, 0, '2026-06-02 00:47:52', '2026-06-02 00:47:52'),
(337, 'Kerjasama', NULL, 'APAKAH UPITRA MELAKUKAN KOLABORASI RISET?', '<p>Ya. UPITRA mendorong kolaborasi riset dengan berbagai mitra untuk menghasilkan inovasi, pengembangan ilmu pengetahuan, dan solusi yang relevan dengan kebutuhan masyarakat maupun industri.</p>', '[\"kolaborasi riset\",\"kerjasama penelitian\",\"riset bersama\",\"penelitian industri\",\"penelitian kolaboratif\"]', 'Aktif', 0, 0, '2026-06-02 00:48:54', '2026-06-02 00:48:54'),
(338, 'Kerjasama', NULL, 'SIAPA SAJA MITRA UPITRA?', '<p>UPITRA bekerja sama dengan berbagai perusahaan, institusi pendidikan, organisasi, dan mitra strategis untuk mendukung kegiatan akademik, penelitian, pengembangan mahasiswa, serta peluang karier lulusan.</p><p>Informasi mitra terbaru dapat dilihat melalui kanal resmi UPITRA.</p>', '[\"mitra upitra\",\"partner upitra\",\"perusahaan mitra\",\"institusi mitra\",\"kerjasama dengan siapa\"]', 'Aktif', 0, 0, '2026-06-02 00:50:14', '2026-06-02 00:50:14'),
(339, 'Kerjasama', 'Umum', 'APAKAH KERJASAMA MENDUKUNG IMMERSION PROGRAM?', '<p>Kerja sama yang dimiliki UPITRA menjadi salah satu fondasi pelaksanaan Immersion Program melalui keterlibatan berbagai mitra yang memberikan pengalaman belajar dan praktik langsung bagi mahasiswa.</p>', '[\"kerjasama immersion\",\"mitra immersion\",\"partner immersion\",\"dukungan immersion\"]', 'Aktif', 0, 0, '2026-06-02 00:51:10', '2026-06-02 00:51:10'),
(340, 'Kerjasama', 'Umum', 'APAKAH MAHASISWA BISA TERLIBAT DALAM PROGRAM KERJASAMA?', '<p>Ya. Mahasiswa dapat memperoleh kesempatan mengikuti berbagai program yang berasal dari kerja sama UPITRA dengan mitra, seperti pelatihan, seminar, proyek kolaboratif, Immersion Program, dan kegiatan pengembangan kompetensi lainnya.</p>', '[\"program kerjasama mahasiswa\",\"ikut program mitra\",\"mahasiswa dan kerjasama\",\"program kolaborasi\"]', 'Aktif', 0, 0, '2026-06-02 00:52:02', '2026-06-02 00:52:02'),
(341, 'Kerjasama', NULL, 'APAKAH DOSEN JUGA TERLIBAT DALAM PROGRAM KERJASAMA?', '<p>Ya. Dosen dapat terlibat dalam berbagai kegiatan kerja sama seperti penelitian, pengabdian kepada masyarakat, pengembangan kurikulum, pelatihan, dan kolaborasi akademik lainnya bersama mitra.</p>', '[\"dosen dan kerjasama\",\"peran dosen\",\"kerjasama dosen\",\"kolaborasi dosen\"]', 'Aktif', 0, 0, '2026-06-02 00:53:56', '2026-06-02 00:53:56'),
(342, 'Kerjasama', NULL, 'APAKAH KERJASAMA HANYA DENGAN PERUSAHAAN?', '<p>Tidak. UPITRA menjalin kerja sama dengan berbagai pihak, termasuk perusahaan, institusi pendidikan, organisasi profesi, lembaga pemerintah, komunitas, dan mitra internasional.</p>', '[\"jenis mitra\",\"kerjasama selain perusahaan\",\"mitra kampus\",\"partner kampus\"]', 'Aktif', 0, 0, '2026-06-02 00:55:46', '2026-06-02 00:55:46'),
(343, 'Kerjasama', 'Umum', 'Apakah UPITRA memiliki kerja sama dengan Triputra Group?', NULL, '[]', 'Kosong', 0, 0, '2026-06-02 00:56:15', '2026-06-02 00:56:15'),
(344, 'Kerjasama', NULL, 'Berapa jumlah mitra kerja sama UPITRA?', NULL, '[\"jumlah mitra\",\"jumlah kerjasama\",\"berapa mitra\"]', 'Kosong', 0, 0, '2026-06-02 00:56:49', '2026-06-02 00:56:49'),
(345, 'Kerjasama', NULL, 'Apakah kerja sama mendukung peluang kerja lulusan?', NULL, '[\"kerjasama dan karir\",\"hubungan industri dan karir\"]', 'Kosong', 0, 0, '2026-06-02 00:57:15', '2026-06-02 00:57:15'),
(346, 'Teknologi & Sistem', 'Umum', 'BAGAIMANA CARA MENGAKSES UNITY?', '<p>Mahasiswa dapat mengakses UNITY menggunakan akun yang diberikan oleh UPITRA melalui alamat sistem yang telah ditentukan oleh kampus.</p>', '[\"akses unity\",\"login unity\",\"masuk unity\",\"cara menggunakan unity\"]', 'Aktif', 0, 0, '2026-06-02 01:03:50', '2026-06-02 01:15:31'),
(347, 'Teknologi & Sistem', 'Umum', 'APA ITU SIPER?', '<p>SIPER adalah sistem perpustakaan digital UPITRA yang menyediakan akses ke berbagai koleksi referensi akademik, buku digital, jurnal, dan sumber pembelajaran lainnya.</p>', '[\"siper\",\"perpustakaan digital\",\"digital library\",\"ebook kampus\",\"apa itu siper\"]', 'Aktif', 0, 0, '2026-06-02 01:08:38', '2026-06-02 01:15:39'),
(348, 'Teknologi & Sistem', 'Umum', 'BAGAIMANA CARA MENGAKSES SIPER?', '<p>SIPER dapat diakses menggunakan akun mahasiswa melalui layanan perpustakaan digital yang disediakan UPITRA.</p>', '[\"akses siper\",\"login siper\",\"cara menggunakan siper\",\"masuk perpustakaan digital\"]', 'Aktif', 0, 0, '2026-06-02 01:17:17', '2026-06-02 01:17:17'),
(349, 'Teknologi & Sistem', 'Umum', 'APA ITU PORTAL AKADEMIK?', '<p>Portal Akademik adalah sistem yang digunakan mahasiswa untuk mengakses layanan akademik seperti KRS, KHS, jadwal kuliah, data akademik, dan informasi administrasi mahasiswa.</p>', '[\"portal akademik\",\"siakad\",\"portal mahasiswa\",\"apa itu portal akademik\"]', 'Aktif', 0, 0, '2026-06-02 01:18:12', '2026-06-02 01:23:56'),
(350, 'Teknologi & Sistem', 'Umum', 'APA PERBEDAAN UNITY DAN PORTAL AKADEMIK?', '<p>UNITY digunakan untuk kegiatan pembelajaran seperti materi kuliah, tugas, diskusi, dan evaluasi pembelajaran. Portal Akademik digunakan untuk administrasi akademik seperti KRS, KHS, jadwal kuliah, dan data mahasiswa.</p>', '[\"beda unity dan portal akademik\",\"unity atau portal akademik\",\"perbedaan lms dan siakad\"]', 'Aktif', 0, 0, '2026-06-02 01:19:00', '2026-06-02 01:24:04'),
(351, 'Teknologi & Sistem', 'Umum', 'BAGAIMANA JIKA LUPA PASSWORD?', '<p>Jika mengalami kendala login atau lupa password, mahasiswa dapat menghubungi layanan administrasi akademik atau tim IT UPITRA untuk proses verifikasi dan reset akun.</p>', '[\"lupa password\",\"reset password\",\"akun terkunci\",\"ganti password\",\"tidak bisa login\"]', 'Aktif', 0, 0, '2026-06-02 01:20:05', '2026-06-02 01:24:12'),
(353, 'Teknologi & Sistem', 'Umum', 'BAGAIMANA CARA MELAPORKAN MASALAH SISTEM?', '<p>Apabila mengalami kendala pada sistem kampus, mahasiswa dapat menghubungi unit terkait atau layanan bantuan yang disediakan UPITRA untuk mendapatkan dukungan teknis.</p>', '[\"lapor masalah sistem\",\"kendala sistem\",\"error sistem\",\"helpdesk\",\"dukungan teknis\"]', 'Aktif', 0, 0, '2026-06-02 01:23:26', '2026-06-02 01:23:48'),
(355, 'Teknologi & Sistem', NULL, 'Apakah data mahasiswa aman?', '<p><strong>Ya, UPITRA berkomitmen penuh untuk menjaga keamanan, kerahasiaan, dan privasi data seluruh mahasiswa</strong> melalui pengelolaan sistem terpadu oleh <strong>Biro Teknologi Informasi</strong>:</p><ol><li><p><strong>Perlindungan Server &amp; Database:</strong> Server data akademik mahasiswa dilindungi oleh sistem keamanan jaringan berlapis (<em>firewall</em>) untuk mencegah akses ilegal dan serangan siber dari pihak luar.</p></li><li><p><strong>Enkripsi Data Sensitif:</strong> Informasi penting seperti kata sandi (<em>password</em>) akun portal dan data pribadi mahasiswa dienkripsi di dalam sistem guna memastikan data tidak dapat disalahgunakan.</p></li><li><p><strong>Hak Akses Terbatas:</strong> Akses terhadap basis data mahasiswa dibatasi secara ketat dan hanya diberikan kepada staf atau biro berwenang (seperti Biro Bagian Akademik Administrasi atau Biro Keuangan) sesuai dengan kebutuhan pelayanan kampus.</p></li><li><p><strong>Pencadangan Berkala:</strong> Sistem melakukan <em>backup</em> data secara rutin untuk mencegah hilangnya data penting mahasiswa akibat kendala teknis yang tidak terduga.</p></li></ol><p></p>', '[\"keamanan data\",\"privasi data\",\"perlindungan data mahasiswa\",\"data upitra aman\",\"kebocoran data\",\"keamanan siakad\"]', 'Aktif', 0, 0, '2026-06-02 01:25:52', '2026-07-01 01:19:13'),
(356, 'Teknologi & Sistem', NULL, 'Apakah sistem dapat diakses 24 jam?', '<p><strong>Ya, sebagian besar sistem informasi utama di UPITRA dapat diakses secara daring (<em>online</em>) selama 24 jam penuh</strong> untuk mendukung fleksibilitas aktivitas akademik Anda.</p><p>Layanan yang dapat diakses kapan saja meliputi:</p><ol><li><p><strong>Portal Akademik Mahasiswa:</strong> Untuk pengecekan jadwal, nilai KHS, histori pembayaran, dan pengisian KRS pada masa jadwalnya.</p></li><li><p><strong>LMS UNITY:</strong> Untuk mengakses materi kuliah, mengunduh tugas, diskusi kelas, atau mengumpulkan tugas mandiri.</p></li><li><p><strong>Perpustakaan Digital SIPER:</strong> Untuk mencari referensi buku digital dan jurnal kapan pun dibutuhkan.</p></li></ol><p><em>Catatan: Pada waktu-waktu tertentu, akses ke sistem mungkin akan dijeda atau mengalami perlambatan sementara jika sedang dilakukan pemeliharaan berkala (maintenance system) oleh </em><strong><em>Biro Teknologi Informasi</em></strong><em>. Pemberitahuan biasanya akan dirilis terlebih dahulu melalui platform resmi kampus.</em></p>', '[\"akses 24 jam\",\"jam operasional sistem\",\"sistem online kapan saja\",\"siakad 24 jam\",\"unity maintenance\",\"kapan sistem maintenance\",\"jam pelayanan online\",\"akses malam hari\"]', 'Aktif', 0, 0, '2026-06-02 01:26:30', '2026-07-01 01:19:48'),
(357, 'Riset & Publikasi', NULL, 'APAKAH UPITRA MENDUKUNG KEGIATAN PENELITIAN?', '<p>Ya. UPITRA mendukung kegiatan penelitian sebagai bagian dari pelaksanaan Tri Dharma Perguruan Tinggi. Penelitian dilakukan oleh dosen maupun mahasiswa untuk menghasilkan inovasi, pengembangan ilmu pengetahuan, dan solusi bagi masyarakat serta industri.</p>', '[\"penelitian\",\"riset\",\"kegiatan riset\",\"research\",\"penelitian kampus\"]', 'Aktif', 0, 0, '2026-06-02 01:29:06', '2026-06-02 01:29:06'),
(358, 'Riset & Publikasi', 'Umum', 'SIAPA KETUA LPPM UPITRA?', NULL, '[\"ketua lppm\",\"pimpinan lppm\"]', 'Kosong', 0, 0, '2026-06-02 01:31:14', '2026-06-02 01:31:14'),
(359, 'Riset & Publikasi', NULL, 'APAKAH MAHASISWA DAPAT TERLIBAT DALAM PENELITIAN?', '<p>Ya. Mahasiswa memiliki kesempatan untuk terlibat dalam berbagai kegiatan penelitian bersama dosen maupun melalui proyek penelitian yang diselenggarakan oleh program studi dan LPPM.</p>', '[\"penelitian mahasiswa\",\"ikut penelitian\",\"riset mahasiswa\",\"mahasiswa dan penelitian\"]', 'Aktif', 0, 0, '2026-06-02 01:32:03', '2026-06-02 01:32:03'),
(360, 'Riset & Publikasi', 'Umum', 'APAKAH MAHASISWA DAPAT MEMUBLIKASIKAN KARYA ILMIAH?', '<p>Ya. UPITRA mendorong mahasiswa untuk menghasilkan dan mempublikasikan karya ilmiah melalui jurnal, seminar, konferensi, maupun media publikasi akademik lainnya sesuai bidang keilmuan masing-masing.</p>', '[\"publikasi mahasiswa\",\"jurnal mahasiswa\",\"karya ilmiah mahasiswa\",\"artikel ilmiah\"]', 'Aktif', 0, 0, '2026-06-02 01:32:50', '2026-06-02 01:32:50'),
(361, 'Riset & Publikasi', 'Umum', 'APAKAH DOSEN UPITRA AKTIF MELAKUKAN PENELITIAN?', '<p>Ya. Dosen UPITRA aktif melakukan penelitian sebagai bagian dari pengembangan ilmu pengetahuan, inovasi, dan kontribusi terhadap kebutuhan masyarakat maupun industri.</p>', '[\"penelitian dosen\",\"riset dosen\",\"dosen meneliti\",\"aktivitas penelitian dosen\"]', 'Aktif', 0, 0, '2026-06-02 01:33:44', '2026-06-02 01:33:44'),
(362, 'Riset & Publikasi', 'Umum', 'BAGAIMANA CARA MENGAKSES JURNAL UPITRA?', '<p>Jurnal ilmiah UPITRA dapat diakses melalui platform publikasi yang dikelola kampus. Informasi akses tersedia melalui website resmi UPITRA atau LPPM.</p>', '[\"akses jurnal\",\"website jurnal\",\"open journal system\",\"ojs\"]', 'Aktif', 0, 0, '2026-06-02 01:35:27', '2026-06-02 01:35:27'),
(363, 'Riset & Publikasi', 'Umum', 'APAKAH ADA PROGRAM HIBAH PENELITIAN?', '<p>UPITRA mendukung kegiatan penelitian melalui berbagai program yang dapat mencakup pendanaan penelitian sesuai kebijakan dan program yang berlaku.</p>', '[\"hibah penelitian\",\"grant penelitian\",\"pendanaan riset\",\"bantuan penelitian\"]', 'Aktif', 0, 0, '2026-06-02 01:36:17', '2026-06-02 01:36:17'),
(364, 'Riset & Publikasi', NULL, 'APAKAH HASIL PENELITIAN DIMANFAATKAN UNTUK INDUSTRI?', '<p>UPITRA mendorong penelitian yang relevan dengan kebutuhan industri dan masyarakat sehingga hasil penelitian dapat memberikan manfaat nyata serta mendukung pengembangan inovasi.</p>', '[\"riset industri\",\"penelitian industri\",\"hasil penelitian\",\"inovasi industri\"]', 'Aktif', 0, 0, '2026-06-02 01:37:14', '2026-06-02 01:37:14'),
(365, 'Riset & Publikasi', NULL, 'Apakah ada Program Kreativitas Mahasiswa (PKM)?', NULL, '[\"program kreativitas mahasiswa\",\"pkm\",\"kompetisi penelitian mahasiswa\"]', 'Kosong', 0, 0, '2026-06-02 01:37:53', '2026-06-02 01:37:53'),
(366, 'Riset & Publikasi', NULL, 'Apakah mahasiswa dapat menjadi asisten peneliti?', NULL, '[\"asisten penelitian\",\"research assistant\",\"bantu penelitian dosen\"]', 'Kosong', 0, 0, '2026-06-02 01:38:20', '2026-06-02 01:38:20'),
(367, 'Riset & Publikasi', NULL, 'Apakah UPITRA menyelenggarakan seminar ilmiah?', NULL, '[\"seminar ilmiah\",\"konferensi\",\"conference\",\"seminar penelitian\"]', 'Kosong', 0, 0, '2026-06-02 01:38:59', '2026-06-02 01:38:59'),
(368, 'Riset & Publikasi', NULL, 'Apakah UPITRA memiliki Hak Kekayaan Intelektual (HKI)?', NULL, '[\"hak kekayaan intelektual\",\"hki\",\"hak cipta penelitian\",\"paten\"]', 'Kosong', 0, 0, '2026-06-02 01:39:35', '2026-06-02 01:39:35'),
(369, 'Program Studi', 'FST', 'Apa prospek karir lulusan Informatika UPITRA?', '<p>Lulusan Informatika memiliki peluang karier sebagai Software Developer, Programmer, Data Analyst, AI Engineer, System Analyst, Cyber Security Specialist, hingga Tech Entrepreneur sesuai minat dan kompetensi yang dikembangkan selama studi.</p>', '[\"karir informatika\",\"lulusan informatika\",\"kerja informatika\",\"prospek kerja informatika\"]', 'Aktif', 0, 0, '2026-06-02 01:50:18', '2026-06-02 01:50:18'),
(370, 'Program Studi', 'FEB', 'Apa keunggulan Prodi Manajemen UPITRA?', '<p>Program Studi Manajemen UPITRA mengembangkan kompetensi mahasiswa dalam bidang manajemen bisnis, kepemimpinan, kewirausahaan, pemasaran, dan strategi organisasi. Pembelajaran dirancang untuk menghasilkan lulusan yang siap menghadapi tantangan bisnis dan dunia kerja yang terus berkembang.</p>', '[\"manajemen\",\"prodi manajemen\",\"jurusan manajemen\",\"keunggulan manajemen\"]', 'Aktif', 0, 0, '2026-06-02 01:55:35', '2026-06-02 01:56:32'),
(371, 'Program Studi', 'FEB', 'Apa prospek karir lulusan Manajemen UPITRA?', '<p>Lulusan Manajemen memiliki peluang karier sebagai Business Development Officer, Marketing Executive, Human Resource Specialist, Operations Manager, Entrepreneur, maupun berbagai posisi manajerial di perusahaan dan organisasi.</p>', '[\"karir manajemen\",\"lulusan manajemen\",\"prospek kerja manajemen\",\"kerja manajemen\"]', 'Aktif', 0, 0, '2026-06-02 01:58:47', '2026-06-02 01:58:47'),
(372, 'Program Studi', 'FSH', 'Apa keunggulan Prodi Pariwisata UPITRA?', '<p>Program Studi Pariwisata UPITRA membekali mahasiswa dengan kompetensi dalam pengelolaan destinasi wisata, hospitality, event management, dan bisnis pariwisata yang berkelanjutan.</p>', '[\"keunggulan pariwisata\",\"pariwisata\",\"jurusan pariwisata\",\"prodi pariwisata\"]', 'Aktif', 0, 0, '2026-06-02 02:00:39', '2026-06-02 02:00:39'),
(373, 'Program Studi', 'FSH', 'Apa keunggulan Prodi Bahasa Inggris UPITRA?', '<p>Program Studi Bahasa Inggris UPITRA mengembangkan kemampuan komunikasi global, penerjemahan, public speaking, serta keterampilan bahasa yang mendukung kebutuhan profesional dan internasional.</p>', '[\"keunggulan bahasa inggris\",\"bahasa inggris\",\"jurusan bahasa inggris\",\"prodi bahasa inggris\"]', 'Aktif', 0, 0, '2026-06-02 02:01:47', '2026-06-02 02:01:47'),
(374, 'Program Studi', 'FSH', 'Apa prospek karir lulusan Pariwisata UPITRA?', '<p>Lulusan Pariwisata dapat berkarier di sektor hospitality, travel consultant, event organizer, pengelola destinasi wisata, tour operator, hingga entrepreneur di bidang pariwisata dan ekonomi kreatif.</p>', '[\"prospek kerja pariwisata\",\"karir pariwisata\",\"lulusan pariwisata\",\"kerja pariwisata\"]', 'Aktif', 0, 0, '2026-06-02 02:03:09', '2026-06-02 02:03:09');
INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(375, 'Program Studi', 'FSH', 'Apa prospek karir lulusan Bahasa Inggris UPITRA?', '<p>Lulusan Bahasa Inggris dapat berkarier sebagai Translator, Interpreter, Content Writer, Public Relations Officer, Corporate Communication Specialist, tenaga pengajar, maupun profesional di perusahaan multinasional.</p>', '[\"karir bahasa inggris\",\"lulusan bahasa inggris\",\"kerja bahasa inggris\",\"prospek kerja bahasa inggris\"]', 'Aktif', 0, 0, '2026-06-02 02:03:58', '2026-06-02 02:03:58'),
(376, 'Program Studi', 'FK', 'Apa keunggulan Prodi Fisioterapi UPITRA?', '<p>Program Studi Fisioterapi UPITRA membekali mahasiswa dengan kompetensi dalam rehabilitasi fisik, terapi gerak, pencegahan cedera, serta peningkatan kualitas hidup pasien melalui pendekatan profesional dan berbasis praktik.</p>', '[\"fisioterapi\",\"jurusan fisioterapi\",\"prodi fisioterapi\",\"keunggulan prodi fisioterapi\",\"keunggulan fisioterapi\"]', 'Aktif', 0, 0, '2026-06-02 02:05:28', '2026-06-08 02:05:30'),
(377, 'Program Studi', NULL, 'Lulusan Prodi Fisioterapi bisa bekerja sebagai apa?', '<p>Lulusan Fisioterapi dapat berkarier sebagai Fisioterapis di rumah sakit, klinik, pusat rehabilitasi, klub olahraga, fasilitas kesehatan, maupun membuka layanan praktik sesuai regulasi yang berlaku.</p>', '[\"karir fisioterapi\",\"lulusan fisioterapi\",\"kerja fisioterapi\",\"prospek kerja fisioterapi\"]', 'Aktif', 0, 0, '2026-06-02 02:06:17', '2026-06-04 19:51:51'),
(378, 'Program Studi', NULL, 'Apa keunggulan Prodi Keselamatan dan Kesehatan Kerja (K3) UPITRA?', '<p>Program Studi Keselamatan dan Kesehatan Kerja (K3) UPITRA membekali mahasiswa dengan kompetensi dalam manajemen risiko, keselamatan kerja, kesehatan kerja, serta penerapan standar keselamatan di berbagai sektor industri.</p>', '[\"k3\",\"keselamatan dan kesehatan kerja\",\"prodi keselamatan dan kesehatan kerja\",\"prodi k3\",\"jurusan keselamatan dan kesehatan kerja\",\"jurusan k3\",\"keunggulan keselamatan dan kesehatan kerja\",\"keunggulan k3\"]', 'Aktif', 0, 0, '2026-06-02 02:07:18', '2026-06-04 19:51:55'),
(379, 'Program Studi', NULL, 'Lulusan Prodi K3 bisa bekerja sebagai apa?', '<p>Lulusan K3 dapat berkarier sebagai HSE Officer, Safety Officer, Safety Supervisor, Risk Management Officer, Auditor K3, maupun profesional keselamatan kerja di berbagai sektor industri dan organisasi.</p>', '[\"karir k3\",\"lulusan k3\",\"kerja k3\",\"prospek kerja k3\"]', 'Aktif', 0, 0, '2026-06-02 02:08:13', '2026-06-04 19:52:00'),
(380, 'Profil Universitas', 'Slogan', 'Apa slogan atau tagline UPITRA?', '<p>Slogan atau tagline utama yang merepresentasikan arah pendidikan di <strong>Universitas Pignatelli Triputra (UPITRA)</strong> berfokus pada kesiapan kerja dan integrasi dunia industri, yaitu:</p><p>💡 <strong>\"Pendidikan Berbasis Industri (<em>Link and Match</em>)\"</strong></p><p>Slogan ini menegaskan komitmen UPITRA untuk menyelenggarakan kurikulum yang selaras dengan kebutuhan industri nyata, didukung penuh oleh jaringan ekosistem Triputra Group guna mencetak lulusan yang berkarakter, kompeten, profesional, dan siap kerja langsung di tingkat global.</p>', '[\"slogan upitra\",\"tagline upitra\",\"motto kampus\",\"link and match\",\"pignatelli triputra slogan\",\"semboyan upitra\",\"identitas universitas\"]', 'Aktif', 0, 0, '2026-06-02 02:14:48', '2026-06-24 00:08:34'),
(381, 'Profil Universitas', 'DNA UPITRA', 'Nilai-nilai apa yang dijunjung di DNA UPITRA?', '<p><strong>DNA UPITRA dibentuk atas landasan nilai-nilai luhur kepemimpinan, integritas, dan profesionalisme yang kuat.</strong> &gt; Nilai-nilai utama yang dijunjung tinggi dan diintegrasikan ke dalam karakter setiap sivitas akademika UPITRA meliputi:</p><ol><li><p><strong>Integritas (Integrity):</strong> Bertindak jujur, selaras antara perkataan dan perbuatan, serta menjunjung tinggi kode etik akademik maupun profesional.</p></li><li><p><strong>Profesionalisme (Professionalism):</strong> Memiliki kompetensi yang mumpuni di bidangnya, berkomitmen pada kualitas hasil kerja, serta adaptif terhadap kebutuhan dunia industri.</p></li><li><p><strong>Semangat Berinovasi (Innovation):</strong> Selalu haus akan ilmu pengetahuan baru, kreatif dalam memecahkan masalah, dan berani melakukan terobosan positif.</p></li><li><p><strong>Semangat Melayani (Servant Leadership):</strong> Menumbuhkan karakter pemimpin yang peduli, rendah hati, dan berorientasi pada kontribusi nyata bagi masyarakat dan kemajuan bangsa.</p></li></ol><p><em>Internalisasi nilai DNA kampus ini dipantau secara konsisten melalui program pengembangan karakter oleh </em><strong><em>Biro Bagian Kemahasiswaan</em></strong><em>.</em></p>', '[\"dna upitra\",\"nilai nilai upitra\",\"karakter mahasiswa\",\"budaya kampus\",\"visi misi karakter\",\"integritas upitra\"]', 'Aktif', 0, 0, '2026-06-02 02:15:05', '2026-07-01 01:24:52'),
(384, 'Lainnya', 'Lokasi FST', 'Di mana lokasi Fakultas Sains dan Teknologi (FST)?', '<p>Fakultas Sains dan Teknologi (FST) Universitas Pignatelli Triputra berada di <strong>Gedung 2, Lantai 2</strong>, kawasan Kampus Universitas Pignatelli Triputra. Silakan menuju Gedung 2 dan naik ke lantai 2 untuk menemukan area FST.</p>', '[\"lokasi fst\",\"fst dimana\",\"fakultas sains dan teknologi dimana\",\"gedung fst\",\"gedung 2 lantai 2\",\"lokasi fakultas teknologi\",\"lokasi prodi teknologi\"]', 'Aktif', 0, 0, '2026-06-03 19:47:07', '2026-06-03 19:47:07'),
(385, 'Lainnya', 'Akreditasi Prodi', 'Program studi di UPITRA telah terakreditasi dengan predikat Baik dan Baik Sekali.', '<p><strong>Akreditasi Baik Sekali:</strong></p><ul><li><p>D3 Bahasa Inggris</p></li><li><p>S1 Akuntansi</p></li><li><p>S1 Sistem Informasi</p></li></ul><p><strong>Akreditasi Baik:</strong></p><ul><li><p>S1 Manajemen</p></li><li><p>D3 Manajemen Keuangan</p></li><li><p>S1 Rekayasa Perangkat Lunak</p></li><li><p>S1 Informatika</p></li><li><p>D3 Akuntansi</p></li></ul><p>Untuk informasi nomor SK dan masa berlaku akreditasi masing-masing program studi, silakan tanyakan program studi yang ingin Anda ketahui.</p>', '[\"akreditasi prodi upitra\",\"akreditasi program studi upitra\",\"akreditasi jurusan upitra\",\"akreditasi semua prodi\",\"daftar akreditasi prodi\",\"status akreditasi prodi\",\"akreditasi seluruh prodi\",\"akreditasi kampus upitra\",\"akreditasi program studi\",\"akreditasi jurusan\",\"apa akreditasi prodi di upitra\",\"bagaimana akreditasi prodi upitra\",\"prodi upitra terakreditasi apa\",\"akreditasi masing masing prodi\",\"daftar akreditasi jurusan\",\"akreditasi fakultas dan prodi\",\"akreditasi pendidikan di upitra\",\"mutu program studi upitra\",\"akreditasi yang dimiliki upitra\",\"akreditasi semua jurusan upitra\",\"status akreditasi jurusan upitra\",\"informasi akreditasi prodi\",\"akreditasi akademik upitra\",\"akreditasi program kuliah\"]', 'Aktif', 0, 0, '2026-06-03 20:13:52', '2026-06-03 20:13:52'),
(386, 'Lainnya', 'Akreditasi FST', 'Bagaimana akreditasi S1 Sistem Informasi?', '<p>Program Studi <strong>S1 Sistem Informasi UPITRA</strong> terakreditasi <strong>Baik Sekali</strong> berdasarkan SK LAM-INFOKOM Nomor <strong>049/SK/LAM-INFOKOM/Ak.P/S/XII/2024</strong> dan berlaku hingga <strong>2 Desember 2029</strong>.</p>', '[\"akreditasi sistem informasi\",\"akreditasi si\",\"s1 sistem informasi\",\"sistem informasi upitra\",\"status akreditasi sistem informasi\",\"prodi sistem informasi\",\"akreditasi program studi sistem informasi\",\"sistem informasi akreditasinya apa\",\"sistem informasi sudah terakreditasi\",\"akreditasi jurusan sistem informasi\",\"bagaimana akreditasi sistem informasi\",\"berapa akreditasi sistem informasi\",\"sistem informasi upitra akreditasinya apa\",\"jurusan si akreditasinya apa\",\"si upitra akreditasinya apa\",\"sistem informasi bagus tidak\",\"mutu sistem informasi upitra\",\"nilai akreditasi sistem informasi\",\"status prodi sistem informasi\",\"sistem informasi terakreditasi apa\",\"apakah sistem informasi sudah terakreditasi\",\"sistem informasi upitra bagus\",\"akreditasi kuliah sistem informasi\",\"jurusan sistem informasi di upitra\",\"kualitas sistem informasi upitra\",\"sistem informasi upitra terakreditasi\",\"info akreditasi sistem informasi\"]', 'Aktif', 0, 0, '2026-06-03 20:19:02', '2026-06-03 22:34:53'),
(387, 'Lainnya', 'Akreditasi FST', 'Bagaimana akreditasi S1 Rekayasa Perangkat Lunak?', '<p>Program Studi <strong>S1 Rekayasa Perangkat Lunak (RPL) Universitas Pignatelli Triputra (UPITRA)</strong> telah memperoleh akreditasi <strong>Baik</strong> dari <strong>LAM-INFOKOM</strong> berdasarkan <strong>SK Nomor 101/SK/LAM-INFOKOM/Ak.P/S/XII/2024</strong>. Akreditasi ini diterbitkan pada tahun <strong>2024</strong> dan berlaku hingga <strong>16 Desember 2029</strong>.</p>', '[\"akreditasi rekayasa perangkat lunak\",\"akreditasi s1 rekayasa perangkat lunak\",\"akreditasi rpl\",\"status akreditasi rekayasa perangkat lunak\",\"prodi rekayasa perangkat lunak\",\"jurusan rekayasa perangkat lunak\",\"akreditasi rekayasa perangkat lunak upitra\",\"rpl upitra\",\"rekayasa perangkat lunak upitra\",\"akreditasi program studi rekayasa perangkat lunak\",\"akreditasi software engineering\",\"software engineering upitra\",\"akreditasi software engineering upitra\",\"status prodi rpl\",\"rpl akreditasinya apa\",\"rekayasa perangkat lunak akreditasinya apa\",\"bagaimana akreditasi rpl\",\"bagaimana akreditasi rekayasa perangkat lunak\",\"rpl upitra akreditasinya apa\",\"jurusan rpl akreditasinya apa\",\"software engineering akreditasinya apa\",\"software engineering upitra akreditasi\",\"apakah rpl sudah terakreditasi\",\"apakah rekayasa perangkat lunak sudah terakreditasi\",\"berapa akreditasi rpl\",\"nilai akreditasi rpl\",\"mutu prodi rpl\",\"kualitas rekayasa perangkat lunak upitra\",\"status akreditasi rpl upitra\",\"rpl upitra bagus tidak\",\"rekayasa perangkat lunak upitra bagus tidak\",\"info akreditasi rpl\",\"info akreditasi software engineering\",\"prodi rpl terakreditasi apa\"]', 'Aktif', 0, 0, '2026-06-03 20:25:21', '2026-06-03 20:25:21'),
(388, 'Lainnya', 'Akreditasi FST', 'Bagaimana akreditasi S1 Informatika?', '<p>Program Studi <strong>S1 Informatika UPITRA</strong> terakreditasi <strong>Baik</strong> oleh <strong>LAM-INFOKOM</strong> berdasarkan <strong>SK Nomor 044/SK/LAM-INFOKOM/Ak.P/S/XII/2024</strong> dan berlaku hingga <strong>2 Desember 2029</strong>.</p>', '[\"akreditasi informatika\",\"akreditasi s1 informatika\",\"status akreditasi informatika\",\"prodi informatika\",\"jurusan informatika\",\"akreditasi informatika upitra\",\"informatika upitra\",\"akreditasi program studi informatika\",\"status prodi informatika\",\"akreditasi teknik informatika\",\"teknik informatika upitra\",\"akreditasi teknik informatika upitra\",\"status jurusan informatika\",\"akreditasi prodi informatika\",\"informatika akreditasinya apa\",\"bagaimana akreditasi informatika\",\"berapa akreditasi informatika\",\"jurusan informatika akreditasinya apa\",\"prodi informatika akreditasinya apa\",\"informatika upitra akreditasinya apa\",\"apakah informatika sudah terakreditasi\",\"status akreditasi informatika upitra\",\"nilai akreditasi informatika\",\"mutu prodi informatika\",\"kualitas informatika upitra\",\"informatika upitra bagus tidak\",\"jurusan informatika bagus tidak\",\"info akreditasi informatika\",\"informasi akreditasi informatika\",\"akreditasi kuliah informatika\",\"informatika terakreditasi apa\",\"teknik informatika akreditasinya apa\"]', 'Aktif', 0, 0, '2026-06-03 20:33:13', '2026-06-03 20:33:13'),
(389, 'Lainnya', 'Dosen FST', 'Siapa saja dosen di Fakultas Sains dan Teknologi (FST)?', '<p>Fakultas Sains dan Teknologi (FST) Universitas Pignatelli Triputra (UPITRA) didukung oleh dosen-dosen yang berpengalaman di bidangnya. Berikut daftar dosen berdasarkan program studi:</p><h3>💻 S1 Informatika</h3><ul><li><p><strong>Endang Anggiratih, S.T., M.Cs </strong><em>(Kaprodi)</em></p></li><li><p>Bagas Dwi Yulianto, S.Kom, M.Kom</p></li><li><p>Very Dwi Setiawan, S.T., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a></p></li><li><p>Tutus Praningki, S.Kom, M.Kom</p></li></ul><h3>🖥️ S1 Rekayasa Perangkat Lunak (RPL)</h3><ul><li><p><strong>Tutus Praningki, S.Kom, M.Kom </strong><em>(Kaprodi)</em></p></li><li><p>Moyo Hady Poernomo, S.Kom, M.Kom</p></li><li><p>Wisnu Wendanto, S.Kom, M.Kom</p></li><li><p>Aldian Umbu Tamu Ama, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Si\">S.Si</a>, M.Cs</p></li><li><p>Said Hirzi Hadi, S.Kom, M.Eng</p></li></ul><h3>📊 S1 Sistem Informasi</h3><ul><li><p><strong>Mawar Hardiyanti, S.Kom, M.Kom </strong><em>(Kaprodi)</em></p></li><li><p>Benedictus Herry Suharto, S.T., M.T.</p></li><li><p>Maria Karmelia Fajarlestari, S.Kom, M.Kom</p></li><li><p>Yeremia Victor Rondonuwu, S.Kom, M.M.</p></li><li><p>Imanuel Zega, S.Kom, M.Kom</p></li></ul><p>Untuk informasi profil, bidang keahlian, atau riwayat pendidikan dosen tertentu, silakan sebutkan nama dosen yang ingin Anda ketahui.</p>', '[\"dosen fst\",\"dosen fakultas sains dan teknologi\",\"daftar dosen fst\",\"tenaga pengajar fst\",\"dosen informatika\",\"dosen sistem informasi\",\"dosen rekayasa perangkat lunak\",\"dosen rpl\",\"dosen fakultas teknologi\",\"staf pengajar fst\",\"siapa saja dosen fst\",\"siapa dosen di fst\",\"dosen informatika siapa saja\",\"dosen sistem informasi siapa saja\",\"dosen rpl siapa saja\",\"daftar dosen informatika\",\"daftar dosen sistem informasi\",\"daftar dosen rpl\",\"pengajar di fst\",\"siapa kaprodi sistem informasi\",\"siapa kaprodi informatika\",\"siapa kaprodi rpl\",\"dosen upitra\",\"nama dosen fst\",\"dosen fakultas teknologi siapa saja\",\"siapa yang mengajar di fst\",\"siapa saja dosen di FST?\"]', 'Aktif', 0, 0, '2026-06-07 20:12:09', '2026-06-08 01:34:37'),
(390, 'Lainnya', 'Dosen FEB', 'Siapa saja dosen di Fakultas Ekonomika dan Bisnis (FEB)?', '<p>Fakultas Ekonomika dan Bisnis (FEB) Universitas Pignatelli Triputra (UPITRA) didukung oleh dosen-dosen yang kompeten dan berpengalaman di bidang ekonomi, bisnis, akuntansi, dan manajemen. Berikut daftar dosen berdasarkan program studi:</p><h3>📊 S1 Akuntansi</h3><ul><li><p><strong>Hirawresti Langen Apsari, S.E., M.Ak</strong> <em>(Kaprodi)</em></p></li><li><p>Heru Suwasono, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a></p></li><li><p>Vitalis Ari Widiyaningsih, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a></p></li><li><p>Remon Gunanta, S.Pd., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a></p></li><li><p>Gisilowati Dian Purnamasari, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Si\">M.Si</a></p></li><li><p>Dr. Ir. Dwi Poetra Sedjati, M.M.</p></li><li><p>Titik Dwiyani, S.E., M.M.</p></li><li><p>Dewi Kartikasari, S.E., M.M., M.Ak</p></li><li><p>Maria Rosa Kumala Dewi, S.E., M.Ak</p></li></ul><h3>📈 S1 Manajemen</h3><ul><li><p><strong>Agustinus Kismet N. J., S.E., MBA</strong> <em>(Kaprodi)</em></p></li><li><p>Neil Semuel Rupidara, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>., Ph.D</p></li><li><p>Dr. Alfa Santoso B. P., S.E., M.M.</p></li><li><p>Dr. Endang Purwaningsih, S.E., M.M.</p></li><li><p>Tjong Budisantoso, S.E., MBA, Ph.D</p></li><li><p>Margareta Ernanda Rahardani, S.M., M.M.</p></li><li><p>Yenni Maria Sridarta, S.E., M.M.</p></li><li><p>Vincentia Indah Puspita Sari, S.E., M.M.</p></li><li><p>Yusup Hari Subagya, S.E., M.M.</p></li><li><p>Dra. Margaretha Prihatiningsih, M.M.</p></li></ul><p>Untuk informasi lebih lanjut mengenai profil, bidang keahlian, atau riwayat pendidikan dosen tertentu, silakan sebutkan nama dosen yang ingin Anda ketahui.</p>', '[\"dosen feb\",\"dosen fakultas ekonomika dan bisnis\",\"daftar dosen feb\",\"tenaga pengajar feb\",\"dosen akuntansi\",\"dosen manajemen\",\"dosen fakultas bisnis\",\"staf pengajar feb\",\"dosen ekonomi\",\"dosen upitra feb\",\"siapa saja dosen feb\",\"siapa dosen di feb\",\"dosen akuntansi siapa saja\",\"dosen manajemen siapa saja\",\"daftar dosen akuntansi\",\"daftar dosen manajemen\",\"siapa kaprodi akuntansi\",\"siapa kaprodi manajemen\",\"pengajar di feb\",\"nama dosen akuntansi\",\"nama dosen manajemen\",\"dosen fakultas ekonomi siapa saja\",\"dosen bisnis upitra\",\"siapa yang mengajar di feb\",\"daftar pengajar feb\"]', 'Aktif', 0, 0, '2026-06-08 01:09:06', '2026-06-08 01:10:50'),
(391, 'Lainnya', 'Dosen FSH', 'Siapa saja dosen di Fakultas Sosial dan Humaniora (FSH)?', '<p>Fakultas Sosial dan Humaniora (FSH) Universitas Pignatelli Triputra (UPITRA) didukung oleh dosen-dosen yang berkompeten dan berpengalaman di bidang pariwisata, bahasa, komunikasi, serta pengembangan sumber daya manusia. Berikut daftar dosen berdasarkan program studi:</p><h3>Pariwisata</h3><ul><li><p><strong>Oktavianus I Wayan Semuel, S.E., M.M.</strong> <em>(Kaprodi)</em></p></li><li><p>Dr. RR. Erna Sadiarti Budiningtyas, S.Sos., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>.</p></li><li><p>Wahyu Setiawan, S.M., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>.</p></li><li><p>Albert Josua Putera Maliogha, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Si\">S.Si</a>.-Teol., MTS.</p></li><li><p>Fendy Kurniawan, <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.Tr\">S.Tr</a>.Par., M.Par.</p></li></ul><h3>Bahasa Inggris</h3><ul><li><p><strong>Tan Michael Chandra, S.S., M.Hum. </strong><em>(Kaprodi)</em></p></li><li><p>Yulia Milka Nugraheni, S.S., M.A.</p></li><li><p>Vinsensius Galuh Kusuma, S.Pd., M.Pd.</p></li><li><p>Sangaji Yudhi Pratama, S.Pd., M.Pd.</p></li><li><p>Nanda Pambudi, S.Pd., M.Pd.</p></li><li><p>Fitria Yuliani, S.Pd., M.Pd.</p></li></ul><p>Untuk informasi lebih lanjut mengenai profil, bidang keahlian, atau latar belakang pendidikan dosen tertentu, silakan sebutkan nama dosen yang ingin Anda ketahui.</p>', '[\"dosen fsh\",\"dosen fakultas sosial dan humaniora\",\"daftar dosen fsh\",\"tenaga pengajar fsh\",\"dosen pariwisata\",\"dosen bahasa inggris\",\"dosen fakultas sosial humaniora\",\"staf pengajar fsh\",\"dosen upitra fsh\",\"dosen fakultas sosial\",\"siapa saja dosen fsh\",\"siapa dosen di fsh\",\"dosen pariwisata siapa saja\",\"dosen bahasa inggris siapa saja\",\"daftar dosen pariwisata\",\"daftar dosen bahasa inggris\",\"siapa kaprodi pariwisata\",\"pengajar di pariwisata\",\"pengajar di bahasa inggris\",\"nama dosen pariwisata\",\"nama dosen bahasa inggris\",\"dosen fakultas sosial siapa saja\",\"dosen humaniora siapa saja\",\"siapa yang mengajar di fsh\",\"daftar pengajar fsh\"]', 'Aktif', 0, 0, '2026-06-08 01:26:46', '2026-06-08 01:30:32'),
(392, 'Lainnya', 'Pertanyaan Random', 'Apa itu Upitra ?', '<p>UPITRA menawarkan pengalaman belajar yang mengintegrasikan keunggulan akademik, wawasan industri, pengembangan karakter, serta peluang pembelajaran global untuk mempersiapkan lulusan yang kompeten dan siap menghadapi tantangan dunia kerja maupun kewirausahaan.</p><p>Informasi lebih lanjut mengenai profil universitas, program unggulan, fasilitas, kerja sama industri, dan berbagai peluang pengembangan mahasiswa dapat diakses melalui situs resmi UPITRA:</p><p>🌐 <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://upitra.ac.id?utm_source=chatgpt.com\">Website Resmi UPITRA</a></p><p>Untuk mengetahui informasi terkait fakultas, program studi, kurikulum, prospek karier, kompetensi lulusan, fasilitas pembelajaran, serta kebutuhan dan peluang di masing-masing bidang, silakan eksplorasi halaman fakultas berikut:</p><p>📘 Fakultas Ekonomi dan Bisnis (FEB): <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://upitra.ac.id/feb\">https://upitra.ac.id/feb</a></p><p>📗 Fakultas Sosial dan Humaniora (FSH): <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://upitra.ac.id/fsh\">https://upitra.ac.id/fsh</a></p><p>📙 Fakultas Sains dan Teknologi (FST): <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://upitra.ac.id/fst\">https://upitra.ac.id/fst</a></p><p>Setiap halaman fakultas telah menyediakan informasi yang komprehensif mengenai program studi, kurikulum, kompetensi yang akan diperoleh, prospek karier lulusan, serta berbagai peluang pengembangan akademik dan profesional. Untuk mendapatkan gambaran yang lebih sesuai dengan minat dan tujuan karier Anda, silakan mengeksplorasi fakultas dan program studi yang diminati melalui tautan tersebut.</p>', '[\"apakah ada matematika diskrit di semester satu prodi rpl\",\"apaa itu php native\",\"kenapa saya harus memilih upitra\"]', 'Aktif', 0, 0, '2026-06-08 01:43:41', '2026-06-08 01:45:36'),
(393, 'Lainnya', 'Informasi Buka Upitra', 'Buka jam berapa UPITRA?', '<p>Jam operasional layanan UPITRA adalah sebagai berikut:</p><ul><li><p>Senin: 08.00–17.00 WIB</p></li><li><p>Selasa: 08.00–17.00 WIB</p></li><li><p>Rabu: 08.00–17.00 WIB</p></li><li><p>Kamis: 08.00–17.00 WIB</p></li><li><p>Jumat: 08.00–17.00 WIB</p></li><li><p>Sabtu: 08.00–14.00 WIB</p></li><li><p>Minggu: Tutup</p></li></ul><p>Untuk informasi lebih lanjut mengenai layanan dan kegiatan di lingkungan UPITRA, silakan kunjungi <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://upitra.ac.id?utm_source=chatgpt.com\">Website Resmi UPITRA</a>.</p>', '[\"buka jam berapa ?\",\"upitra buka jam ?\",\"perpustakaan jam berapa ?\",\"perpustakaan buka jam berapa ?\"]', 'Aktif', 0, 0, '2026-06-08 01:48:52', '2026-06-08 01:48:52'),
(394, 'Akademik', 'Remedial', 'Bagaimana prosedur pengajuan remedial mata kuliah?', '<p style=\"text-align: justify;\">Mahasiswa yang belum memenuhi standar kelulusan nilai mata kuliah dapat mengikuti remedial dengan prosedur berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Pendaftaran:</strong> Daftar program remedial melalui SIAKAD sesuai jadwal kalender akademik.</p></li><li><p style=\"text-align: justify;\"><strong>Pembayaran:</strong> Bayar biaya remedial per SKS melalui bank mitra UPITRA.</p></li><li><p style=\"text-align: justify;\"><strong>Persetujuan:</strong> Lakukan konfirmasi dan minta persetujuan ke Dosen Pembimbing Akademik (PA).</p></li><li><p style=\"text-align: justify;\"><strong>Pelaksanaan:</strong> Ikuti ujian atau penugasan dari dosen pengampu mata kuliah terkait.</p></li></ol><p style=\"text-align: justify;\"><em>Catatan: Nilai maksimal remedial disesuaikan dengan peraturan akademik program studi masing-masing.</em></p>', '[\"remedial\",\"remedi\",\"perbaikan nilai\",\"nilai kurang\",\"tidak lulus mata kuliah\",\"daftar remedi\",\"biaya remedial\",\"siakad remedi\"]', 'Aktif', 0, 0, '2026-06-08 22:53:34', '2026-06-24 20:10:04'),
(395, 'Akademik', 'Semester Pendek', 'Apa syarat agar mahasiswa bisa mengambil semester pendek (SP) di UPITRA?', '<p style=\"text-align: justify;\">Mahasiswa dapat mengikuti program Semester Pendek (SP) di UPITRA dengan memenuhi syarat berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Status Aktif:</strong> Terdaftar sebagai mahasiswa aktif pada semester berjalan (tidak sedang cuti).</p></li><li><p style=\"text-align: justify;\"><strong>Ketentuan Mata Kuliah:</strong> Mengambil mata kuliah yang ingin diperbaiki nilainya atau mata kuliah baru yang diizinkan oleh prodi.</p></li><li><p style=\"text-align: justify;\"><strong>Batas SKS:</strong> Maksimal beban studi yang dapat diambil adalah 9 SKS.</p></li><li><p style=\"text-align: justify;\"><strong>Administrasi:</strong> Mendaftar melalui SIAKAD dan melunasi biaya SP per SKS sesuai tarif berlaku.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"SKS semester pendek\",\"maksimal SKS SP\",\"batasan SKS pendek\",\"kuliah pendek\"]', 'Aktif', 0, 0, '2026-06-08 22:53:50', '2026-06-24 20:11:33'),
(396, 'Akademik', 'Surat keterangan aktif', 'Bagaimana cara mengajukan Surat Keterangan Mahasiswa Aktif?', '<p style=\"text-align: justify;\">Prosedur pengajuan Surat Keterangan Mahasiswa Aktif untuk tunjangan orang tua adalah sebagai berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Pengajuan Online:</strong> Masuk ke Portal Akademik Mahasiswa, lalu pilih menu layanan surat keterangan.</p></li><li><p style=\"text-align: justify;\"><strong>Isi Formulir:</strong> Lengkapi data yang diminta (nama, instansi tujuan, dan NIP orang tua jika diperlukan).</p></li><li><p style=\"text-align: justify;\"><strong>Verifikasi:</strong> Proses verifikasi oleh Administrasi Akademik membutuhkan waktu 1–2 hari kerja.</p></li><li><p style=\"text-align: justify;\"><strong>Pengambilan:</strong> Unduh dokumen digital ber-undangan resmi (<em>e-sign</em>) atau ambil langsung di loket layanan akademik.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"surat aktif kuliah\",\"surat keterangan aktif\",\"tunjangan orang tua\",\"urus surat aktif\",\"surat aktif\",\"keterangan aktif kuliah\",\"surat tunjangan\",\"tunjangan instansi\",\"surat bapak ibu\",\"slip aktif kuliah\"]', 'Aktif', 0, 0, '2026-06-08 22:54:07', '2026-06-24 20:11:26'),
(397, 'Biaya Kuliah', 'Telat bayar', 'Apakah ada denda jika telat bayar cicilan kuliah?', '<p style=\"text-align: justify;\"><strong>Ya, terdapat ketentuan denda administratif</strong> bagi mahasiswa yang terlambat membayar cicilan uang kuliah melewati batas tanggal (tenggat waktu) yang telah ditentukan pada kalender akademik atau perjanjian cicilan.</p><ul><li><p style=\"text-align: justify;\">⚠️ <strong>Denda Keterlambatan:</strong> Dikenakan biaya denda flat sebesar nominal yang ditetapkan per prodi/kebijakan keuangan, atau berupa penangguhan sementara akses SIAKAD jika keterlambatan melewati batas toleransi.</p></li><li><p style=\"text-align: justify;\">💡 <strong>Saran:</strong> Jika mengalami kendala keuangan yang mendesak, mahasiswa sangat disarankan untuk mengajukan surat permohonan penundaan/keringanan ke bagian keuangan sebelum tanggal jatuh tempo agar terhindar dari denda atau sanksi akademik.</p></li></ul><p style=\"text-align: justify;\"></p>', '[\"denda kuliah\",\"telat bayar\",\"keterlambatan cicilan\",\"sanksi bayar kuliah\",\"jatuh tempo spp\",\"denda upitra\",\"telat bayar spp\"]', 'Aktif', 0, 0, '2026-06-08 22:54:30', '2026-06-24 20:16:12'),
(398, 'Biaya Kuliah', 'Tunda bayar', 'Cara mengajukan penundaan bayar kuliah', '<p style=\"text-align: justify;\">Prosedur pengajuan keringanan atau penundaan pembayaran kuliah di UPITRA adalah sebagai berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Ajukan Surat Permohonan:</strong> Unduh dan isi formulir permohonan penundaan/keringanan pembayaran yang ditujukan kepada Bagian Keuangan.</p></li><li><p style=\"text-align: justify;\"><strong>Melampirkan Bukti Pendukung:</strong> Sertakan dokumen pendukung (seperti surat keterangan penghasilan orang tua, surat PHK, atau bukti kendala finansial lainnya).</p></li><li><p style=\"text-align: justify;\"><strong>Persetujuan Otoritas:</strong> Mintalah tanda tangan persetujuan dari Dosen Pembimbing Akademik (PA) dan Ketua Program Studi (Prodi).</p></li><li><p style=\"text-align: justify;\"><strong>Verifikasi Keuangan:</strong> Serahkan berkas ke Biro Keuangan untuk divalidasi. Jika disetujui, sistem SIAKAD akan menyesuaikan tenggat waktu pembayaran baru Anda.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"keringanan kuliah\",\"tunda bayar\",\"penundaan spp\",\"surat permohonan tunda\",\"keringanan biaya\",\"telat bayar kuliah\",\"dispensasi kuliah\"]', 'Aktif', 0, 0, '2026-06-08 22:54:47', '2026-06-24 20:16:24'),
(399, 'Biaya Kuliah', 'Praktikum', 'Apakah biaya praktikum laboratorium sudah termasuk ke dalam biaya semesteran (UKS)?', '<p><strong>Ya, biaya praktikum laboratorium umumnya sudah termasuk (include) ke dalam Uang Kuliah Semesteran (UKS)</strong> untuk mata kuliah wajib yang Anda ambil pada semester berjalan.</p><p>Namun, khusus untuk beberapa program studi yang memerlukan bahan habis pakai spesifik, alat penunjang ekstra, atau sertifikasi kompetensi laboratorium tertentu, mungkin akan dikenakan biaya penyesuaian. Informasi mendetail mengenai hal ini akan diumumkan oleh program studi masing-masing sebelum masa perkuliahan dimulai.</p>', '[\"biaya praktikum\",\"uang lab\",\"biaya laboratorium\",\"uks upitra\",\"komponen uks\",\"praktikum bayar lagi\",\"spp include praktikum\"]', 'Aktif', 0, 0, '2026-06-08 22:55:14', '2026-06-23 19:10:44'),
(400, 'Fasilitas & Layanan', 'Peminjaman Perpustakaan', 'Bagaimana cara meminjam buku di perpustakaan UPITRA dan berapa hari batas maksimal peminjamannya?', '<p>Prosedur peminjaman buku di Perpustakaan UPITRA adalah sebagai berikut:</p><ol><li><p><strong>Kunjungi Perpustakaan:</strong> Mahasiswa datang langsung ke area perpustakaan kampus atau menelusuri katalog buku secara digital melalui <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://siper.upitra.ac.id\">SIPER UPITRA</a>.</p></li><li><p><strong>Tunjukkan KTM:</strong> Pilih buku yang ingin dipinjam, lalu bawa ke meja sirkulasi dengan menunjukkan Kartu Tanda Mahasiswa (KTM) aktif sebagai bukti keanggotaan.</p></li><li><p><strong>Batas Peminjaman:</strong> Batas maksimal peminjaman buku umumnya adalah <strong>7 hari (1 minggu)</strong> dengan jumlah maksimal 2–3 buku (sesuai regulasi berjalan).</p></li><li><p><strong>Perpanjangan &amp; Keterlambatan:</strong> Peminjaman dapat diperpanjang sebanyak 1 kali jika buku tidak sedang dipesan oleh mahasiswa lain. Keterlambatan pengembalian akan dikenakan sanksi denda administratif per hari per buku.</p></li></ol><p></p>', '[\"cara pinjam buku\",\"pinjam perpustakaan\",\"batas pinjam buku\",\"denda perpustakaan\",\"siper upitra\",\"durasi pinjam buku\",\"pengembalian buku\"]', 'Aktif', 0, 0, '2026-06-08 22:55:39', '2026-06-23 21:24:29'),
(401, 'Fasilitas & Layanan', 'Fasilitas Lab', 'Apakah ada fasilitas ruang komputer (lab) yang bisa digunakan mahasiswa di luar jam kuliah?', '<p><strong>Ya, mahasiswa UPITRA dapat menggunakan fasilitas laboratorium komputer di luar jam kuliah</strong> untuk keperluan mengerjakan tugas, riset, atau proyek akademik.</p><p><strong>Ketentuan penggunaan:</strong></p><ol><li><p><strong>Izin Penggunaan:</strong> Mahasiswa wajib melapor dan meminta izin kepada laboran atau penjaga lab yang bertugas sebelum menggunakan ruangan.</p></li><li><p><strong>Jadwal Kosong:</strong> Fasilitas hanya dapat digunakan selama laboratorium tidak sedang dipakai untuk kegiatan praktikum resmi atau kelas perkuliahan lain.</p></li><li><p><strong>Menjaga Ketertiban:</strong> Mahasiswa diharapkan ikut menjaga kebersihan, ketertiban, serta tidak mengubah konfigurasi perangkat keras maupun perangkat lunak di dalam lab.</p></li></ol><p></p>', '[\"pinjam lab komputer\",\"fasilitas lab\",\"pake lab luar jam kuliah\",\"laboratorium komputer\",\"akses lab upitra\",\"nugas di lab\",\"jam buka lab\"]', 'Aktif', 0, 0, '2026-06-08 22:56:20', '2026-06-23 21:32:20'),
(402, 'Fasilitas & Layanan', 'Wifi', 'Bagaimana cara mengakses fasilitas Wi-Fi kampus dan di mana saya bisa mendapatkan akunnya?', '<p>Untuk mengakses fasilitas Wi-Fi di lingkungan kampus UPITRA, mahasiswa dapat mengikuti langkah-langkah berikut:</p><ol><li><p><strong>Pilih Jaringan:</strong> Aktifkan Wi-Fi pada perangkat Anda, lalu hubungkan ke SSID/nama jaringan Wi-Fi resmi kampus yang tersedia.</p></li><li><p><strong>Login Akun:</strong> Setelah terhubung, halaman masuk (<em>captive portal</em>) akan otomatis muncul. Masukkan username dan password akun Wi-Fi Anda.</p></li></ol><p><strong>Di mana mendapatkan akun Wi-Fi?</strong></p><ul><li><p>Akun Wi-Fi mahasiswa biasanya dibuat secara otomatis menggunakan <strong>NIM</strong> sebagai username dan password bawaan yang diberikan saat registrasi awal/aktivasi portal akademik.</p></li><li><p>Jika Anda belum menerima akun, lupa password, atau mengalami kendala koneksi, silakan hubungi bagian <strong>Biro IT</strong> di gedung kampus untuk dibantu reset atau aktivasi.</p></li></ul><p></p>', '[\"cara konek wifi\",\"password wifi kampus\",\"akun wifi upitra\",\"wifi error\",\"layanan it wifi\",\"it support wifi\",\"internet kampus\"]', 'Aktif', 0, 0, '2026-06-08 22:56:33', '2026-06-23 21:33:53'),
(403, 'Immersion Program', 'Syarat Immersion', 'Apa saja persyaratan administrasi dan akademik untuk bisa mengikuti Immersion Program?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:56:57', '2026-06-08 22:56:57'),
(405, 'Immersion Program', 'Konversi SKS', 'Bagaimana skema konversi SKS setelah mahasiswa menyelesaikan Immersion Program di industri?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:57:24', '2026-06-08 22:57:24'),
