(407, 'Karir & Alumni', 'Bimbingan karir', 'Apakah ada program bimbingan karier atau pembuatan CV gratis bagi mahasiswa tingkat akhir?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:58:00', '2026-06-08 22:58:00'),
(408, 'Karir & Alumni', 'Kontribusi', 'Bagaimana kontribusi Ikatan Alumni UPITRA dalam membantu lulusan baru mendapat pekerjaan?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:58:53', '2026-06-08 22:58:53'),
(409, 'Kemahasiswaan', 'UKM', 'Bagaimana prosedur dan syarat mengajukan pendirian UKM (Unit Kegiatan Mahasiswa) baru?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:59:11', '2026-06-08 22:59:11'),
(410, 'Kemahasiswaan', 'Bantuan Dana', 'Apakah ada dana bantuan atau insentif dari kampus untuk mahasiswa yang menang lomba tingkat nasional?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:59:26', '2026-06-08 22:59:26'),
(411, 'Kemahasiswaan', 'Informasi BEM', 'Di mana mahasiswa bisa mendapatkan informasi mengenai pemilihan Ketua BEM UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 22:59:38', '2026-06-08 22:59:38'),
(412, 'Kerjasama', 'Kerjasama', 'Apa keuntungan langsung bagi mahasiswa dengan adanya kerja sama antara UPITRA dan Triputra Group?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:00:05', '2026-06-08 23:00:05'),
(413, 'Kerjasama', 'Program Magang', 'Apakah ada program magang khusus yang jalurnya diprioritaskan melalui kemitraan industri UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:00:27', '2026-06-08 23:00:27'),
(414, 'Penerimaan Mahasiswa Baru', NULL, 'Apakah UPITRA menerima pendaftaran mahasiswa pindahan atau transfer dari kampus lain?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:01:48', '2026-06-08 23:01:48'),
(415, 'Penerimaan Mahasiswa Baru', NULL, 'Kapan batas akhir pendaftaran untuk PMB Gelombang Terakhir tahun ini?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:01:59', '2026-06-08 23:01:59'),
(416, 'Penerimaan Mahasiswa Baru', NULL, 'Apakah ada tes seleksi masuk khusus (seperti TPA atau wawancara) untuk jalur reguler?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:02:15', '2026-06-08 23:02:15'),
(417, 'Program Studi', NULL, 'Siapa nama Rektor Universitas Pignatelli Triputra yang menjabat saat ini?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:02:40', '2026-06-08 23:02:40'),
(418, 'Program Studi', NULL, 'Apakah program studi di UPITRA sudah terakreditasi oleh BAN-PT/LAM?', '<p style=\"text-align: justify;\"><strong>Ya, seluruh program studi di Universitas Pignatelli Triputra (UPITRA) telah resmi terakreditasi</strong> oleh Badan Akreditasi Nasional Perguruan Tinggi (<strong>BAN-PT</strong>) maupun Lembaga Akreditasi Mandiri terkait (seperti <strong>LAM-INFOKOM</strong> untuk rumpun ilmu komputer dan <strong>LAMEMBA</strong> untuk rumpun ekonomi dan bisnis).</p><p style=\"text-align: justify;\">Program studi baru di UPITRA telah memenuhi syarat akreditasi minimal untuk penyelenggaraan pendidikan, sementara program studi lainnya telah berhasil meraih predikat peringkat <strong>Baik</strong> hingga <strong>Baik Sekali</strong>.</p><p style=\"text-align: justify;\"><em>Untuk melihat detail nomor SK serta peringkat akreditasi terbaru dari masing-masing program studi secara lengkap, Anda dapat mengunjungi laman resmi </em><strong><em>Lembaga Penjaminan Mutu (LPM) UPITRA</em></strong><em> atau melalui tautan resmi </em><a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://lpm.upitra.ac.id\"><em>LPM UPITRA</em></a><em>.</em></p>', '[\"akreditasi prodi\",\"akreditasi kampus\",\"ban-pt upitra\",\"lam-infokam\",\"lamemba upitra\",\"status akreditasi\",\"apakah upitra terakreditasi\",\"sertifikat akreditasi\",\"nilai akreditasi jurusan\",\"legalitas hukum prodi\",\"cek akreditasi\"]', 'Aktif', 0, 0, '2026-06-08 23:03:06', '2026-06-25 00:45:08'),
(419, 'Program Studi', 'FST', 'Apa keunggulan memilih prodi bidang teknik/komputer di UPITRA dibanding kampus lain?', '<p style=\"text-align: justify;\">Memilih program studi bidang komputer dan teknologi di <strong>Fakultas Sains &amp; Teknologi (FST) UPITRA</strong> memberikan beberapa keunggulan strategis bagi mahasiswa, di antaranya:</p><ul><li><p style=\"text-align: justify;\"><strong>Kurikulum Berbasis Kebutuhan Industri:</strong> Program pembelajaran dirancang secara dinamis agar selaras dengan perkembangan teknologi global terkini, seperti fokus pada <em>Artificial Intelligence</em> (AI), <em>Machine Learning</em>, <em>DevOps</em>, hingga <em>Cyber Security</em>.</p></li><li><p style=\"text-align: justify;\"><strong>Dosen Praktisi &amp; Ahli:</strong> Dibimbing oleh jajaran dosen kompeten yang memiliki sertifikasi keahlian profesional dan rekam jejak aktif di dunia industri teknologi, rekayasa perangkat lunak, serta riset data.</p></li><li><p style=\"text-align: justify;\"><strong>Fasilitas Laboratorium Modern:</strong> Didukung oleh infrastruktur IT dan fasilitas laboratorium komputer yang mumpuni untuk menunjang kebutuhan praktikum pemrograman, pengembangan sistem, hingga pengerjaan proyek digital mahasiswa.</p></li><li><p style=\"text-align: justify;\"><strong>Kemitraan Luas (Triputra Group):</strong> Memiliki jaringan kerja sama yang kuat dengan dunia usaha dan industri (DUDI), membuka peluang besar bagi mahasiswa dalam program magang kerja (<em>internship</em>), riset kolaboratif, hingga serapan karier lulusan yang tinggi.</p></li></ul><p style=\"text-align: justify;\"></p>', '[\"keunggulan fst\",\"kelebihan informatika upitra\",\"kenapa pilih upitra\",\"fasilitas lab komputer\",\"prospek prodi IT\",\"keunggulan software engineering\",\"sistem informasi vs informatika\",\"keuntungan kuliad di upitra\",\"kerja sama upitra\"]', 'Aktif', 0, 0, '2026-06-08 23:03:24', '2026-06-25 00:50:10'),
(420, 'Riset & Publikasi', NULL, 'Bagaimana cara mahasiswa mengakses jurnal ilmiah atau prosiding hasil riset dosen UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:04:41', '2026-06-08 23:04:41'),
(421, 'Riset & Publikasi', NULL, 'Apakah ada bantuan dana atau insentif untuk mahasiswa yang berhasil mempublikasikan skripsinya di jurnal terakreditasi?', NULL, '[]', 'Kosong', 0, 0, '2026-06-08 23:04:56', '2026-06-08 23:04:56'),
(422, 'Teknologi & Sistem', NULL, 'Bagaimana cara mengatasi jika UNITY atau SIAKAD error?', '<p>Jika Anda mengalami kendala <em>error</em>, <em>blank</em>, atau tidak bisa memuat halaman saat mengakses aplikasi UNITY atau SIAKAD, silakan coba beberapa langkah solutif berikut:</p><ol><li><p><strong>Bersihkan Cache Browser:</strong> Hapus <em>cache</em> dan <em>cookies</em> pada peramban (browser) yang Anda gunakan, atau coba akses menggunakan mode samaran (<em>Incognito Window</em>).</p></li><li><p><strong>Periksa Koneksi Internet:</strong> Pastikan perangkat Anda terhubung dengan jaringan internet yang stabil atau Wi-Fi resmi kampus UPITRA.</p></li><li><p><strong>Coba Perangkat Lain:</strong> Gunakan perangkat (<em>device</em>) atau browser alternatif untuk memastikan kendala bukan berasal dari setelan lokal gawai Anda.</p></li></ol><p><em>Apabila sistem tetap menampilkan pesan error atau sedang dalam masa perbaikan (maintenance), silakan hubungi langsung </em><strong><em>Biro Teknologi Informasi</em></strong><em> untuk mendapatkan bantuan teknis lebih lanjut.</em></p>', '[\"unity error\",\"siakad error\",\"gagal akses siakad\",\"aplikasi blank\",\"tidak bisa buka unity\",\"sistem down\",\"it helpdesk\"]', 'Aktif', 0, 0, '2026-06-08 23:05:09', '2026-07-01 01:20:20'),
(423, 'Teknologi & Sistem', NULL, 'Apakah data KRS otomatis tersinkronisasi dengan dosen wali?', '<p><strong>Ya, data pengisian KRS online di portal mahasiswa akan langsung tersinkronisasi secara real-time dengan sistem SIAKAD milik Dosen Wali.</strong></p><p>Namun, perlu diperhatikan proses berikut:</p><ol><li><p><strong>Status Ajuan:</strong> Setelah Anda selesai memilih matakuliah dan menyimpannya, status KRS Anda akan masuk ke daftar antrean persetujuan (<em>approval</em>) di akun dosen wali.</p></li><li><p><strong>Bimbingan &amp; Validasi:</strong> Mahasiswa disarankan untuk tetap melakukan konsultasi/bimbingan dengan Dosen Wali agar rencana studi yang diambil disetujui (di-validasi) sehingga status KRS Anda resmi aktif.</p></li></ol><p><em>Jika setelah melakukan pengisian data tidak muncul di sistem dosen wali, kemungkinan terjadi kendala sinkronisasi. Silakan laporkan hal ini ke </em><strong><em>Biro Teknologi Informasi</em></strong><em>.</em></p>', '[\"sinkronisasi krs\",\"krs dosen wali\",\"acc krs\",\"persetujuan krs\",\"siakad dosen\",\"bimbingan akademik\"]', 'Aktif', 0, 0, '2026-06-08 23:05:28', '2026-07-01 01:20:42'),
(425, 'Akademik', 'Sidang Skripsi', 'Apa saja syarat pendaftaran sidang skripsi?', '<p style=\"text-align: justify;\">Untuk mendaftar Sidang Skripsi/Tugas Akhir di UPITRA, mahasiswa wajib memenuhi syarat akademik berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Kelulusan Mata Kuliah:</strong> Telah menempuh minimal 138 SKS (atau sesuai ketentuan prodi), tidak ada nilai E, dan nilai D tidak melebihi batas maksimal.</p></li><li><p style=\"text-align: justify;\"><strong>Bimbingan Selesai:</strong> Menyelesaikan bimbingan dengan Dosen Pembimbing I &amp; II (dibuktikan dengan kartu/log bimbingan).</p></li><li><p style=\"text-align: justify;\"><strong>Persetujuan (Approval):</strong> Mendapat rekomendasi/persetujuan maju sidang dari Dosen Pembimbing dan Ketua Program Studi.</p></li><li><p style=\"text-align: justify;\"><strong>Syarat Tambahan:</strong> Memiliki sertifikat TOEFL dengan skor minimal serta bukti publikasi ilmiah/jurnal (jika diwajibkan prodi).</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"syarat sidang skripsi\",\"daftar sidang\",\"sidang tugas akhir\",\"persyaratan ujian skripsi\",\"sidang TA\",\"ujian skripsi\",\"daftar pendadaran\",\"persyaratan TA\",\"kelulusan skripsi\",\"toefl skripsi\",\"jurnal skripsi\",\"sks sidang\",\"persetujuan pembimbing\"]', 'Aktif', 0, 0, '2026-06-10 20:24:40', '2026-06-24 20:11:17'),
(427, 'Akademik', 'Portal Orang Tua', 'Bagaimana cara orang tua melihat IPK/nilai mahasiswa?', '<p style=\"text-align: justify;\">Orang tua dapat memantau perkembangan nilai (IPS/IPK) dan kehadiran mahasiswa melalui <strong>Portal Pantauan Orang Tua</strong> dengan langkah berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Akses Halaman:</strong> Buka halaman khusus pemantauan orang tua yang terintegrasi di sistem akademik UPITRA.</p></li><li><p style=\"text-align: justify;\"><strong>Login Sistem:</strong> Masuk menggunakan <strong>Parent ID</strong> dan <em>password</em> yang dikirimkan kampus ke kontak resmi orang tua saat registrasi awal.</p></li><li><p style=\"text-align: justify;\"><strong>Cek Nilai:</strong> Pilih menu <strong>\"Laporan Hasil Studi\"</strong> untuk melihat grafik dan detail perkembangan nilai mahasiswa dari semester ke semester.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"portal orang tua\",\"pantauan ortu\",\"cek nilai anak\",\"parent id upitra\",\"nilai anak\",\"kehadiran anak\",\"rapor kuliah\",\"akun orang tua\",\"ips mahasiswa\"]', 'Aktif', 0, 0, '2026-06-10 20:25:15', '2026-06-24 20:11:52'),
(428, 'Akademik', 'Cuti akademik', 'Bagaimana prosedur dan syarat cuti akademik?', '<p style=\"text-align: justify;\"><strong>Syarat &amp; Ketentuan Cuti Akademik:</strong></p><ul><li><p style=\"text-align: justify;\"><strong>Syarat:</strong> Minimal telah menempuh 2 semester pertama dan tidak ada tunggakan biaya kuliah.</p></li><li><p style=\"text-align: justify;\"><strong>Batas Waktu:</strong> Diajukan maksimal <strong>2 minggu sebelum semester baru dimulai</strong>.</p></li><li><p style=\"text-align: justify;\"><strong>Batas Periode:</strong> Maksimal <strong>2 semester</strong> selama masa studi.</p></li></ul><p style=\"text-align: justify;\"><strong>Prosedur Pengajuan:</strong></p><ol><li><p style=\"text-align: justify;\">Unduh dan isi formulir permohonan cuti akademik.</p></li><li><p style=\"text-align: justify;\">Minta tanda tangan/persetujuan dari <strong>Dosen PA</strong> dan <strong>Ketua Prodi</strong>.</p></li><li><p style=\"text-align: justify;\">Serahkan formulir ke <strong>Biro Administrasi Akademik</strong> untuk penerbitan SK Cuti Resmi.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"cuti akademik\",\"prosedur cuti\",\"syarat libur kuliah\",\"berhenti kuliah sementara\",\"cuti kuliah\",\"sk cuti\",\"libur semesteran\",\"istirahat kuliah\",\"off kuliah\",\"maksimal cuti\",\"batas pengajuan cuti\",\"mangkir kuliah\"]', 'Aktif', 0, 0, '2026-06-10 20:25:29', '2026-06-24 20:12:08'),
(429, 'Akademik', 'Student exchange', 'Bagaimana cara konversi nilai pertukaran pelajar?', '<p style=\"text-align: justify;\">Alur konversi nilai bagi mahasiswa program pertukaran pelajar adalah sebagai berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Learning Agreement:</strong> Sebelum program dimulai, konsultasikan dan cocokkan mata kuliah universitas mitra dengan kurikulum prodi Anda di UPITRA.</p></li><li><p style=\"text-align: justify;\"><strong>Serah Transkrip:</strong> Setelah program selesai, serahkan salinan transkrip nilai resmi dari universitas mitra ke bagian akademik fakultas.</p></li><li><p style=\"text-align: justify;\"><strong>Penyetaraan Nilai:</strong> Tim kurikulum prodi akan memetakan kompetensi dan mengonversi bobot nilai ke skala UPITRA (A, B, C, dst.) untuk diinput ke Transkrip Nilai Kumulatif.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"konversi nilai pertukaran\",\"learning agreement\",\"transfer nilai\",\"nilai mahasiswa inbound\",\"student exchange\",\"pertukaran mahasiswa\",\"kampus merdeka\",\"pkm\",\"kuliah diluar\",\"nilai transkrip\",\"penyetaraan nilai\",\"pindahan nilai\",\"sks luar kampus\"]', 'Aktif', 0, 0, '2026-06-10 20:25:47', '2026-06-24 20:12:14'),
(431, 'Akademik', 'Hybrid Learning', 'Apakah kuliah di UPITRA menggunakan sistem hybrid?', '<p style=\"text-align: justify;\">UPITRA menerapkan sistem <strong>Hybrid Learning</strong> (kombinasi kuliah tatap muka/luring dan daring).</p><ul><li><p style=\"text-align: justify;\"><strong>Sesi Luring (Offline):</strong> Diutamakan untuk kegiatan interaktif seperti praktikum, proyek tim, studi kasus, dan ujian.</p></li><li><p style=\"text-align: justify;\"><strong>Sesi Daring (Online):</strong> Penyampaian materi teori dan penugasan mandiri difasilitasi secara fleksibel melalui platform <em>Learning Management System</em> (LMS) resmi kampus.</p></li></ul><p style=\"text-align: justify;\"></p>', '[\"hybrid learning\",\"kuliah online offline\",\"sistem perkuliahan\",\"tatap muka upitra\",\"lms upitra\",\"e-learning\",\"kuliah daring\",\"kuliah luring\",\"pembelajaran jarak jauh\",\"apakah harus ke kampus\",\"kuliah dari rumah\",\"jadwal online\"]', 'Aktif', 0, 0, '2026-06-10 20:26:15', '2026-06-24 20:12:25'),
(432, 'Akademik', 'Ganti PA', 'Bagaimana cara mengganti dosen pembimbing akademik (PA)?', '<p style=\"text-align: justify;\">Jika Dosen Pembimbing Akademik (PA) berhalangan tetap (pensiun, studi lanjut, atau mengundurkan diri), mahasiswa dapat mengajukan penggantian dengan prosedur berikut:</p><ol><li><p style=\"text-align: justify;\"><strong>Melapor ke Prodi:</strong> Ajukan permohonan penggantian dosen PA baru secara tertulis atau lisan ke Ketua/Sekretaris Program Studi.</p></li><li><p style=\"text-align: justify;\"><strong>Proses Plotting:</strong> Program Studi akan menunjuk dosen pengganti berdasarkan kuota bimbingan yang tersedia.</p></li><li><p style=\"text-align: justify;\"><strong>Pembaruan Sistem:</strong> Bagian Administrasi Akademik akan memperbarui data dosen PA Anda di SIAKAD.</p></li><li><p style=\"text-align: justify;\"><strong>Konfirmasi:</strong> Mahasiswa dapat melihat nama dosen PA terbaru di portal masing-masing dan segera melakukan koordinasi.</p></li></ol><p style=\"text-align: justify;\"></p>', '[\"ganti dosen PA\",\"pembimbing akademik berhalangan\",\"dosen PA pensiun\",\"plotting PA baru\"]', 'Aktif', 0, 0, '2026-06-10 20:26:29', '2026-06-24 20:12:32');
INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(433, 'Akademik', 'TOEFL Score', 'Berapa skor minimal TOEFL untuk syarat wisuda?', '<p style=\"text-align: justify;\">Syarat minimal skor TOEFL/EPT untuk kelulusan wisuda di UPITRA adalah:</p><ul><li><p style=\"text-align: justify;\">🇬🇧 <strong>Prodi Non-Bahasa Inggris:</strong> Minimal <strong>450</strong>.</p></li><li><p style=\"text-align: justify;\">🌐 <strong>Prodi Bahasa Inggris / Kelas Internasional:</strong> Minimal <strong>500</strong>.</p></li></ul><p style=\"text-align: justify;\"><em>Sertifikat wajib dikeluarkan oleh Pusat Bahasa UPITRA atau lembaga resmi yang diakui. Mahasiswa disarankan mengambil tes sebelum semester akhir.</em></p>', '[\"toefl wisuda\",\"skor toefl\",\"syarat bahasa inggris\",\"ept upitra\",\"minimal toefl\",\"pusat bahasa\",\"syarat lulus\"]', 'Aktif', 0, 0, '2026-06-10 20:26:45', '2026-06-24 20:12:41'),
(434, 'Biaya Kuliah', 'Info Komponen Biaya', 'Apa saja komponen biaya yang sudah termasuk dalam uang pangkal pada semester pertama?', '<p style=\"text-align: justify;\">Uang pangkal pada semester pertama di UPITRA merupakan biaya investasi pendidikan awal yang umumnya sudah mencakup komponen-komponen berikut:</p><ul><li><p style=\"text-align: justify;\">💳 <strong>Biaya Matrikulasi/PPSMB:</strong> Kegiatan orientasi dan pengenalan kampus bagi mahasiswa baru.</p></li><li><p style=\"text-align: justify;\">👔 <strong>Atribut Mahasiswa:</strong> Jas almamater, dasi, kartu tanda mahasiswa (KTM), dan perlengkapan resmi lainnya.</p></li><li><p style=\"text-align: justify;\">🪪 <strong>Layanan Akademik Awal:</strong> Pembuatan akun sistem informasi akademik (SIAKAD), e-learning, serta fasilitas perpustakaan.</p></li></ul><p style=\"text-align: justify;\"><em>Catatan: Komponen ini tidak mencakup Uang Kuliah Semesteran (UKS) atau biaya praktikum khusus (jika ada di prodi tertentu). Detail rincian resmi per angkatan dapat dilihat di lampiran surat keputusan admisi Anda.</em></p>', '[\"uang pangkal\",\"komponen uang pangkal\",\"biaya semester 1\",\"dapat almamater\",\"rincian uang pangkal\",\"biaya awal masuk\",\"uang gedung\"]', 'Aktif', 0, 0, '2026-06-10 20:27:05', '2026-06-24 20:16:36'),
(436, 'Biaya Kuliah', 'Keringanan Biaya', 'Syarat mengajukan keringanan biaya kuliah ?', '<p style=\"text-align: justify;\">Syarat umum yang diperlukan bagi mahasiswa aktif untuk mengajukan keringanan atau potongan biaya kuliah di UPITRA meliputi:</p><ol><li><p style=\"text-align: justify;\"><strong>Surat Permohonan:</strong> Formulir resmi pengajuan keringanan yang ditandatangani oleh mahasiswa dan orang tua/wali.</p></li><li><p style=\"text-align: justify;\"><strong>Bukti Kemampuan Ekonomi:</strong> Slip gaji orang tua, surat keterangan penghasilan dari kelurahan, atau surat pernyataan terdampak kendala finansial (seperti PHK/usahabangkrut).</p></li><li><p style=\"text-align: justify;\"><strong>Dokumen Pendukung:</strong> Fotokopi Kartu Keluarga (KK) dan bukti pembayaran PBB atau rekening listrik terbaru.</p></li><li><p style=\"text-align: justify;\"><strong>Syarat Akademik:</strong> Nilai KHS terakhir menunjukkan mahasiswa tidak sedang dalam masa sanksi akademik (beberapa program mensyaratkan IPK minimum tertentu).</p></li></ol><p style=\"text-align: justify;\"><em>Berkas diajukan kepada Biro Keuangan setelah mendapatkan rekomendasi atau persetujuan dari Dosen Pembimbing Akademik (PA).</em></p>', '[\"syarat keringan\",\"syarat potongan kuliah\",\"pengajuan potongan spp\",\"keringanan mahasiswa aktif\",\"berkas diskon kuliah\",\"bantuan biaya kuliah\"]', 'Aktif', 0, 0, '2026-06-10 20:27:34', '2026-06-24 20:16:44'),
(437, 'Biaya Kuliah', 'Cek Tagihan', 'Mengapa tagihan virtual account anak saya belum ter-update padahal sudah melakukan pembayaran semesteran?', '<p>Jika tagihan di Virtual Account (VA) belum ter-update setelah pembayaran, hal tersebut biasanya disebabkan oleh beberapa kemungkinan:</p><ol><li><p><strong>Proses Sinkronisasi Sistem:</strong> Sistem bank dan SIAKAD membutuhkan waktu interkoneksi (biasanya 1x24 jam pada hari kerja) untuk memperbarui status secara otomatis.</p></li><li><p><strong>Metode Pembayaran Transfer Manual:</strong> Jika Anda melakukan transfer antarbank secara manual (bukan melalui menu VA), sistem tidak dapat membacanya secara otomatis.</p></li></ol><p><strong>Solusi:</strong></p><ul><li><p>Mohon simpan bukti bayar Anda dengan aman.</p></li><li><p>Kirimkan foto/tangkapan layar bukti transfer tersebut beserta <strong>Nama, NIM, dan Program Studi</strong> mahasiswa ke Bagian Keuangan Kampus atau melalui WhatsApp Biro Keuangan untuk proses verifikasi dan pemutakhiran data manual.</p></li></ul><p></p>', '[\"tagihan belum update\",\"sudah bayar tapi belum lunas\",\"virtual account error\",\"bukti bayar tidak masuk\",\"konfirmasi pembayaran\",\"gagal update siakad\",\"masalah transfer spp\"]', 'Aktif', 0, 0, '2026-06-10 20:27:50', '2026-06-23 19:17:54'),
(438, 'Biaya Kuliah', 'Info Beasiswa', 'Apakah ada beasiswa penuh sampai lulus?', '<p><strong>Ya, UPITRA menyediakan program beasiswa penuh (biaya kuliah 100% hingga lulus)</strong> bagi calon mahasiswa yang berprestasi secara akademik/non-akademik namun memiliki keterbatasan ekonomi.</p><p>Beberapa jalur beasiswa penuh yang dapat diikuti antara lain:</p><ul><li><p>🎓 <strong>Beasiswa KIP Kuliah (Kartu Indonesia Pintar):</strong> Program bantuan dari pemerintah untuk lulusan SMA/SMK/sederajat yang memenuhi kriteria kemiskinan dan prestasi.</p></li><li><p>🤝 <strong>Beasiswa Kemitraan / Yayasan:</strong> Program khusus hasil kerja sama UPITRA dengan Triputra Group atau yayasan terkait.</p></li></ul><p><em>Informasi mengenai jadwal pendaftaran, kuota, dan seleksi berkas terupdate dapat diakses langsung melalui portal PMB di </em><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.upitra.ac.id\"><em>pmb.upitra.ac.id</em></a><em>.</em></p>', '[\"beasiswa penuh\",\"beasiswa sampai lulus\",\"beasiswa 100%\",\"kip kuliah\",\"beasiswa kurang mampu\",\"beasiswa prestasi\",\"kipk upitra\"]', 'Aktif', 0, 0, '2026-06-10 20:28:03', '2026-06-23 19:20:33'),
(439, 'Biaya Kuliah', 'Sanksi Keterlambatan', 'Sanksi telat bayar UKT melewati batas akademik ?', '<p>Mahasiswa yang terlambat membayar UKT melewati batas waktu yang telah ditentukan dalam kalender akademik akan dikenakan sanksi administratif berupa:</p><ul><li><p>🚫 <strong>Penangguhan Akses SIAKAD:</strong> Mahasiswa tidak dapat melakukan pengisian KRS untuk semester berjalan.</p></li><li><p>📉 <strong>Status Akademik Non-Aktif:</strong> Status mahasiswa pada semester tersebut otomatis dinyatakan <strong>\"Mangkir\"</strong> atau <strong>\"Cuti Akademik Non-Aktif\"</strong>, kecuali jika sudah mengajukan penundaan resmi sebelum tenggat waktu.</p></li><li><p>⏱️ <strong>Keterlambatan Kelulusan:</strong> Seluruh aktivitas perkuliah, penginputan nilai, dan bimbingan tidak dapat diproses di sistem selama status pembayaran belum diselesaikan.</p></li></ul><p></p>', '[\"sanksi telat bayar\",\"konsekuensi telat ukt\",\"lupa bayar ukt\",\"siakad dikunci\",\"mangkir kuliah\",\"telat krs\",\"karena ukt\",\"dampat telat bayar\"]', 'Aktif', 0, 0, '2026-06-10 20:28:19', '2026-06-23 19:22:26'),
(441, 'Biaya Kuliah', 'Pengembalian Dana', 'Regulasi pengembalian uang kuliah jika mundur ?', '<p>Regulasi pengembalian dana kuliah bagi mahasiswa yang mengundurkan diri di UPITRA diatur berdasarkan waktu pengajuan pemutusan studi:</p><ul><li><p>🗓️ <strong>Sebelum Perkuliahan Dimulai:</strong> Dana yang sudah dibayarkan (seperti UKS) dapat dikembalikan sebagian setelah dipotong biaya administrasi resmi dan biaya atribut/matrikulasi yang sudah diproses (jika ada).</p></li><li><p>🏫 <strong>Setelah Perkuliahan Berjalan:</strong> Jika mahasiswa mengundurkan diri setelah masa perkuliahan aktif dimulai, maka seluruh biaya semester berjalan yang telah dibayarkan tidak dapat ditarik kembali.</p></li></ul><p><em>Prosedur pengajuan wajib menyertakan Surat Pengunduran Diri resmi dari prodi dan bukti bebas tanggungan kampus. Ketentuan persentase pengembalian detail dapat dikonfirmasi langsung ke Biro Keuangan.</em></p>', '[\"pengembalian dana\",\"mundur kuliah\",\"tarik uang kuliah\",\"refund spp\",\"batal kuliah upitra\",\"mengundurkan diri\",\"uang kembali\"]', 'Aktif', 0, 0, '2026-06-10 20:28:51', '2026-06-23 19:24:48'),
(442, 'Biaya Kuliah', 'Perbandingan Biaya', 'Berapa estimasi total biaya kuliah dari awal masuk hingga lulus untuk Program Studi Teknik Informatika?', '<p>Estimasi total biaya kuliah untuk Program Studi Teknik Informatika di UPITRA dari awal masuk hingga lulus dihitung berdasarkan komponen standar seperti Uang Pangkal (semester 1) dan Uang Kuliah Semesteran (UKS) selama 8 semester (asumsi lulus tepat waktu).</p><p>Karena nominal biaya dapat bervariasi tergantung pada gelombang pendaftaran, jalur masuk (reguler/beasiswa), serta tahun angkatan, Anda dapat melihat rincian simulasi biaya terlengkap dan mengunduh brosur tarif terbaru melalui tautan berikut:</p><ul><li><p>🌐 <strong>Portal PMB:</strong> <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.upitra.ac.id\">pmb.upitra.ac.id</a></p></li><li><p>📞 <strong>WhatsApp Admission:</strong> 0811-290-7500</p></li></ul><p></p>', '[\"biaya teknik informatika\",\"total biaya kuliah ti\",\"biaya sampai lulus\",\"estimasi biaya upitra\",\"biaya informatika\",\"uang kuliah ti\",\"biaya kuliah total\"]', 'Aktif', 0, 0, '2026-06-10 20:29:06', '2026-06-23 19:27:23'),
(443, 'Biaya Kuliah', 'Biaya Administrasi', 'Berapa biaya yang dikenakan untuk legalisir ijazah dan transkrip nilai cetak di UPITRA?', '<p>Biaya administrasi untuk pelayanan legalisir ijazah dan transkrip nilai cetak di UPITRA diatur berdasarkan jumlah lembar atau paket dokumen yang diajukan.</p><p>Untuk mengetahui nominal tarif terbaru, mekanisme pengajuan (online/offline), serta prosedur pembayarannya, silakan menghubungi bagian Layanan Akademik atau Biro Keuangan Kampus pada hari dan jam kerja.</p>', '[\"biaya legalisir\",\"legalisir ijazah\",\"legalisir transkrip\",\"harga legalisir\",\"legalisir cetak\",\"biaya administrasi alumni\",\"legalisasi dokumen\"]', 'Aktif', 0, 0, '2026-06-10 20:29:23', '2026-06-23 20:22:04'),
(444, 'Fasilitas & Layanan', 'Akses Fasilitas', 'Bagaimana prosedur peminjaman auditorium atau gedung serbaguna?', '<p>Prosedur peminjaman ruang auditorium atau gedung serbaguna untuk kegiatan organisasi mahasiswa di UPITRA adalah sebagai berikut:</p><ol><li><p><strong>Ajukan Proposal:</strong> Organisasi/UKM wajib menyusun proposal kegiatan resmi yang telah disetujui oleh Pembina Organisasi dan Wakil Rektor bidang Kemahasiswaan.</p></li><li><p><strong>Cek Ketersediaan &amp; Surat Izin:</strong> Menghubungi bagian sarana prasarana (Sarpras) atau rumah tangga kampus untuk mengecek jadwal kosong ruangan, kemudian menyerahkan Surat Peminjaman Tempat resmi.</p></li><li><p><strong>Konfirmasi &amp; Koordinasi:</strong> Setelah izin keluar, lakukan koordinasi dengan teknisi kampus terkait kebutuhan fasilitas penunjang (seperti sound system, proyektor, atau tata letak kursi) paling lambat H-3 acara.</p></li><li><p><strong>Kebersihan &amp; Ketertiban:</strong> Setelah acara selesai, organisasi peminjam wajib memastikan ruangan kembali bersih, rapi, dan semua perangkat elektronik telah dimatikan.</p></li></ol><p></p>', '[\"pinjam auditorium\",\"sewa gedung serbaguna\",\"peminjaman ruangan\",\"izin pakai gedung\",\"prosedur pinjam aula\",\"fasilitas organisasi\",\"surat peminjaman tempat\"]', 'Aktif', 0, 0, '2026-06-10 20:29:47', '2026-06-23 21:36:16'),
(445, 'Fasilitas & Layanan', 'Info Akomodasi', 'Apakah tersedia fasilitas asrama bagi mahasiswa baru?', '<p>Saat ini, UPITRA tidak menyediakan fasilitas asrama internal (milik kampus sendiri) bagi mahasiswa baru.</p><p>Namun, Anda tidak perlu khawatir karena di sekitar lingkungan kampus terdapat banyak pilihan hunian tempat tinggal seperti <strong>rumah kos (putra/putri) dan kontrakan</strong> dengan jarak yang sangat dekat dan harga sewa yang bervariasi.</p><p>Bagian Kemahasiswaan atau Ikatan Mahasiswa juga seringkali memiliki daftar rekomendasi tempat kos terpercaya di sekitar kampus yang dapat membantu mempermudah pencarian Anda.</p>', '[\"asrama upitra\",\"fasilitas asrama\",\"asrama mahasiswa baru\",\"kos dekat kampus\",\"info kosan\",\"tempat tinggal luar kota\",\"asrama maba\"]', 'Aktif', 0, 0, '2026-06-10 20:30:00', '2026-06-23 21:37:39'),
(447, 'Fasilitas & Layanan', 'Akses Perpustakaan', 'Bagaimana cara mengakses jurnal internasional yang dilanggan oleh perpustakaan pusat UPITRA secara daring?', '<p>Mahasiswa dan civitas akademika UPITRA dapat mengakses jurnal internasional yang dilanggan secara daring melalui langkah-langkah berikut:</p><ol><li><p><strong>Buka Portal Perpustakaan:</strong> Akses layanan perpustakaan digital melalui platform resmi 🌐 <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://siper.upitra.ac.id\">SIPER UPITRA</a>.</p></li><li><p><strong>Login Akun:</strong> Masuk menggunakan akun keanggotaan perpustakaan atau akun e-learning/SIAKAD Anda yang aktif.</p></li><li><p><strong>Pilih Menu Jurnal/E-Resources:</strong> Di dalam dasbor, pilih menu e-journal atau direktori database jurnal internasional yang sedang dikerjasamakan (seperti ScienceDirect, Scopus, E-Book, dll).</p></li><li><p><strong>Akses E-Repository:</strong> Anda juga dapat memanfaatkan kredensial atau <em>remote access</em> khusus yang disediakan oleh petugas perpustakaan jika ingin mengaksesnya dari luar jaringan Wi-Fi kampus. <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"https://ejournal.upitra.ac.id/index/en\">JURNAL UPITRA</a></p></li></ol><p><em>Jika mengalami kendala hak akses atau memerlukan panduan pencarian literatur spesifik, silakan langsung menghubungi staf pustakawan di Gedung Perpustakaan Pusat.</em></p>', '[\"akses jurnal internasional\",\"jurnal dilanggan upitra\",\"cara cari jurnal\",\"siper jurnal\",\"e-journal upitra\",\"jurnal daring\",\"perpus pusat jurnal\"]', 'Aktif', 0, 0, '2026-06-10 20:30:31', '2026-06-23 23:19:55'),
(448, 'Fasilitas & Layanan', 'Keamanan Kampus', 'Bagaimana sistem keamanan 24 jam di kampus dan parkiran?', '<p><strong>UPITRA berkomitmen menjaga keamanan dan kenyamanan lingkungan kampus serta area parkir selama 24 jam penuh</strong> melalui sistem keamanan terpadu berikut:</p><ol><li><p><strong>Petugas Keamanan (Satpam):</strong> Adanya personel satpam yang berjaga dan melakukan patroli rutin secara berkala di seluruh area gedung dan kantong parkir, baik siang maupun malam hari.</p></li><li><p><strong>Pengawasan CCTV:</strong> Area-area krusial, termasuk akses masuk utama, koridor gedung, serta kawasan parkir kendaraan roda dua dan roda empat dipantau melalui kamera pengawas (CCTV) selama 24 jam.</p></li><li><p><strong>Pencahayaan Area Parkir:</strong> Kantong parkir telah dilengkapi dengan fasilitas penerangan yang memadai untuk memastikan keamanan kendaraan mahasiswa dan staf yang beraktivitas hingga malam hari.</p></li></ol><p></p>', '[\"keamanan kampus\",\"satpam upitra\",\"parkir aman\",\"cctv kampus\",\"keamanan 24 jam\",\"kehilangan di kampus\",\"pos satpam\"]', 'Aktif', 0, 0, '2026-06-10 20:30:46', '2026-06-23 23:29:42'),
(449, 'Fasilitas & Layanan', 'Pengaduan Kerusakan', 'Bagaimana cara melaporkan fasilitas kelas yang rusak?', '<p>Jika mahasiswa menemukan adanya kerusakan pada fasilitas kelas (seperti AC tidak dingin, proyektor mati, kursi rusak, atau lampu padam), silakan melaporkannya melalui prosedur berikut:</p><ol><li><p><strong>Laporkan ke Biro Sarana dan Prasarana (Sarpras):</strong> Mahasiswa dapat mendatangi langsung ruang Biro Sarpras kampus atau mengisi formulir pengaduan kerusakan fasilitas yang telah disediakan (jika ada secara digital).</p></li><li><p><strong>Sebutkan Detail Lokasi:</strong> Saat melapor, pastikan Anda menginformasikan nomor ruang kelas, jenis fasilitas yang rusak, serta detail kendala yang terjadi secara jelas agar dapat segera ditindaklanjuti.</p></li><li><p><strong>Melalui Ketua Kelas/Dosen:</strong> Anda juga dapat meminta bantuan ketua kelas atau dosen yang sedang mengajar untuk meneruskan laporan tersebut ke bagian sarpras atau teknisi yang bertugas pada hari itu.</p></li></ol><p></p>', '[\"fasilitas kelas rusak\",\"lapor ac rusak\",\"proyektor error\",\"biro sarpras\",\"pengaduan fasilitas\",\"sarana prasarana\",\"perbaikan kelas upitra\"]', 'Aktif', 0, 0, '2026-06-10 20:31:00', '2026-06-23 23:27:48'),
(450, 'Fasilitas & Layanan', 'Sewa Tempat', 'Apakah laboratorium UPITRA bisa disewa oleh pihak luar?', '<p><strong>Ya, UPITRA membuka peluang kerja sama bagi pihak luar atau mitra industri untuk memanfaatkan fasilitas laboratorium kampus</strong>, baik untuk keperluan pengujian komersial, riset bersama, maupun pelatihan teknis.</p><p><strong>Ketentuan dan Prosedur Kerja Sama:</strong></p><ol><li><p><strong>Pengajuan Resmi:</strong> Mitra industri wajib mengajukan surat permohonan atau proposal kerja sama resmi yang ditujukan kepada Kepala Laboratorium terkait atau bagian Kerja Sama Institusi.</p></li><li><p><strong>Ketersediaan &amp; Jadwal:</strong> Penggunaan laboratorium oleh pihak eksternal harus disesuaikan dengan jadwal akademik kampus agar tidak mengganggu kegiatan praktikum reguler mahasiswa.</p></li><li><p><strong>Tarif &amp; Kontrak:</strong> Besaran biaya sewa, kompensasi operasional, serta hak kekayaan intelektual (jika ada hasil riset) akan diatur tersendiri dalam dokumen Nota Kesepahaman (MoU) atau Perjanjian Kerja Sama (PKS).</p></li></ol><p></p>', '[\"sewa laboratorium\",\"mitra industri lab\",\"pengujian komersil\",\"kerjasama lab\",\"sewa fasilitas upitra\",\"pihak luar pakai lab\",\"penggunaan lab eksternal\"]', 'Aktif', 0, 0, '2026-06-10 20:31:15', '2026-06-23 23:26:00'),
(451, 'Fasilitas & Layanan', 'Layanan Konseling', 'Apakah tersedia layanan konseling psikologis gratis untuk mahasiswa?', '<p><strong>Ya, UPITRA menyediakan layanan konseling psikologis secara gratis</strong> bagi seluruh mahasiswa aktif yang membutuhkan pendampingan terkait stres akademik maupun masalah pribadi.</p><p>Layanan ini dirancang untuk membantu mahasiswa menjaga kesehatan mental dan emosional agar proses perkuliahan tetap berjalan dengan baik. Seluruh sesi konseling bersifat rahasia dan akan didampingi oleh konselor atau psikolog yang kompeten di bidangnya.</p><p><em>Untuk informasi jadwal, prosedur pendaftaran sesi, atau konsultasi lebih lanjut, silakan hubungi bagian Kemahasiswaan atau Layanan Konseling Kampus.</em></p>', '[\"layanan konseling\",\"konseling gratis\",\"psikolog kampus\",\"stres akademik\",\"kesehatan mental\",\"curhat mahasiswa\",\"konsultasi psikologis\"]', 'Aktif', 0, 0, '2026-06-10 20:31:35', '2026-06-23 23:23:59'),
(452, 'Fasilitas & Layanan', 'Fasilitas Difabel', 'Apakah tersedia fasilitas kampus untuk penyandang disabilitas?', '<p><strong>Ya, UPITRA berkomitmen menyediakan lingkungan kampus yang inklusif</strong> dengan terus mengembangkan fasilitas aksesibilitas yang ramah bagi penyandang disabilitas (difabel).</p><p>Beberapa fasilitas penunjang yang tersedia di area gedung kampus antara lain:</p><ul><li><p>♿ <strong>Akses Jalur Bidang Miring (<em>Ramp</em>):</strong> Tersedia di beberapa area masuk utama gedung untuk mempermudah pengguna kursi roda.</p></li><li><p>🚻 <strong>Toilet Aksesibel:</strong> Fasilitas toilet khusus yang dirancang dengan ruang gerak dan pegangan tangan (<em>handrail</em>) penunjang keselamatan.</p></li><li><p>🛗 <strong>Fasilitas Lift:</strong> Tersedia di gedung bertingkat untuk mempermudah mobilisasi antarlantai bagi mahasiswa atau pengunjung yang membutuhkan.</p></li></ul><p><em>UPITRA secara berkala terus melakukan perbaikan dan peningkatan fasilitas sarana prasarana agar seluruh civitas akademika dapat beraktivitas dengan nyaman tanpa hambatan.</em></p>', '[\"fasilitas difabel\",\"aksesibilitas disabilitas\",\"kampus ramah difabel\",\"lift upitra\",\"toilet disabilitas\",\"kursi roda kampus\",\"fasilitas inklusif\"]', 'Aktif', 0, 0, '2026-06-10 20:31:49', '2026-06-23 23:22:27'),
(454, 'Immersion Program', 'Info Program', 'Apa yang dimaksud dengan Immersion Program di UPITRA dan negara mana saja yang menjadi tujuannya?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:32:24', '2026-06-10 20:32:24'),
