(462, 'Immersion Program', 'Kerjasama Institusi', 'Bagaimana cara universitas luar negeri mengajukan diri menjadi mitra tujuan baru untuk Immersion Program UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:34:23', '2026-06-10 20:34:23'),
