(513, 'Penerimaan Mahasiswa Baru', 'Mahasiswa Asing', 'Apakah UPITRA menerima pendaftaran mahasiswa asing dan dokumen keimigrasian apa saja yang wajib dilampirkan?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:52:40', '2026-06-10 20:52:40'),
(514, 'Profil Universitas', 'Akreditasi Kampus', 'Apa status akreditasi kampus UPITRA saat ini?', '<p><strong>Universitas Pignatelli Triputra (UPITRA)</strong> merupakan institusi perguruan tinggi resmi yang telah <strong>terakreditasi oleh Badan Akreditasi Nasional Perguruan Tinggi (BAN-PT)</strong> sejak resmi didirikan melalui penggabungan dan transformasi institusi.</p><p>Selain akreditasi institusi, program-program studi di bawah naungan UPITRA juga telah memperoleh status akreditasi dari BAN-PT maupun Lembaga Akreditasi Mandiri (LAM) terkait dengan peringkat <strong>\"Baik\"</strong> hingga <strong>\"Baik Sekali\"</strong> (seperti pada prodi D3 Bahasa Inggris, S1 Sistem Informasi, S1 Akuntansi, S1 Manajemen, dll.).</p><p><em>Proses penjaminan mutu secara internal dan eksternal terus dijalankan secara berkelanjutan di bawah koordinasi </em><strong><em>Biro LPM (Lembaga Penjaminan Mutu)</em></strong><em> guna mempertahankan dan menaikkan peringkat akreditasi institusi maupun program studi ke tingkat yang lebih tinggi.</em></p>', '[\"akreditasi upitra\",\"akreditasi kampus\",\"status ban pt\",\"peringkat akreditasi\",\"apakah upitra terakreditasi\",\"surat keputusan akreditasi\"]', 'Aktif', 0, 0, '2026-06-10 20:53:24', '2026-07-01 01:23:38'),
(515, 'Profil Universitas', 'Peringkat Kampus', 'Berapa peringkat nasional kampus UPITRA saat ini?', '<p>Sebagai universitas yang resmi bertransformasi sejak tahun 2022, UPITRA berfokus penuh pada peningkatan mutu akademik dan kesiapan kerja lulusan melalui skema <em>Link and Match</em> bersama industri.</p><p>Peringkat nasional maupun klasterisasi perguruan tinggi UPITRA terus bergerak positif seiring dengan pemenuhan indikator kinerja utama (IKU) dari Kemendikbudristek, peningkatan akreditasi institusi, publikasi riset dosen, serta prestasi mahasiswa. UPITRA berkomitmen secara berkelanjutan untuk menembus jajaran universitas swasta papan atas di tingkat regional maupun nasional.</p><p><em>Pengembangan mutu, evaluasi klasterisasi, dan pelaporan peringkat institusi ini dipantau secara berkala oleh </em><strong><em>Biro LPM (Lembaga Penjaminan Mutu)</em></strong><em> bersama dengan </em><strong><em>Biro Akademik Administrasi</em></strong><em>.</em></p>', '[\"peringkat upitra\",\"ranking nasional\",\"klasterisasi kemendikbud\",\"universitas terbaik di solo\",\"peringkat kampus\",\"upitra ranking\"]', 'Aktif', 0, 0, '2026-06-10 20:53:40', '2026-07-01 01:24:05'),
(516, 'Profil Universitas', 'Sejarah & Visi', 'Apa visi utama dan keunggulan universitas UPITRA?', '<p><strong>Visi Universitas Pignatelli Triputra (UPITRA)</strong> adalah menjadi universitas unggul yang menghasilkan lulusan berkarakter, profesional, inovatif, dan siap bersaing di tingkat nasional maupun global.</p><p>Berbeda dengan perguruan tinggi swasta lainnya, UPITRA memiliki nilai lebih dan keunggulan utama sebagai berikut:</p><ol><li><p><strong>Pendidikan Berbasis Industri (<em>Link and Match</em>):</strong> Kurikulum dirancang secara khusus agar relevan dengan kebutuhan nyata dunia kerja dan industri saat ini.</p></li><li><p><strong>Ekosistem Triputra Group:</strong> Didukung penuh oleh jaringan industri Triputra Group, membuka akses kolaborasi yang kuat bagi mahasiswa dalam hal penyerapan kerja dan pengalaman profesional.</p></li><li><p><strong>Immersion Program:</strong> Menyediakan pengalaman belajar langsung di dunia industri nyata sebagai bagian integral dari proses perkuliahan.</p></li><li><p><strong>Pengembangan Karakter &amp; Kepemimpinan:</strong> Tidak hanya fokus pada aspek akademis dan sains-teknologi, tetapi juga menanamkan nilai-nilai integritas serta kompetensi profesional yang kokoh pada setiap lulusan.</p></li></ol><p><em>Pengawasan kualitas kurikulum dan arah strategis pemenuhan visi ini dikawal secara berkala oleh </em><strong><em>Biro LPM (Lembaga Penjaminan Mutu)</em></strong><em> bersama dengan rektorat.</em></p>', '[\"visi upitra\",\"keunggulan upitra\",\"visi misi upitra\",\"visi misi kampus\",\"kelebihan upitra\",\"link and match\",\"keunggulan universitas\"]', 'Aktif', 0, 0, '2026-06-10 20:53:53', '2026-07-01 01:24:24'),
(517, 'Profil Universitas', 'Identitas Kampus', 'Apa makna logo UPITRA dan siapa pencipta lagu Mars?', '<p><strong>Lagu Mars UPITRA</strong> diciptakan sebagai salah satu identitas resmi kampus untuk membakar semangat sivitas akademika dalam menuntut ilmu, berinovasi, dan mengabdi pada bangsa dengan integritas tinggi.</p><p>Sementara itu, <strong>Logo Universitas Pignatelli Triputra (UPITRA)</strong> memiliki makna filosofis yang mendalam:</p><ol><li><p><strong>Sinergi dan Kolaborasi:</strong> Melambangkan penyatuan kekuatan akademik dan nilai-nilai industri (<em>Link and Match</em>) bersama ekosistem Triputra Group.</p></li><li><p><strong>Inovasi dan Masa Depan:</strong> Representasi dari visi kampus untuk mencetak pemimpin masa depan yang profesional, adaptif, dan siap bersaing di kancah global.</p></li><li><p><strong>Karakter dan Integritas:</strong> Bentuk dan warna logo mencerminkan keteguhan karakter, nilai humaniora, serta profesionalisme yang dijunjung tinggi oleh seluruh keluarga besar universitas.</p></li></ol><p><em>Informasi detail mengenai teks lirik lengkap Mars serta dokumen resmi arti lambang dapat Anda koordinasikan lebih lanjut melalui </em><strong><em>Biro Bagian Kemahasiswaan</em></strong><em> atau Humas Kampus.</em></p>', '[\"pencipta mars upitra\",\"makna logo upitra\",\"arti lambang kampus\",\"lagu mars upitra\",\"filosofi logo\",\"identitas kampus\"]', 'Aktif', 0, 0, '2026-06-10 20:54:08', '2026-07-01 01:25:15'),
(518, 'Profil Universitas', 'Jumlah Mahasiswa', 'Berapa total jumlah mahasiswa aktif dan jumlah dosen bergelar Doktor (S3) yang dimiliki UPITRA sekarang?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:54:24', '2026-06-10 20:54:24'),
(520, 'Profil Universitas', 'Fokus Kampus', 'Apakah UPITRA berfokus pada pengembangan sains dan teknologi saja atau juga unggul di bidang humaniora?', '<p>Universitas Pignatelli Triputra (UPITRA) tidak hanya berfokus pada pengembangan sains dan teknologi, melainkan juga unggul dalam bidang humaniora. Hal ini tecermin dari integrasi kurikulum yang seimbang antara kompetensi teknis dan penguatan aspek sosial, bisnis, serta nilai-nilai kemanusiaan guna mencetak lulusan yang adaptif dan berintegritas.</p>', '[\"fokus kampus\",\"keunggulan UPITRA\"]', 'Draft', 0, 0, '2026-06-10 20:54:52', '2026-07-06 21:34:35'),
(521, 'Profil Universitas', 'Milestones', 'Penghargaan internasional terbesar apa saja yang berhasil diraih oleh UPITRA dalam tiga tahun terakhir?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:55:07', '2026-06-10 20:55:07'),
(522, 'Profil Universitas', 'Lokasi Cabang', 'Selain kampus utama, apakah UPITRA memiliki kampus cabang?', '<p>Saat ini, <strong>Universitas Pignatelli Triputra (UPITRA)</strong> berfokus penuh pada pengembangan seluruh aktivitas akademik, perkuliahan, dan fasilitas penunjang di <strong>Kampus Utama yang berlokasi di Jl. Duwet No. 1, Karangasem, Laweyan, Surakarta, Jawa Tengah</strong>. UPITRA belum memiliki lokasi kampus cabang atau pusat pelatihan fisik di kota lain.</p><p>Meskipun demikian, melalui jaringan kerja sama industri yang luas (termasuk dengan ekosistem Triputra Group), mahasiswa UPITRA memiliki akses untuk melaksanakan program magang, <em>Immersion Program</em>, maupun pelatihan profesional langsung di berbagai lokasi perusahaan mitra yang tersebar di berbagai wilayah Indonesia.</p>', '[\"kampus cabang\",\"lokasi upitra\",\"upitra surakarta\",\"cabang upitra\",\"pusat pelatihan kampus\",\"kuliah diluar solo\"]', 'Aktif', 0, 0, '2026-06-10 20:55:21', '2026-06-24 00:07:12'),
(523, 'Profil Universitas', 'Fasilitas Unggulan', 'Apa fasilitas ikonik atau laboratorium riset tercanggih yang menjadi kebanggaan dari universitas UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 20:55:35', '2026-06-10 20:55:35'),
(524, 'Program Studi', 'Pilihan Prodi', 'Apa saja program studi jenjang S1 yang tersedia di bawah naungan Fakultas Ilmu Komputer UPITRA?', '<p>Di Universitas Pignatelli Triputra (UPITRA), program studi jenjang S1 di bidang ilmu komputer dan teknologi berada di bawah naungan <strong>Fakultas Sains &amp; Teknologi</strong>.</p><p>Berikut adalah daftar program studi S1 yang tersedia:</p><ul><li><p><strong>S1 Informatika</strong></p></li><li><p><strong>S1 Sistem Informasi</strong></p></li><li><p><strong>S1 Software Engineering (Rekayasa Perangkat Lunak)</strong></p></li></ul><p><em>Ketiga program studi ini dirancang untuk menghasilkan lulusan yang kompeten di bidang teknologi digital, pengembangan perangkat lunak, serta analisis sistem informasi yang siap bersaing di industri global.</em></p>', '[\"prodi ilkom\",\"jurusan komputer\",\"fakultas ilmu komputer\",\"sains dan teknologi\",\"program studi fst\",\"s1 informatika\",\"s1 sistem informasi\",\"software engineering\",\"jurusan IT upitra\",\"pilihan prodi teknik\"]', 'Aktif', 0, 0, '2026-06-10 21:04:26', '2026-06-24 23:51:51'),
(525, 'Program Studi', 'Akreditasi Prodi', 'Apakah Program Studi Sistem Informasi di UPITRA sudah mendapatkan akreditasi Unggul atau A?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 21:04:39', '2026-06-10 21:04:39'),
