(529, 'Program Studi', 'Biaya Khusus', 'Apakah ada perbedaan biaya kuliah semesteran yang signifikan antar program studi di rumpun eksakta dan sosial?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 21:05:34', '2026-06-10 21:05:34'),
