(532, 'Program Studi', 'Tugas Akhir', 'Apakah di rumpun prodi desain diperbolehkan mengganti skripsi tertulis dengan proyek karya kreatif akhir?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 21:06:23', '2026-06-10 21:06:23'),
(533, 'Program Studi', 'Kelas Karyawan', 'Apakah UPITRA menyediakan program kelas karyawan atau kelas malam untuk program studi Hukum?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 21:06:36', '2026-06-10 21:06:36'),
(534, 'Riset & Publikasi', 'Akses Jurnal', 'Bagaimana alur publikasi artikel ilmiah skripsi mahasiswa ke jurnal internal UPITRA yang terindeks SINTA?', '<p>Mahasiswa dapat mempublikasikan artikel ilmiah hasil skripsi ke jurnal internal UPITRA melalui alur berikut:</p><ol><li><p><strong>Penyusunan &amp; Rekomendasi:</strong> Menyusun artikel bersama dosen pembimbing hingga mendapat rekomendasi publikasi.</p></li><li><p><strong>Pendaftaran Jurnal:</strong> Memilih dan mendaftar pada portal jurnal internal UPITRA yang sesuai dengan bidang keilmuan.</p></li><li><p><strong>Submisi &amp; Review:</strong> Mengunggah naskah melalui sistem OJS (Open Journal System) kampus untuk proses review oleh mitra bestari.</p></li><li><p><strong>Publikasi:</strong> Naskah yang dinyatakan lolos akan diterbitkan pada jurnal terindeks SINTA terkait.</p></li></ol><p></p>', '[\"publikasi skripsi\",\"jurnal internal\",\"alur publikasi\",\"jurnal SINTA\",\"unggah jurnal UPITRA\"]', 'Aktif', 0, 0, '2026-06-10 23:07:47', '2026-07-06 21:33:16'),
(535, 'Riset & Publikasi', 'Dana Riset', 'Bagaimana prosedur bagi lembaga eksternal untuk berkolaborasi mendanai proyek riset dosen UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:08:01', '2026-06-10 23:08:01'),
(536, 'Riset & Publikasi', 'Hibah Penelitian', 'Apakah ada bantuan dana atau dana stimulus dari kampus bagi mahasiswa yang proposal penelitiannya lolos ke PKM?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:08:16', '2026-06-10 23:08:16'),
(537, 'Riset & Publikasi', 'Plagiarisme', 'Berapa persen batas maksimal kemiripan (turnitin) yang ditoleransi untuk naskah publikasi ilmiah mahasiswa?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:08:40', '2026-06-10 23:08:40'),
(538, 'Riset & Publikasi', 'Hak Cipta', 'Bagaimana alur komersialisasi produk inovasi atau paten hasil riset bersama antara UPITRA dengan industri?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:08:56', '2026-06-10 23:08:56'),
(539, 'Riset & Publikasi', 'Pusat Riset', 'Apa saja nama pusat studi atau research center aktif yang bisa diikuti oleh mahasiswa untuk magang riset?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:09:09', '2026-06-10 23:09:09'),
(540, 'Riset & Publikasi', 'Reward Publikasi', 'Apakah universitas memberikan insentif uang tunai bagi mahasiswa yang berhasil menembus jurnal internasional bereputasi (Scopus)?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:09:24', '2026-06-10 23:09:24'),
(541, 'Riset & Publikasi', 'Keahlian Dosen', 'Dimana kami bisa melihat portofolio kepakaran, daftar paten, dan rekam jejak riset para dosen UPITRA?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:10:46', '2026-06-10 23:10:46'),
(542, 'Riset & Publikasi', 'Etika Riset', 'Bagaimana cara mendapatkan surat izin kelaikan etik (ethical clearance) sebelum melakukan penelitian medis di kampus?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:11:06', '2026-06-10 23:11:06'),
(543, 'Riset & Publikasi', 'Kolaborasi Riset', 'Apakah ada program kolaborasi riset berbayar (asisten riset) bagi mahasiswa tingkat akhir bersama dosen?', NULL, '[]', 'Kosong', 0, 0, '2026-06-10 23:11:19', '2026-06-10 23:11:19'),
(544, 'Teknologi & Sistem', 'Masalah Sistem', 'Kenapa tidak bisa isi KRS online padahal sudah bayar kuliah?', '<p>Jika Anda sudah melunasi pembayaran semesteran tetapi akses pengisian KRS online masih terkunci, hal tersebut biasanya disebabkan oleh beberapa kemungkinan berikut:</p><ol><li><p><strong>Proses Sinkronisasi Data:</strong> Sistem pembayaran bank dengan SIAKAD memerlukan waktu sinkronisasi otomatis (umumnya beberapa jam setelah transaksi berhasil). Mohon tunggu beberapa saat dan lakukan cek berkala.</p></li><li><p><strong>Verifikasi Manual Keuangan:</strong> Pada beberapa kasus/jalur tertentu, bukti pembayaran perlu diverifikasi secara manual oleh Biro Keuangan sebelum status di sistem berubah menjadi \"Lunas\".</p></li><li><p><strong>Belum Masa Pengisian:</strong> Pastikan jadwal pengisian KRS Anda memang sudah dibuka sesuai dengan Kalender Akademik berjalan berjalan.</p></li></ol><p><em>Apabila dalam waktu 1x24 jam setelah pembayaran status Anda belum berubah, silakan hubungi Biro Keuangan atau Layanan Bantuan IT dengan melampirkan bukti transfer sah untuk dilakukan aktivasi manual.</em></p>', '[\"krs terkunci\",\"gagal isi krs\",\"krs error\",\"sudah bayar spp tapi krs kunci\",\"maslaah siakad krs\",\"verifikasi pembayaran krs\",\"sinkronisasi bayar kuliah\"]', 'Aktif', 0, 0, '2026-06-10 23:14:55', '2026-06-23 23:35:08');
INSERT INTO `ai_dataset` (`id`, `category`, `subcategory`, `question`, `answer`, `keywords`, `status`, `is_template`, `sort_order`, `created_at`, `updated_at`) VALUES
(545, 'Teknologi & Sistem', 'Akun Pengguna', 'Kapan mahasiswa baru akan mendapatkan akun email resmi kampus dengan domain @upitra.ac.id?', '<p style=\"text-align: justify;\">Akun email resmi mahasiswa dengan domain <strong>@</strong><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://upitra.ac.id\"><strong>upitra.ac.id</strong></a> akan dibuatkan secara massal dan dibagikan kepada mahasiswa baru pada saat masa <strong>Orientasi Kampus / PKKMB (Pengenalan Kehidupan Kampus bagi Mahasiswa Baru)</strong> atau menjelang dimulainya perkuliahan semester pertama.</p><p style=\"text-align: justify;\">Informasi mengenai detail <em>username</em> dan <em>password</em> bawaan (<em>default</em>) akan dikirimkan melalui email pribadi yang didaftarkan saat PMB atau diumumkan melalui grup koordinasi mahasiswa baru.</p><p style=\"text-align: justify;\"><em>Apabila hingga perkuliahan perdana dimulai Anda belum menerima akun tersebut, silakan hubungi </em><strong><em>Biro Teknologi Informasi</em></strong><em> di gedung kampus dengan membawa bukti KTM/KTP untuk aktivasi manual.</em></p>', '[\"email kampus\",\"email institusi\",\"domain upitra\",\"akun email baru\",\"email maba\",\"kapan dapat email\",\"cara login email kampus\",\"akun email @upitra.ac.id\",\"layanan IT maba\"]', 'Aktif', 0, 0, '2026-06-10 23:15:22', '2026-06-24 23:45:25'),
(546, 'Teknologi & Sistem', 'Panduan Sistem', 'Bagaimana cara mereset password portal akademik yang lupa?', '<p>Jika Anda lupa atau akun portal akademik (SIAKAD/UNITY) Anda terkunci, Anda dapat melakukan reset kata sandi melalui prosedur berikut:</p><ol><li><p><strong>Fitur \"Lupa Password\":</strong> Pada halaman login portal akademik, klik tautan <strong>\"Lupa Password?\"</strong> (jika tersedia), lalu ikuti instruksi pemulihan yang dikirimkan ke email resmi institusi Anda .</p></li><li><p><strong>Melapor ke Biro Teknologi Informasi:</strong> Jika fitur mandiri tidak berhasil atau akun Anda terkunci total, silakan hubungi atau datangi langsung ruangan <strong>Biro Teknologi Informasi</strong> di gedung kampus.</p></li><li><p><strong>Siapkan Identitas:</strong> Pastikan Anda menyiapkan Nomor Induk Mahasiswa (NIM) serta Kartu Tanda Mahasiswa (KTM) aktif untuk proses verifikasi data oleh petugas sebelum password di-reset ke pengaturan bawaan (<em>default</em>).</p></li></ol><p></p>', '[\"reset password portal\",\"lupa sandi siakad\",\"akun terkunci upitra\",\"lupa password unity\",\"ganti password mahasiswa\",\"it support reset\"]', 'Aktif', 0, 0, '2026-06-10 23:15:36', '2026-07-01 01:21:06'),
(548, 'Teknologi & Sistem', 'Sistem Pemantauan', 'Apakah ada portal khusus orang tua untuk memantau kuliah?', '<p>Saat ini, UPITRA belum menyediakan aplikasi mobile atau portal berbasis web khusus yang terpisah bagi orang tua untuk memantau aktivitas perkuliahan mahasiswa secara langsung.</p><p>Namun, orang tua tetap dapat memantau perkembangan akademik anak (seperti kehadiran kuliah, jadwal, dan nilai KHS) secara berkala dengan cara mengakses <strong>Portal Akademik Mahasiswa</strong> melalui akun login (username dan password) milik putra/putrinya.</p>', '[\"portal orang tua\",\"pantau nilai anak\",\"aplikasi orang tua\",\"kehadiran mahasiswa orang tua\",\"cek absen anak\",\"akses orang tua\",\"sistem pemantauan\"]', 'Aktif', 0, 0, '2026-06-10 23:16:04', '2026-06-23 23:43:00'),
(550, 'Teknologi & Sistem', 'Integrasi Sistem', 'Bagaimana cara input sertifikat prestasi ke portofolio kampus?', '<p>Untuk menyinkronkan atau memasukkan data sertifikat prestasi yang Anda peroleh dari luar kampus ke dalam sistem portofolio digital, silakan ikuti prosedur berikut:</p><ol><li><p><strong>Login ke Portal Mahasiswa:</strong> Akses akun portal akademik Anda dan masuk ke menu <strong>Portofolio / Prestasi Mahasiswa</strong>.</p></li><li><p><strong>Isi Formulir &amp; Unggah Berkas:</strong> Input detail kompetisi/kegiatan, kategori prestasi, serta unggah scan sertifikat asli dalam format PDF atau JPG sesuai ketentuan sistem.</p></li><li><p><strong>Validasi oleh Biro Kemahasiswaan:</strong> Data yang Anda ajukan tidak langsung muncul secara publik, melainkan akan diperiksa dan divalidasi terlebih dahulu oleh <strong>Biro Kemahasiswaan</strong> untuk memastikan keabsahannya.</p></li></ol><p><em>Jika sertifikat telah disetujui namun tidak muncul pada transkrip portofolio digital Anda, silakan hubungi </em><strong><em>Biro Teknologi Informasi</em></strong><em> untuk bantuan pengecekan sinkronisasi sistem.</em></p>', '[\"input sertifikat\",\"portofolio digital\",\"sinkronisasi prestasi\",\"upload sertifikat lomba\",\"skpi upitra\",\"prestasi luar kampus\"]', 'Aktif', 0, 0, '2026-06-10 23:16:32', '2026-07-01 01:25:40'),
(551, 'Teknologi & Sistem', 'E-Learning', 'Di mana bisa mengunduh panduan penggunaan UNITY (LMS)?', '<p>Panduan lengkap penggunaan platform LMS <strong>UNITY</strong> untuk pengerjaan tugas, mengikuti kuis, maupun aktivitas pembelajaran daring lainnya dapat diakses melalui langkah berikut:</p><ol><li><p><strong>Melalui Halaman Utama UNITY:</strong> Buka laman resmi 🌐 <a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline ng-star-inserted\" href=\"https://unity.upitra.ac.id\">UNITY UPITRA</a>. Biasanya terdapat tautan unduhan panduan (<em>User Manual</em>) untuk mahasiswa di halaman awal sebelum login.</p></li><li><p><strong>Melalui Biro Teknologi Informasi:</strong> Jika memerlukan berkas panduan cetak digital terbaru atau mengalami kesulitan teknis akses, Anda dapat menghubungi <strong>Biro Teknologi Informasi</strong> atau melihat bagian pengumuman di portal akademik.</p></li><li><p><strong>Melalui Biro Akademik Administrasi:</strong> Panduan dasar mengenai sistem e-learning juga kerap dibagikan oleh <strong>Biro Bagian Akademik Administrasi</strong> saat masa orientasi mahasiswa baru (PKKMB).</p></li></ol><p></p>', '[\"panduan lms\",\"download manual unity\",\"cara pakai unity\",\"tutorial tugas daring\",\"lms upitra\",\"buku panduan siakad\"]', 'Aktif', 0, 0, '2026-06-10 23:17:55', '2026-07-01 01:22:18'),
(552, 'Teknologi & Sistem', 'Keamanan Data', 'Bagaimana keamanan data mitra perusahaan di server UPITRA?', '<p>UPITRA berkomitmen penuh menjaga kerahasiaan dan keamanan data sensitif milik mitra perusahaan melalui kebijakan perlindungan data terpadu yang dikelola oleh <strong>Biro Teknologi Informasi</strong>:</p><ol><li><p><strong>Enkripsi Data:</strong> Semua data penting dan sensitif milik mitra dienkripsi baik saat ditransmisikan maupun saat disimpan di dalam server sistem informasi kampus.</p></li><li><p><strong>Kontrol Akses Ketat:</strong> Hak akses ke server dibatasi secara ketat menggunakan metode autentikasi berlapis. Hanya staf teknis berwenang yang dapat mengakses data tersebut sesuai dengan kepentingan kerja sama.</p></li><li><p><strong>Keamanan Jaringan &amp; Audit berkala:</strong> Server kampus dilengkapi dengan sistem proteksi <em>firewall</em> untuk mencegah akses ilegal dari luar, serta dilakukan monitoring keamanan dan pemeliharaan rutin secara berkala.</p></li></ol><p><em>Ketentuan mengenai jaminan kerahasiaan ini juga tertuang secara legal dalam klausul Non-Disclosure Agreement (NDA) pada dokumen kerja sama (MoU/PKS) antara UPITRA dan pihak mitra.</em></p>', '[\"keamanan data mitra\",\"data perusahaan aman\",\"server upitra\",\"perlindungan data\",\"kerahasiaan data\",\"keamanan server\"]', 'Aktif', 0, 0, '2026-06-10 23:18:09', '2026-07-01 01:22:38'),
(553, 'Teknologi & Sistem', 'Pengaduan Teknis', 'Ke mana melapor jika terjadi error saat ujian online (CBT)?', '<p>Jika Anda mengalami kendala teknis atau <em>error</em> saat pelaksanaan ujian online (CBT), segera lakukan langkah-langkah darurat berikut:</p><ol><li><p><strong>Ambil Bukti Terlebih Dahulu:</strong> Ambil foto atau tangkapan layar (<em>screenshot</em>) pesan error yang muncul pada perangkat Anda sebagai bukti kendala.</p></li><li><p><strong>Hubungi Layanan Bantuan:</strong> Segera kirimkan laporan aduan beserta bukti foto, NIM, nama lengkap, dan mata kuliah ujian ke nomor Helpdesk <strong>Biro Teknologi Informasi</strong> (atau pengawas ruang ujian yang bertugas).</p></li><li><p><strong>Lapor Dosen Pengampu:</strong> Jika terjadi kendala jaringan yang menyebabkan waktu ujian habis, koordinasikan juga dengan dosen pengampu mata kuliah terkait kebijakan ujian susulan atau reset sesi.</p></li></ol><p></p>', '[\"error ujian online\",\"cbt error\",\"gagal cbt\",\"helpdesk ujian\",\"ujian susulan\",\"masalah cbt upitra\",\"nomer it helpdesk\"]', 'Aktif', 0, 0, '2026-06-10 23:18:23', '2026-07-01 01:22:57'),
(554, 'Akademik', 'Standar Lulus', 'Berapa standar nilai minimal agar dinyatakan lulus mata kuliah?', '<p style=\"text-align: justify;\">Standar kelulusan minimum untuk mata kuliah umum/pilihan di UPITRA adalah <strong>C</strong>. Namun, untuk mata kuliah kompetensi utama program studi atau prasyarat skripsi, beberapa prodi mewajibkan nilai minimal <strong>B</strong> atau <strong>B+</strong>. Jika mendapatkan nilai D atau E, mahasiswa sangat disarankan untuk melakukan her/remedial atau mengulang mata kuliah tersebut di semester berikutnya.</p>', '[\"nilai minimal lulus\",\"standar kelulusan mata kuliah\",\"dapat nilai d\",\"apakah nilai c lulus\",\"syarat lulus matakuliah\"]', 'Aktif', 0, 0, '2026-06-24 00:43:54', '2026-06-24 20:09:01'),
(555, 'Akademik', 'Keterlambatan', 'Bagaimana jika terlambat melakukan pengisian KRS online?', '<p style=\"text-align: justify;\">Mahasiswa yang terlambat mengisi KRS sesuai batas waktu di kalender akademik wajib segera melapor ke Dosen Pembimbing Akademik (PA) dan Ketua Program Studi. Pengisian KRS susulan hanya dapat dilakukan jika mendapatkan dispensasi khusus dari <strong>Biro Akademik Administrasi</strong>. Jika melewati batas dispensasi, mahasiswa berisiko dinyatakan tidak aktif (berstatus non-aktif) pada semester tersebut.</p>', '[\"terlambat krs\",\"krs ditutup\",\"krs susulan\",\"krs terlambat\",\"telat krs\"]', 'Aktif', 0, 0, '2026-06-24 00:44:47', '2026-06-24 20:09:09'),
(556, 'Akademik', 'Cumlaude', 'Apa saja syarat untuk mendapatkan predikat kelulusan Cumlaude?', '<p style=\"text-align: justify;\">Syarat kelulusan dengan predikat Terpuji (Cumlaude) di UPITRA meliputi: 1) IPK Kumulatif akhir &gt; 3.51, 2) Masa studi tepat waktu (maksimal 8 semester untuk S1), 3) Tidak pernah memiliki nilai E atau mengulang mata kuliah, dan 4) Tidak pernah mendapat sanksi akademik atau pelanggaran kode etik.</p>', '[\"syarat cumlaude\",\"predikat cumlaude\",\"lulus terpuji\",\"ipk cumlaude\"]', 'Aktif', 0, 0, '2026-06-24 00:46:02', '2026-06-24 20:09:16'),
(557, 'Akademik', 'Legalisir', 'Bagaimana cara mengajukan legalisir ijazah atau transkrip nilai?', '<p style=\"text-align: justify;\">Pengajuan legalisir dokumen kelulusan dapat dilakukan secara langsung di loket layanan <strong>Biro Akademik Administrasi</strong> dengan membawa fotokopi ijazah/transkrip asli sebanyak maksimal 5 lembar per pengajuan. Untuk alumni luar kota, pengajuan dapat dikoordinasikan melalui sistem layanan alumni online (jika tersedia) dengan biaya administrasi dan ongkos kirim sesuai ketentuan.</p>', '[\"legalisir ijazah\",\"legalisir transkrip\",\"minta tanda tangan ijazah\",\"legalisir upitra\"]', 'Aktif', 0, 0, '2026-06-24 00:47:23', '2026-06-24 20:09:29'),
(558, 'Akademik', 'Registrasi', 'Apa bedanya registrasi administratif dan registrasi akademik tiap semester?', '<ol><li><p style=\"text-align: justify;\"><strong>Registrasi Administratif:</strong> Proses penyelesaian kewayaran biaya kuliah (UKT/SPP) melalui bank mitra yang divalidasi oleh Biro Keuangan.</p></li></ol><ol start=\"2\"><li><p style=\"text-align: justify;\"><strong>Registrasi Akademik:</strong> Proses pengisian Kartu Rencana Studi (KRS) secara online melalui portal SIAKAD mahasiswa yang disetujui oleh Dosen Pembimbing Akademik (PA).</p></li></ol><p style=\"text-align: justify;\">Mahasiswa wajib menyelesaikan registrasi administratif terlebih dahulu sebelum sistem mengizinkan Anda melakukan registrasi akademik (KRS). Panduan lengkap pengisiannya dapat dilihat pada menu \'Cara Mengisi KRS\'.</p><p style=\"text-align: justify;\"></p>', '[\"herregistrasi\",\"daftar ulang semesteran\",\"syarat isi krs\",\"aktif kuliah kembali\"]', 'Aktif', 0, 0, '2026-06-24 00:55:04', '2026-06-24 20:09:37'),
(559, 'Akademik', 'Pengulangan', 'Jika saya mengulang mata kuliah, nilai mana yang akan diambil di transkrip akhir?', '<p style=\"text-align: justify;\">Jika mahasiswa melakukan perbaikan atau mengulang mata kuliah yang sama di semester berikutnya, sistem akademik UPITRA secara otomatis akan mendeteksi dan <strong>menggunakan nilai tertinggi/terbaik</strong> yang Anda peroleh untuk dimasukkan ke dalam Transkrip Nilai Kumulatif akhir.</p>', '[\"mengulang matakuliah\",\"perbaikan nilai\",\"nilai transkrip akhir\",\"kuliah ulang\"]', 'Aktif', 0, 0, '2026-06-24 00:56:09', '2026-06-24 20:09:48'),
(560, 'Kemahasiswaan', 'Prestasi', 'Prestasi apa saja yang pernah diraih mahasiswa UPITRA?', '<p style=\"text-align: justify;\"><strong>Mahasiswa Universitas Pignatelli Triputra (UPITRA) telah menorehkan berbagai prestasi di tingkat nasional maupun internasional, mulai dari bidang inovasi, teknologi, kewirausahaan, penelitian, hingga seni. Beberapa capaian membanggakan antara lain perolehan Gold Medal dan Silver Medal pada ajang internasional seperti AISEFF dan WYIIA, serta berbagai penghargaan pada kompetisi nasional di bidang bisnis, teknologi, dan akademik. Prestasi ini mencerminkan komitmen UPITRA dalam mencetak lulusan yang kompeten, inovatif, dan berdaya saing global.</strong></p><p style=\"text-align: justify;\"><strong>Untuk informasi lebih lengkap mengenai prestasi, kegiatan, organisasi mahasiswa, serta program pengembangan kemahasiswaan di UPITRA, silakan kunjungi:</strong><br><a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://www.upitra.ac.id/kemahasiswaan?utm_source=chatgpt.com\">Halaman Kemahasiswaan UPITRA</a></p>', '[\"prestasi mahasiswa UPITRA\",\"penghargaan mahasiswa UPITRA\",\"lomba yang dimenangkan UPITRA\",\"prestasi internasional UPITRA\",\"prestasi nasional UPITRA\",\"medali mahasiswa UPITRA\",\"achievement UPITRA\"]', 'Aktif', 0, 0, '2026-06-24 20:07:33', '2026-06-24 20:07:33'),
(561, 'Lainnya', 'Dies Natalis', 'Apa itu Dies Natalis UPITRA?', '<p>Dies Natalis UPITRA adalah peringatan hari jadi Universitas Pignatelli Triputra yang diselenggarakan setiap tahun sebagai bentuk rasa syukur atas perjalanan dan perkembangan universitas. Pada tahun 2026, UPITRA merayakan <strong>Dies Natalis ke-4</strong> dengan mengusung tema <strong>\"Funtastic 4 – Build, Bloom, Breakthrough, Beyond\"</strong>.</p><p>Rangkaian Dies Natalis tidak hanya menjadi perayaan ulang tahun kampus, tetapi juga menghadirkan berbagai kegiatan akademik, sosial, olahraga, kompetisi, seminar, dan pengembangan diri yang melibatkan dosen, tenaga kependidikan, mahasiswa, serta mitra UPITRA. Melalui kegiatan ini, UPITRA memperkuat semangat kebersamaan, kolaborasi, inovasi, dan komitmen dalam menghadirkan <strong>Academic Excellence with Industrial Edge</strong>.</p><p>Untuk informasi lebih lengkap mengenai Dies Natalis ke-4 UPITRA, silakan kunjungi:<br><a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://upitra.ac.id/berita/upitra-resmi-buka-rangkaian-dies-natalis-ke-4-dengan-semangat-funtastic-4-6a3df756dfbe9?utm_source=chatgpt.com\"><strong>UPITRA Resmi Buka Rangkaian Dies Natalis ke-4 dengan Semangat \"Funtastic 4\"</strong></a></p>', '[\"dies natalis\",\"dies natalis upitra\",\"dies upitra\",\"ulang tahun upitra\",\"hari jadi upitra\",\"anniversary upitra\",\"hut upitra\",\"ultah upitra\",\"birthday upitra\",\"dies itu apa\",\"dies natalis itu apa\",\"dies kampus\",\"acara ulang tahun kampus\",\"acara dies\",\"dies kapan\",\"upitra ulang tahun\",\"perayaan dies\",\"funtastic 4\",\"funtastic four\",\"build bloom breakthrough beyond\",\"tema dies\",\"kenapa ada dies natalis\",\"dies natalis ke 4\"]', 'Aktif', 0, 0, '2026-06-26 00:43:06', '2026-06-26 00:47:32'),
(562, 'Lainnya', 'Kegiatan Dies Natalis', 'Apa saja kegiatan atau event Dies Natalis UPITRA?', '<p>Dalam rangka <strong>Dies Natalis ke-4</strong>, UPITRA menyelenggarakan berbagai kegiatan yang dapat diikuti oleh sivitas akademika, di antaranya:</p><ul><li><p>🎉 Launching Dies Natalis</p></li><li><p>💻 Workshop dan Bootcamp</p></li><li><p>🤖 Generative AI Bootcamp</p></li><li><p>📚 Coaching Clinic Research</p></li><li><p>🩸 Donor Darah dan Cek Kesehatan</p></li><li><p>🎬 Diskusi Film</p></li><li><p>🎤 Seminar dan Talkshow</p></li><li><p>🏆 Berbagai kompetisi (Essay, Web Development, UI/UX, Mobile Legends, Basket, E-Sport, Web Design, dan lainnya)</p></li><li><p>🛍️ Bazaar Mahasiswa</p></li><li><p>🙏 Misa Syukur</p></li><li><p>🎊 Puncak Perayaan Dies Natalis pada <strong>22 Juli 2026</strong></p></li></ul><p>Seluruh kegiatan dirancang untuk memberikan ruang belajar, berkolaborasi, mengembangkan kreativitas, berprestasi, serta mempererat kebersamaan seluruh keluarga besar UPITRA.</p><p>Jadwal lengkap dan informasi setiap kegiatan dapat dilihat pada:<br><a target=\"_blank\" rel=\"noopener\" class=\"text-primary underline decorated-link\" href=\"https://www.upitra.ac.id/pengumuman/dies-natalis-ke-4-upitra-satu-perayaan-puluhan-pengalaman-seru-6a3dfcffbddef?utm_source=chatgpt.com\"><strong>Dies Natalis ke-4 UPITRA: Satu Perayaan, Puluhan Pengalaman Seru!</strong></a></p>', '[\"event dies\",\"kegiatan dies\",\"acara dies\",\"agenda dies\",\"jadwal dies\",\"kalender dies\",\"rundown dies\",\"event upitra\",\"agenda upitra\",\"ada acara apa\",\"ada event apa\",\"ada lomba apa\",\"kegiatan kampus apa\",\"kegiatan bulan ini\",\"acara minggu ini\",\"acara juli\",\"acara juni\",\"event juli\",\"event kampus\",\"kalender event\",\"kegiatan mahasiswa\",\"info event\",\"info dies\",\"dies ada apa saja\",\"dies ngapain aja\",\"dies isinya apa\",\"ada kompetisi apa\",\"ada seminar apa\",\"ada workshop apa\",\"ada donor darah\",\"ada bazaar\",\"ada bootcamp\"]', 'Aktif', 0, 0, '2026-06-26 00:43:39', '2026-06-26 00:51:35'),
(563, 'Lainnya', NULL, 'apakah akronim dari upitra?', '<p>Ya. <strong>UPITRA</strong> merupakan akronim dari <strong>Universitas Pignatelli Triputra</strong>.</p><p>UPITRA adalah perguruan tinggi swasta yang berlokasi di <strong>Surakarta, Jawa Tengah</strong>, dengan komitmen menghadirkan pendidikan berkualitas melalui semangat <strong>\"Academic Excellence with Industrial Edge\"</strong>. Universitas ini mengintegrasikan keunggulan akademik dengan kebutuhan dunia industri agar lulusannya siap menghadapi tantangan profesional.</p>', '[\"akronim upitra\",\"singkatan upitra\",\"upitra singkatan apa\",\"kepanjangan upitra apa\",\"arti upitra\",\"apa itu upitra\",\"upitra adalah\",\"nama lengkap upitra\",\"universitas pignatelli triputra\",\"upitra stands for\"]', 'Aktif', 0, 0, '2026-06-26 00:54:38', '2026-06-26 00:54:38');

