CREATE TABLE `berita` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `category` varchar(255) NOT NULL,
  `date` date NOT NULL,
  `excerpt` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `thumbnail` varchar(255) DEFAULT NULL,
  `url` varchar(255) DEFAULT NULL,
  `status` enum('Published','Draft') NOT NULL DEFAULT 'Draft',
  `featured` tinyint(1) NOT NULL DEFAULT 0,
  `views_count` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `berita`
--

INSERT INTO `berita` (`id`, `title`, `slug`, `category`, `date`, `excerpt`, `content`, `thumbnail`, `url`, `status`, `featured`, `views_count`, `created_at`, `updated_at`) VALUES
(6, 'English Fest 2025: UPITRA Rayakan Kreativitas Bahasa dan Karakter Lewat Storytelling & Interpreting Seminar', 'english-fest-2025-upitra-rayakan-kreativitas-bahasa-dan-karakter-lewat-storytelling-interpreting-seminar-69ea1891e13bf', 'Kemahasiswaan', '2025-11-07', 'Program Studi S1 Bahasa dan Kebudayaan Inggris UPITRA menggelar English Fest 2025: Storytelling Competition and Interpreting Seminar.', '<p style=\"text-align: justify;\"><span>Suasana penuh semangat dan kreativitas memenuhi kampus Universitas Pignatelli Triputra (UPITRA) pada Kamis, 30 Oktober 2025, Program Studi D3 Bahasa Inggris berkolaborasi dengan Program Studi S1 Bahasa dan Kebudayaan Inggris UPITRA menggelar English Fest 2025: Storytelling Competition and Interpreting Seminar. Tahun ini, acara berlangsung lebih meriah dengan diikuti peserta dari berbagai SMA/SMK di Soloraya dan sekitarnya, serta peserta kategori mahasiswa tingkat nasional.</span></p><p style=\"text-align: justify;\"><span>Mengangkat tema “Weaving Virtues Through Stories: Forging Indonesia’s Future Character”, kegiatan ini tidak hanya menjadi ajang kompetisi, tetapi juga sarana penguatan nilai moral dan karakter melalui bahasa. Peserta diajak untuk menghidupkan cerita-cerita yang menanamkan nilai keutamaan, sembari menunjukkan kemampuan berbahasa Inggris yang komunikatif, kreatif, dan ekspresif.</span></p><p style=\"text-align: justify;\"><span>Selain kompetisi, English Fest 2025 juga menghadirkan Interpreting Seminar: Practical Skill Workshop, yang mengenalkan dunia profesi penerjemah dan juru bahasa. Peserta diajak memahami dinamika dunia interpreting, praktik komunikasi lintas budaya, dan bagaimana profesi ini menjadi kunci dalam banyak sektor global — mulai dari diplomasi hingga industri kreatif.</span></p><p style=\"text-align: justify;\"><span>Acara kemudian ditutup dengan pengumuman pemenang, yang merupakan momen paling ditunggu oleh para peserta. Berikut daftar pemenang tahun ini</span></p><p style=\"text-align: justify;\"><span>Kategori Pelajar SMA/SMK</span></p><p style=\"text-align: justify;\"><span>Juara I Tiara Putri Pramono (SMA PL Santo Yosef)<br>Juara II Syafa Aura Medinira (SMA Negeri 1 Nguntoronadi)<br>Juara III Alisya Haura Dzakirah (SMA Muhammadiyah 1 Surakarta)<br><br></span></p><p style=\"text-align: justify;\"><span>Kategori Mahasiswa</span></p><p style=\"text-align: justify;\"><span>Juara I Andika Ahmad Baihaqi (Universitas Pignatelli Triputra)<br>Juara II Melinda Rose Jeffry (Universitas Katolik Parahyangan Bandung)<br>Juara III Aisha Rona Zalila (Politeknik Negeri Padang)<br>Juara Favorit Innocent Siroal Kelyombar (STIKom Yos Sudarso Purwokerto)<br><br></span></p><p style=\"text-align: justify;\"><span>Ketua Pelaksana English Fest 2025, Vinsensius Galuh Kusuma, S.Pd., M.Pd. menyampaikan bahwa English Fest 2025 bukan hanya kompetisi bahasa, tetapi juga ruang pengembangan karakter dan soft skills generasi muda, selaras dengan nilai Academic Excellence with Industrial Edge yang menjadi DNA UPITRA.</span></p><p style=\"text-align: justify;\"><span>“Bahasa bukan hanya alat komunikasi, tapi jembatan untuk membangun karakter, kreativitas, dan masa depan. Kami ingin para peserta pulang dengan pengalaman bermakna, bukan sekadar gelar juara.”</span></p><p style=\"text-align: justify;\"><span>Kegiatan ini turut menjadi momentum memperkuat kolaborasi UPITRA dengan sekolah dan perguruan tinggi, sekaligus memperkenalkan inovasi pembelajaran prodi D3 Bahasa Inggris dan S1 Bahasa dan Kebudayaan Inggris UPITRA yang fokus pada komunikasi, kreativitas, global readiness, serta praktik nyata di dunia kerja.</span></p><p style=\"text-align: justify;\"><span>Melalui ajang seperti English Fest, UPITRA menegaskan perannya sebagai kampus yang mendukung pengembangan kompetensi bahasa, budaya, serta soft skills menjadi fondasi penting generasi muda Indonesia dalam memasuki dunia global.</span></p><ul><li><p style=\"text-align: justify;\"></p></li></ul><p style=\"text-align: justify;\"><br></p>', '/images/berita/1776949393_69ea1891e0fbb.jpg', NULL, 'Published', 0, 94, '2026-04-23 06:03:13', '2026-10-20 18:03:47'),
(7, 'UPITRA Solo Diakui di Cita Loka Fest 2025 Berkat Inovasi dan Kolaborasi Pendidikan', 'upitra-solo-diakui-di-cita-loka-fest-2025-berkat-inovasi-dan-kolaborasi-pendidikan-69ea196edd27d', 'Prestasi', '2025-11-10', 'Universitas Pignatelli Triputra (UPITRA) Solo berhasil meraih penghargaan kategori Kemitraan dan Pengembangan Pendidikan dalam acara Cita Loka Fest 2025.', '<p style=\"text-align: justify;\"><span>Universitas Pignatelli Triputra (UPITRA) Solo berhasil meraih penghargaan kategori Kemitraan dan Pengembangan Pendidikan dalam acara Cita Loka Fest 2025, Rabu (5/11/2025).</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>Penghargaan tersebut diraih UPITRA Solo karena dinilai mampu menjadi inisiator kerja sama strategis dengan industri dan kontributor pengembangan pendidikan di Solo Raya.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>Sertifikat dan piagam penghargaan langsung diberikan oleh Direktur PT Tribun Berita Online, Vovo Susatio, dan diterima oleh perwakilan UPITRA Solo, Thomas Ambar Prihastomo, S.S.,</span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\"><span>M.Sc</span></a><span> selaku Wakil Rektor (Warek) III bagian kemahasiswaan dan kerjasama.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>Dalam sambutannya, Ambar mengucapkan terima kasih atas penghargaan yang diberikan kepada UPITRA Solo.Ia menilai pencapaian ini tak lepas dari keterbukaan sektor industri terhadap dunia pendidikan yang mendorong terwujudnya berbagai kerja sama.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>“Kami bersyukur atas penghargaan ini. Kami sadar, capaian ini berkat kerja sama yang kami bangun dengan berbagai pihak pemerintah, industri, akademisi, masyarakat, dan media. Jadi pentahelix,” ujar Ambar.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span><strong>Kolaborasi Jadi Kunci</strong></span></p><p style=\"text-align: justify;\"><span>Ia menegaskan, kolaborasi lintas sektor menjadi kunci kemajuan UPITRA Solo.Sejak berdiri tiga tahun lalu, universitas ini berkomitmen untuk terus mengembangkan kualitas pendidikan di Solo Raya, Jawa Tengah, dan Indonesia.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>Ambar juga menambahkan, kedekatan UPITRA Solo dengan industri, khususnya Triputra Group, menjadi nilai tambah dalam pengembangan pendidikan berbasis kebutuhan dunia kerja.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>“Shareholder kami, Triputra Group dan Persada Group, berharap UPITRA mampu mencetak generasi muda berkualitas, bukan intelektual pengangguran baru,” ujarnya.</span></p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\"><span>Ia menutup dengan harapan bahwa penghargaan ini akan menjadi pemantik bagi UPITRA Solo untuk semakin berdampak di bidang akademik dan memperluas jejaring kolaborasi di masa depan.</span></p>', '/images/berita/1776949614_69ea196edd054.jpg', NULL, 'Published', 0, 88, '2026-04-23 06:06:54', '2026-10-13 15:08:51'),
(8, 'UPITRA Resmikan Gedung Baru, Perkuat Pendidikan Karakter dan Industri', 'upitra-resmikan-gedung-baru-perkuat-pendidikan-karakter-dan-industri-69ea1a505b110', 'Akademik', '2025-12-09', 'Universitas Pignatelli Triputra (UPITRA) meresmikan gedung baru, gedung tiga lantai berkonsep industrial campus itu menggantikan fungsi bangunan lama di kompleks yang sama.', '<p>Universitas Pignatelli Triputra (UPITRA) meresmikan gedung baru yang berlokasi di Jl. Duwet, Kelurahan Karangasem, Kecamatan Laweyan, Kota Solo, Sabtu (15/11/2025). Gedung tiga lantai berkonsep industrial campus itu menggantikan fungsi bangunan lama di kompleks yang sama.</p><p style=\"text-align: justify;\">Pihak kampus juga berencana membongkar gedung lama dan memanfaatkannya untuk pembangunan fasilitas pendidikan lanjutan. Gedung baru tersebut telah dilengkapi ruang kelas modern, kantor rektorat, lembaga penjamin mutu, ruang rapat humility, ruang LPPM, ruang yayasan, biro kepegawaian, serta fasilitas pendukung lainnya.</p><p style=\"text-align: justify;\">Peresmian gedung dihadiri pemilik Triputra Group TP Rachmat, CEO Triputra Group Tjandra Karya Hermanto, Presiden Direktur PT Persada Capital Investama Arini Saraswati Subianto, CEO Triputra Edukasi Nusantara Yohanes Tan, Kepala LLDIKTI Wilayah VI Jawa Tengah Prof. Dr. Ir. Aisyah Endah Palupi, MPd, Wali Kota Solo Respati Ardi, serta beberapa pejabat di jajaran Forkompimda Kota Solo.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Dalam kesempatan itu, Arini Saraswati mengatakan bahwa investasi terbesar Triputra Group adalah pada sumber daya manusia. Ia menilai pendidikan harus membentuk kecerdasan sekaligus karakter dan integritas agar lulusan tidak mudah tergoda melakukan kecurangan.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Oleh sebab itu, ia berharap melalui tenaga pendidik di Upitra mereka mampu melatih mahasiswa sesuai kebutuhan dunia usaha, sekaligus berkarakter. “Kami percaya banget bahwa pendidikan menjadi alasan buat kami berinvestasi di Indonesia. Kami juga sangat mengutamakan pelatihan dan pendidikan tenaga pengajar. Harapannya, mereka dapat mencetak lulusan-lulusan yang punya kemampuan yang dibutuhkan masyarakat, sekaligus memiliki karakter dan integritas,” ujar Arini.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Kepada mahasiswa UPITRA, Arini berpesan agar mereka menjalani proses, tidak takut gagal, dan terus bangkit untuk meraih kesuksesan.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Sementara itu, presiden direktur Triputra Grup, Tjandra Karya Hermanto menjelaskan bahwa kolaborasi Triputra dengan Upitra dilakukan untuk memperkuat pendidikan berbasis karakter. Triputra membawa empat nilai utama, yakni Integrity &amp; Ethics, Excellence, Compassion, dan Humility, yang kini menjadi DNA pendidikan di Upitra.</p><p style=\"text-align: justify;\">Ia menambahkan bahwa Triputra akan menghadirkan para CEO dari berbagai unit bisnis, mulai dari agro, logistik, kesehatan hingga manufaktur otomotif, untuk memberikan pengalaman industri langsung bagi mahasiswa. Dengan mendekatkan dunia pendidikan dan industri, Tjandra optimistis lulusan Upitra akan lebih siap menghadapi tantangan profesi.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">“Di UPITRA ini kami masukkan DNA triputra yatu Integrity &amp; Ethics, Excellence, Compassion, dan Humility. Dan kami berusaha untuk mendekatkan pendidikan dengan industri sehingga di kampus ini para CEO di Triputra Group memberikan kuliah kepada mahasiswa. Kami yakin, pendidikan yang baik dari keluarga, kampus, dan industri menjadi kunci sukses dalam mencetak lulusan,” ujarnya.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Sementara itu, CEO Triputra Edukasi Nusantara, Yohanes Tan, menegaskan komitmen Triputra memberikan pendidikan berkualitas dengan biaya terjangkau. Menurutnya, tujuan utama adalah menghasilkan lulusan yang memiliki pekerjaan sesuai kompetensi, bukan sekadar gelar sarjana.</p><p style=\"text-align: justify;\">Triputra menjadikan keterlibatannya di kampus sebagai bagian dari program CSR setelah lebih dari 20 tahun fokus pada pemberian beasiswa. Saat ini Triputra telah mengelola empat perguruan tinggi: Upitra Solo, satu kampus di Maumere, satu di Karawang, serta satu kampus hasil joint venture dengan Fitma Education di Filipina.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Dalam kesempatan yang sama, Rektor Upitra, Dr. Francisca Ninik Yudianti, M.Acc., QIA., CSRA., menyampaikan bahwa kampus tidak hanya mengejar keunggulan akademik, tetapi juga pengembangan karakter mahasiswa melalui empat pilar yang dibawa Triputra.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Salah satu program unggulannya adalah Bina Karakter Mahasiswa (BKM), di mana mahasiswa mengikuti camp pembentukan karakter selama tiga hari di luar kampus.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Mengenai gedung baru, rektor mengatakan bahwa fasilitas tersebut ini diharapkan semakin memperkuat proses akademik, terutama dengan penerapan kurikulum 3 plus 1, yaitu tiga tahun kuliah di kampus dan satu tahun di luar kampus melalui program community development serta internship.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Dengan hadirnya gedung baru dan dukungan kuat dari dunia industri, Upitra menegaskan komitmennya menjadi perguruan tinggi yang menghasilkan lulusan berkarakter, berintegritas, sekaligus siap bersaing di dunia kerja.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">“Bangunan baru ini kami yakin akan memperkuat akademik. Selain itu, kami punya relasi yang kuat dengan industri. Dalam satu tahun ini sudah melakukan internship dengan berbagai industri, baik Triputra Group maupun Persada Capital Investama atau industri lain di Solo dan sekitarnya,” ujarnya.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Di sisi lain, peresmian dimeriahkan dengan berbagai pertunjukan dari mahasiswa, serta campus tour untuk melihat langsung fasilitas-fasilitas yang ada di gedung baru.</p>', '/images/berita/1776949840_69ea1a505af18.jpg', NULL, 'Published', 0, 104, '2026-04-23 06:10:40', '2026-10-17 21:25:27'),
(9, 'Wisuda Angkatan Ketiga, UPITRA Buktikan Hampir Separuh Lulusan Telah Diterima Kerja', 'wisuda-angkatan-ketiga-upitra-buktikan-hampir-separuh-lulusan-telah-diterima-kerja-69ea1b355c54a', 'Akademik', '2025-12-10', 'Universitas Pignatelli Triputra (UPITRA) menggelar wisuda bagi 61 lulusan di Ballroom Hotel Alana Solo.', '<p>Universitas Pignatelli Triputra (UPITRA) menggelar wisuda bagi 61 lulusan di Ballroom Hotel Alana Solo, Rabu (19/10/2025).</p><p style=\"text-align: justify;\">Ke-61 wisudawan tersebut merupakan angkatan ketiga sejak kampus Upitra berdiri di Kota Solo.</p><p style=\"text-align: justify;\">Acara yang diawali dengan sidang Senat Terbuka tersebut dihadiri sejumlah pihak seperti jajaran petinggi UPITRA Solo, perwakilan Triputra Edukasi Nusantara (TEN), perwakilan PT Persada Capital Investama, perwakilan Yayasan Santo Yosef Maria Pignateli Surakarta, perwakilan ikatan alumni, dan wali mahasiswa yang lulus pada hari ini.</p><p style=\"text-align: justify;\">Acara yang diawali dengan sidang Senat Terbuka tersebut dihadiri sejumlah pihak seperti jajaran petinggi UPITRA Solo, perwakilan Triputra Edukasi Nusantara (TEN), perwakilan PT Persada Grup, perwakilan Yayasan Santo Yosef Maria Pignateli Surakarta, perwakilan IKA UPITRA, dan wali mahasiswa yang lulus pada hari ini.<br>Dalam sambutannya, salah satu wisudawan, Teddy Setia Budi Sutrisno, tak lupa mengucap terima kasih atas dedikasi civitas akademika UPITRA Solo dalam membimbing dirinya dan teman-temannya selama duduk di bangku kuliah. Hal serupa juga diungkap oleh perwakilan orang tua wisudawan, Yulianto.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Saya mewakili wisudawan dan wisudawati ingin mengucapkan terima kasih yang sebesar-besarnya kepada ibu rektor beserta jajarannya, para dekan fakultas beserta jajarannya. Kaprodi, bapak ibu dosen serta seluruh civitas akademika Universitas Pignateli Triputra yang sudah mendampingi kami sampai titik wisuda hari ini,\" ungkap Teddy dalam sambutannya.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Pada kesempatan hari ini saya selaku perwakilan orang tua wisudawan-wisudawari mengucapkan terima kasih dan apresiasi tertinggi kepada Universitas Pignateli Triputra dan yayasan yang berhasil memimpin, mendidik dan mengantarkan para wisudawan-wisudawati sehingga berhasil menyelesaikan pendidikan yang tidak gampang. Kami sangat bahagia dan bangga karena anak-anak kami sampai ke titik ini,\" ungkap Yulianto.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Seperti janji UPITRA saat didirikan pertama kali di Solo, pada wisuda kali ini menjadi pembuktian bahwa UPITRA tak hanya menambah jumlah sarjana dan diploma tetapi juga menyalurkan para lulusan terbaiknya untuk langsung terjun ke dunia kerja.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Dari 61 wisudawan yang telah lulus dari UPITRA Solo pada hari ini, setidaknya ada 22 orang yang telah diterima bekerja.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Menanggapi hal tersebut Rektor UPITRA Solo, Ninik Yudianti mengatakan bahwa pencapaian tersebut membuka lebar potensi kampus yang beralamat di jalan Duwet Raya, Karangasem Kota Solo untuk menjadi kampus bagi mahasiswa yang siap terjun ke dunia kerja.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Saya kira ini sebuah prestasi tapi ini juga tetap harus kita tingkatkan. Kita memang berharap lebih dari separuh mahasiswa sebelum diwisuda sudah mendapatkan pekerjaan. Tapi karena memang mereka ujiannya baru Agustus hingga September, jadi waktunya sangat mepet dalam artian setelah mereka lulus langsung mencari pekerjaan,\" terang Ninik.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Wisudawan angkatan kali ini juga diakui Ninik menjadi tonggak penerapan Immersion program yang diterapkan UPITRA Solo sejak berdiri.&nbsp;</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Harapannya karena program kita berikutnya terkait dengan Immersion program untuk S1 Akuntansi khususnya memang sedang baru mulai. Memang angkatan ini belum menikmati karena angkatan ini adalah angkatan terakhir dari institusi lama,\" lanjut dia.</p><p style=\"text-align: justify;\">Dengan adanya gedung baru pun diakui Ninik semakin menjadi pendorong penerapan Immersion program dengan fokus penyiapan wisudawan di dunia kerja.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Saya berharap untuk tahun depan sudah ikut Immersion program, sudah ikut magang, ataupun community development maka harapannya jumlah yang bekerja sebelum wisuda itu sudah semakin besar,\" kata dia.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Dalam wisuda angkatan kali ini juga dikatakan oleh Ninik menjadi bukti adanya koordinasi dan kerjasama yang baik antar grup pendiri UPITRA dimana salah satu wisudawan mampu bersaing dan diterima di anak perusahaan Triputra grup.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">\"Kami juga bersyukur salah satu lulusan kami juga telah diterima oleh salah satu perusahaan di Triputra grup karena kemampuannya,\" pungkasnya.</p>', '/images/berita/1776950069_69ea1b355c361.jpg', NULL, 'Published', 0, 42, '2026-04-23 06:14:29', '2026-10-17 00:43:51'),
(10, 'UPITRA Gelar BKM Level 2, Menumbuhkan Grit dan Inovasi.', 'upitra-gelar-bkm-level-2-menumbuhkan-grit-dan-inovasi-69ea1c180cac5', 'Kemahasiswaan', '2025-12-09', 'Program BKM merupakan agenda tahunan yang diberikan sebagai bekal pengembangan karakter mahasiswa UPITRA.', '<p>Suasana dinamis terasa sejak pagi ketika mahasiswa semester 5 Universitas Pignatelli Triputra (UPITRA) mengikuti rangkaian kegiatan Bina Karakter Mahasiswa (BKM) pada tanggal 28-29 November 2025, dengan tema “Beyond Limits: Building Grit and Innovation”. Bertempat di rumah ret-ret yang berada di kawasan Tawangmangu, kegiatan ini menghadirkan tim dari AnterAja, salah satu Subco Triputra Group, untuk berbagi pengalaman tentang dunia kerja, ketangguhan mental, serta kemampuan berinovasi di tengah perubahan industri.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Program BKM merupakan agenda tahunan yang diberikan sebagai bekal pengembangan karakter mahasiswa UPITRA. Untuk semester 5, fokus utamanya adalah menyiapkan mahasiswa memasuki fase perkuliahan akhir dan persiapan menuju dunia profesional. Karena itu, menghadirkan praktisi lapangan menjadi langkah strategis agar mahasiswa memperoleh gambaran nyata tentang kompetensi yang dibutuhkan di industri.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Dalam pemaparannya, salah satu perwakilan AnterAja, Ansel Fabianta Tambunan - Head of Business Operation Anteraja menjelaskan pentingnya memiliki skill problem solving ketangguhan untuk terus maju meski menghadapi tantangan.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">“Dunia kerja itu cepat berubah. Yang membedakan seseorang bisa bertahan atau tidak bukan hanya skill, tapi kemampuan dalam memecahkan suatu permasalahan dengan baik dan benar,” ujar salah Ansel.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Selain berdiskusi mengenai ketangguhan, sesi ini juga menekankan pentingnya inovasi dalam menghadapi perkembangan teknologi dan kebutuhan pelanggan. Mahasiswa diajak melihat bagaimana AnterAja sebagai perusahaan logistik tumbuh melalui kultur adaptif dan pemanfaatan teknologi digital. Materi tersebut disambut antusias, terutama oleh mahasiswa yang sedang mempersiapkan diri untuk magang dan penulisan tugas akhir.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Beberapa mahasiswa menyampaikan bahwa kegiatan ini membantu mereka memahami tantangan dunia kerja secara lebih konkret.&nbsp;“Selama ini inovasi terdengar abstrak, tapi lewat contoh yang dibawakan pemateri, kami jadi tahu bagaimana ide bisa jadi solusi di lapangan,” ujar Galih mahasiswa Sistem Informasi.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Secara keseluruhan, BKM tahun ini tidak hanya menjadi forum pembelajaran, tetapi juga titik refleksi mengenai karakter apa yang perlu dibangun mahasiswa UPITRA untuk menjadi lulusan yang tangguh dan relevan dengan kebutuhan industri. Kegiatan ini semakin menguatkan komitmen UPITRA dalam menghadirkan pendidikan yang terhubung dengan dunia profesional dan menerapkan nilai Academic Excellence with Industrial Edge.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Dengan mengikuti rangkaian BKM ini, mahasiswa diharapkan mampu menata langkah lebih mantap menghadapi semester akhir dan berbagai peluang karier. UPITRA berencana melanjutkan kerja sama dengan berbagai mitra industri agar pembinaan karakter dapat berjalan berkelanjutan dan semakin memberi dampak nyata bagi perkembangan mahasiswa.</p>', '/images/berita/1776950296_69ea1c180c773.jpg', NULL, 'Published', 0, 67, '2026-04-23 06:18:16', '2026-10-16 06:45:51'),
(12, 'Mahasiswa UPITRA Mengurai Dunia Kerja Bersama Solo Paragon Hotel', 'mahasiswa-upitra-mengurai-dunia-kerja-bersama-solo-paragon-hotel-69ea1dd5c9496', 'Kemahasiswaan', '2025-12-11', 'Kegiatan kuliah lapangan seperti ini menjadi bentuk nyata komitmen Fakultas Ekonomika dan Bisnis UPITRA dalam memberikan pembelajaran yang terhubung dengan dunia kerja.', '<p>Mahasiswa S1 Akuntansi Fakultas Ekonomika dan Bisnis UPITRA mengikuti sesi Kuliah Pengantar Bisnis yang dikemas berbeda dari biasanya pada hari Senin, 24 November 2025 . Alih-alih duduk di kelas, mereka diajak turun langsung ke lingkungan industri perhotelan untuk memahami bagaimana konsep bisnis berjalan dengan baik, khususnya di bidang perhotelan.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Pada pertemuan ini, mahasiswa mendapatkan materi dari HR Manager Solo Paragon Hotel, Ibu Lionessa Yuliani, seorang profesional yang sudah belasan tahun berkecimpung di sektor perhotelan. Dengan gaya penyampaian yang ramah dan terbuka, ia memulai sesi dengan memperkenalkan dinamika bisnis hotel mulai dari operasional, manajemen sumber daya manusia, hingga strategi mempertahankan kualitas layanan di tengah persaingan yang ketat.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Suasana diskusi berkembang hangat ketika Ibu Lionessa mengaitkan teori bisnis yang biasanya dipelajari di kelas dengan kondisi lapangan.&nbsp;“Bisnis itu tidak hanya tentang angka, tetapi tentang bagaimana kalian membangun relasi, memahami kebutuhan pelanggan, dan bekerja sama dengan banyak karakter berbeda,” jelasnya.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Ia juga menekankan pentingnya sumber daya manusia yang adaptif dan berintegritas, dua hal yang menurutnya menjadi fondasi kesuksesan perusahaan jasa seperti perhotelan.&nbsp;Bagi mahasiswa Akuntansi, sesi ini menjadi pengalaman belajar yang membuka perspektif baru. Mereka tidak hanya melihat hotel sebagai tempat menginap, tetapi sebagai unit bisnis kompleks yang melibatkan perencanaan keuangan, pengendalian operasional, hingga manajemen risiko. Beberapa mahasiswa menyampaikan bahwa pengalaman ini membuat materi pengantar bisnis terasa lebih “hidup” dan mudah dihubungkan dengan praktik nyata.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">“Dari penjelasan Bu Lionessa, kami jadi paham bahwa akuntansi itu bukan kerja di belakang meja saja. Ada keputusan-keputusan bisnis yang perlu data keuangan kuat, dan itu membuat profesi kami relevan di banyak sektor,” ungkap Reno mahasiswa semester 1 prodi Akuntansi.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Kegiatan kuliah lapangan seperti ini menjadi bentuk nyata komitmen Fakultas Ekonomika dan Bisnis UPITRA dalam memberikan pembelajaran yang terhubung dengan dunia kerja. Dengan menghadirkan praktisi industri, mahasiswa didorong untuk melihat lebih jauh bahwa teori bisnis bukan sekadar konsep, tetapi alat untuk memecahkan masalah dan mendukung pengambilan keputusan di lingkungan profesional.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Pertemuan ini ditutup dengan sesi tanya jawab santai dan refleksi singkat mengenai peluang karier di sektor perhotelan, terutama bagi mahasiswa yang ingin memperluas pengalaman di luar ranah akuntansi konvensional. UPITRA berharap kegiatan semacam ini terus memberi ruang bagi mahasiswa untuk memadukan pengetahuan akademik dengan pengalaman nyata, sehingga siap menghadapi tantangan industri yang semakin beragam.</p>', '/images/berita/1776950741_69ea1dd5c923a.jpg', NULL, 'Published', 0, 100, '2026-04-23 06:25:41', '2026-10-20 05:15:25'),
(13, 'Gramedia Goes To Campus Hadir di UPITRA, Dua Hari Penuh Wawasan, Kreativitas, dan Inspirasi untuk Mahasiswa', 'gramedia-goes-to-campus-hadir-di-upitra-dua-hari-penuh-wawasan-kreativitas-dan-inspirasi-untuk-mahasiswa-69ea1ed769555', 'Kemahasiswaan', '2025-12-03', NULL, '<p><span>Gedung T.P. Rachmat dan Benny Subianto UPITRA tampak lebih ramai dari biasanya pada 3–4 Desember, ketika ratusan mahasiswa berkumpul untuk mengikuti rangkaian kegiatan Gramedia Goes to Campus. Selama dua hari, kampus dipenuhi suasana yang hidup—perpaduan antara diskusi edukatif, bazar buku, kelas interaktif, hingga sesi inspiratif dari para tokoh muda yang dekat dengan dunia mahasiswa.</span></p><p style=\"text-align: justify;\"><span>Acara ini menghadirkan empat kegiatan utama: interactive class, bazar Gramedia, student expo, dan Inspire Talks. Seluruh rangkaian dirancang agar mahasiswa tidak hanya belajar, tetapi juga mengeksplorasi minat, mengenal peluang industri kreatif, dan mendapatkan wawasan baru mengenai masa depan karier mereka.</span></p><p style=\"text-align: justify;\"><span>Salah satu sesi yang paling menarik perhatian adalah <em>Inspire Talks</em>, menghadirkan dua narasumber muda: Fathia Izzati- aktivis, penyanyi, sekaligus YouTuber yang dikenal dengan konten kreatif dan pandangan sosialnya; serta Angga Fauzan, CEO </span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://MySkill.id\"><span>MySkill.id</span></a><span>, platform pembelajaran yang populer di kalangan mahasiswa dan profesional muda.</span></p><p style=\"text-align: justify;\"><span>Dalam sesi berbagi cerita, Fathia membuka pembahasan tentang pentingnya keberanian untuk memulai, terutama di dunia kreatif. “Banyak hal besar lahir dari langkah kecil yang kita ambil hari ini. Yang penting, berani mencoba dan tetap jujur pada diri sendiri,” ujarnya, disambut tepuk tangan mahasiswa.</span></p><p style=\"text-align: justify;\"><span>Sementara itu, Angga Fauzan mengajak peserta melihat realitas pasar kerja masa kini yang semakin kompetitif. Ia menekankan pentingnya <em>upskilling</em> dan kemampuan adaptasi. “Industri berubah cepat. Kalian tidak harus ahli dalam semuanya, tapi harus tahu cara belajar hal baru dengan cepat,” katanya.</span></p><p style=\"text-align: justify;\"><span>Di sela talkshow, bazar Gramedia menjadi pusat perhatian. Mahasiswa bergerak dari satu rak ke rak lain, mencari buku-buku terbaru, novel populer, hingga referensi akademik. Banyak dari mereka memanfaatkan diskon khusus yang hanya tersedia selama acara berlangsung.</span></p><p style=\"text-align: justify;\"><span>Kegiatan ini, bagi UPITRA, bukan sekadar event kolaboratif. Gramedia Goes to Campus menjadi ruang bertemunya mahasiswa dengan dunia inspirasi: kreativitas, literasi, dan peluang karier. Kehadiran program seperti ini juga memperkuat komitmen UPITRA untuk menghadirkan lingkungan belajar yang dinamis di mana teori, praktik, dan jejaring industri saling bertemu.</span></p><p style=\"text-align: justify;\"><span>Salah satu mahasiswa UPITRA Amanda, mengungkapkan bahwa acara ini membuatnya lebih termotivasi untuk mengembangkan diri. “Biasanya kami belajar dari membaca buku, tapi kali ini kami bisa langsung mendengar cerita dari orang-orang yang sudah berkarya. Rasanya lebih dekat dan relevan,” tuturnya.</span></p><p style=\"text-align: justify;\"><span>Dua hari ini ditutup dengan suasana hangat dan penuh energi. Banyak mahasiswa pulang membawa buku baru, ide baru, dan semangat baru. UPITRA berharap kegiatan serupa dapat dilaksanakan secara berkelanjutan, agar mahasiswa terus mendapatkan ruang tumbuh, terinspirasi, dan mempersiapkan diri menghadapi masa depan yang penuh kemungkinan.</span></p>', '/images/berita/1776950999_69ea1ed768fdb.jpg', NULL, 'Published', 0, 91, '2026-04-23 06:29:59', '2026-10-19 05:48:51'),
(14, 'Mendekatkan Kampus dan Dunia Kerja, UPITRA Job Fair Buka Ruang Dialog Karier bagi Pencari Kerja', 'mendekatkan-kampus-dan-dunia-kerja-upitra-job-fair-buka-ruang-dialog-karier-bagi-pencari-kerja-69ea1f667142c', 'Kerjasama', '2025-12-04', 'UPITRA Job Fair diselenggarakan sebagai bagian dari komitmen universitas untuk mendampingi mahasiswa tidak hanya selama masa studi, tetapi juga dalam proses transisi menuju dunia profesional.', '<p><span>Suasana Gedung T.P. Rachmat dan Benny Subianto Universitas Pignatelli Triputra (UPITRA) terasa berbeda pada 3-4 Desember 2025. Di sela aktivitas akademik, kampus menjadi ruang pertemuan antara para pencari kerja dan dunia profesional melalui pelaksanaan UPITRA Job Fair. Selama dua hari, mahasiswa, calon wisudawan dan fresh gradute berkesempatan berinteraksi langsung dengan berbagai perusahaan, mengenal kebutuhan industri, sekaligus memetakan langkah awal karier mereka sejak masih berada di bangku kuliah.</span></p><p style=\"text-align: justify;\"><span>Kegiatan ini menghadirkan sejumlah perusahaan besar lintas sektor, mulai dari Logan Food, Duniatex, Apparel One Indonesia, hingga Triputra Group. Kehadiran perusahaan-perusahaan tersebut memberi gambaran nyata kepada mahasiswa tentang kebutuhan industri, peluang kerja, serta kompetensi yang relevan dengan perkembangan saat ini.</span></p><p style=\"text-align: justify;\"><span>UPITRA Job Fair diselenggarakan sebagai bagian dari komitmen universitas untuk mendampingi mahasiswa tidak hanya selama masa studi, tetapi juga dalam proses transisi menuju dunia profesional. Selama dua hari pelaksanaan, peserta dapat mengikuti sesi rekrutmen langsung, konsultasi karier, hingga diskusi singkat mengenai budaya kerja dan pengembangan karier di masing-masing perusahaan.</span></p><p style=\"text-align: justify;\"><span>“Job fair ini bukan sekadar soal melamar kerja, tapi tentang membuka wawasan mahasiswa mengenai dunia industri yang sesungguhnya,” ujar Estina salah satu panitia kegiatan. Menurutnya, interaksi langsung dengan praktisi industri menjadi pengalaman penting yang tidak selalu bisa didapatkan di ruang kelas.</span></p><p style=\"text-align: justify;\"><span>Antusiasme peserta terlihat jelas dari padatnya stan perusahaan sejak hari pertama. Sejumlah mahasiswa mengaku kegiatan ini membantu mereka lebih percaya diri menghadapi dunia kerja. “Saya jadi tahu posisi apa saja yang dibutuhkan perusahaan dan skill apa yang harus dipersiapkan sejak sekarang,” kata Tantri, mahasiswa tingkat akhir UPITRA. Ia menilai kesempatan berbincang langsung dengan HR perusahaan memberi perspektif yang lebih realistis tentang proses rekrutmen.</span></p><p style=\"text-align: justify;\"><span>Bagi perusahaan peserta, UPITRA Job Fair juga menjadi ajang strategis untuk menjaring talenta muda yang potensial. Perwakilan salah satu perusahaan menyebut mahasiswa UPITRA memiliki karakter yang terbuka untuk belajar dan cukup adaptif terhadap tantangan industri. “Kami melihat potensi besar dari mahasiswa yang tidak hanya punya dasar akademik, tapi juga kemauan untuk berkembang,” ujarnya.</span></p><p style=\"text-align: justify;\"><span>Melalui kegiatan ini, UPITRA menegaskan perannya sebagai kampus yang aktif membangun jejaring dengan industri dan menghadirkan pengalaman pembelajaran yang relevan. Job fair bukan sekadar agenda tahunan, melainkan bagian dari ekosistem pengembangan karier mahasiswa.</span></p><p style=\"text-align: justify;\"><span>Ke depan, UPITRA berharap kegiatan serupa dapat terus diperluas, baik dari sisi jumlah mitra industri maupun ragam program pendukung karier. Dengan begitu, kampus tidak hanya menjadi tempat belajar, tetapi juga ruang awal bagi mahasiswa untuk melangkah lebih mantap menuju dunia profesional.</span></p>', '/images/berita/1776951142_69ea1f6671154.jpeg', NULL, 'Published', 0, 84, '2026-04-23 06:32:22', '2026-10-22 08:18:39'),
(15, 'Cultural Fest 2025: Refleksi Keberagaman Budaya dalam Satu Semangat di Kampus UPITRA', 'cultural-fest-2025-refleksi-keberagaman-budaya-dalam-satu-semangat-di-kampus-upitra-69ea2053944bb', 'Akademik', '2025-12-12', 'Fakultas Sosial dan Humaniora (FSH) UPITRA untuk pertama kalinya menggelar Cultural Fest 2025, sebuah perhelatan budaya bertema “Reflections of Heritage: Different Cultures, One Spirit”.', '<p style=\"text-align: justify;\">Multifunction Hall Gedung T.P. Rachmat Universitas Pignatelli Triputra (UPITRA) dipenuhi warna, ekspresi, dan semangat kebersamaan mahasiswa dan dosen pada Rabu, 11 Desember 2025. Fakultas Sosial dan Humaniora (FSH) UPITRA untuk pertama kalinya menggelar Cultural Fest 2025, sebuah perhelatan budaya bertema “Reflections of Heritage: Different Cultures, One Spirit” yang mengajak sivitas akademika untuk merefleksikan makna keberagaman dalam konteks akademik dan kehidupan modern.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Kegiatan ini lahir dari gagasan untuk merayakan persatuan dalam keberagaman budaya, sekaligus menjadi ruang belajar berbasis proyek bagi mahasiswa. Cultural Fest 2025 merupakan implementasi pembelajaran project-based learning dari mata kuliah Event Management, Local Cultural Heritage, dan Cross-Cultural Understanding, yang sepenuhnya dirancang dan dijalankan oleh mahasiswa.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Acara dibuka sejak pagi melalui sesi Art Exhibition yang menampilkan beragam karya foto dan lukisan bertema sosial, religi, dan budaya. Karya-karya tersebut dipamerkan di area depan Multifunction Hall dan menarik perhatian ratusan pengunjung yang melintas. Panitia juga menghadirkan sistem voting sebagai bentuk apresiasi terhadap kreativitas mahasiswa, dengan total partisipasi lebih dari 100 suara.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Memasuki sore hari, suasana semakin semarak melalui sesi Performing Arts. Beragam pertunjukan ditampilkan, mulai dari dokumenter mini CFD, tarian Samba, kisah legenda Nusantara seperti Sangkuriang dan Malin Kundang, hingga cerita Houyi yang dikenal dalam tradisi Mid-Autumn Festival. Penonton juga disuguhkan tarian tradisional fusion Jawa-Dayak, drama bertema isu rasisme, tari yang merepresentasikan nilai gotong royong, serta pertunjukan dance dengan gaya budaya mancanegara.</p><p style=\"text-align: justify;\"><strong>&nbsp;</strong></p><p style=\"text-align: justify;\">Salah satu panitia menyampaikan bahwa Cultural Fest tidak hanya ajang pentas seni mahasiswa. “Lewat acara ini, kami belajar bagaimana budaya bisa menjadi medium refleksi dan dialog, bukan hanya hiburan,” ujarnya.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Puncak acara ditandai dengan sesi Appreciation and Awarding, di mana para dosen pengampu mata kuliah memberikan penghargaan kepada mahasiswa sebagai bentuk apresiasi atas dedikasi, kreativitas, dan kerja keras mereka.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Cultural Fest 2025 melibatkan mahasiswa D-3 Bahasa Inggris semester 5 sebagai panitia, serta mahasiswa S-1 Bahasa dan Kebudayaan Inggris dan S-1 Pariwisata semester 1 sebagai penampil. Dosen-dosen FSH UPITRA turut memeriahkan acara dengan mengenakan busana adat dari berbagai negara, menambah nuansa lintas budaya yang kuat.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Melalui Cultural Fest 2025, FSH UPITRA menegaskan komitmennya untuk menghadirkan pembelajaran yang kontekstual, kreatif, dan berdampak. Acara ini menjadi pengingat bahwa kampus bukan hanya ruang akademik, tetapi juga tempat bertumbuhnya kesadaran budaya, empati, dan semangat kebersamaan dalam keberagaman.</p>', '/images/berita/1776951379_69ea2053942bc.jpeg', NULL, 'Published', 0, 96, '2026-04-23 06:36:19', '2026-10-16 19:18:23'),
(16, 'Mahasiswa Software Engineering UPITRA Hadirkan Aplikasi Siap Pakai', 'mahasiswa-software-engineering-upitra-hadirkan-aplikasi-siap-pakai-69ea21688fea3', 'Akademik', '2025-12-19', 'Melalui Capstone Project, mahasiswa tidak hanya diuji kemampuan teknisnya, tetapi juga cara berpikir, berkolaborasi, dan menyelesaikan masalah riil.', '<p>Beberapa bulan terakhir, diskusi mahasiswa Fakultas Sains dan Teknologi Universitas Pignatelli Triputra (UPITRA) tidak lagi berhenti pada tugas dan teori di kelas. Bukan tanpa alasan mahasiswa Program Studi S1 Software Engineering tengah menuntaskan Capstone Project berupa pengembangan produk aplikasi yang dirancang untuk menjawab kebutuhan nyata pengguna. Proyek ini menjadi penanda penting penerapan kurikulum Outcome-Based Education (OBE) yang diimplementasikan secara konsisten di UPITRA.</p><p style=\"text-align: left;\"><strong>&nbsp;</strong></p><p style=\"text-align: left;\">Melalui Capstone Project, mahasiswa tidak hanya diuji kemampuan teknisnya, tetapi juga cara berpikir, berkolaborasi, dan menyelesaikan masalah riil. Dua produk aplikasi berhasil dikembangkan dan siap diserahkan kepada mitra yang sudah bekerja sama, sekaligus akan diaplikasikan di lingkungan UPITRA sebagai bagian dari pemanfaatan sistem digital kampus.</p><p style=\"text-align: left;\"><strong>&nbsp;</strong></p><p style=\"text-align: left;\">Produk pertama bertajuk “UPITRA VR EXPLORE”, dikembangkan oleh Muhammad Nibros Daffa Abroor (233036001), Laurensia Sangdewi Kurnianti (233036019), Farras Rizqi Adhiprawira (233036012), dan Leonardo Perolino Murat (233036007). Aplikasi ini dirancang untuk menghadirkan pengalaman eksplorasi kampus UPITRA secara virtual, memanfaatkan teknologi virtual reality sebagai media informasi dan promosi yang interaktif.</p><p style=\"text-align: left;\"><strong>&nbsp;</strong></p><p style=\"text-align: left;\">Sementara itu, produk kedua berjudul “Visensi”, dikembangkan oleh Anggara Desectio Caesar Paryta (233036008), Gregorius Alvin Duta Pratama (233036020), Laurensia Cahyani Kusuma Putri (233036013), Roi Fransisko S. (233036009), dan Stefanus Anggara Murti (233036006). Aplikasi ini disiapkan sebagai sistem yang mendukung kebutuhan mitra pengguna, Arsyanendra Panuntun, dengan pendekatan pengembangan berbasis kebutuhan lapangan.</p><p style=\"text-align: left;\"><strong>&nbsp;</strong></p><p style=\"text-align: left;\">Salah satu mahasiswa, Laurensia menyampaikan bahwa Capstone Project menjadi pengalaman belajar paling menantang selama kuliah. “Kami tidak hanya menulis kode, tapi belajar memahami kebutuhan pengguna, melakukan revisi, dan memastikan sistem benar-benar bisa dipakai untuk mitra,” ujarnya.</p><p style=\"text-align: left;\"></p><p style=\"text-align: left;\">Pendekatan OBE dalam proyek ini terlihat dari proses yang dilalui mahasiswa, mulai dari analisis kebutuhan, perancangan sistem, pengembangan, pengujian, hingga rencana implementasi. Dosen pembimbing berperan sebagai fasilitator yang mengarahkan, bukan sekadar pemberi instruksi, sehingga mahasiswa terbiasa mengambil keputusan secara mandiri dan bertanggung jawab.</p><p style=\"text-align: left;\">&nbsp;</p><p style=\"text-align: left;\">Bagi Program Studi S1 Software Engineering UPITRA, Capstone Project menjadi bukti bahwa pembelajaran berbasis proyek mampu menjembatani dunia akademik dan kebutuhan industri. Keterlibatan mitra eksternal serta rencana penerapan sistem di lingkungan kampus memperkuat nilai kebermanfaatan karya mahasiswa.</p><p style=\"text-align: left;\">&nbsp;</p><p style=\"text-align: left;\">Ke depan, UPITRA berharap semakin banyak karya mahasiswa yang lahir dari proses pembelajaran kontekstual dan berdampak langsung. Capstone Project ini bukan hanya penutup masa studi, melainkan awal kontribusi nyata mahasiswa sebagai calon profesional di bidang teknologi.</p><p style=\"text-align: left;\"></p><div data-youtube-embed=\"\" class=\"youtube-embed-container my-4\"><iframe src=\"https://www.youtube.com/embed/sa7c3LYWLE4?rel=0\" class=\"youtube-embed-iframe\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"true\" style=\"width: 100%; height: 400px; border: 1px solid rgb(229, 231, 235); border-radius: 6px;\"></iframe></div><p style=\"text-align: left;\"></p><div data-youtube-embed=\"\" class=\"youtube-embed-container my-4\"><iframe src=\"https://www.youtube.com/embed/vpdEXbb-fAw?rel=0\" class=\"youtube-embed-iframe\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen=\"true\" style=\"width: 100%; height: 400px; border: 1px solid rgb(229, 231, 235); border-radius: 6px;\"></iframe></div><p></p>', '/images/berita/1776951656_69ea21688fc05.jpg', NULL, 'Published', 0, 120, '2026-04-23 06:40:56', '2026-10-22 07:26:11'),
(17, 'UPITRA dan STIKOM Yos Sudarso Purwokerto Perkuat Kolaborasi melalui Kerja Sama dan Benchmarking', 'upitra-dan-stikom-yos-sudarso-purwokerto-perkuat-kolaborasi-melalui-kerja-sama-dan-benchmarking-69f18bc351c52', 'Kerjasama', '2026-02-12', 'Universitas Pignatelli Triputra (UPITRA) menerima kunjungan dari STIKOM Yos Sudarso Purwokerto dalam rangka penandatanganan kerja sama sekaligus kegiatan benchmarking.', '<p>UPITRA, Surakarta (11/02) — Universitas Pignatelli Triputra (UPITRA) menerima kunjungan dari STIKOM Yos Sudarso Purwokerto dalam rangka penandatanganan kerja sama sekaligus kegiatan benchmarking, Rabu (11/2/2026). Kegiatan yang berlangsung di lingkungan kampus UPITRA ini menjadi momentum penting untuk mempererat hubungan antar perguruan tinggi sekaligus saling berbagi praktik baik dalam pengelolaan institusi pendidikan tinggi.</p><p style=\"text-align: justify;\">Penandatanganan kerja sama dilakukan oleh perwakilan pimpinan dari kedua institusi, disaksikan oleh jajaran dosen dan tim pengelola akademik. Melalui kesepakatan ini, UPITRA dan STIKOM Yos Sudarso sepakat membuka ruang kolaborasi di berbagai bidang, mulai dari pengembangan akademik, penelitian bersama, hingga program penguatan kompetensi mahasiswa dan dosen.</p><p style=\"text-align: justify;\">Tidak hanya sebatas seremoni, agenda dilanjutkan dengan sesi benchmarking yang diisi dengan diskusi terbuka terkait pengelolaan kurikulum, sistem pembelajaran, hingga strategi pengembangan institusi berbasis kebutuhan industri. Dalam sesi ini, pihak STIKOM Yos Sudarso menggali lebih dalam pengalaman UPITRA dalam menerapkan berbagai program inovatif, termasuk penguatan kurikulum berbasis outcome dan kemitraan dengan dunia usaha dan industri.</p><p style=\"text-align: justify;\">Selain itu, STIKOM Yos Sudarso dan UPITRA juga saling memberikan masukan di bidang marketing dan kerjasama. Hal ini dinilai relevan dengan tantangan perguruan tinggi saat ini yang tidak hanya dituntut unggul secara akademik, tetapi juga adaptif dalam menjangkau calon mahasiswa dan dunia kerja.</p><p style=\"text-align: justify;\">Salah satu perwakilan STIKOM Yos Sudarso Purwokerto menyampaikan bahwa kegiatan benchmarking ini menjadi ruang belajar yang relevan dan kontekstual. “Kami melihat banyak praktik baik di UPITRA, terutama dalam membangun sinergi antara akademik dan kebutuhan industri. Ini menjadi referensi penting bagi kami untuk pengembangan institusi ke depan,” ujarnya.</p><p style=\"text-align: justify;\">Hal senada juga disampaikan perwakilan UPITRA yang menilai bahwa kolaborasi antar perguruan tinggi menjadi kunci dalam menghadapi dinamika pendidikan tinggi saat ini. “Benchmarking seperti ini bukan soal siapa yang lebih unggul, tetapi bagaimana kita bisa saling belajar dan tumbuh bersama,” ungkapnya.</p><p style=\"text-align: justify;\">Kegiatan ini menunjukkan bahwa kerja sama antar kampus tidak hanya berhenti pada dokumen formal, tetapi juga diwujudkan melalui pertukaran gagasan, pengalaman, dan praktik nyata di lapangan. Bagi UPITRA, kolaborasi ini sekaligus menjadi bagian dari komitmen untuk terus membuka diri terhadap jejaring akademik yang lebih luas.</p><p style=\"text-align: justify;\">Ke depan, UPITRA dan STIKOM Yos Sudarso Purwokerto berharap kerja sama ini dapat berkembang menjadi program-program konkret yang memberi dampak langsung bagi sivitas akademika kedua institusi, baik dalam bentuk kegiatan akademik bersama, riset kolaboratif, maupun pengembangan kapasitas sumber daya manusia. Dengan semangat saling belajar, kolaborasi ini diharapkan menjadi awal dari hubungan jangka panjang yang produktif dan berkelanjutan.</p>', '/images/berita/1777437635_69f18bc351910.jpg', NULL, 'Published', 0, 133, '2026-04-28 21:40:35', '2026-10-21 17:49:25');
INSERT INTO `berita` (`id`, `title`, `slug`, `category`, `date`, `excerpt`, `content`, `thumbnail`, `url`, `status`, `featured`, `views_count`, `created_at`, `updated_at`) VALUES
(18, 'Mahasiswa UPITRA Ubah Sampah Jadi Cuan Lewat Platform RESIK di Ajang Krenova 2026', 'mahasiswa-upitra-ubah-sampah-jadi-cuan-lewat-platform-resik-di-ajang-krenova-2026-69f1a0f3b0ee9', 'Prestasi', '2026-04-21', 'Platform digital karya orisinal yang dibawa delegasi UPITRA dalam ajang Kompetisi Riset Unggulan Kota Surakarta 2026 yang diselenggarakan oleh Badan Riset dan Inovasi Daerah (BRIDA) Kota Surakarta.', '<p style=\"text-align: justify;\"><span>Mengubah tumpukan sampah menjadi pundi-pundi rupiah bukan lagi sekadar impian bagi sekelompok mahasiswa Universitas Pignatelli Triputra (UPITRA). Di tengah riuhnya Solo Techno Park pada 14 hingga 15 April 2026, UPITRA memberikan inovasi terhadap pengelolaan sampah. Platform digital ini merupakan karya orisinal yang dibawa delegasi UPITRA dalam ajang Kompetisi Riset Unggulan Kota Surakarta 2026 yang diselenggarakan oleh Badan Riset dan Inovasi Daerah (BRIDA) Kota Surakarta.</span></p><p style=\"text-align: justify;\">Tim yang terdiri dari tiga mahasiswa Program Studi S1 Akuntansi—Evan Fajar Nugraha, Leonardo Reyhan, dan Surya Wicaksono ini menawarkan solusi konkret atas isu lingkungan di Kota Solo. Melalui proyek bertajuk \"RESIK: <em>Real-time Eco Friendly Solo Integrated Keeper</em>\", mereka menciptakan ekosistem digital yang menghubungkan penghasil sampah organik, pembudidaya maggot, hingga konsumen akhir.</p><p style=\"text-align: justify;\">Berbeda dengan aplikasi pengelolaan sampah biasa, RESIK fokus pada pemanfaatan <em>Maggot Black Soldier Fly</em>&nbsp;(BSF) sebagai agen biokonversi alami. Di bawah bimbingan dosen pendamping, Vitalis Ari Widiyaningsih, S.E., M.Si, para mahasiswa ini berhasil mengawinkan ilmu akuntansi mengenai efisiensi biaya dan manajemen aset dengan teknologi lingkungan.</p><p style=\"text-align: justify;\">Evan Fajar Nugraha, perwakilan tim, menjelaskan bahwa ide ini berangkat dari keinginan untuk menciptakan nilai ekonomi dari limbah dapur. \"Sampah organik sering dianggap beban, padahal punya nilai ekonomi tinggi jika dikelola dengan sistem yang terintegrasi. Lewat RESIK, kami ingin memastikan aliran sampah organik ini tercatat dan transparan, sehingga pembudidaya maggot tidak kesulitan bahan baku dan warga pun bisa mendapatkan keuntungan,\" ujar Evan di sela-sela presentasi risetnya.</p><p style=\"text-align: justify;\">Keikutsertaan mahasiswa Akuntansi dalam kompetisi riset teknologi ini menunjukkan bahwa UPITRA sangat serius dalam mengimplementasikan filosofi \"Academic Excellence with Industrial Edge\". Keunggulan akademik tidak lagi dikurung dalam batasan teori kelas saja. Mahasiswa didorong untuk memiliki ketajaman industri (<em>industrial edge</em>) dengan menciptakan produk yang mampu menjawab kebutuhan pasar dan kebijakan daerah.</p><p style=\"text-align: justify;\">Dari sisi akademik, riset ini membuktikan bahwa kompetensi akuntansi sangat relevan dalam membangun model bisnis berkelanjutan (<em>sustainable business model</em>). Sementara dari sisi industri, platform RESIK siap menjadi prototipe yang bisa diadaptasi oleh pemerintah daerah atau komunitas UMKM di Surakarta untuk memperkuat ketahanan pangan melalui pakan ternak berbasis maggot.</p><p style=\"text-align: justify;\">Branding UPITRA sebagai kampus yang mencetak inovator kini semakin nyata. Kehadiran mereka di ajang BRIDA ini mempertegas posisi universitas sebagai mitra strategis pembangunan Kota Surakarta melalui riset-riset mahasiswa yang membumi.</p><p style=\"text-align: justify;\">Langkah Evan dan tim di Solo Techno Park hanyalah awal. Ke depan, proyek RESIK diharapkan tidak hanya berhenti sebagai materi kompetisi, tetapi bisa diuji coba secara luas di lingkungan pasar atau rumah tangga di Solo.</p><p style=\"text-align: justify;\">Prestasi ini menjadi pengingat bagi mahasiswa lainnya bahwa inovasi bisa datang dari mana saja, selama kita peka terhadap masalah di sekitar kita. Selamat untuk Tim UPITRA, teruslah berkarya dan bawa dampak positif bagi Kota Solo!</p>', '/images/berita/1777443059_69f1a0f3b0bfb.jpeg', NULL, 'Published', 0, 306, '2026-04-28 23:10:59', '2026-10-18 23:38:35'),
(19, 'Mengawali tahun 2026 UPITRA berhasil menembus pendanaan nasional melalui enam riset dosen yang mencakup AI, Energi, hingga Ekonomi Inklusif', 'mengawali-tahun-2026-upitra-berhasil-menembus-pendanaan-nasional-melalui-enam-riset-dosen-yang-mencakup-ai-energi-hingga-ekonomi-inklusif-69f1bc4c2e333', 'Riset', '2026-04-15', 'Sebanyak enam judul dari dosen UPITRA dinyatakan lolos sebagai penerima pendanaan program penelitian bergengsi tahun anggaran 2026.', '<p><span>Kabar membanggakan datang dari koridor riset Universitas Pignatelli Triputra (UPITRA). Berdasarkan pengumuman resmi dari Direktorat Jenderal Riset dan Pengembangan, Kementerian Pendidikan Tinggi, Sains, dan Teknologi pada 9 April 2026, sebanyak enam judul dari dosen UPITRA dinyatakan lolos sebagai penerima pendanaan program penelitian bergengsi tahun anggaran 2026. Prestasi ini menjadi sinyal kuat bahwa inovasi yang lahir dari kampus kini semakin diperhitungkan untuk menjawab tantangan nasional.</span></p><p style=\"text-align: justify;\"><span>Enam proposal yang didanai mencakup spektrum inovasi yang luas, mulai dari teknologi kecerdasan buatan hingga ekonomi inklusif. Berikut adalah daftar para peneliti penerima hibah:<br><strong>Ketua : Tutus Praningki, S.Kom., M.Kom. | Penelitian Dosen Pemula (PDP)</strong>, dengan riset mengembangkan teknologi kecerdasan buatan untuk otomatisasi produksi batik melalui Hybrid Computer Vision-Deep Learning.<br><strong>Ketua : Heru Suwasono, S.E., </strong></span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\"><span><strong>M.Sc</strong></span></a><span><strong>. | Penelitian Fundamental - Reguler (PFR)</strong>meneliti fondasi ekonomi inklusif melalui pelaporan berkelanjutan pada UMKM Hijau di Surakarta.<br><strong>Ketua : Benedictus Herry Suharto, S.T., M.T. | Penelitian Fundamental - Reguler (PFR)</strong>merancang efisiensi energi gedung cerdas menggunakan pemodelan hibrida LSTM-GNN.<br><strong>Ketua : Imanuel Zega, S.Kom., M.Kom. | Penelitian Dosen Pemula (PDP)</strong>mengintegrasikan sistem paperless digital sebagai solusi keabsahan dokumen di era ekonomi hijau.<br><strong>Ketua : Wahyu Setiawan, S.M., </strong></span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\"><span><strong>M.Sc</strong></span></a><span><strong>. | Penelitian Dosen Pemula (PDP)</strong>memetakan karakteristik pendaki ramah lingkungan untuk pengelolaan destinasi wisata yang berkelanjutan.<br><strong>Ketua : Aldian Umbu Tamu Ama, </strong></span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://S.SI\"><span><strong>S.SI</strong></span></a><span><strong>., M.Cs. | Penelitian Dosen Pemula (PDP)</strong>menciptakan sistem deteksi dan perhitungan obat otomatis secara real-time untuk farmasi rumah sakit.</span></p>', '/images/berita/1777450060_69f1bc4c2e105.jpg', NULL, 'Published', 0, 144, '2026-04-29 01:07:40', '2026-10-21 10:15:51'),
(21, 'Membedah Masa Depan AI dan IoT: Dr. Toni Anwar Bagikan Perspektif Global di UPITRA', 'membedah-masa-depan-ai-dan-iot-dr-toni-anwar-bagikan-perspektif-global-di-upitra-6a0c029a3fc0f', 'Akademik', '2026-05-07', 'novasi dan kolaborasi global adalah kunci. Bersama UPITRA, setiap mahasiswa memiliki peluang yang sama untuk bertumbuh dalam ekosistem pendidikan yang terkoneksi dengan dunia internasional.', '<p style=\"text-align: justify;\"><span>Tren kecerdasan buatan (<em>Artificial Intelligence</em>) dan <em>Internet of Things</em> (IoT) bukan lagi sekadar wacana, melainkan kebutuhan kompetensi yang harus dikuasai mahasiswa saat ini. Memahami hal tersebut, Fakultas Sains dan Teknologi (FST) UPITRA menggelar kuliah umum bertajuk \"IoT and AI Application\" pada 15 April 2026 di Auditorium UPITRA.</span></p><p style=\"text-align: justify;\"><span>Acara ini menghadirkan Dr. rer. nat. Ts. Toni Anwar, seorang pakar sekaligus <em>Associate Professor</em> dari Universiti Teknologi Petronas, Malaysia. Kehadirannya memberikan kesempatan langka bagi mahasiswa dan dosen FST untuk berdialog langsung mengenai penerapan teknologi digital di skala internasional.</span></p><p style=\"text-align: justify;\"><span>Sepanjang sesi, Dr. Toni Anwar memaparkan bagaimana integrasi antara perangkat keras dan sistem cerdas mampu menciptakan solusi efisien bagi industri. Sebagai ahli di bidang <em>Embedded System</em>, <em>Smart Agriculture</em>, hingga <em>Machine Learning</em>, ia menekankan bahwa teknologi harus dirancang untuk mempermudah hidup manusia.</span></p><p style=\"text-align: justify;\"><span>Salah satu dosen yang hadir mencatat bahwa wawasan ini sangat relevan dengan kurikulum kampus. \"Diskusi tadi memberi gambaran nyata bagaimana teori yang dipelajari di kelas diaplikasikan pada industri besar seperti di Malaysia. Ini memotivasi mahasiswa untuk berpikir lebih luas, tidak hanya di lingkup lokal saja,\" ujarnya.</span></p><p style=\"text-align: justify;\"><span>Kegiatan ini mempertegas komitmen UPITRA dalam menjaga kualitas Academic Excellence with Industrial Edge. Keunggulan akademik dosen dan mahasiswa kini diperkuat dengan paparan standar industri global (<em>edge</em>) melalui relasi internasional yang telah dibangun universitas. Memiliki akses langsung ke pakar dari universitas mancanegara merupakan nilai plus bagi mahasiswa UPITRA agar siap bersaing setelah lulus nanti.</span></p><p style=\"text-align: justify;\"><span>Insight utama dari kegiatan ini adalah penyelarasan kompetensi digital mahasiswa dengan standar teknologi yang digunakan oleh perusahaan global. Dengan rutin mengadakan kuliah umum tingkat internasional, UPITRA memastikan lulusannya tidak hanya memiliki ijazah, tetapi juga wawasan industri yang tajam.</span></p><p style=\"text-align: justify;\"><span>Kuliah umum ini diakhiri dengan sesi tanya jawab yang dinamis, menunjukkan antusiasme tinggi dari para peserta. Diharapkan, paparan dari Dr. Toni Anwar menjadi pemicu bagi mahasiswa FST untuk mulai merancang proyek-proyek inovatif berbasis IoT dan AI yang dapat memberikan dampak positif bagi masyarakat.</span></p><p style=\"text-align: justify;\"><span>Inovasi dan kolaborasi global adalah kunci. Bersama UPITRA, setiap mahasiswa memiliki peluang yang sama untuk bertumbuh dalam ekosistem pendidikan yang terkoneksi dengan dunia internasional.</span></p>', '/images/berita/1779171994_6a0c029a3f66b.jpg', NULL, 'Published', 0, 208, '2026-05-18 23:26:34', '2026-10-22 07:40:28'),
(22, 'UPITRA Hadirkan Seminar yang Buka Jalan Gen Z Menuju Karier Global', 'upitra-hadirkan-seminar-yang-buka-jalan-gen-z-menuju-karier-global-6a0c0475b1aec', 'Akademik', '2026-05-08', 'Universitas Pignatelli Triputra (UPITRA) Surakarta tempat lahirnya generasi muda yang siap kerja, siap bersaing, dan siap sukses di dunia industri.', '<p style=\"text-align: justify;\">Surakarta, 30 April 2026 - Universitas Pignatelli Triputra kembali menegaskan posisinya&nbsp;sebagai kampus yang progresif dan relevan dengan kebutuhan zaman melalui&nbsp; penyelenggaraan UPITRA’s SOCIETY 5.0 Seminar Series #2 bertema “Travel, Content &amp; Global&nbsp; Experience: Cara Gen Z Menjelajah Dunia dan Bangun Masa Depan” yang digelar di Multi Function Hall UPITRA.&nbsp;</p><p style=\"text-align: justify;\"><br>Di tengah era digital yang serba cepat, UPITRA memahami bahwa Gen Z membutuhkan lebih dari sekadar teori. Mereka butuh arah, exposure, dan skill nyata. Seminar ini menjadi jawaban&nbsp;atas kebutuhan tersebut—membuka wawasan bahwa passion seperti traveling dan content&nbsp;creator bukan lagi sekadar hobi, tetapi bisa menjadi pintu masuk menuju karier global yang nyata dan menjanjikan.</p><p style=\"text-align: justify;\"></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1779176083_6a0c129343bfa.jpg\" alt=\"society-2.jpg\"><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">Menghadirkan dua akademisi berpengalaman, Wahyu Setiawan, S.M., M.Sc. dan Yulia Milka&nbsp; Nugraheni, S.S., M.A., peserta diajak memahami bagaimana membangun personal branding,&nbsp;mengolah perspektif lokal menjadi konten global, hingga membaca peluang karier di industri kreatif internasional. Materi disampaikan secara ringan, relatable, dan langsung bisa&nbsp; dipraktikkan gaya belajar yang sangat dekat dengan karakter Gen Z.</p><p style=\"text-align: justify;\"><br>“Di era digital, keunggulan bukan lagi soal siapa yang terbesar, tapi siapa yang paling autentik. Gen Z punya kekuatan itu tinggal bagaimana mengasah dan mengarahkannya,” ungkap Wahyu Setiawan dalam sesi seminar.&nbsp;</p><p style=\"text-align: justify;\">Antusiasme tinggi terlihat dari par sipasi sekitar 60 siswa-siswi SMA/SMK dari 10 sekolah di&nbsp; Surakarta. Mereka tidak hanya mendapatkan sertifikat, tetapi juga insight praktis, mindset baru, dan pengalaman langsung merasakan atmosfer kampus yang modern, suportif, dan berorientasi pada masa depan.&nbsp;</p><p style=\"text-align: justify;\"><br>UPITRA percaya bahwa masa depan tidak menunggu, namun masa depan harus dipersiapkan dengan baik. Dengan pendekatan pembelajaran yang relevan, jejaring global, dan lingkungan yang suportif, UPITRA hadir sebagai partner terbaik bagi generasi muda dalam merancang masa depan yang lebih luas dan bermakna.</p><p style=\"text-align: justify;\">&nbsp;<br>Nantikan rangkaian Seminar Series berikutnya dengan tema-tema yang dak kalah menarik dan berdampak. Bersama UPITRA, saatnya generasi muda melangkah lebih jauh, berani bermimpi besar, dan siap menaklukkan dunia.</p><p style=\"text-align: justify;\"><br>Universitas Pignatelli Triputra (UPITRA) Surakarta tempat lahirnya generasi muda yang&nbsp;siap kerja, siap bersaing, dan siap sukses di dunia industri.</p>', '/images/berita/1779172469_6a0c0475b1846.jpg', NULL, 'Published', 0, 326, '2026-05-18 23:34:29', '2026-10-18 03:32:37'),
(23, 'UPITRA Resmi Buka Rangkaian Dies Natalis Ke-4 dengan Semangat \"Funtastic 4\"', 'upitra-resmi-buka-rangkaian-dies-natalis-ke-4-dengan-semangat-funtastic-4-6a3df756dfbe9', 'Akademik', '2026-06-17', 'UPITRA resmi membuka Dies Natalis ke-4 bertema \"Funtastic 4\" melalui Senam Sehat, mengawali rangkaian kegiatan yang memperkuat kebersamaan, kolaborasi, dan semangat inovasi.', '<p><strong>Surakarta, 17 Juni 2026</strong> – Universitas Pignatelli Triputra (UPITRA) secara resmi membuka rangkaian perayaan Dies Natalis ke-4 melalui kegiatan Senam Sehat yang berlangsung meriah pada Rabu (17/6). Mengusung tema \"Funtastic 4 – Build, Bloom, Breakthrough, Beyond\", kegiatan ini menjadi awal dari berbagai agenda yang akan dilaksanakan sebagai bagian dari perayaan perjalanan empat tahun UPITRA dalam memberikan kontribusi bagi dunia pendidikan.</p><p style=\"text-align: justify;\">Kegiatan pembukaan dihadiri oleh Ketua Yayasan Santo Yosef Maria Pignatelli Surakarta, Bapak Laurentius Sumadi, Rektor UPITRA Dr. Fr. Ninik Yudianti, M.Acc., QIA., CSRA<strong>.</strong>, serta seluruh dosen, tenaga kependidikan, dan mahasiswa UPITRA. Suasana pagi yang penuh semangat mencerminkan kebersamaan seluruh sivitas akademika dalam menyambut momen istimewa ini.</p><p style=\"text-align: justify;\">Rangkaian acara diawali dengan senam sehat yang diikuti secara antusias oleh seluruh peserta. Selain menjadi ajang untuk menjaga kesehatan dan kebugaran, kegiatan ini juga menjadi ruang untuk mempererat hubungan antarpegawai, dosen, dan mahasiswa di luar aktivitas akademik sehari-hari. Tawa, semangat, dan kebersamaan yang terjalin selama kegiatan menjadi gambaran bahwa Dies Natalis bukan hanya tentang perayaan usia, tetapi juga tentang memperkuat rasa memiliki terhadap kampus.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1782445890_6a3df74247007.jpg\" alt=\"SENAM2.jpg\"><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1782445900_6a3df74c517cf.jpg\" alt=\"SENAM.jpg\"><p style=\"text-align: justify;\">Usai senam, seluruh peserta menikmati sarapan bersama dalam suasana yang hangat dan penuh keakraban. Momen sederhana ini menjadi kesempatan untuk saling berbincang, bertukar cerita, dan mempererat kolaborasi lintas unit maupun program studi.</p><p style=\"text-align: justify;\">Mengangkat tema \"Funtastic 4 – Build, Bloom, Breakthrough, Beyond\", Dies Natalis tahun ini mengajak seluruh keluarga besar UPITRA untuk terus membangun fondasi yang kuat (<em>Build</em>), bertumbuh bersama (<em>Bloom</em>), berani menciptakan terobosan (<em>Breakthrough</em>), serta melangkah lebih jauh menuju masa depan yang lebih baik (<em>Beyond</em>). Tema ini menjadi representasi komitmen UPITRA untuk terus berkembang sebagai perguruan tinggi yang mengedepankan kualitas akademik sekaligus kedekatan dengan dunia industri.</p><p style=\"text-align: justify;\">Pembukaan Dies Natalis ke-4 menjadi langkah awal dari berbagai kegiatan yang telah dipersiapkan panitia untuk melibatkan seluruh sivitas akademika. Diharapkan, setiap rangkaian kegiatan tidak hanya menghadirkan suasana yang menyenangkan, tetapi juga memperkuat budaya kolaborasi, kekeluargaan, serta semangat untuk terus memberikan kontribusi positif bagi masyarakat.</p><p style=\"text-align: justify;\">Melalui semangat Dies Natalis ke-4 ini, UPITRA terus menegaskan komitmennya untuk menghadirkan pendidikan yang relevan dengan kebutuhan zaman melalui tagline <strong>\"</strong>Academic Excellence with Industrial Edge\", sekaligus membangun lingkungan kampus yang sehat, inklusif, dan penuh semangat untuk terus tumbuh bersama.</p>', '/images/berita/1782445910_6a3df756df910.jpg', NULL, 'Published', 0, 186, '2026-06-25 20:51:50', '2026-10-22 03:00:59'),
(24, 'UPITRA Gelar Cek Kesehatan dan Donor Darah, Wujud Kepedulian terhadap Gaya Hidup Sehat dan Kolaborasi Dunia Kesehatan', 'upitra-gelar-cek-kesehatan-dan-donor-darah-wujud-kepedulian-terhadap-gaya-hidup-sehat-dan-kolaborasi-dunia-kesehatan-6a3df8709dea8', 'Akademik', '2026-06-25', 'UPITRA menggelar cek kesehatan dan donor darah dalam rangka Dies Natalis ke-4, bekerja sama dengan RS Brayat Minulya untuk mendorong budaya hidup sehat dan kepedulian sosial.', '<p><strong>Surakarta, 25 Juni 2026</strong> – Universitas Pignatelli Triputra (UPITRA) kembali melanjutkan rangkaian Dies Natalis ke-4 melalui kegiatan Cek Kesehatan dan Donor Darah yang diselenggarakan pada Kamis (25/6). Kegiatan ini menjadi bagian dari semangat Dies Natalis bertema \"Funtastic 4 – Build, Bloom, Breakthrough, Beyond\", yang tidak hanya menghadirkan berbagai kegiatan kebersamaan, tetapi juga mendorong budaya hidup sehat di lingkungan kampus.</p><p style=\"text-align: justify;\">Kegiatan diawali dengan pemeriksaan kesehatan bagi dosen dan tenaga kependidikan UPITRA yang meliputi pengecekan tekanan darah, kadar gula darah, kolesterol, hingga konsultasi kesehatan. Pemeriksaan ini merupakan implementasi nyata dari kerja sama antara UPITRA dan RS Brayat Minulya, sebagai bentuk sinergi antara dunia pendidikan dan layanan kesehatan dalam menciptakan lingkungan kerja yang lebih sehat dan produktif.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1782446176_6a3df8605580a.jpeg\" alt=\"donor darah.jpeg\"><p style=\"text-align: justify;\">Setelah pemeriksaan kesehatan, kegiatan dilanjutkan dengan aksi donor darah yang diikuti oleh dosen, tenaga kependidikan, mahasiswa, serta masyarakat yang ingin berpartisipasi. Selain membantu memenuhi kebutuhan stok darah, kegiatan ini juga menjadi ajakan sederhana untuk menumbuhkan kepedulian terhadap sesama melalui aksi nyata yang memberikan manfaat bagi banyak orang.</p><p style=\"text-align: justify;\">Kolaborasi dengan RS Brayat Minulya sekaligus menjadi salah satu langkah UPITRA dalam memperluas jejaring dengan berbagai mitra di bidang kesehatan. Sejalan dengan komitmen tersebut, UPITRA kini terus memperkuat kontribusinya dalam mencetak tenaga kesehatan yang profesional melalui pembukaan beberapa program studi baru, yaitu S1 Fisioterapi, S1 Kesehatan dan Keselamatan Kerja (K3), serta D3 Keperawatan.</p><p style=\"text-align: justify;\">Kehadiran program-program studi tersebut menjadi bagian dari upaya UPITRA untuk menjawab kebutuhan dunia kerja akan tenaga kesehatan yang kompeten, adaptif, dan siap menghadapi tantangan industri maupun pelayanan masyarakat. Mahasiswa tidak hanya dibekali dengan pembelajaran di kelas, tetapi juga didorong untuk memperoleh pengalaman nyata melalui kolaborasi dengan rumah sakit, institusi kesehatan, dan mitra industri.</p><p style=\"text-align: justify;\">Melalui kegiatan ini, UPITRA berharap semangat hidup sehat tidak hanya menjadi bagian dari perayaan Dies Natalis, tetapi juga menjadi budaya yang terus tumbuh di lingkungan kampus. Bersama mitra strategis, UPITRA akan terus menghadirkan berbagai program yang mendukung peningkatan kualitas pendidikan sekaligus memberikan manfaat bagi masyarakat.</p><p style=\"text-align: justify;\">Dengan semangat Academic Excellence with Industrial Edge, UPITRA terus menghadirkan pendidikan yang relevan dengan kebutuhan zaman, membangun kolaborasi yang berdampak, serta mempersiapkan lulusan yang siap berkarya di dunia profesional.</p>', '/images/berita/1782446192_6a3df8709db8e.jpeg', NULL, 'Published', 0, 226, '2026-06-25 20:56:32', '2026-10-22 03:34:37'),
(25, 'Empat Tahun Perjalanan UPITRA: Dari Pembenahan Internal Hingga Dorongan Inovasi Kampus', 'empat-tahun-perjalanan-upitra-dari-pembenahan-internal-hingga-dorongan-inovasi-kampus-6a66bedecfdbd', 'Akademik', '2026-07-27', 'UPITRA merayakan Dies Natalis ke-4 bertema Funtastic 4 dengan laporan rektor, orasi ilmiah, awarding, dan penguatan kolaborasi industri sebagai wujud komitmen pada mutu pendidikan.', '<p><strong>SOLO</strong> – Suasana Auditorium Universitas Pignatelli Triputra (UPITRA) tampak ramai pada Rabu, 22 Juli 2026. Ratusan civitas akademika—mulai dari pimpinan yayasan, dosen, tenaga kependidikan, hingga perwakilan mahasiswa—berkumpul untuk merayakan puncak peringatan Dies Natalis UPITRA yang ke-4. Mengusung tema <em>\"Funtastic 4: Build, Bloom, Breakthrough, Beyond\"</em>, momen ini menjadi wadah refleksi atas perjalanan kampus selama empat tahun terakhir.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1785118369_6a66bea1be311.jpeg\" alt=\"WhatsApp Image 2026-07-217 at 08.59.16.jpeg\"><p>Acara dibuka dengan penyampaian laporan empat tahun masa kepemimpinan Rektor UPITRA, Dr. Fr. Ninik Yudianti, M.Acc., QIA., CSRA<strong>.</strong> Dalam paparan tersebut, rektor menjelaskan fase perkembangan kampus yang dimulai dari penataan sistem internal, peningkatan mutu akademik, hingga perluasan jaringan kerja sama dengan dunia industri. Laporan ini memberikan gambaran riil mengenai arah pertumbuhan universitas sejak awal berdiri.</p><p>Suasana semakin terasa sakral saat salah satu dosen UPITRA, Dr. Dra. Endang Purwaningsih, M.M., M.H. menyampaikan orasi ilmiah. Pemaparan dengan tema meningkatkan good governance untuk keberlanjutan institusi sangat perlu melibatkan seluruh elemen, baik internal maupun eksternal, termasuk shareholder dan juga mitra.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1785118574_6a66bf6ed8c4e.jpeg\" alt=\"WhatsApp Image 2026-07-27 at 0e8.59.16.jpeg\"><p>\"Empat tahun ini menjadi proses belajar yang intens bagi kita semua. Meskipun belum semua terselesaikan, perkembangan kampus UPITRA sudah cukup pesat dan bisa memberikan dampak positif untuk seluruh masyarakat, khususnya di Solo,\" ujar salah satu dosen peserta acara di sela-sela kegiatan.</p><p>Melalui dukungan jaringan industri seperti Triputra Group dan Persada Capital Investama, UPITRA terus memperkuat relevansi pendidikan tinggi dengan dunia kerja. Pendekatan <em>Academic Excellence with Industrial Edge</em> diwujudkan lewat program riset terapan, kolaborasi proyek lingkungan, hingga penguatan standar pengajaran di kelas.</p><p>Sebagai bentuk apresiasi atas kontribusi internal, acara dilanjutkan dengan penyerahan penghargaan (<em>awarding</em>) bagi dosen peneliti, pengabdi, dan pengajar terbaik, serta tenaga kependidikan yang konsisten menerapkan nilai-nilai Triputra DNA. Momen peringatan ini diakhiri dengan pemotongan tumpeng dan ramah tamah antarcivitas academica.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1785118633_6a66bfa94538a.jpeg\" alt=\"WhatsApp Image 2026-07-27w at 08.59.16.jpeg\"><p></p>', '/images/berita/1785118430_6a66bedecfaed.jpeg', NULL, 'Published', 0, 244, '2026-07-26 19:13:50', '2026-10-19 22:09:55'),
(26, 'Buktikan Kualitas Akademik Global, Mahasiswa FEB UPITRA Kritis Berdiskusi dalam Kuliah Tamu Bersama Profesor Waseda University Jepang', 'buktikan-kualitas-akademik-global-mahasiswa-feb-upitra-kritis-berdiskusi-dalam-kuliah-tamu-bersama-profesor-waseda-university-jepang-6a9e8ae5d9b19', 'Kemahasiswaan', '2026-09-07', 'UPITRA menggelar kuliah tamu metodologi riset eksperimental bersama Prof. Robert Veszteg dari Waseda University untuk membekali mahasiswa dengan wawasan serta daya saing global.', '<p style=\"text-align: justify;\"><strong>SURAKARTA</strong> — Fakultas Ekonomika dan Bisnis (FEB) berkolaborasi dengan FAM Universitas Pignatelli Triputra (UPITRA) Surakarta sukses menggelar kuliah tamu bertajuk \"Research Workshop: Experimental Research Methodology\" pada Senin (7/9/2026). Bertempat di Gedung T.P. Rachmat UPITRA, acara ini menghadirkan pakar kelas dunia, Prof. Robert Veszteg, seorang akademisi di bidang Political Science and Economics dari Waseda University, Jepang. </p><p style=\"text-align: justify;\">Kegiatan yang dihadiri oleh jajaran dosen dan didominasi oleh mahasiswa FEB UPITRA ini secara khusus membedah materi \"Brief Introduction to the Experimental Method in Economics\". Kehadiran profesor dari universitas terkemuka di Jepang ini menjadi bukti nyata komitmen UPITRA dalam membawa ekosistem pendidikan berwawasan global langsung ke dalam ruang kelas mahasiswanya. </p><p style=\"text-align: justify;\">Menariknya, atmosfer perkuliahan berjalan sangat hidup dan interaktif. Walaupun seluruh pemaparan materi hingga sesi tanya jawab berlangsung penuh menggunakan bahasa Inggris, hal tersebut sama sekali tidak menyurutkan keberanian peserta. Sebaliknya, terbangun diskusi dua arah yang sangat baik antara mahasiswa FEB UPITRA dengan Prof. Robert Veszteg. </p><p style=\"text-align: justify;\">Bagi calon mahasiswa dan orang tua, pemandangan dinamika kelas yang proaktif ini adalah cerminan nyata dari kualitas pendidikan di UPITRA. Di kampus ini, mahasiswa dididik untuk tidak sekadar menelan mentah-mentah teori ekonomi konvensional dari buku teks, tetapi diperkenalkan pada metode riset eksperimental tingkat lanjut. Melalui perkuliahan semacam ini, mahasiswa diajak untuk berpikir selangkah lebih maju— membuktikan teori perilaku pasar secara langsung, melatih logika analitis, dan yang terpenting, membangun kepercayaan diri untuk beradu argumen dengan pakar internasional. </p><p style=\"text-align: justify;\">Keberanian mahasiswa UPITRA dalam berinteraksi menggunakan bahasa asing dan membedah isu-isu riset akademis ini merupakan modal yang sangat berharga. Bekal ini dipersiapkan secara matang oleh institusi agar lulusan UPITRA kelak tidak hanya mengantongi ijazah, tetapi juga adaptif, berdaya saing global, dan tangguh dalam memecahkan permasalahan nyata di dunia kerja profesional. </p><p style=\"text-align: justify;\">Ke depannya, UPITRA akan terus membuka dan memperbanyak ruang-ruang kolaborasi akademik berskala internasional. Langkah strategis ini senantiasa diselaraskan dengan visi universitas untuk mencetak talenta-talenta muda tepercaya yang siap menghadapi tantangan masa depan.unggul, berdaya saing tinggi, dan siap menjadi talenta tepercaya di masa depan.  </p><p>salam UPITRA READY!, Campus to Career </p>', '/images/berita/1788775141_6a9e8ae5d96a8.jpeg', NULL, 'Published', 0, 99, '2026-09-07 02:59:01', '2026-10-19 09:15:20'),
(27, 'Bangun Relasi Global Lewat \"Fun Day\", UPITRA Sambut 26 Mahasiswa UTP Malaysia dalam Program Pertukaran Akademik', 'bangun-relasi-global-lewat-fun-day-upitra-sambut-26-mahasiswa-utp-malaysia-dalam-program-pertukaran-akademik-6a9fd9a1873bb', 'Event', '2026-09-08', 'UPITRA Surakarta menyambut 26 mahasiswa Universiti Teknologi PETRONAS Malaysia dalam program Academic Exchange. Acara diisi kegiatan \"Fun Day\" dan tur budaya Yogyakarta–Surakarta hingga Jumat.', '<p><strong>SURAKARTA</strong> — Universitas Pignatelli Triputra (UPITRA) Surakarta kembali menunjukkan komitmennya dalam mencetak mahasiswa berwawasan global. Kali ini, UPITRA menyambut hangat kedatangan 26 mahasiswa dari Universiti Teknologi PETRONAS (UTP) Malaysia dalam rangkaian program <em>Academic Exchange</em>. Pertemuan lintas negara ini dibuka dengan penuh keceriaan melalui kegiatan \"Fun Day\" yang digelar di kampus UPITRA pada Selasa (8/9/2026).</p><p style=\"text-align: justify;\">Delegasi mahasiswa asal negeri jiran tersebut hadir didampingi oleh akademisi sekaligus peneliti UTP, Assoc. Prof. Ts. Dr. Toni Anwar. Kehadiran mereka disambut langsung oleh jajaran pimpinan UPITRA, di antaranya Wakil Rektor 1 Bidang Akademik, Prof. Johana E. Prawitasari, Ph.D., Psi., serta Direktur Urusan Kemahasiswaan &amp; Kerjasama, Thomas Ambar Prihastomo, S.S., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>.</p><p style=\"text-align: justify;\">Bagi calon mahasiswa dan orang tua, program pertukaran akademik semacam ini adalah bukti nyata bahwa iklim belajar di UPITRA tidak hanya terjadi di dalam kelas. Mahasiswa secara aktif didorong untuk berinteraksi dengan dunia internasional guna melatih kemampuan adaptasi dan komunikasi lintas budaya.</p><p style=\"text-align: justify;\">Hal ini sejalan dengan pesan yang disampaikan oleh Thomas Ambar Prihastomo dalam sambutannya. Ia menekankan bahwa kegiatan ini adalah momentum emas bagi mahasiswa untuk memperluas pergaulan.</p><p style=\"text-align: justify;\">\"Ini adalah kesempatan yang sangat baik untuk membangun jejaring pertemanan antara mahasiswa UPITRA dan UTP Malaysia. Bagi teman-teman UPITRA, jadikan ini kesempatan untuk keluar dari zona nyaman. Bangunlah relasi dengan dunia luar, karena siapa tahu jejaring pertemanan internasional yang kalian mulai hari ini bisa bertahan hingga bertahun-tahun ke depan,\" ujar Thomas memotivasi para mahasiswa.</p><p style=\"text-align: justify;\">Senada dengan hal tersebut, Assoc. Prof. Ts. Dr. Toni Anwar dari UTP juga mengajak seluruh peserta untuk memaksimalkan program kolaborasi ini. \"Mari kita manfaatkan kesempatan berharga ini sebaik mungkin, karena kita tidak pernah tahu kapan momen kebersamaan dan pertukaran ilmu seperti ini akan muncul kembali,\" pesannya.</p><p style=\"text-align: justify;\">Keseruan \"Fun Day\" diisi dengan tiga jenis kompetisi persahabatan, yaitu Bola Basket, <em>E-Sport</em> (Mobile Legends), dan <em>Local Games</em>. Momen yang paling mencuri perhatian adalah saat mahasiswa UTP diperkenalkan pada permainan tradisional Indonesia (<em>Local Games</em>) seperti lompat tali, congklak, ular naga, dan gobak sodor. Para mahasiswa internasional tersebut tampak sangat antusias, penuh semangat, dan bahagia menikmati interaksi budaya yang hangat ini.</p><p style=\"text-align: justify;\">Program <em>Academic Exchange</em> ini rencananya akan berlangsung hingga Jumat mendatang. Setelah diisi dengan kegiatan <em>Fun Day</em> di kampus, rombongan mahasiswa UTP bersama perwakilan UPITRA akan melanjutkan agenda dengan tur pengenalan budaya melintasi Yogyakarta hingga Surakarta.</p><p style=\"text-align: justify;\">Ke depannya, baik UPITRA maupun UTP berharap kolaborasi ini dapat terus berjalan lancar dan berkesinambungan, membuka jalan bagi program-program pertukaran pelajar tingkat lanjut yang memberikan dampak positif bagi pendidikan karakter mahasiswa di kedua institusi.</p><p style=\"text-align: justify;\">&nbsp;</p><p>salam UPITRA READY!, Campus to Career</p>', '/images/berita/1788916050_6aa0b1529c9f8.jpeg', NULL, 'Published', 0, 177, '2026-09-08 02:47:13', '2026-10-20 18:15:14'),
(28, 'Dari Bangku Kuliah ke Dunia Industri,  Mahasiswi UPITRA Rintis Karier di Triputra Group', 'dari-bangku-kuliah-ke-dunia-industri-mahasiswi-upitra-rintis-karier-di-triputra-group-6aa240d08895a', 'Prestasi', '2026-09-10', 'Dyah dan Angelica, mahasiswa S1 Sistem Informasi UPITRA, sukses diterima kerja di ASSA Group sebelum wisuda lewat program Immersion 3+1 yang membekali mahasiswa siap bersaing di industri.', '<p><span><strong>SURAKARTA</strong> - Kualitas pendidikan dan relevansi kurikulum dengan kebutuhan industri kembali dibuktikan oleh mahasiswa Universitas Pignatelli Triputra (UPITRA) Surakarta. Dua mahasiswi dari program studi S1 Sistem Informasi, yakni Dyah Lintang Ambarwari dan Angelica Rachel Dheantina, sukses menorehkan kebanggaan dengan diterima bekerja secara profesional bahkan sebelum mereka resmi diwisuda.</span></p><p style=\"text-align: justify;\"><span>Keduanya berhasil lolos seleksi dan kini menempati posisi strategis sebagai <em>BPO Agent – Dept. ICT Logistic</em> di ASSA Group. Sebagai informasi, ASSA Group merupakan salah satu perusahaan raksasa berskala nasional yang terkemuka di Indonesia, berfokus pada penyediaan layanan mobilitas, transportasi, dan logistik yang terintegrasi. Keberhasilan menembus perusahaan besar ini diumumkan secara resmi melalui Biro Layanan Organisasi dan Kesejahteraan Mahasiswa UPITRA pada September 2026.</span></p><p style=\"text-align: justify;\"><span>Bagi calon mahasiswa dan orang tua, kepastian prospek karier setelah lulus tentu menjadi pertimbangan utama dalam memilih perguruan tinggi. Pencapaian Dyah dan Angelica menjadi tolok ukur nyata bahwa ekosistem pembelajaran di UPITRA tidak hanya membekali mahasiswa dengan penguasaan teori akademik, tetapi juga kesiapan mental dan keahlian praktis yang tajam untuk langsung terserap oleh dunia industri yang kompetitif. \"Pencapaian ini menjadi bukti bahwa mahasiswa UPITRA mampu mempersiapkan diri dan bersaing di dunia industri bahkan sebelum menyelesaikan masa studinya,\" demikian pernyataan resmi yang disampaikan oleh Biro Layanan Organisasi dan Kesejahteraan Mahasiswa UPITRA menyambut kabar gembira tersebut.</span></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1789018272_6aa240a0e3895.jpeg\" alt=\"WhatsApp Image 2026-09-10 at 11.26.07.jpeg\"><p style=\"text-align: justify;\"><span><br><strong>Dibentuk untuk Siap Masuk Industri melalui Immersion 3+1</strong></span></p><p style=\"text-align: justify;\"><span>Kesiapan mahasiswa UPITRA menuju dunia kerja tidak dibangun secara instan. Salah satu keunggulan yang menjadi pembeda pengalaman pendidikan di UPITRA adalah <strong>program Immersion 3+1</strong>, yang dirancang untuk mendekatkan mahasiswa dengan dunia industri sejak masih berada di bangku kuliah.</span></p><p style=\"text-align: justify;\"><span>Melalui skema <strong>3+1</strong>, mahasiswa menjalani proses pembelajaran akademik di kampus pada tahap awal perkuliahan, kemudian mendapatkan pengalaman pembelajaran langsung di lingkungan industri. Pendekatan ini memberikan ruang bagi mahasiswa untuk memahami bagaimana pengetahuan yang diperoleh di kelas diterapkan dalam situasi kerja yang nyata, sekaligus membangun kemampuan beradaptasi, berkolaborasi, memecahkan masalah, dan berkomunikasi secara profesional.</span></p><p style=\"text-align: justify;\"><span>Lebih dari sekadar pengalaman kerja, proses Immersion juga menjadi bagian dari pembentukan <strong>DNA Triputra Group</strong> yang ditanamkan sejak mahasiswa berada di bangku kuliah. Mahasiswa tidak hanya dipersiapkan untuk <em>job ready</em>, tetapi juga dibentuk menjadi talenta yang memiliki karakter dan nilai yang sejalan dengan kebutuhan dunia industri. Empat nilai utama tersebut tercermin dalam <strong>Integrity &amp; Ethics, Excellence, Compassion, dan Humility</strong>.</span></p><p style=\"text-align: justify;\"><span>Perpaduan antara pembelajaran akademik, pengalaman industri, dan pembentukan karakter tersebut menjadi bagian dari upaya UPITRA dalam menjalankan semangat <strong>link and match</strong> antara perguruan tinggi dan dunia industri.</span></p><p style=\"text-align: justify;\"><span>Keberhasilan dua mahasiswi Sistem Informasi ini diharapkan dapat menjadi inspirasi sekaligus pemacu semangat bagi seluruh sivitas akademika. UPITRA secara konsisten terus mendorong para mahasiswanya untuk proaktif mengembangkan potensi diri, berani mengambil peluang, dan menyiapkan portofolio yang matang guna menjemput karier impian sejak dini.</span></p><p style=\"text-align: justify;\"><span>Langkah awal karier yang gemilang dari Dyah dan Angelica menjadi bukti bahwa bersama UPITRA, mahasiswa dibentuk untuk tidak sekadar siap lulus dengan ijazah, tetapi siap bersaing dan menjadi talenta andal di dunia kerja profesional.</span></p><p><span><strong><em>salam UPITRA READY! From Campus to Career</em></strong></span></p>', '/images/berita/1789023187_6aa253d3178fb.jpeg', NULL, 'Published', 0, 119, '2026-09-09 22:32:00', '2026-10-21 21:44:05'),
(29, 'Lulusan Berdaya Saing, Dua Mahasiswi Sistem Informasi UPITRA Sukses Direkrut Perusahaan Sebelum Wisuda', 'lulusan-berdaya-saing-dua-mahasiswi-sistem-informasi-upitra-sukses-direkrut-perusahaan-sebelum-wisuda-6aa8ef1228aa2', 'Prestasi', '2026-09-15', 'Dua mahasiswi S1 Sistem Informasi UPITRA, Valencia dan Benedikta, berhasil diterima bekerja di perusahaan besar sebelum resmi diwisuda berkat kualitas kurikulum dan program Immersion 3+1.', '<p><strong>SURAKARTA</strong> — Kualitas pendidikan dan relevansi kurikulum dengan kebutuhan industri kembali dibuktikan oleh mahasiswa Universitas Pignatelli Triputra (UPITRA) Surakarta. Dua mahasiswi dari program studi S1 Sistem Informasi, yakni Valencia Angel Saputra dan Benedikta Cindy Permatasari, sukses menorehkan kebanggaan dengan diterima bekerja secara profesional bahkan sebelum mereka resmi diwisuda.</p><p style=\"text-align: justify;\">Keduanya berhasil lolos seleksi dan kini menempati posisi strategis di dua perusahaan besar. Valencia Angel Saputra telah resmi bergabung menempati posisi di Departemen Marketing pada Divisi Ekspedisi terhitung sejak 27 Juli 2026. Menyusul keberhasilan tersebut, Benedikta Cindy Permatasari juga berhasil menembus industri digital dengan menempati posisi strategis sebagai <em>Web Designer</em> di Divisi Digital Marketing mulai 1 Agustus 2026.</p><p style=\"text-align: justify;\">Kesuksesan kedua mahasiswi ini menembus dunia kerja tidak lepas dari reputasi tempat mereka bernaung. Benedikta Cindy direkrut oleh PT Duta Niaga Indonesia Manunggal, sebuah perusahaan besar yang merupakan bagian dari jaringan <strong>Dwi Manunggal Group</strong>. Sementara itu, Valencia Angel terserap sebagai tenaga profesional di <strong>PT Sumber Plastik Top</strong>, salah satu perusahaan terkemuka di sektornya.</p><p style=\"text-align: justify;\">Bagi calon mahasiswa dan orang tua, kepastian prospek karier setelah lulus tentu menjadi pertimbangan utama dalam memilih perguruan tinggi. Pencapaian Valencia dan Benedikta menjadi tolok ukur nyata bahwa ekosistem pembelajaran di UPITRA tidak hanya membekali mahasiswa dengan penguasaan teori akademik, tetapi juga kesiapan mental dan keahlian praktis yang tajam untuk langsung terserap oleh dunia industri yang kompetitif.</p><p style=\"text-align: justify;\"><strong>Dibentuk untuk Siap Masuk Industri melalui Immersion 3+1</strong></p><p style=\"text-align: justify;\">Kesiapan mahasiswa UPITRA menuju dunia kerja tentu tidak dibangun secara instan. Salah satu keunggulan yang menjadi pembeda pengalaman pendidikan di UPITRA adalah program <em>Immersion 3+1</em>, yang dirancang untuk mendekatkan mahasiswa dengan dunia industri sejak masih berada di bangku kuliah.</p><p style=\"text-align: justify;\">Melalui skema 3+1 ini, mahasiswa menjalani proses pembelajaran akademik di kampus pada tahap awal perkuliahan, kemudian mendapatkan pengalaman pembelajaran langsung di lingkungan industri. Pendekatan ini memberikan ruang bagi Valencia, Benedikta, dan mahasiswa lainnya untuk memahami bagaimana pengetahuan yang diperoleh di kelas diterapkan dalam situasi kerja yang nyata. Sekaligus, program ini membangun kemampuan beradaptasi, berkolaborasi, memecahkan masalah, dan berkomunikasi secara profesional.</p><p style=\"text-align: justify;\">Lebih dari sekadar pengalaman kerja, proses <em>Immersion</em> juga menjadi kawah candradimuka bagi pembentukan DNA Triputra Group yang ditanamkan sejak dini. Mahasiswa tidak hanya dipersiapkan untuk sekadar <em>job ready</em>, tetapi juga dibentuk menjadi talenta yang memiliki karakter dan nilai yang sejalan dengan kebutuhan dunia industri. Empat nilai utama tersebut tercermin dalam <em>Integrity &amp; Ethics</em>, <em>Excellence</em>, <em>Compassion</em>, dan <em>Humility</em>.</p><p style=\"text-align: justify;\">Bagi calon mahasiswa dan orang tua, terserapnya mahasiswa di dunia kerja sebelum masa kelulusan merupakan indikator penting akan kualitas sebuah perguruan tinggi. Perpaduan antara pembelajaran akademik, pengalaman industri, dan pembentukan karakter di UPITRA terbukti menjalankan semangat <em>link and match</em> antara dunia pendidikan dan profesional.</p><p style=\"text-align: justify;\">\"Pencapaian ini menjadi bukti nyata bahwa mahasiswa UPITRA mampu mempersiapkan diri dengan matang dan bersaing di dunia industri, bahkan sebelum menyelesaikan masa studinya,\" tulis pernyataan resmi dari Biro Layanan Organisasi dan Kesejahteraan Mahasiswa UPITRA.</p><p style=\"text-align: justify;\">Melalui pencapaian ini, UPITRA berharap langkah awal yang gemilang dari Valencia dan Benedikta dapat membawa kesuksesan, pengalaman, serta peluang yang semakin terbuka lebar ke depannya. Sekaligus, prestasi ini diharapkan mampu memantik semangat mahasiswa UPITRA lainnya untuk terus mengembangkan potensi dan menyiapkan portofolio guna menjemput karier impian sedini mungkin.</p>', '/images/berita/1789456146_6aa8ef1228845.png', NULL, 'Published', 0, 127, '2026-09-15 00:09:06', '2026-10-22 01:02:40'),
(30, 'Bangun Ekosistem Inovasi Sejak Dini,  UPITRA Terjun Langsung Gembleng 700 Siswa SMA Regina Pacis Rintis Startup', 'bangun-ekosistem-inovasi-sejak-dini-upitra-terjun-langsung-gembleng-700-siswa-sma-regina-pacis-rintis-startup-6aabfb89df301', 'Event', '2026-09-17', 'UPITRA dan SMA Regina Pacis menggelar Workshop Futurepreneur untuk 700 siswa. Dipandu CEO Triputra Group dan dosen UPITRA, siswa dilatih menyusun BMC hingga pitching ide bisnis.', '<p><strong>SURAKARTA</strong> — Universitas Pignatelli Triputra (UPITRA) Surakarta kembali membuktikan perannya sebagai motor penggerak pendidikan yang berorientasi pada kesiapan industri. Berkolaborasi dengan SMA Regina Pacis Surakarta, UPITRA sukses menggelar Workshop Futurepreneur Project: \"See the Problem, Create the Solution, Build the Future\" pada Kamis, 17 September 2026. Kegiatan akbar yang berlangsung di Auditorium SMA Regina Pacis Surakarta ini diikuti secara antusias oleh 700 peserta didik dari kelas X dan XI.</p><p style=\"text-align: justify;\">Menggandeng jajaran CEO dari ekosistem Triputra Group dan para akademisi ahli dari UPITRA, acara ini dirancang untuk mendobrak batasan ruang kelas konvensional. Siswa diajak untuk tidak sekadar menghafal teori, tetapi mempraktikkan langsung bagaimana membangun sebuah <em>startup</em> dan bisnis yang berdampak.</p><p style=\"text-align: justify;\">Pada sesi pembuka, Yohanes Tan, CEO PT Triputra Edukasi Nusantara (TEN), membagikan pengalaman inspiratifnya bertransformasi dari profesional bidang <em>supply chain</em> hingga memimpin sektor pendidikan. Ia menekankan bahwa kunci utama membangun <em>startup</em> adalah kepekaan melihat permasalahan yang ada (<em>the problem</em>) dan memastikan bahwa solusi yang ditawarkan memiliki nilai yang layak untuk diwujudkan (<em>worth solving</em>).</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1789655822_6aabfb0e5eee3.jpeg\" alt=\"WhatsApp Image 2026-09-17 at 17.08.53.jpeg\"><p><em>CEO PT Triputra Edukasi Nusantara (TEN), Yohanes Tan, saat berbagi inspirasi dan pengalaman dunia industri</em></p><p style=\"text-align: justify;\">Menguatkan fondasi tersebut, Pius Petura Sinuraya selaku CEO PT Lintas Samudra Borneo Line &amp; PUMA (Trive’s Subco) mengawal para siswa dalam menyusun <em>Business Model Canvas</em> (BMC). Dengan mengusung semangat <em>living serviam through innovation</em>, Pius mengajak generasi muda untuk membangun inovasi yang berakar pada empati lokal. \"Inovasi dimulai dari masalah nyata di sekitar kita, bukan sekadar ide program acak,\" tegasnya saat membimbing para siswa memetakan model bisnis personal mereka di masa depan.</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1789655847_6aabfb2752552.jpeg\" alt=\"WhatsApp Image 2026-09-1w7 at 17.08.52.jpeg\"><p><em>CEO PT Lintas Samudra Borneo Line &amp; PUMA, Pius Petura Sinuraya, memandu para siswa merancang inovasi bisnis melalui pemetaan Business Model Canvas (BMC).</em></p><p style=\"text-align: justify;\">Keseruan semakin terbangun pada sesi kedua. Layaknya di dunia kampus dan industri profesional, peserta didik dibagi ke dalam empat kelas spesialisasi operasional bisnis yang dimentori langsung oleh para pakar dan dosen UPITRA. Kelas <em>CEO/Project Manager</em> dipandu oleh Agustinus Kismet N. J., S.E., MBA. dan Margareta Ernanda Rahardani, S.M., M.M. Kelas <em>Finance</em> dibimbing oleh Heru Suwasono, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>.</p><p style=\"text-align: justify;\">Sementara itu, kelas <em>Product Development</em> dikawal oleh Mawar Hardiyanti S.Kom., M.Kom. dan Yeremia Victor Rondonuwu, S.Kom., M.M. Terakhir, strategi pengenalan produk di kelas <em>Marketing</em> dibedah tuntas oleh Maria Karmelia Fajarlestari S.Kom., M.Kom., Vincentia Indah Puspita Sari, S.E., M.M., dan Veronica Tiara, S.Kom., M.M., CPS., iCPM. Di dalam kelas-kelas ini, ide-ide mentah siswa dikonstruksi menjadi konsep bisnis yang lebih matang dan terukur.</p><p style=\"text-align: justify;\">Puncak acara berlangsung di sesi ketiga, di mana para siswa ditantang untuk mempresentasikan hasil racikan ide mereka. Bertindak sebagai <em>Lead Mentor</em>, Direktur Urusan Kemahasiswaan dan Kerjasama UPITRA, Thomas Ambar Prihastomo, S.S., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>., hadir langsung mengawal sesi <em>pitching</em> dan memberikan masukan konstruktif ala praktisi bisnis nyata.</p><p style=\"text-align: justify;\">Sinergi berkelanjutan ini tidak akan berhenti pada selembar kanvas ide. Ke depannya, tim UPITRA berkomitmen penuh untuk terus mendampingi para siswa SMA Regina Pacis dalam merancang dan merealisasikan <em>prototype</em> bisnis mereka.</p><p style=\"text-align: justify;\">Kolaborasi proaktif ini menjadi bukti nyata bahwa UPITRA adalah institusi terpercaya yang sungguh-sungguh mewadahi talenta muda sejak dini. Dengan akses ke jaringan industri yang sangat besar, UPITRA siap menjembatani ide-ide brilian generasi penerus bangsa menuju kesuksesan dunia kerja yang sesungguhnya.</p><p style=\"text-align: justify;\">&nbsp;</p><p style=\"text-align: justify;\">Salam UPITRA READY! From Campus to Career.</p>', '/images/berita/1789655945_6aabfb89df14e.jpeg', NULL, 'Published', 0, 150, '2026-09-17 07:39:05', '2026-10-21 19:35:36');
INSERT INTO `berita` (`id`, `title`, `slug`, `category`, `date`, `excerpt`, `content`, `thumbnail`, `url`, `status`, `featured`, `views_count`, `created_at`, `updated_at`) VALUES
(32, 'Sinergi UPITRA dan SMA BOSA: Jembatani Siswa Menuju Dunia Industri Melalui Pendidikan Karakter dan Beasiswa', 'sinergi-upitra-dan-sma-bosa-jembatani-siswa-menuju-dunia-industri-melalui-pendidikan-karakter-dan-beasiswa-6abce7f2d4ee9', 'Kerjasama', '2026-09-30', 'UPITRA dan SMA BOSA Yogyakarta resmi menjalin kerja sama untuk mencetak lulusan siap kerja. Melalui beasiswa dan program 3+1, mahasiswa disiapkan langsung terjun ke industri.', '<p><strong>YOGYAKARTA</strong> — Dalam upaya mempersiapkan generasi muda menuju dunia kerja dan industri profesional yang kompetitif, Universitas Pignatelli Triputra (UPITRA) resmi menjalin kerja sama strategis dengan SMA Bopkri 1 (BOSA) Yogyakarta. Kolaborasi ini dirancang khusus untuk memfasilitasi lulusan sekolah menengah agar mendapatkan akses pendidikan tinggi berkualitas yang terhubung langsung dengan kebutuhan industri masa kini.</p><p style=\"text-align: justify;\">Komitmen ini dikukuhkan melalui penandatanganan Nota Kesepahaman (MoU) yang dilakukan secara langsung oleh Rektor UPITRA, Neil Semuel Rupidara, S.E., <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\">M.Sc</a>., Ph.D., bersama Kepala Sekolah SMA Bopkri 1 Yogyakarta, Catharina Evita Aprilianti, S.Kom., M.Eng.</p><p style=\"text-align: justify;\">Agenda kemudian dilanjutkan dengan langkah taktis berupa penandatanganan Perjanjian Kerja Sama (MoA) oleh Wakil Rektor 2 UPITRA, Yohanes Bayu Samodro, S.Pd., M.Pd., dengan Manajer Multimedia &amp; Public Engagement SMA Bopkri 1, Timotius Tri Yogatama, M.Pd. Gr.</p><p style=\"text-align: justify;\">Sebagai perguruan tinggi yang didukung penuh oleh Triputra Group—korporasi berskala nasional yang menaungi lebih dari 170 perusahaan—UPITRA bertekad kuat mencetak lulusan yang tidak hanya unggul secara akademik, tetapi juga siap kerja. Dalam pemaparannya, pimpinan UPITRA menegaskan bahwa kehadiran universitas ini merupakan wujud pengabdian nyata korporasi bagi anak bangsa.</p><p style=\"text-align: justify;\">\"UPITRA adalah sebuah universitas yang berpikir tentang bagaimana memberikan kesempatan untuk berkarya bagi anak-anak bangsa melalui pendidikan. Kami adalah bagian dari korporasi besar Triputra Group, di mana misi utamanya adalah memberikan kesempatan belajar kepada masyarakat, khususnya agar mereka siap terjun ke dunia profesional,\" ungkap Neil Semuel selaku Rektor UPITRA.</p><p style=\"text-align: justify;\"><strong>Hapus Jarak Kampus dan Industri Lewat Program 3+1</strong></p><p style=\"text-align: justify;\">Kerja sama strategis dengan SMA BOSA ini menjadi jembatan untuk memperkenalkan inovasi pendidikan UPITRA, salah satunya adalah Program <em>Immersion</em> atau 3+1.</p><p style=\"text-align: justify;\">Yohanes Bayu Samodro menjelaskan bahwa pendekatan akademik ini dirancang agar mahasiswa tidak mengalami gegar budaya saat beralih ke dunia kerja sesungguhnya.</p><p style=\"text-align: justify;\">\"Yang kami tawarkan di UPITRA itu memang berfokus pada kampus industri. Artinya, kita berpikir untuk bisa menyiapkan anak-anak ini siap bekerja. Program kita itu ada 3+1; tiga tahun kuliah di dalam kampus, dan satu tahunnya terjun sungguh-sungguh bekerja di industri,\" jelas Bayu.</p><p><span>Melalui skema tersebut, mahasiswa UPITRA nantinya tidak sekadar magang biasa, melainkan diinkubasi langsung di berbagai perusahaan milik Triputra Group maupun mitra industri lainnya.</span></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1790765012_6abce7d4af52f.jpeg\" alt=\"WhatsApp Image 2026-09-30s at 17.35.07.jpeg\"><p><strong>Peluang Beasiswa dan Fokus pada Karakter</strong></p><p style=\"text-align: justify;\">Saat ini, UPITRA menawarkan sejumlah program studi prospektif seperti S1 Manajemen, S1 Akuntansi, S1 Sistem Informasi, S1 Rekayasa Perangkat Lunak, dan D3 Keperawatan, S1 Keselamatan &amp; Kesehatan Kerja. Melalui kemitraan ini, UPITRA juga membuka peluang luas bagi siswa SMA BOSA untuk meraih berbagai skema beasiswa, termasuk Beasiswa A.A. Rahmat. Bantuan ini memastikan para siswa berprestasi bisa terus melanjutkan pendidikan tanpa khawatir terhalang kendala biaya.</p><p style=\"text-align: justify;\">Di samping hardskill, UPITRA menempatkan pembentukan karakter sebagai fondasi utama pendidikannya. Nilai-nilai DNA Triputra, yang meliputi integritas, etika, dan kepedulian (<em>compassion</em>), diintegrasikan dalam proses belajar mengajar agar mahasiswa tumbuh menjadi pribadi tangguh.</p><p style=\"text-align: justify;\">\"Kami menyadari anak-anak masa kini mungkin memiliki pola pikir yang berbeda. Namun, karakter adalah hal yang krusial. Oleh karena itu, titipan utama dari <em>founder</em> kami adalah mendidik karakter. Mahasiswa tidak sekadar hafal nilai-nilai, tapi perilaku dan pola pikirnya terbentuk menjadi pribadi yang peduli pada diri sendiri, keluarga, dan lingkungan sekitarnya,\" tambah perwakilan UPITRA.</p><p style=\"text-align: justify;\">Melalui penandatanganan MoU dan MoA ini, Universitas Pignatelli Triputra dan SMA Bopkri 1 Yogyakarta optimis dapat menghadirkan pendampingan karier yang berkelanjutan bagi para siswa. Sinergi ini diharapkan melahirkan lulusan-lulusan yang tidak hanya cerdas berinovasi, namun juga berkarakter luhur dalam membangun bangsa.</p><p style=\"text-align: justify;\"><strong>Wujudkan Masa Depan Karier Gemilang Bersama UPITRA!</strong></p><p style=\"text-align: justify;\">Bagi para siswa-siswi yang ingin merasakan pengalaman kuliah yang seru, kekinian, lulus langsung siap kerja, dan dibekali ilmu yang <em>relate</em> dengan industri masa depan, Universitas Pignatelli Triputra adalah pilihan yang sangat tepat!</p><p style=\"text-align: justify;\">Untuk para orang tua, tak perlu khawatir mempercayakan putra-putrinya di sini. Selain membekali mahasiswa dengan kompetensi unggul, UPITRA sangat mengedepankan pendidikan karakter yang peduli sesama, serta menyediakan berbagai peluang beasiswa menarik agar langkah anak meraih cita-cita semakin ringan dan terarah.</p><p style=\"text-align: justify;\">Mari melangkah maju dan wujudkan masa depan gemilang bersama UPITRA! Kunjungi website resmi kami di <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.UPITRA.ac.id\">pmb.UPITRA.ac.id</a> untuk informasi pendaftaran mahasiswa baru dan ragam beasiswa yang menanti Anda.</p>', '/images/berita/1790765042_6abce7f2d4c18.jpeg', NULL, 'Published', 0, 74, '2026-09-30 03:44:02', '2026-10-20 05:10:53'),
(33, 'Latih Kepercayaan Diri Generasi Muda, UPITRA Gelar Seminar \"Public Speaking\" di SMAK PNK Surakarta', 'latih-kepercayaan-diri-generasi-muda-upitra-gelar-seminar-public-speaking-di-smak-pnk-surakarta-6acc34fe9d51a', 'Kerjasama', '2026-10-12', 'UPITRA menggelar seminar \"Public Speaking for Student\" di SMAK PNK Surakarta untuk melatih rasa percaya diri dan kemampuan komunikasi siswa sejak dini agar siap bersaing di masa depan.', '<p style=\"text-align: justify;\"><strong>SURAKARTA</strong> — Kemampuan berbicara di depan umum (public speaking) kini menjadi salah satu soft skill krusial yang wajib dimiliki oleh generasi muda dalam menghadapi tantangan masa depan. Menyadari urgensi tersebut, Universitas Pignatelli Triputra (UPITRA) menyelenggarakan seminar bertajuk \"Public Speaking for Student\" di SMAK PNK Surakarta pada Jumat (9/10/2026).</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">​Kegiatan edukatif ini disambut dengan antusiasme yang luar biasa oleh para peserta yang terdiri dari siswa-siswi kelas 10 hingga kelas 12. Sepanjang acara, suasana berlangsung sangat interaktif dan hidup. Para siswa tampak aktif merespons dan terlibat langsung dalam pemaparan materi yang dibawakan oleh Kepala Biro Marketing &amp; Komunikasi UPITRA, Veronica Tiara Kusuma, S.Kom., M.M., CPS., iCPM.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">​Dalam sesinya, Veronica menyoroti esensi dari komunikasi yang efektif. Ia memberikan wawasan praktis kepada para siswa tentang bagaimana menguasai panggung dan memikat audiens.</p><p style=\"text-align: justify;\">​\"Public speaking itu tidak hanya sekadar bisa ngomong, tapi kamu harus bisa membuat orang tertarik dengan apa yang kamu sampaikan,\" tegas Veronica, memotivasi para peserta agar berani tampil beda.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">​Melalui seminar ini, UPITRA berharap para siswa SMAK PNK Surakarta dapat mendobrak rasa gugup mereka dan tumbuh menjadi individu yang lebih percaya diri. Kemampuan mengemas pesan dengan menarik ini diharapkan menjadi bekal berharga bagi mereka, baik untuk kebutuhan presentasi di kelas maupun saat berorganisasi di tengah masyarakat.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\"><strong>Asah Potensimu Bersama Universitas Pignatelli Triputra!</strong></p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">​Kunjungan edukasi ini adalah bukti nyata komitmen Universitas Pignatelli Triputra (UPITRA) dalam mendampingi talenta muda Indonesia agar lebih siap bersaing, bahkan sejak mereka duduk di bangku sekolah menengah.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">​Bagi para siswa-siswi yang ingin merasakan perkuliahan seru, dinamis, dan berfokus pada pengembangan hardskill sekaligus soft skill, UPITRA adalah tempat yang tepat untuk melangkah maju.</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\">Untuk para orang tua, tak perlu ragu mempercayakan masa depan putra-putrinya di kampus yang mengedepankan pendidikan karakter dan kesiapan industri ini. Wujudkan potensi terbaik dan karier gemilang di masa depan dengan bergabung bersama Universitas Pignatelli Triputra!</p><p style=\"text-align: justify;\"></p><p style=\"text-align: justify;\"><strong>Salam UPITRA, READY!</strong></p>', '/images/berita/1792021729_6ad014e113df6.jpg', NULL, 'Published', 0, 36, '2026-10-11 18:16:46', '2026-10-20 05:10:31'),
(34, 'Belum Wisuda, 26 Lulusan UPITRA Sudah Kantongi Pekerjaan', 'belum-wisuda-26-lulusan-upitra-sudah-kantongi-pekerjaan-6ad05d3770972', 'Prestasi', '2026-10-15', 'Dua lulusan Sistem Informasi direkrut ASSA Group, lini bisnis bidang Trading & Services Triputra Group.', '<p><span><strong>SURAKARTA, 14 Oktober 2026 </strong>— Sebelum toga dikenakan dan ijazah diterima, 26 lulusan Universitas Pignatelli Triputra (UPITRA) ternyata sudah lebih dulu mengantongi pekerjaan. Jumlah itu setara satu dari lima wisudawan yang dilepas dalam Sidang Terbuka Senat Wisuda Tahun 2026 di Keraton Ballroom, The Mercure Hotel Solo, Rabu (14/10/2026).</span></p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\"><p><span>&nbsp;</span></p></td><td colspan=\"1\" rowspan=\"1\"><p><span><strong>SOROTAN&nbsp; •&nbsp; MASUK ASSA GROUP</strong></span></p><p><span>Di antara para lulusan itu, <strong>Angelica Rachel Dheantina</strong> dan <strong>Dyah Lintang Ambar Wari</strong>, keduanya lulusan S1 Sistem Informasi, kini sudah bekerja sebagai BPO Agent di Departemen ICT Logistic <strong>ASSA Group</strong>, perusahaan bidang trading &amp; services yang merupakan bagian dari Triputra Group.</span></p></td></tr></tbody></table><p><span>&nbsp;</span></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1792040036_6ad05c6464160.jpeg\" alt=\"WhatsApp Image 2026-10-s15 at 11.47.38.jpeg\"><p style=\"text-align: justify;\"><span>Para lulusan lain tersebar di beragam tempat. Benedikta Cindy Permatasari, lulusan S1 Sistem Informasi, menjadi Web Designer di PT Duta Niaga Indonesia Manunggal. Yohanes Palmanda Santoso, lulusan S1 Manajemen, bekerja sebagai Staff HR di PT Java Energi Semesta. Sementara itu, Nadila Yoni Nofitri, lulusan S1 Akuntansi, mengisi posisi Finance Accounting di PT Tribun Berita Online.</span></p><p style=\"text-align: justify;\"><span>Sebagian lainnya berkarier di rumah sakit, lembaga pendidikan, hingga kantor kelurahan. Dua lulusan memilih jalur berbeda dengan berwiraswasta di bidang kuliner. Secara keseluruhan, 23 dari 26 lulusan tersebut diterima di perusahaan dan institusi.</span></p><p style=\"text-align: justify;\"><span>Wisuda kali ini melepas 84 lulusan sarjana dan 41 lulusan diploma tiga dari delapan program studi. S1 Akuntansi menjadi penyumbang terbanyak dengan 39 lulusan, disusul S1 Manajemen dan D3 Bahasa Inggris.</span></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1792039975_6ad05c275143b.jpeg\" alt=\"WhatsApp Image 2026-10-15 at 11.45.43.jpeg\"><p style=\"text-align: justify;\"><span>Rektor UPITRA, Neil Semuel Rupidara, S.E., </span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://M.Sc\"><span>M.Sc</span></a><span>., Ph.D., menyebut “Saya percaya dan sekaligus berterima kasih, kalian sudah tumbuh bersama-sama kami di UPITRA. Sebagai almamater, kami berharap pendidikan mu di UPITRA cukup untuk mendukung perjalanan karir mu di dunia profesional. Pergilah dan menjadi duta-duta UPITRA yang berperan aktif dalam membawa kemajuan dalam masyarakat kemanapun kamu pergi”</span></p><p style=\"text-align: justify;\"><span>Selain capaian gemilang dalam serapan tenaga kerja, UPITRA juga membuktikan kualitas pendidikannya melalui deretan prestasi mahasiswa di tingkat regional, nasional, hingga internasional. Hal ini menjadi penanda kuat bahwa UPITRA senantiasa mengedepankan prinsip holistic education (pendidikan holistik), di mana kecerdasan akademik dibangun selaras dengan pengembangan karakter, kreativitas, dan bakat seni.</span></p><p style=\"text-align: justify;\"><span>Di kancah sains dan inovasi internasional, mahasiswa UPITRA sukses mendapatkan Gold Medal dari berbagai kompetisi bergengsi, seperti Asean Innovative Science, Environmental &amp; Entrepreneur Fair (AISEEF) 2024 dan 2025, Youth International Science Fair, hingga ajang World Youth Invention and Innovation Award. Prestasi akademik ini diimbangi dengan capaian luar biasa di bidang seni dan budaya. Tim paduan suara UPITRA berhasil meraih Silver Medal di 11th Sapta Gita Choral Festival 2024 dan Bronze Medal di ajang internasional Saint Angela International Choir Festival 2026.</span></p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1792040100_6ad05ca4b91b3.jpeg\" alt=\"WhatsApp Image 2026-10-15 at 11.47.38.jpeg\"><p style=\"text-align: justify;\"><span>Tak berhenti di situ, pada tingkat nasional, mahasiswa UPITRA juga merengkuh Gold Medal (Kategori Musik Religi) dan Silver Medal (Kategori Lagu Rakyat) di Festival Swara Saraswati II 2025, melengkapi gelar Winner Putra Solo Persahabatan 2024 di tingkat regional. Beragam prestasi komprehensif ini menegaskan bahwa ekosistem pendidikan UPITRA benar-benar memfasilitasi mahasiswa secara utuh untuk menjadi insan yang kompeten dan berdaya saing global.</span></p><p style=\"text-align: justify;\"><span>Bagi Anda yang ingin merasakan pengalaman belajar yang menyeluruh dan lulus dengan kesiapan karier yang matang, <strong>Pendaftaran Mahasiswa Baru UPITRA telah dibuka</strong>. Informasi dan pendaftaran dapat diakses melalui: </span><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" class=\"text-primary underline\" href=\"http://pmb.upitra.ac.id\"><span><strong>pmb.upitra.ac.id</strong></span></a></p>', '/images/berita/1792040247_6ad05d37706d7.jpeg', NULL, 'Published', 1, 57, '2026-10-14 21:57:27', '2026-10-21 16:33:25');

-- --------------------------------------------------------

--
-- Table structure for table `brochures`
--

CREATE TABLE `brochures` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `program_studi_id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `file_path` varchar(255) NOT NULL,
  `image_path` varchar(255) DEFAULT NULL,
