CREATE TABLE `kemahasiswaan_page` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `hero_title` varchar(255) NOT NULL DEFAULT 'Kemahasiswaan UPITRA',
  `hero_description` text DEFAULT NULL,
  `tugas_title` varchar(255) NOT NULL DEFAULT 'Tugas dan Fungsi Bidang Kemahasiswaan',
  `tugas_description` text DEFAULT NULL,
  `program_pengembangan` text DEFAULT NULL,
  `organisasi` text DEFAULT NULL,
  `galeri_images` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `kemahasiswaan_page`
--

INSERT INTO `kemahasiswaan_page` (`id`, `title`, `description`, `hero_title`, `hero_description`, `tugas_title`, `tugas_description`, `program_pengembangan`, `organisasi`, `galeri_images`, `created_at`, `updated_at`) VALUES
(1, NULL, NULL, 'Kemahasiswaan UPITRA', 'Kemahasiswaan Universitas Pignatelli Triputra (UPITRA) adalah unit kerja/biro yang bertanggung jawab dalam memberikan pelayanan, pembinaan, dan pengembangan kesejahteraan mahasiswa di luar jalur akademik formal. Kemahasiswaan UPITRA berfungsi mengelola beasiswa, memfasilitasi legalitas dan kegiatan organisasi (BEM, HIMA, UKM), mendampingi kompetisi/prestasi mahasiswa, serta memberikan layanan bimbingan karir dan konseling.', 'Tugas dan Fungsi Bidang Kemahasiswaan', 'Bidang Kemahasiswaan UPITRA mengemban tugas pokok untuk merencanakan, melaksanakan, dan mengevaluasi program pembinaan karakter serta kesejahteraan mahasiswa di luar jalur akademik formal. Bidang ini menjalankan fungsi strategis dalam melegalisasi dan mengawasi Organisasi Mahasiswa (BEM, HIMA, UKM), memfasilitasi pengembangan minat, bakat, dan penalaran kompetisi, mengelola layanan beasiswa serta konseling, hingga mempersiapkan kesiapan karir alumni (tracer study).', '[{\"title\":\"Leadership Development\",\"desc\":\"Leadership Development UPITRA adalah program terstruktur untuk mengasah jiwa kepemimpinan, karakter, dan manajerial mahasiswa. Melalui pelatihan seperti LKMM, workshop komunikasi, dan forum problem solving, mahasiswa ditempa untuk berpikir kritis, berintegritas, serta mampu mengelola organisasi kampus secara profesional sebagai bekal menjadi pemimpin masa depan di industri dan masyarakat.\"},{\"title\":\"Entrepreneurship Program\",\"desc\":\"Entrepreneurship Program UPITRA adalah wadah pembinaan untuk menumbuhkan jiwa wirausaha, kreativitas, dan kemandirian ekonomi mahasiswa. Program ini memfasilitasi mahasiswa mulai dari ideasi, penyusunan business plan, hingga inkubasi bisnis melalui pelatihan digital marketing dan keuangan. Tujuannya adalah mendorong inovasi bisnis yang solutif agar lulusan siap menjadi pencipta lapangan kerja (job creator).\"},{\"title\":\"Career Preparation\",\"desc\":\"Career Preparation UPITRA adalah program pembinaan intensif untuk menjembatani mahasiswa tingkat akhir dan alumni muda menuju dunia kerja profesional. Program ini berfokus pada kesiapan karier melalui pelatihan taktis seperti penyusunan CV ATS-friendly, simulasi wawancara, dan optimasi LinkedIn. Bersama mitra perusahaan, program ini memfasilitasi campus hiring dan job fair untuk mempercepat penyerapan lulusan di dunia industri.\"}]', '[{\"title\":\"BEM\",\"desc\":\"BEM UPITRA adalah lembaga eksekutif tertinggi mahasiswa di tingkat universitas. Organisasi ini berfungsi sebagai wadah resmi penyalur aspirasi mahasiswa, penggerak program kemahasiswaan (akademik, minat-bakat, dan sosial), serta mitra strategis rektorat dalam mewujudkan lingkungan kampus yang dinamis dan solutif.\"},{\"title\":\"HIMA\",\"desc\":\"HIMA UPITRA adalah organisasi mahasiswa di tingkat program studi. Organisasi ini berfungsi sebagai wadah pengembangan potensi, keilmuan, dan profesionalisme yang spesifik sesuai bidang studi, sekaligus menjadi jembatan komunikasi antara mahasiswa dengan dosen dan struktural program studi.\"},{\"title\":\"UKM\",\"desc\":\"UKM UPITRA adalah wadah aktivitas kemahasiswaan di tingkat universitas yang berfokus pada pengembangan minat, bakat, kegemaran, dan kreativitas mahasiswa. Melalui rumpun olahraga, kesenian, penalaran, dan kerohanian, UKM berfungsi mengasah soft skills, mendorong prestasi non-akademik, serta membangun jejaring lintas program studi.\"}]', '[{\"image\":\"\\/images\\/kemahasiswaan\\/keg-1.jpg\",\"title\":\"Kunjungan ke Bank Indonesia\",\"short_description\":\"Mahasiswa UPITRA melakukan kunjungan ke Bank Indonesia Surakarta beserta mahasiswa dari universitas lain di Soloraya.\"},{\"image\":\"\\/images\\/kemahasiswaan\\/dasar.jpg\",\"title\":\"Pelatihan Dasar Kepemimpinan\",\"short_description\":\"Badan Eksekutif Mahasiswa (BEM) UPITRA melaksanakan pelatihan dasar kepemimpinan.\"},{\"image\":\"\\/images\\/kemahasiswaan\\/public-speaking.jpg\",\"title\":\"Kompetisi Public Speaking\",\"short_description\":\"UPITRA melaksanakan kompetisi Public Speaking yang diikuti oleh seluruh mahasiswa aktif di UPITRA.\"}]', '2026-04-16 20:14:19', '2026-06-22 00:40:39');

