--
-- Dumping data for table `kerjasama_page`
--

INSERT INTO `kerjasama_page` (`id`, `hero_title`, `hero_description`, `statistik`, `kegiatan_images`, `created_at`, `updated_at`) VALUES
(1, 'Kerjasama Universitas Pignatelli Triputra', 'Bidang Kerjasama Universitas Pignatelli Triputra memiliki tugas mengembangkan kemitraan strategis dengan berbagai institusi nasional maupun internasional. Kerjasama dilakukan untuk mendukung kegiatan pendidikan, penelitian, pengabdian kepada masyarakat, serta pengembangan kompetensi mahasiswa melalui program magang, pertukaran pelajar, riset kolaboratif, dan berbagai kegiatan akademik lainnya.', '[{\"number\":\"109+\",\"title\":\"Mitra Industri\"},{\"number\":\"107+\",\"title\":\"Kerjasama Nasional\"},{\"number\":\"2+\",\"title\":\"Kerjasama Internasional\"},{\"number\":\"109+\",\"title\":\"Program Kolaborasi\"}]', '[{\"image\":\"\\/images\\/kerjasama\\/1776924178_69e9b612855cb.jpg\",\"title\":\"MoU UPITRA dan AdZU\",\"short_description\":\"UPITRA secara resmi menandatangani Memorandum of Understanding (MoU) dengan Ateneo de Zamboanga University (AdZU), Filipina.\"},{\"image\":\"\\/images\\/kerjasama\\/1776923034_69e9b19a49ff0.jpeg\",\"title\":\"MoU UPITRA dan STIKOM Yos Sudarso\",\"short_description\":\"UPITRA dan STIKOM Yos Sudarso Purwokerto Perkuat Kolaborasi melalui Kerja Sama dan Benchmarking.\"},{\"image\":\"\\/images\\/kerjasama\\/1776841487_69e8730f2888b.jpg\",\"title\":\"MoU UPITRA dan Mangkunegaran\",\"short_description\":\"UPITRA resmi menandatangani Nota Kesepahaman (MoU) dengan Mangkunegaran.\"},{\"image\":\"\\/images\\/kerjasama\\/1776838981_69e869451002f.jpg\",\"title\":\"MoU Prodi Manajemen UPITRA dan Universitas Shanti Buana\",\"short_description\":\"Penandatanganan kerjasama antara Program Studi Manajemen UPITRA dengan Program Studi Manajemen Institut Shanti Bhuana.\"},{\"image\":\"\\/images\\/kerjasama\\/1776833442_69e853a28714c.jpg\",\"title\":\"MoU UPITRA dan IPTAR\",\"short_description\":\"UPITRA menandatangani nota kesepahaman (MoU) bersama Institut Pendidikan dan Teknologi Aisyiyah Riau (IPTAR).\"}]', '2026-04-16 20:14:40', '2026-05-21 21:06:18');

