INSERT INTO `pengumuman` (`id`, `title`, `slug`, `priority`, `icon`, `date`, `expiry_date`, `description`, `content`, `link`, `thumbnail`, `status`, `views_count`, `created_at`, `updated_at`) VALUES
(5, 'PEMBERITAHUAN HER REGISTRASI, BIMBINGAN RENCANA STUDI, PEMBAYARAN SPP & PERKULIAHAN GENAP 2024/2025', 'pemberitahuan-her-registrasi-bimbingan-rencana-studi-pembayaran-spp-perkuliahan-genap-20242025-69e9d8770a629', 'Informasi', 'Megaphone', '2025-01-22', NULL, 'Diberitahukan kepada seluruh mahasiswa Universitas Pignatelli Triputra bahwa perkuliahan semester genap tahun akademik 2024/2025 akan dimulai dengan ketentuan sebagai berikut:', '<ol><li><p>Periode her registrasi dapat dilakukan mulai tanggal 21 Januari s/d 4 Februari 2025.</p></li><li><p>Bimbingan Rencana Studi (BRS) dan pembayaran biaya kuliah (SPP) dapat dilakukan mulai tanggal 3 s/d 14 Februari 2025.</p></li><li><p>Awal perkuliahan semester genap 2024/2025 dimulai tanggal 17 Februari 2025. Informasi lebih lanjut dapat dilihat melalui surat pemberitahuan yang kami lampirkan bersama dengan pengumuman ini. Demikian pengumuman ini kami sampaikan.</p></li></ol><p>Harap menjadi perhatian seluruh mahasiswa.</p><p></p>', NULL, NULL, 'Aktif', 156, '2026-04-23 01:29:43', '2026-10-22 03:33:50'),
(6, '[REVISI] PEMBERITAHUAN HER REGISTRASI, BIMBINGAN RENCANA STUDI & PERKULIAHAN GENAP 2024/2025', 'revisi-pemberitahuan-her-registrasi-bimbingan-rencana-studi-perkuliahan-genap-20242025-69e9e249772fc', 'Informasi', 'Bell', '2025-01-24', NULL, 'PEMBERITAHUAN HER REGISTRASI, BIMBINGAN RENCANA STUDI, PEMBAYARAN SPP & PERKULIAHAN SEMESTER GENAP 2024/2025', '<p>Sehubungan dengan adanya penyesuaian kalender akademik, kami sampaikan bahwa jadwal pelaksanaan Bimbingan Rencana Studi (BRS) mengalami perubahan. BRS akan kembali dilaksanakan sesuai jadwal semula, yaitu pada tanggal 10-15 Februari 2025.</p><p style=\"text-align: left;\">Demikian pengumuman ini disampaikan. Atas perhatiannya, kami ucapkan terima kasih.</p><p style=\"text-align: left;\"></p><p style=\"text-align: left;\"><span>Biro Administrasi Akademik</span><br><span>Universitas Pignatelli Triputra</span></p>', NULL, NULL, 'Aktif', 145, '2026-04-23 02:11:37', '2026-10-17 10:30:06'),
(7, 'PENGUMUMAN UJIAN TENGAH SEMESTER (UTS) GENAP 2024/2025', 'pengumuman-ujian-tengah-semester-uts-genap-20242025-69e9e30e2e9f9', 'Informasi', 'FileText', '2025-03-07', NULL, 'Kepada seluruh Mahasiswa/i Universitas Pignatelli Triputra,', '<p>Sehubungan dengan kalender akademik Universitas Pignatelli Triputra Tahun Akademik 2024/2025, bersama ini kami menginformasikan kepada seluruh mahasiswa bahwa <strong>Ujian Tengah Semester (UTS) Semester Genap TA 2024/2025</strong> akan dilaksanakan pada:</p><ul><li><p><strong>Tanggal:</strong> Senin, 7 April 2025 s.d. Jumat, 11 April 2025</p></li></ul><p>Bersama dengan pengumuman ini, kami lampirkan Surat Pemberitahuan Resmi terkait rincian teknis dan persyaratan pelaksanaan UTS. Mohon agar informasi tersebut dapat dicermati dan dipersiapkan dengan sebaik-baiknya.</p><p>Demikian pemberitahuan ini kami sampaikan. Atas perhatian dan kerja sama Saudara/i, kami ucapkan terima kasih.</p><p style=\"text-align: left;\"><strong>Universitas Pignatelli Triputra</strong><br>Biro Administrasi Akademik</p>', NULL, NULL, 'Aktif', 691, '2026-04-23 02:14:54', '2026-10-17 00:30:57'),
(8, '🎉 Dies Natalis ke-4 UPITRA: Satu Perayaan, Puluhan Pengalaman Seru!', 'dies-natalis-ke-4-upitra-satu-perayaan-puluhan-pengalaman-seru-6a3dfcffbddef', 'Informasi', 'Megaphone', '2026-06-17', '2026-07-22', 'Universitas Pignatelli Triputra (UPITRA) mengundang seluruh sivitas akademika untuk menjadi bagian dari rangkaian Dies Natalis ke-4 yang mengusung tema \"Funtastic 4 – Build, Bloom, Breakthrough, Beyond.\"', '<p>🎊 Satu perayaan, puluhan pengalaman seru!</p><p>Dies Natalis ke-4 Universitas Pignateli Triputra hadir dengan rangkaian kegiatan yang sayang untuk dilewatkan.</p><p>Mulai dari workshop, kompetisi, seminar, donor darah, diskusi film, coaching clinic, bazaar mahasiswa, hingga puncak perayaan pada 22 Juli 2026.</p><p>🌟 Ada ruang untuk belajar.</p><p>🤝 Ada kesempatan untuk berkolaborasi.</p><p>🏆 Ada panggung untuk berprestasi.</p><p>🎉 Dan tentunya, ada momen untuk merayakan perjalanan UPITRA bersama.</p><p>Yuk, catat tanggalnya dan ikuti setiap keseruannya. Mari rayakan Dies Natalis ke-4 dengan semangat Build • Bloom • Breakthrough • Beyond!</p><img class=\"max-w-full rounded my-2\" src=\"/images/editor/1782447389_6a3dfd1dc8f4c.png\" alt=\"Calendar of Events_Dies Natalis ke-4.png\"><p></p>', NULL, NULL, 'Aktif', 242, '2026-06-25 21:15:59', '2026-10-19 23:42:48');

