INSERT INTO `program_studi` (`id`, `name`, `title`, `description`, `short_description`, `slug`, `faculty`, `faculty_name`, `accreditation`, `icon`, `url`, `active`, `views_count`, `hero_title`, `hero_subtitle`, `visi`, `misi`, `tujuan`, `karir`, `kurikulum`, `roadmap`, `kegiatan_images`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'PMB', NULL, NULL, NULL, 'PMB EARLY BIRD', '', '', '', 'BookOpen', NULL, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL),
(2, 'Software Engineering', NULL, 'Program Studi Software Engineering UPITRA mempersiapkan mahasiswa menjadi software engineer profesional yang mampu merancang, mengembangkan, dan memelihara perangkat lunak berkualitas tinggi.', NULL, 'software-engineering', 'FST', 'Fakultas Sains & Teknologi', 'Baik', 'Code', '/software-engineering', 1, 755, 'Program Studi Software Engineering', 'Mempersiapkan lulusan yang inovatif, mempunyai jiwa kemandirian dan berdaya saing global.', 'Menjadi program studi yang unggul dalam bidang industrial software engineering, berorientasi global, menjunjung tinggi nilai-nilai integritas dan bersemangat kebhinekaan.', '[\"Menyelenggarakan program studi Rekayasa Perangkat Lunak secara efektif dan efisien untuk mendukung terlaksananya Tri Dharma perguruan tinggi.\",\"Menghasilkan sarjana di bidang rekayasa perangkat lunak yang kompeten, solutif, berpola pikir logis dan sistematis, memiliki kedalaman spiritual, menjunjung kemanusiaan, rendah hati, berintegritas dan profesional dalam memanfaatkan ilmu rekayasa perangkat lunak di lingkungan kerja maupun kehidupan bermasyarakat.\",\"Menghasilkan penelitian yang unggul, solutif, inovatif dan transformatif bagi masyarakat dibidang rekayasa perangkat lunak.\",\"Memanfaatkan ilmu rekayasa perangkat lunak yang berdaya guna dan berhasil guna bagi masyarakat.\",\"Membangun kerja sama dan mengelola jejaring berkelanjutan dengan dunia pendidikan, masyarakat, pemerintah dan industri untuk mewujudkan keunggulan transformatif dibidang rekayasa perangkat lunak.\"]', '[\"Berkontribusi dalam memperluas akses pendidikan tinggi yang berkualitas dan terjangkau bagi masyarakat di bidang rekayasa perangkat lunak.\",\"Menghasilkan sarjana bidang Rekayasa Perangkat Lunak yang bermoral, berintegritas, profesional, bertanggung jawab, dan mampu berkarya dengan keahliannya di bidang rekayasa perangkat lunak.\",\"Berkontribusi dalam pengembangan dan penelitian perangkat lunak yang unggul, solutif, inovatif dan transformatif bagi masyarakat dan kehidupan.\",\"Menerapkan ilmu rekayasa perangkat lunak yang berdaya guna dan berhasil guna bagi masyarakat.\",\"Menjalin kerja sama dengan dunia pendidikan, masyarakat, pemerintah dan industri yang berkelanjutan, beretika, dan bermanfaat di bidang rekayasa perangkat lunak.\"]', '[{\"title\":\"Software Engineer\",\"desc\":\"Profesi yang merancang, membangun, menguji, dan memelihara perangkat lunak. Mereka tidak hanya menulis kode, tetapi juga memecahkan masalah di industri dengan solusi digital.\"},{\"title\":\"Web Developer\",\"desc\":\"Profesi yang merancang dan membangun website atau aplikasi berbasis web. Mereka memastikan tampilan menarik, fungsionalitas berjalan baik, dan pengalaman pengguna di berbagai perangkat.\"},{\"title\":\"Mobile Application Developer\",\"desc\":\"Profesi yang merancang dan membangun aplikasi untuk perangkat mobile seperti smartphone dan tablet, baik berbasis Android maupun iOS.\"},{\"title\":\"Game Developer\",\"desc\":\"Profesi yang membuat permainan digital, mulai dari konsep awal, desain karakter, pemrograman mekanik permainan, hingga efek suara dan visual.\"},{\"title\":\"Software Quality Assurance Tester\",\"desc\":\"Profesi yang memastikan perangkat lunak berjalan sesuai fungsinya, bebas dari kesalahan, dan siap digunakan oleh pengguna.\"},{\"title\":\"Program Analyst\",\"desc\":\"Profesi yang menjembatani kebutuhan bisnis dengan solusi teknologi. Mereka menganalisis\\tproses, mengidentifikasi masalah, dan merancang sistem atau perangkat lunak yang sesuai.\"},{\"title\":\"VR\\/AR Developer\",\"desc\":\"Profesional yang menciptakan pengalaman digital imersif menggunakan teknologi Virtual Reality (VR) dan Augmented Reality (AR) menggabungkan dunia nyata dengan dunia digital.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Sistem Operasi\",\"sks\":2},{\"code\":\"2\",\"name\":\"Business Communication\",\"sks\":2},{\"code\":\"3\",\"name\":\"Pengantar Teknologi Informasi\",\"sks\":4},{\"code\":\"4\",\"name\":\"Matematika Diskrit\",\"sks\":3},{\"code\":\"5\",\"name\":\"Introduction to Software Engineering\",\"sks\":3},{\"code\":\"6\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"7\",\"name\":\"Pancasila\",\"sks\":2}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Statistika dan Probabilitas\",\"sks\":3},{\"code\":\"2\",\"name\":\"Basis Data\",\"sks\":3},{\"code\":\"3\",\"name\":\"Pemrograman Web Dasar\",\"sks\":3},{\"code\":\"4\",\"name\":\"Algoritma dan Struktur Data\",\"sks\":4},{\"code\":\"5\",\"name\":\"Analisis Kebutuhan Software\",\"sks\":3},{\"code\":\"6\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"7\",\"name\":\"Bahasa Indonesia\",\"sks\":2}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Jaringan Komunikasi Data\",\"sks\":3},{\"code\":\"2\",\"name\":\"Pemrograman Web Lanjut\",\"sks\":3},{\"code\":\"3\",\"name\":\"UPITRA DNA\",\"sks\":3},{\"code\":\"4\",\"name\":\"Pemrograman Berorientasi Objek\",\"sks\":3},{\"code\":\"5\",\"name\":\"Proses Perangkat Lunak\",\"sks\":3},{\"code\":\"6\",\"name\":\"Software Process\",\"sks\":3},{\"code\":\"7\",\"name\":\"Software Modeling\",\"sks\":3},{\"code\":\"8\",\"name\":\"Arsitektur Industri\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Pemrograman Mobile\",\"sks\":3},{\"code\":\"2\",\"name\":\"Pemrograman Framework\",\"sks\":3},{\"code\":\"3\",\"name\":\"Kewirausahaan\",\"sks\":3},{\"code\":\"4\",\"name\":\"Software Security\",\"sks\":3},{\"code\":\"5\",\"name\":\"Konstruksi Perangkat Lunak\",\"sks\":3},{\"code\":\"6\",\"name\":\"Manajemen Proyek\",\"sks\":2},{\"code\":\"7\",\"name\":\"Mata Kuliah Pilihan 1\",\"sks\":0},{\"code\":\"8\",\"name\":\"MK Pilihan Perancangan Gim\",\"sks\":3},{\"code\":\"9\",\"name\":\"MK Pilihan VR Application Development\",\"sks\":3},{\"code\":\"10\",\"name\":\"MK Pilihan Device Integration\",\"sks\":3},{\"code\":\"11\",\"name\":\"MK Pilihan Intelligent Software Engineering\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Pemrograman Mobile Lanjut\",\"sks\":2},{\"code\":\"2\",\"name\":\"Etika Profesi\",\"sks\":2},{\"code\":\"3\",\"name\":\"Metodologi Penelitian\",\"sks\":3},{\"code\":\"4\",\"name\":\"Interaksi Manusia dan Komputer\",\"sks\":2},{\"code\":\"5\",\"name\":\"Software Quality\",\"sks\":3},{\"code\":\"6\",\"name\":\"Konsep AI\",\"sks\":2},{\"code\":\"7\",\"name\":\"Industrial Sofware Engineering\",\"sks\":4},{\"code\":\"8\",\"name\":\"Mata Kuliah Pilihan 2\",\"sks\":0},{\"code\":\"9\",\"name\":\"MK Pilihan Pemrograman Gim\",\"sks\":3},{\"code\":\"10\",\"name\":\"MK Pilihan AR Application Development\",\"sks\":3},{\"code\":\"11\",\"name\":\"MK Pilihan Data Acquisition\",\"sks\":3},{\"code\":\"12\",\"name\":\"MK Pilihan AI-Driven Software Development\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Immersion Program I\",\"sks\":20}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Immersion Program II\",\"sks\":20}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Tugas Akhir\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Programming Basics\",\"desc\":\"Algoritma dan pemrograman dasar.\"},{\"semester\":\"Semester 2\",\"title\":\"Software Foundation\",\"desc\":\"Struktur data dan OOP.\"},{\"semester\":\"Semester 3\",\"title\":\"Development Core\",\"desc\":\"Database dan web development.\"},{\"semester\":\"Semester 4\",\"title\":\"Software Engineering\",\"desc\":\"RPL dan manajemen proyek.\"},{\"semester\":\"Semester 5\",\"title\":\"Advanced Development\",\"desc\":\"Mobile dan cloud development.\"},{\"semester\":\"Semester 6\",\"title\":\"Immersion Program\",\"desc\":\"Magang industri 1 semester.\"},{\"semester\":\"Semester 7\",\"title\":\"Immersion Program\",\"desc\":\"Magang industri lanjutan.\"},{\"semester\":\"Semester 8\",\"title\":\"Capstone Project\",\"desc\":\"Pengembangan produk aplikasi siap pakai.\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"r\",\"9\":\"p\",\"10\":\"l\",\"11\":\"\\/\",\"12\":\"r\",\"13\":\"p\",\"14\":\"l\",\"15\":\"-\",\"16\":\"1\",\"17\":\".\",\"18\":\"j\",\"19\":\"p\",\"20\":\"g\",\"image\":\"\\/images\\/rpl\\/rpl-1.jpg\",\"title\":\"VR Kampus UPITRA\",\"short_description\":\"Mahasiswa S-1 Software Engineering mampu menerapkan teknologi VR dengan membuat produk UPITRA VR EXPLORE.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"r\",\"9\":\"p\",\"10\":\"l\",\"11\":\"\\/\",\"12\":\"r\",\"13\":\"p\",\"14\":\"l\",\"15\":\"-\",\"16\":\"2\",\"17\":\".\",\"18\":\"j\",\"19\":\"p\",\"20\":\"g\",\"image\":\"\\/images\\/rpl\\/rpl-2.jpg\",\"title\":\"Project Base di Laboratorium\",\"short_description\":\"Pengerjaan Project oleh mahasiswa Software Engineering di Laboratorium FST.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"r\",\"9\":\"p\",\"10\":\"l\",\"11\":\"\\/\",\"12\":\"r\",\"13\":\"p\",\"14\":\"l\",\"15\":\"-\",\"16\":\"3\",\"17\":\".\",\"18\":\"j\",\"19\":\"p\",\"20\":\"g\",\"image\":\"\\/images\\/rpl\\/rpl-3.jpg\",\"title\":\"Mahasis Software Engineering\",\"short_description\":\"Kegiatan mahasiswa program studi S-1 Software Engineering Fakultas Sains dan Teknologi UPITRA.\"},{\"image\":\"\\/images\\/program-studi\\/1777435752_69f1846805848.jpg\",\"title\":\"Kolaborasi Mahasiswa Software Engineering dan Desa Bendungan\",\"short_description\":\"Mahasiswa program studi Software Engineering melakukan kolaborasi dengan Desa Bendungan Kecamatan Kedawung Kabupaten Sragen dalam menghasilkan produk Aplikasi Sidamis.\"}]', 2, '2026-04-16 20:16:04', '2026-10-22 01:53:50'),
(3, 'Informatika', NULL, 'Program Studi Informatika UPITRA mempersiapkan mahasiswa menjadi ahli di bidang ilmu komputer, kecerdasan buatan, dan teknologi informasi terkini.', NULL, 'informatika', 'FST', 'Fakultas Sains & Teknologi', 'Baik', 'Cpu', '/informatika', 1, 658, 'Program Studi Informatika', 'Mempersiapkan lulusan yang inovatif, mempunyai jiwa kemandirian dan berdaya saing global.', 'Program studi yang unggul dalam bidang informatika, berorientasi global, menjunjung tinggi nilai-nilai integritas dan bersemangat kebhinekaan.', '[\"Menyelenggarakan program studi informatika secara efektif dan efisien untuk mendukung terlaksananya tri dharma perguruan tinggi.\",\"Menghasilkan sarjana informatika yang kompeten, kompetitif, memiliki pola pikir logis, sistematis, kedalaman spiritual, kemanusiaan, kemampuan berjejaring, dan profesional dalam memanfatkan bidang ilmu informatika di lingkungan kerja.\",\"Menghasilkan penelitian yang unggul, kreatif, inovatif dan transformatif bagi masyarakat di bidang informatika.\",\"Memanfaatkan bidang ilmu informatika yang berdaya guna bagi masyarakat.\",\"Membangun kerja sama dan mengelola jejaring berkelanjutan dengan dunia pendidikan, masyarakat, pemerintah dan industri untuk mewujudkan keunggulan transformatif di bidang informatika.\"]', '[\"Berkontribusi dalam memperluas akses pendidikan tinggi yang berkualitas dan terjangkau bagi masyarakat di bidang informatika.\",\"Menghasilkan sarjana bidang informatika yang bermoral, berintegritas, profesional, bertanggung jawab, dan mampu berkarya dengan ilmu informatika.\",\"Berkontribusi dalam pengembangan dan penelitian perangkat lunak yang unggul, solutif, inovatif dan transformatif bagi masyarakat dan kehidupan.\",\"Menerapkan ilmu informatika yang berdaya guna dan berhasil guna bagi masyarakat.\",\"Menjalin kerja sama dengan dunia pendidikan, masyarakat, pemerintah dan industri yang berkelanjutan, beretika, dan bermanfaat di bidang informatika.\"]', '[{\"title\":\"AI Engineer\",\"desc\":\"Merancang, membuat, membangun, dan mengembangkan AI dalam perusahaan yang bertuuan untuk otomatisasi proses kerja dan operasional harian.\"},{\"title\":\"Data Scientist\",\"desc\":\"Mengambil atau mengumpulkan data yang besar, kemudian mengolah data tersebut serta menggali sebuah insight baru yang akan berguna di masa depan terutama dalam membantu perusahaan untuk proses pengambilan keputusan.\"},{\"title\":\"Data Engineer\",\"desc\":\"Mengembangkan platform untuk data-data yang telah diolah dan ditafsirkan oleh seorang Data Analyst dan juga Data Scientist. Mulai dari merancang arsitektur database serta memelihara infrastruktur data di suatu perusahaan.\"},{\"title\":\"Data Analyst\",\"desc\":\"Mengambil atau mengumpulkan data, mengaturnya dan menggunakannya untuk mendapatkan suatu kesimpulan sesuai dengan proyek yang sedang diamati, seperti penjualan, inventaris, atau media sosial.\"},{\"title\":\"Data Administrator\",\"desc\":\"Mengatur, mengelola, dan mengamankan data di satu sistem atau lebih agar pengguna dapat menganalisis data tersebut untuk kepentingan perusahaan.\"},{\"title\":\"Technopreneur\",\"desc\":\"Membuat sebuah peluang usaha dengan memanfaatkan teknologi yang sedang berkembang pesat saat ini.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"2\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"3\",\"name\":\"Arsitektur & Organisasi Komputer\",\"sks\":3},{\"code\":\"4\",\"name\":\"Bahasa Inggris\",\"sks\":2},{\"code\":\"5\",\"name\":\"Matematika Diskret\",\"sks\":3},{\"code\":\"6\",\"name\":\"Sistem Digital\",\"sks\":2},{\"code\":\"7\",\"name\":\"Sistem Operasi\",\"sks\":3},{\"code\":\"8\",\"name\":\"Pemrograman Dasar\",\"sks\":3}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"3\",\"name\":\"Statistika dan Probabilitas\",\"sks\":3},{\"code\":\"4\",\"name\":\"Algoritma dan Struktur Data\",\"sks\":3},{\"code\":\"5\",\"name\":\"Aljabar Linier\",\"sks\":3},{\"code\":\"6\",\"name\":\"Basis Data\",\"sks\":3},{\"code\":\"7\",\"name\":\"Kecerdasan Buatan\",\"sks\":2},{\"code\":\"8\",\"name\":\"Pemrograman Web\",\"sks\":2}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Pengembangan Kepribadian UPITRA DNA\",\"sks\":3},{\"code\":\"2\",\"name\":\"Analisis dan Desain Sistem\",\"sks\":2},{\"code\":\"3\",\"name\":\"Data dan Informasi\",\"sks\":2},{\"code\":\"4\",\"name\":\"Jaringan Komputer\",\"sks\":2},{\"code\":\"5\",\"name\":\"Kalkulus\",\"sks\":3},{\"code\":\"6\",\"name\":\"Pemrograman Berorientasi Objek\",\"sks\":3},{\"code\":\"7\",\"name\":\"Penambangan Data\",\"sks\":2},{\"code\":\"8\",\"name\":\"Statistika Analis\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewirausahaan\",\"sks\":3},{\"code\":\"2\",\"name\":\"Interaksi Manusia dan Komputer\",\"sks\":2},{\"code\":\"3\",\"name\":\"Metode Numerik\",\"sks\":2},{\"code\":\"4\",\"name\":\"Pemrograman Mobile\",\"sks\":3},{\"code\":\"5\",\"name\":\"Pemrograman Web Client-Server\",\"sks\":2},{\"code\":\"6\",\"name\":\"Struktur dan Analisis Algoritma\",\"sks\":3},{\"code\":\"7\",\"name\":\"Keamanan Data\",\"sks\":3},{\"code\":\"Pilihan 1\",\"name\":\"Sains Data\",\"sks\":3},{\"code\":\"Pilihan 1\",\"name\":\"Metodologi Perangkat Lunak\",\"sks\":3},{\"code\":\"Pilihan 1\",\"name\":\"Big Data\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Etika Profesi\",\"sks\":2},{\"code\":\"2\",\"name\":\"Metode Penelitian dan Penulisan Ilmiah\",\"sks\":3},{\"code\":\"3\",\"name\":\"Pembelajaran Mesin\",\"sks\":3},{\"code\":\"4\",\"name\":\"Teori Bahasa dan Automata\",\"sks\":2},{\"code\":\"5\",\"name\":\"Proyek Informatika\",\"sks\":3},{\"code\":\"Pilihan 2\",\"name\":\"Pengolahan Bahasa Alami\",\"sks\":3},{\"code\":\"Pilihan 2\",\"name\":\"Pemrograman Mobile Framework\",\"sks\":3},{\"code\":\"Pilihan 2\",\"name\":\"Data Engineering\",\"sks\":3},{\"code\":\"Pilihan 3\",\"name\":\"Pengolahan Citra Digital\",\"sks\":3},{\"code\":\"Pilihan 3\",\"name\":\"Pemrograman Web Framework\",\"sks\":3},{\"code\":\"Pilihan 3\",\"name\":\"Data Warehouse\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Social Responsibility\",\"sks\":5},{\"code\":\"2\",\"name\":\"Informatics Experience\",\"sks\":5},{\"code\":\"3\",\"name\":\"Technology Solution\",\"sks\":5},{\"code\":\"4\",\"name\":\"Informatics Practices\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Collaborative Development\",\"sks\":5},{\"code\":\"2\",\"name\":\"Informatics Environment\",\"sks\":5},{\"code\":\"3\",\"name\":\"IT Tools and Techniques\",\"sks\":5},{\"code\":\"4\",\"name\":\"Informatics Implementation\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Tugas Akhir\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Computing Basics\",\"desc\":\"Algoritma Dasar, Logika dan Matematika Diskret.\"},{\"semester\":\"Semester 2\",\"title\":\"Programming Foundation\",\"desc\":\"Pengenalan Web, Basis Data, dan AI Dasar.\"},{\"semester\":\"Semester 3\",\"title\":\"Computer Science Core\",\"desc\":\"OOP, Jaringan Komputer dan Komputasi\"},{\"semester\":\"Semester 4\",\"title\":\"Software Development\",\"desc\":\"Web dan Mobile Development\"},{\"semester\":\"Semester 5\",\"title\":\"Computer Ethics\",\"desc\":\"Etika Profesi dan Penulisan Ilmiah\"},{\"semester\":\"Semester 6\",\"title\":\"Immersion Program\",\"desc\":\"Magang di Perusahaan Teknologi.\"},{\"semester\":\"Semester 7\",\"title\":\"Immersion Program\",\"desc\":\"Kolaborasi dengan Dunia Industri.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Penelitian dan Penulisan Tugas Akhir\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"i\",\"9\":\"n\",\"10\":\"f\",\"11\":\"o\",\"12\":\"r\",\"13\":\"m\",\"14\":\"a\",\"15\":\"t\",\"16\":\"i\",\"17\":\"k\",\"18\":\"a\",\"19\":\"\\/\",\"20\":\"i\",\"21\":\"n\",\"22\":\"f\",\"23\":\"-\",\"24\":\"1\",\"25\":\".\",\"26\":\"j\",\"27\":\"p\",\"28\":\"g\",\"image\":\"\\/images\\/informatika\\/inf-1.jpg\",\"title\":\"Kuliah Umum Machine Learning\",\"short_description\":\"Program studi S-1 Informatika Fakultas Sains dan Teknologi mengadakan kuliah umum bidang Mechine Learning.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"i\",\"9\":\"n\",\"10\":\"f\",\"11\":\"o\",\"12\":\"r\",\"13\":\"m\",\"14\":\"a\",\"15\":\"t\",\"16\":\"i\",\"17\":\"k\",\"18\":\"a\",\"19\":\"\\/\",\"20\":\"i\",\"21\":\"n\",\"22\":\"f\",\"23\":\"-\",\"24\":\"2\",\"25\":\".\",\"26\":\"j\",\"27\":\"p\",\"28\":\"g\",\"image\":\"\\/images\\/program-studi\\/1777433516_69f17bac0c517.jpg\",\"title\":\"Audit Mutu Internal FST\",\"short_description\":\"Fakultas Sains dan Teknologi melakukan Audit Mutu Internal (AMI) tahun 2026.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"i\",\"9\":\"n\",\"10\":\"f\",\"11\":\"o\",\"12\":\"r\",\"13\":\"m\",\"14\":\"a\",\"15\":\"t\",\"16\":\"i\",\"17\":\"k\",\"18\":\"a\",\"19\":\"\\/\",\"20\":\"i\",\"21\":\"n\",\"22\":\"f\",\"23\":\"-\",\"24\":\"3\",\"25\":\".\",\"26\":\"j\",\"27\":\"p\",\"28\":\"g\",\"image\":\"\\/images\\/informatika\\/inf-3.jpg\",\"title\":\"Suasana Perkuliahan\",\"short_description\":\"Kegiatan perkuliahan di program studi S-1 Informatika Fakultas Sains dan Teknologi Upitra.\"}]', 3, '2026-04-16 20:16:04', '2026-10-22 01:49:47'),
(4, 'Akuntansi', NULL, 'Program Studi Akuntansi UPITRA dirancang untuk menghasilkan lulusan yang memiliki kompetensi bidang akuntansi, kemampuan analisis bisnis, serta jiwa kewirausahaan yang kuat.', NULL, 'akuntansi', 'FEB', 'Fakultas Ekonomi & Bisnis', 'Baik Sekali', 'Calculator', '/akuntansi', 1, 670, 'Program Studi Akuntansi', 'Mempersiapkan pemimpin bisnis masa depan yang inovatif dan berdaya saing global.', 'Program studi S1 Akuntansi yang unggul, menghasilkan lulusan yang berdaya saing global pada bidang akuntansi, serta berintegritas dan adaptif.', '[\"Menyelenggarakan program pendidikan yang menghasilkan lulusan yang kompeten dalam bidang akuntansi, berintegritas, kedalaman spiritualitas, kemampuan beradaptasi, kemampuan berkomunikasi dengan kepribadian unggul, berintegritas serta memiliki kerendahan hati, berbelarasa pada sesama maupun lingkungan.\",\"Menyelenggarakan penelitian dalam bidang akuntansi yang berdampak positif bagi masyarakat.\",\"Berperan aktif dalam kegiatan sosial melalui kegiatan pengabdian kepada masyarakat dibidang akuntansi.\",\"Memberikan kesempatan kepada masyarakat untuk mewujudkan pendidikan tinggi melalui program beasiswa dibidang akuntansi.\",\"Mengembangkan jaringan kerjasama dengan dunia usaha, dunia industri, dan dunia kerja (DUDIKA) untuk meningkatkan kualitas pendidikan.\",\"Menciptakan ruang belajar dan berkegiatan kepada mahasiswa dengan penyediaan fasilitas dan sarana prasarana yang mendukung serta sesuai dengan kebutuhan.\"]', '[\"Menghasilkan lulusan yang mampu bekerja dan mengembangkan di kantor akuntan publik dan perusahaan sebagai auditor forensic, accounting analyst, dan accounting system consultant.\",\"Menghasilkan lulusan yang mampu menggunakan program akuntansi berbasis teknologi memiliki integritas dan rendah hati.\",\"Menghasilkan riset bidang akuntansi yang bermanfaat untuk pengembangan pembelajaran dan meningkatkan kesejahteraan masyarakat serta dapat dipublikasikan pada jurnal nasional dan internasional terakreditasi.\",\"Meningkatnya kesejahteraan masyarakat melalui kegiatan Pengabdian kepada Masyarakat (PkM) dengan menggunakan teknologi informasi sesuai dengan kebutuhan masyarakat.\",\"Terjalinnya kerjasama dengan Dunia Usaha dan Dunia Industri Kerja (DUDIKA) untuk meningkatkan kualitas lulusan melalui kerja magang, pelatihan, sertifikasi kompetensi maupun kuliah praktisi.\"]', '[{\"title\":\"Accounting Staff\",\"desc\":\"Memiliki kemampuan managerial dan analisis kinerja keuangan.\"},{\"title\":\"Accounting Technopreneur\",\"desc\":\"Membangun bisnis dan startup berbasis akuntansi.\"},{\"title\":\"Tax Staff\",\"desc\":\"Merencanakan dan melaporkan perpajakan.\"},{\"title\":\"Auditor\",\"desc\":\"Melakukan audit keuangan dan internal.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Teknologi Keuangan Dasar\",\"sks\":2},{\"code\":\"2\",\"name\":\"Pengantar Bisnis dan Manajemen\",\"sks\":3},{\"code\":\"3\",\"name\":\"Pengantar Aplikasi Komputer Bisnis\",\"sks\":2},{\"code\":\"4\",\"name\":\"Pengantar Akuntansi\",\"sks\":3},{\"code\":\"5\",\"name\":\"Pengantar Ekonomi Mikro\",\"sks\":2},{\"code\":\"6\",\"name\":\"Pengantar Bisnis\",\"sks\":3},{\"code\":\"7\",\"name\":\"Bahasa Inggris I\",\"sks\":2},{\"code\":\"8\",\"name\":\"Agama\",\"sks\":2}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Akuntansi Keuangan Menengah I\",\"sks\":3},{\"code\":\"2\",\"name\":\"Komunikasi dan Negosiasi Bisnis\",\"sks\":3},{\"code\":\"3\",\"name\":\"Pengantar Ekonomi Makro\",\"sks\":2},{\"code\":\"4\",\"name\":\"Enterprise Resource Planning\",\"sks\":3},{\"code\":\"5\",\"name\":\"Teknik Pelaporan Keuangan\",\"sks\":3},{\"code\":\"6\",\"name\":\"Statistik\",\"sks\":3},{\"code\":\"7\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"8\",\"name\":\"Kewarganegaraan\",\"sks\":2}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Financial Audit\",\"sks\":3},{\"code\":\"2\",\"name\":\"Teknologi Pelaporan Keuangan Dasar\",\"sks\":3},{\"code\":\"3\",\"name\":\"Akuntansi Keuangan Menengah II\",\"sks\":3},{\"code\":\"4\",\"name\":\"Sistem Informasi Akuntansi\",\"sks\":3},{\"code\":\"5\",\"name\":\"Pengantar Perpajakan\",\"sks\":3},{\"code\":\"6\",\"name\":\"Akuntansi Biaya\",\"sks\":3},{\"code\":\"7\",\"name\":\"Analisa Laporan Keuangan\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Perpajakan Lanjutan\",\"sks\":3},{\"code\":\"2\",\"name\":\"Audit Internal\",\"sks\":3},{\"code\":\"3\",\"name\":\"Akuntansi Manajemen\",\"sks\":3},{\"code\":\"4\",\"name\":\"Financial Audit Lanjutan\",\"sks\":3},{\"code\":\"5\",\"name\":\"Akuntansi Keuangan Lanjutan\",\"sks\":3},{\"code\":\"6\",\"name\":\"Akuntansi Sektor Publik\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Akuntansi Perbankan\",\"sks\":3},{\"code\":\"2\",\"name\":\"English For Business\",\"sks\":3},{\"code\":\"3\",\"name\":\"Teori Akuntansi\",\"sks\":3},{\"code\":\"4\",\"name\":\"Sistem Pengendalian Manajemen\",\"sks\":3},{\"code\":\"5\",\"name\":\"Analisis Statistik Ekonomi dan Bisnis\",\"sks\":3},{\"code\":\"6\",\"name\":\"Akuntansi Keuangan Lanjutan I\",\"sks\":3},{\"code\":\"7\",\"name\":\"Akuntansi Forensik dan Audit Investigation\",\"sks\":3},{\"code\":\"8\",\"name\":\"Teori Investasi Pasar Modal\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Bahasa Inggris Ekstensif\",\"sks\":2},{\"code\":\"2\",\"name\":\"Teori Akuntansi\",\"sks\":3},{\"code\":\"3\",\"name\":\"AKUNTANSI PERBANKAN II\",\"sks\":3},{\"code\":\"4\",\"name\":\"Kepemimpinan dan Pengambilan Keputusan\",\"sks\":3},{\"code\":\"5\",\"name\":\"Akuntansi Keuangan Lanjutan II\",\"sks\":3},{\"code\":\"6\",\"name\":\"Akuntansi Perpajakan\",\"sks\":3}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Professional Soft Skill\",\"sks\":5},{\"code\":\"2\",\"name\":\"Financial Reporting\",\"sks\":5},{\"code\":\"3\",\"name\":\"Accounting Solution\",\"sks\":5},{\"code\":\"4\",\"name\":\"Accounting Technology Implementation\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Tugas Akhir\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Basic Accounting\",\"desc\":\"Pengantar akuntansi dan ekonomi.\"},{\"semester\":\"Semester 2\",\"title\":\"Financial Accounting\",\"desc\":\"Akuntansi keuangan dasar.\"},{\"semester\":\"Semester 3\",\"title\":\"Intermediate Accounting\",\"desc\":\"Akuntansi biaya dan sistem informasi akuntansi.\"},{\"semester\":\"Semester 4\",\"title\":\"Accounting Analysis\",\"desc\":\"Analisis laporan keuangan.\"},{\"semester\":\"Semester 5\",\"title\":\"Professional Accounting\",\"desc\":\"Audit dan perpajakan.\"},{\"semester\":\"Semester 6\",\"title\":\"Immersion Program\",\"desc\":\"Magang di perusahaan atau kantor akuntan.\"},{\"semester\":\"Semester 7\",\"title\":\"Immersion Program\",\"desc\":\"Magang lanjutan.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Skripsi akuntansi.\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"a\",\"9\":\"k\",\"10\":\"u\",\"11\":\"n\",\"12\":\"t\",\"13\":\"a\",\"14\":\"n\",\"15\":\"s\",\"16\":\"i\",\"17\":\"\\/\",\"18\":\"a\",\"19\":\"k\",\"20\":\"t\",\"21\":\"-\",\"22\":\"1\",\"23\":\".\",\"24\":\"j\",\"25\":\"p\",\"26\":\"g\",\"image\":\"\\/images\\/akuntansi\\/akt-1.jpg\",\"title\":\"Kegiatan Praktikum Akuntansi\",\"short_description\":\"Mahasiswa program studi S-1 Akuntansi melakukan praktikum akuntansi.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"a\",\"9\":\"k\",\"10\":\"u\",\"11\":\"n\",\"12\":\"t\",\"13\":\"a\",\"14\":\"n\",\"15\":\"s\",\"16\":\"i\",\"17\":\"\\/\",\"18\":\"a\",\"19\":\"k\",\"20\":\"t\",\"21\":\"-\",\"22\":\"2\",\"23\":\".\",\"24\":\"j\",\"25\":\"p\",\"26\":\"g\",\"image\":\"\\/images\\/akuntansi\\/akt-2.jpg\",\"title\":\"Perkuliahan Tahun Akademik 2025\\/2026 Gasal\",\"short_description\":\"Perkuliahan tahun akademik 2025\\/2026 Gasal di program studi S-1 Akuntansi.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"a\",\"9\":\"k\",\"10\":\"u\",\"11\":\"n\",\"12\":\"t\",\"13\":\"a\",\"14\":\"n\",\"15\":\"s\",\"16\":\"i\",\"17\":\"\\/\",\"18\":\"a\",\"19\":\"k\",\"20\":\"t\",\"21\":\"-\",\"22\":\"3\",\"23\":\".\",\"24\":\"j\",\"25\":\"p\",\"26\":\"g\",\"image\":\"\\/images\\/program-studi\\/1777434103_69f17df780839.jpg\",\"title\":\"Kuliah Umum Akuntansi\",\"short_description\":\"Program studi S-1 Akuntansi Fakultas Ekonomika dan Bisnis melaksanakan kuliah umum bekerjasama dengan IAPI.\"},{\"image\":\"\\/images\\/program-studi\\/1777434809_69f180b948b61.jpg\",\"title\":\"Kunjungan Literasi ke Bank Indonesia\",\"short_description\":\"Mahasiswa Fakultas Ekonomika dan Bisnis melakukan kunjungan literasi ke Bank Indonesia Solo.\"}]', 4, '2026-04-16 20:16:04', '2026-10-22 01:05:16'),
(5, 'Manajemen', NULL, 'Lulusan program studi manajemen yang menguasai kompetensi utama pilar manajemen yang memimpin dengan 10 keutamaan lulusan UPITRA (Leading with Ten Virtues), serta ⁠keterampilan dan pengalaman bisnis berbasis industri (Industrial Business Skill and Experience)', NULL, 'manajemen', 'FEB', 'Fakultas Ekonomi & Bisnis', 'Baik', 'Briefcase', '/manajemen', 1, 727, 'Program Studi Manajemen', 'Mempersiapkan pemimpin bisnis masa depan yang inovatif dan berdaya saing global.', 'Menghasilkan lulusan di bidang Manajemen Pemasaran yang memiliki kompetensi unggul dan berwawasan global serta memiliki jiwa kepemimpinan.', '[\"Menyelenggarakan proses pembelajaran yang berkualitas di bidang Manajemen Pemasaran dan Manajemen Keuangan yang mampu berfikir kritis, inovatif serta memiliki jiwa kepemimpinan.\",\"Menghasilkan lulusan yang memiliki integritas dan kompeten di bidang ilmu Manajemen berbasis teknologi.\",\"Mendorong mahasiswa mampu menjadi agen perubahan dalam bidang Manajemen Pemasaran dan Manajemen Keuangan.\",\"Melaksanakan penelitian dan pengabdian kepada masyarakat bidang Manajemen yang berbasis pada persaingan global dan pemberdayaan masyarakat baik secara nasional maupun internasional.\",\"Menjalin jaringan kerjasama dengan dunia usaha, dunia industri, dan dunia kerja (DUDIKA) untuk meningkatkan kualitas tridharma.\"]', '[\"Menghasilkan lulusan yang kompeten, mampu berfikir kritis, inovatif bidang ilmu Manajemen untuk bersaing di dunia kerja serta memiliki integritas dan rendah hati.\",\"Menghasilkan lulusan yang memiliki jiwa kepemimpinan dan mampu berorganisasi dalam dunia kerja maupun dalam melaksanakan usaha mandiri dengan menerapkan ilmu Manajemen berbasis teknologi.\",\"Menghasilkan penelitian, pengabdian dan publikasi karya ilmiah baik jurnal nasional maupun internasional bidang ilmu Manajemen yang dapat dimanfaatkan untuk pengembangan pembelajaran dan mampu memberikan kontribusi terhadap kesejahteraan masyarakat.\",\"Menjalin kerjasama dengan DUDIKA dan lembaga lain ditingkat nasional maupun internasional untuk meningkatkan kualitas tridharma.\"]', '[{\"title\":\"Junior Manajer\",\"desc\":\"Mampu memimpin pelaksanaan pekerjaan dan mengoordinasikan tim untuk mencapai tujuan organisasi. Memiliki kemampuan mengelola sumber daya, mengambil keputusan, dan menyelesaikan masalah secara efektif. Terbiasa bekerja secara kolaboratif dengan berbagai pihak.\"},{\"title\":\"Analis\",\"desc\":\"Mampu mengubah data menjadi informasi yang bernilai untuk mendukung keputusan bisnis. Memiliki kemampuan berpikir kritis, logis, dan berbasis fakta dalam memecahkan masalah. Terampil menggunakan berbagai metode analisis untuk mengidentifikasi peluang maupun risiko bisnis.\"},{\"title\":\"Konsultan\",\"desc\":\"Mampu memberikan rekomendasi dan solusi yang tepat untuk menjawab berbagai tantangan. Memiliki kemampuan mengidentifikasi akar permasalahan dan menyusun strategi perbaikan yang relevan. Terampil berkomunikasi, bernegosiasi, dan membangun hubungan profesional dengan berbagai pihak.\"},{\"title\":\"Wirausahawan\",\"desc\":\"Mampu menciptakan peluang bisnis yang inovatif dan memberikan nilai bagi masyarakat. Memiliki keberanian mengambil peluang, menghadapi tantangan, dan mengembangkan usaha secara berkelanjutan. Kreatif, adaptif, serta mampu memanfaatkan teknologi untuk menciptakan keunggulan kompetitif.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"AGAMA\",\"sks\":2},{\"code\":\"2\",\"name\":\"PANCASILA\",\"sks\":2},{\"code\":\"3\",\"name\":\"BASIC ENGLISH\",\"sks\":2},{\"code\":\"4\",\"name\":\"DASAR DASAR AKUNTANSI\",\"sks\":3},{\"code\":\"5\",\"name\":\"PRAKTIKA DASAR AKUNTANSI\",\"sks\":0},{\"code\":\"6\",\"name\":\"PENGANTAR BISNIS\",\"sks\":3},{\"code\":\"7\",\"name\":\"TEORI EKONOMI MIKRO\",\"sks\":3},{\"code\":\"8\",\"name\":\"MATEMATIKA EKONOMI\",\"sks\":3}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"KEWARGANEGARAAN\",\"sks\":2},{\"code\":\"2\",\"name\":\"BAHASA INDONESIA\",\"sks\":2},{\"code\":\"3\",\"name\":\"APLIKASI KOMPUTER BISNIS\",\"sks\":3},{\"code\":\"4\",\"name\":\"KOMUNIKASI DAN NEGOSIASI BISNIS\",\"sks\":3},{\"code\":\"5\",\"name\":\"TEORI EKONOMI MAKRO\",\"sks\":3},{\"code\":\"6\",\"name\":\"PENGANTAR MANAJEMEN\",\"sks\":3},{\"code\":\"7\",\"name\":\"AKUNTANSI MENENGAH\",\"sks\":3}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"PENGEMBANGAN KEPRIBADIAN UPITRA DNA\",\"sks\":3},{\"code\":\"2\",\"name\":\"MANAJEMEN KEUANGAN\",\"sks\":3},{\"code\":\"3\",\"name\":\"PRAKTIKA MANAJEMEN KEUANGAN\",\"sks\":0},{\"code\":\"4\",\"name\":\"MANAJEMEN PEMASARAN\",\"sks\":3},{\"code\":\"5\",\"name\":\"MANAJEMEN SUMBER DAYA MANUSIA\",\"sks\":3},{\"code\":\"6\",\"name\":\"MANAJEMEN OPERASI\",\"sks\":3},{\"code\":\"7\",\"name\":\"SISTEM INFORMASI MANAJEMEN\",\"sks\":3},{\"code\":\"8\",\"name\":\"STATISTIKA 1\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"KEWIRAUSAHAAN\",\"sks\":3},{\"code\":\"2\",\"name\":\"STATISTIKA 2\",\"sks\":3},{\"code\":\"3\",\"name\":\"METODE KUANTITATIF BISNIS\",\"sks\":3},{\"code\":\"4\",\"name\":\"Konsentrasi MK 1: MANAJEMEN KEUANGAN LANJUTAN\",\"sks\":3},{\"code\":\"5\",\"name\":\"Konsentrasi MK 2: ANALISIS LAPORAN KEUANGAN\",\"sks\":3},{\"code\":\"6\",\"name\":\"Konsentrasi MK 3: PASAR DAN LEMBAGA KEUANGAN\",\"sks\":3},{\"code\":\"7\",\"name\":\"Konsentrasi MP 1: MANAJEMEN MEREK DAN INOVASI\",\"sks\":3},{\"code\":\"8\",\"name\":\"Konsentrasi MP 2: PERILAKU KONSUMEN\",\"sks\":3},{\"code\":\"9\",\"name\":\"Konsentrasi MP 3: DIGITAL MARKETING\",\"sks\":3},{\"code\":\"10\",\"name\":\"Konsentrasi MSDM 1: PERENCANAAN TENAGA KERJA\",\"sks\":3},{\"code\":\"11\",\"name\":\"Konsentrasi MSDM 2: MANAJEMEN TALENTA\",\"sks\":3},{\"code\":\"12\",\"name\":\"Konsentrasi MSDM 3: HUBUNGAN INDUSTRIAL\",\"sks\":3},{\"code\":\"13\",\"name\":\"MANAJEMEN STRATEGIS\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"METODOLOGI PENELITIAN BISNIS\",\"sks\":2},{\"code\":\"2\",\"name\":\"PERILAKU ORGANISASI\",\"sks\":3},{\"code\":\"3\",\"name\":\"ETIKA BISNIS\",\"sks\":2},{\"code\":\"4\",\"name\":\"Konsentrasi MK 1: TEORI INVESTASI DAN PASAR MODAL\",\"sks\":3},{\"code\":\"5\",\"name\":\"Konsentrasi MK 2: MANAJEMEN KEUANGAN INTERNASIONAL\",\"sks\":3},{\"code\":\"6\",\"name\":\"Konsentrasi MK 3: ANGGARAN PERUSAHAAN\",\"sks\":3},{\"code\":\"7\",\"name\":\"Konsentrasi MP 1: PEMASARAN JASA\",\"sks\":3},{\"code\":\"8\",\"name\":\"Konsentrasi MP 2: PEMASARAN INTERNASIONAL\",\"sks\":3},{\"code\":\"9\",\"name\":\"Konsentrasi MP 3: KEPUTUSAN PEMASARAN KREATIF\",\"sks\":3},{\"code\":\"10\",\"name\":\"Konsentrasi MSDM 1: MANAJEMEN PELATIHAN DAN PENGEMBANGAN\",\"sks\":3},{\"code\":\"11\",\"name\":\"Konsentrasi MSDM 2: MANAJEMEN REMUNERASI\",\"sks\":3},{\"code\":\"12\",\"name\":\"Konsentrasi MSDM 3: MANAJEMEN PERUBAHAN\",\"sks\":3},{\"code\":\"13\",\"name\":\"PERSONNAL BRANDING\",\"sks\":2},{\"code\":\"14\",\"name\":\"ENGLISH CONVERSATION FOR BUSINESS\",\"sks\":2}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Collaborative Development\",\"sks\":5},{\"code\":\"2\",\"name\":\"Management in Practice\",\"sks\":5},{\"code\":\"3\",\"name\":\"Experience in Business Management\",\"sks\":5},{\"code\":\"4\",\"name\":\"Experience in Business Development\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Professional Soft Skills\",\"sks\":5},{\"code\":\"2\",\"name\":\"Management Solutions\",\"sks\":5},{\"code\":\"3\",\"name\":\"Business Management Environment\",\"sks\":5},{\"code\":\"4\",\"name\":\"Business Development Implementation\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"SKRIPSI\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Fundamental Business\",\"desc\":\"Dasar-dasar ekonomi, manajemen, dan matematika bisnis.\"},{\"semester\":\"Semester 2\",\"title\":\"Basic Management\",\"desc\":\"Konsep organisasi, etika bisnis, dan pengantar manajemen operasional.\"},{\"semester\":\"Semester 3\",\"title\":\"Management Core\",\"desc\":\"Pendalaman bidang manajemen seperti SDM, keuangan, dan perilaku organisasi.\"},{\"semester\":\"Semester 4\",\"title\":\"Business Analysis\",\"desc\":\"Analisis strategi bisnis dan sistem informasi manajemen.\"},{\"semester\":\"Semester 5\",\"title\":\"Advanced Management\",\"desc\":\"Pendalaman manajemen pemasaran dan strategi bisnis.\"},{\"semester\":\"Semester 6\",\"title\":\"Entrepreneurship\",\"desc\":\"Inovasi bisnis dan pengembangan startup.\"},{\"semester\":\"Semester 7\",\"title\":\"Industry Internship\",\"desc\":\"Magang di perusahaan mitra.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Skripsi atau proyek akhir.\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"m\",\"9\":\"a\",\"10\":\"n\",\"11\":\"a\",\"12\":\"j\",\"13\":\"e\",\"14\":\"m\",\"15\":\"e\",\"16\":\"n\",\"17\":\"\\/\",\"18\":\"d\",\"19\":\"i\",\"20\":\"g\",\"21\":\"i\",\"22\":\"t\",\"23\":\"a\",\"24\":\"l\",\"25\":\"-\",\"26\":\"m\",\"27\":\"a\",\"28\":\"r\",\"29\":\"k\",\"30\":\"e\",\"31\":\"t\",\"32\":\"i\",\"33\":\"n\",\"34\":\"g\",\"35\":\".\",\"36\":\"j\",\"37\":\"p\",\"38\":\"g\",\"image\":\"\\/images\\/manajemen\\/digital-marketing.jpg\",\"title\":\"Praktek Digital Marketing\",\"short_description\":\"Mahasiswa program studi S-1 Manajemen Fakultas Ekonomika dan Bisnis UPITRA melakukan praktek langsung digital marketing.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"m\",\"9\":\"a\",\"10\":\"n\",\"11\":\"a\",\"12\":\"j\",\"13\":\"e\",\"14\":\"m\",\"15\":\"e\",\"16\":\"n\",\"17\":\"\\/\",\"18\":\"o\",\"19\":\"l\",\"20\":\"m\",\"21\":\"a\",\"22\":\".\",\"23\":\"j\",\"24\":\"p\",\"25\":\"g\",\"image\":\"\\/images\\/manajemen\\/olma.jpg\",\"title\":\"Olimpiade Manajemen dan Akuntansi\",\"short_description\":\"Fakultas Ekonomika dan Bisnis Universitas Pignatelli Triputra menyelenggarakan Olimpiade Manajemen dan Akuntansi tahun 2025.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"m\",\"9\":\"a\",\"10\":\"n\",\"11\":\"a\",\"12\":\"j\",\"13\":\"e\",\"14\":\"m\",\"15\":\"e\",\"16\":\"n\",\"17\":\"\\/\",\"18\":\"s\",\"19\":\"h\",\"20\":\"o\",\"21\":\"o\",\"22\":\"p\",\"23\":\"e\",\"24\":\".\",\"25\":\"j\",\"26\":\"p\",\"27\":\"g\",\"image\":\"\\/images\\/manajemen\\/shoope.jpg\",\"title\":\"Kuliah Marketing di Shoope\",\"short_description\":\"Mahasiswa program studi S-1 Manajemen melakukan belajar marketing secara langsung dengan mengadakan kuliah di kantor pemasaran Shoope Solo.\"}]', 5, '2026-04-16 20:16:04', '2026-10-22 04:47:06');
INSERT INTO `program_studi` (`id`, `name`, `title`, `description`, `short_description`, `slug`, `faculty`, `faculty_name`, `accreditation`, `icon`, `url`, `active`, `views_count`, `hero_title`, `hero_subtitle`, `visi`, `misi`, `tujuan`, `karir`, `kurikulum`, `roadmap`, `kegiatan_images`, `sort_order`, `created_at`, `updated_at`) VALUES
(6, 'Pariwisata', NULL, 'Program Studi S1 Pariwisata UPITRA dirancang untuk mencetak generasi muda yang kreatif, profesional, multikultural, kosmopolitan, dan siap bersaing di industri pariwisata global dengan fokus pada usaha layanan wisata, manajemen perhotelan, operasional destinasi wisata, event MICE, kewirausahaan, public speaking, inovasi digital, community based tourism dan wisata minat khusus.', NULL, 'pariwisata', 'FSH', 'Fakultas Sosial & Humaniora', 'Prodi Baru', 'Hotel', '/pariwisata', 1, 540, 'Program Studi Pariwisata', 'Mempersiapkan profesional pariwisata yang kreatif, inovatif, dan berdaya saing global.', 'Menjadi program studi unggulan yang multikultural dan kosmopolitan di bidang hospitaliti dan pariwisata khususnya wisata minat khusus berbasis inovasi teknologi dan berkelanjutan.', '[\"Menyelenggarakan pendidikan berkualitas berbasisOutcome Based Education(OBE) di bidanghospitaliti dan pariwisatakhususnya wisata minat khusus berbasis inovasi teknologi berlandaskan keberlanjutan yang multikulturalisme dan kosmopolitan yang berorientasi pada kebutuhan industri pariwisata\",\"Mengembangkan penelitian dalam bidanghospitaliti dan pariwisata khususnya wisata minat khusus berbasis inovasi teknologi berlandaskan keberlanjutan yang multikulturalisme dan kosmopolitan\",\"Melaksanakan pengabdian kepada masyarakat lewat program penyuluhan dan pendampingan pemberdayaan komunitas lokal, UMKM lokal, dan bisnis pariwisata untuk meningkatkan kualitas pengalaman kegiatan kepariwisataan\",\"Membangun kemitraan strategis dengan pemangku kepentingan pada kegiatan tridharma perguruan tinggi guna meningkatkan daya saing lulusan\",\"Menumbuhkan budaya mutu, tata kelola transparan, dan kewirausahaan agar lulusan adaptif terhadap transformasi global yang berwawasan multikultural dan kosmopolitan untuk kegiatan kepariwisataan yang berkelanjutan.\"]', '[\"Menghasilkan lulusan yang kompeten di bidang Manajemen Pariwisata atau Manajemen Hospitaliti dengan sertifikasi kompetensi nasional\\/internasional.\",\"Menghasilkan luaran penelitian berkualitas yang berkontribusi pada penguatan sumber daya manusia, sosial budaya, destinasi, wisataminat khusus, industri pariwisata, inovasi teknologi produk pariwisata dengan standar nasional dan internasional\",\"Meningkatkan kualitas masyarakat dalam kegiatan kepariwisataan melalui solusi inovatif dengan memanfaatkan teknologi informasi untuk menjawab tantangan pariwisata berkelanjutan\",\"Memperkuat kemitraan untuk kesesuaian kurikulum berbasisOutcome Based Education(OBE) sesuai kebutuhan global melalui kegiatan yang mendukung kompetensi lulusan untuk mempercepat transisi ke dunia kerja\",\"Mewujudkan budaya mutu tridharma perguruan tinggi, tata kelola transparan, dan kewirausahaan agar lulusan berwawasan multikultural dan kosmopolitan untuk kegiatan kepariwisataan yang berkelanjutan.\"]', '[{\"title\":\"AKADEMISI\",\"desc\":\"Menjadi asisten peneliti atau pengajar lingkup kepariwisataan\"},{\"title\":\"KONSULTAN PARIWISATA\",\"desc\":\"Pemberi rekomendasi strategis terkait pengembangan pariwisata\"},{\"title\":\"STAFF HOTEL\",\"desc\":\"Di bidang Front Office, Kitchen, Food & Beverage Service, Housekeeping, dan Back Office Department\"},{\"title\":\"MANAGER HOTEL\",\"desc\":\"Perencana, pengawas, dan pengelola operasional harian hotel\"},{\"title\":\"STAFF TRAVEL AGENT\",\"desc\":\"Di bidang tour planner, operator biro perjalanan, dan guiding\"},{\"title\":\"MANAGER TOUR & TRAVEL\",\"desc\":\"Perencana, pengawas, dan pengelola operasional harian travel agent\"},{\"title\":\"EVENT PLANNER\",\"desc\":\"Di bidang MICE, wedding organizer, dan promotor event\"},{\"title\":\"PUBLIC SPEAKER\",\"desc\":\"Mampu berbicara dengan jelas dan percaya diri, pemandu jalannya acara\\/event\"},{\"title\":\"TOURISM PRENEURSHIP\",\"desc\":\"Menciptakan, mengembangkan, dan mengelola inovasi bisnis di sektor pariwisata \\/ hospitaliti\"},{\"title\":\"PENGELOLA DESTINASI WISATA\",\"desc\":\"Di bidang destination marketing, tourism sales, digital marketing untuk destinasi dan produk wisata\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"2\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"3\",\"name\":\"Cross Cultural Understanding\",\"sks\":3},{\"code\":\"4\",\"name\":\"Personal Branding\",\"sks\":2},{\"code\":\"5\",\"name\":\"Pengantar Pariwisata\",\"sks\":3},{\"code\":\"6\",\"name\":\"Sosiologi dan Antropologi Pariwisata\",\"sks\":3},{\"code\":\"7\",\"name\":\"Geografi Pariwisata\",\"sks\":3},{\"code\":\"8\",\"name\":\"English for Tourism\",\"sks\":2}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"2\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"3\",\"name\":\"Kebijakan Pariwisata\",\"sks\":2},{\"code\":\"4\",\"name\":\"Pariwisata dan Bisnis Internasional\",\"sks\":2},{\"code\":\"5\",\"name\":\"Sistem Informasi Kepariwisataan\",\"sks\":2},{\"code\":\"6\",\"name\":\"Sistem dan Prinsip Dasar Pariwisata\",\"sks\":3},{\"code\":\"7\",\"name\":\"Pariwisata Berbasis Komunitas\",\"sks\":3},{\"code\":\"8\",\"name\":\"Ekowisata dan Pariwisata Berkelanjutan\",\"sks\":3},{\"code\":\"9\",\"name\":\"English for Hospitality\",\"sks\":1}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Pengembangan Kepribadian UPITRA DNA\",\"sks\":3},{\"code\":\"2\",\"name\":\"Manajemen Layanan,Hygiene, dan Sanitasi\",\"sks\":2},{\"code\":\"3\",\"name\":\"Data Analisis Kepariwisataan\",\"sks\":3},{\"code\":\"4\",\"name\":\"Consumer Behaviour and Marketing in Tourism\",\"sks\":3},{\"code\":\"5\",\"name\":\"MICE dan Manajemen Event\",\"sks\":3},{\"code\":\"6\",\"name\":\"Manajemen Sumber Daya Manusia Pariwisata\",\"sks\":3},{\"code\":\"7\",\"name\":\"K3 dan Manajemen Kebencanaan\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewirausahaan\",\"sks\":3},{\"code\":\"2\",\"name\":\"Digital Tourism\",\"sks\":3},{\"code\":\"3\",\"name\":\"Inovasi dan Daya Saing Pariwisata\",\"sks\":3},{\"code\":\"4\",\"name\":\"Keimigrasian\",\"sks\":2},{\"code\":\"5\",\"name\":\"Perencanaan dan Pengembangan Pariwisata\",\"sks\":3},{\"code\":\"6\",\"name\":\"Guiding dan Interpretation\",\"sks\":3},{\"code\":\"7\",\"name\":\"Manajemen Perjalanan Wisata\",\"sks\":3},{\"code\":\"8\",\"name\":\"Manajemen Hotel\",\"sks\":2},{\"code\":\"9\",\"name\":\"Manajemen Food and Beverage\",\"sks\":3},{\"code\":\"10\",\"name\":\"Operasional Front Office\",\"sks\":3},{\"code\":\"11\",\"name\":\"Operasional Housekeeping\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Metodologi Penelitian Pariwisata\",\"sks\":3},{\"code\":\"2\",\"name\":\"Pariwisata Gastronomi\",\"sks\":3},{\"code\":\"3\",\"name\":\"Etika Profesi\",\"sks\":2},{\"code\":\"4\",\"name\":\"Adventure Tourism\",\"sks\":3},{\"code\":\"5\",\"name\":\"Rural Urban Tourism\",\"sks\":3},{\"code\":\"6\",\"name\":\"Cultural Tourism\",\"sks\":3},{\"code\":\"7\",\"name\":\"Wellness Tourism\",\"sks\":3},{\"code\":\"8\",\"name\":\"Pastry and Bakery\",\"sks\":3},{\"code\":\"9\",\"name\":\"Asian Cuisine\",\"sks\":3},{\"code\":\"10\",\"name\":\"Operasional Kitchen\",\"sks\":3},{\"code\":\"11\",\"name\":\"Operasional Bar dan Restoran\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Sikap I\",\"sks\":5},{\"code\":\"2\",\"name\":\"Pengetahuan I\",\"sks\":5},{\"code\":\"3\",\"name\":\"Ketrampilan Umum I\",\"sks\":5},{\"code\":\"4\",\"name\":\"Ketrampilan Khusus I\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Sikap II\",\"sks\":5},{\"code\":\"2\",\"name\":\"Pengetahuan II\",\"sks\":5},{\"code\":\"3\",\"name\":\"Ketrampilan Umum II\",\"sks\":5},{\"code\":\"4\",\"name\":\"Ketrampilan Khusus II\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Tugas Akhir\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Tourism Scientific Foundations and Orientation\",\"desc\":\"Mahasiswa dibekali landasan akademik, karakter, dan pengenalan dasar kepariwisataan.\"},{\"semester\":\"Semester 2\",\"title\":\"Understanding the Tourism System\",\"desc\":\"Memperluas wawasan mahasiswa terhadap regulasi, sistem, dan jejaring industri pariwisata.\"},{\"semester\":\"Semester 3\",\"title\":\"Operational and Analytical Strengthening\",\"desc\":\"Mahasiswa mulai masuk ke kompetensi profesional yang lebih aplikatif, baik di bidang layanan, analisis data, pemasaran, maupun manajemen sumber daya.\"},{\"semester\":\"Semester 4\",\"title\":\"Innovation, Digitalization, and Early Interest\",\"desc\":\"Mahasiswa diarahkan pada penguatan daya saing, inovasi, dan pengenalan jalur peminatan yang lebih spesifik: tourism dan hospitality.\"},{\"semester\":\"Semester 5\",\"title\":\"Initial Research and Deepening of Specialization\",\"desc\":\"Menyiapkan mahasiswa untuk masuk ke penelitian dan pendalaman kompetensi sesuai bidang keahlian tourism atau hospitality.\"},{\"semester\":\"Semester 6\",\"title\":\"Immersion Program\",\"desc\":\"Mahasiswa difokuskan pada kegiatan internship \\/ magang industri sebagai pengalaman belajar nyata di dunia kerja.\"},{\"semester\":\"Semester 7\",\"title\":\"Immersion Program\",\"desc\":\"Mahasiswa difokuskan pada kegiatan internship \\/ magang industri sebagai pengalaman belajar nyata di dunia kerja.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Tahap ini menjadi puncak integrasi antara pengetahuan teori, project based learning, praktik industri, dan kemampuan analitis mahasiswa.\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"p\",\"9\":\"a\",\"10\":\"r\",\"11\":\"i\",\"12\":\"w\",\"13\":\"i\",\"14\":\"s\",\"15\":\"a\",\"16\":\"t\",\"17\":\"a\",\"18\":\"\\/\",\"19\":\"p\",\"20\":\"a\",\"21\":\"r\",\"22\":\"-\",\"23\":\"1\",\"24\":\".\",\"25\":\"j\",\"26\":\"p\",\"27\":\"g\",\"image\":\"\\/images\\/program-studi\\/1779695775_6a14009f00a4e.jpg\",\"title\":\"Pengabdian Kepada Masyarakat di Desa Binaan\",\"short_description\":\"Mahasiswa dan dosen Prodi S1 Pariwisata melaksanakan kegiatan pengabdian di Desa Kenalan, Pakis, Magelang.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"p\",\"9\":\"a\",\"10\":\"r\",\"11\":\"i\",\"12\":\"w\",\"13\":\"i\",\"14\":\"s\",\"15\":\"a\",\"16\":\"t\",\"17\":\"a\",\"18\":\"\\/\",\"19\":\"p\",\"20\":\"a\",\"21\":\"r\",\"22\":\"-\",\"23\":\"2\",\"24\":\".\",\"25\":\"j\",\"26\":\"p\",\"27\":\"g\",\"image\":\"\\/images\\/program-studi\\/1779695820_6a1400ccc92cc.jpg\",\"title\":\"Kegiatan Paduan Suara Mahasiswa (PSM) UPITRA\",\"short_description\":\"Persiapan mahasiswa Prodi S1 Pariwisata dalam mengikuti perlombaan paduan suara mahasiswa tingkat nasional di Bandung.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"p\",\"9\":\"a\",\"10\":\"r\",\"11\":\"i\",\"12\":\"w\",\"13\":\"i\",\"14\":\"s\",\"15\":\"a\",\"16\":\"t\",\"17\":\"a\",\"18\":\"\\/\",\"19\":\"p\",\"20\":\"a\",\"21\":\"r\",\"22\":\"-\",\"23\":\"3\",\"24\":\".\",\"25\":\"j\",\"26\":\"p\",\"27\":\"g\",\"image\":\"\\/images\\/program-studi\\/1779695869_6a1400fd5d1a2.jpg\",\"title\":\"Kolaborasi Mahasiswa Dengan Miss Batik Indonesia\",\"short_description\":\"Kegiatan non akademik Prodi S1 Pariwisata, mahasiswa terlibat sebagai panitia penyelenggara event Miss Batik Indonesia di Surakarta.\"},{\"image\":\"\\/images\\/program-studi\\/1779695909_6a140125a2170.jpg\",\"title\":\"Kunjungan ke Dinas Kebudayaan dan Pariwisata Kota Surakarta\",\"short_description\":\"Mahasiswa Prodi S1 Pariwisata melakukan kunjungan resmi ke Dinas Kebudayaan dan Pariwisata Kota Surakarta.\"},{\"image\":\"\\/images\\/program-studi\\/1779695950_6a14014e36c0f.jpg\",\"title\":\"Kegiatan Hiking di Gunung Ungaran\",\"short_description\":\"Salah satu unit kegiatan mahasiswa Prodi S1 Pariwisata, mountaineering di Gunung Ungaran.\"},{\"image\":\"\\/images\\/program-studi\\/1779695995_6a14017b987f0.jpg\",\"title\":\"Pembelajaran Luar Kelas (Outdoor Study)\",\"short_description\":\"Outdoor Study merupakan salah satu metode pembelajaran mahasiswa Prodi S1 Pariwisata  yang bertujuan memupuk kreatifitas, inisiatif, kerjasama dan mengakrabkan mahasiswa dengan lingkungan luar kampus.\"}]', 6, '2026-04-16 20:16:04', '2026-10-22 08:17:35'),
(7, 'Bahasa Inggris', NULL, 'Program Studi S1 Bahasa Inggris (Bahasa dan Kebudayaan Inggris) UPITRA dirancang untuk mencetak generasi muda yang komunikatif, kreatif, profesional, dan siap bersaing di era global dengan fokus pada kemampuan bahasa Inggris, komunikasi internasional, linguistik, penerjemahan, public speaking, digital communication, teaching methodology, content creation, intercultural understanding, serta pengembangan karier di bidang pendidikan, bisnis, media, dan industri kreatif.', NULL, 'bahasa-inggris', 'FSH', 'Fakultas Sosial & Humaniora', 'Prodi Baru', 'GraduationCap', '/bahasa-inggris', 1, 555, 'Program Studi Bahasa Inggris', 'Mempersiapkan profesional bahasa Inggris yang komunikatif, kreatif, dan berdaya saing global.', 'Menjadi program studi unggulan dalam bahasa, sastra, dan budaya Inggris yang terintegrasi dengan teknologi digital untuk memajukan komunikasi lintas budaya dan kemanusiaan yang berwawasan multikultural dan kosmopolitan.', '[\"\\u25cf\\tMenyelenggarakan pendidikan bahasa, sastra, dan budaya Inggris yang berkualitas dengan memanfaatkan pendekatan berbasis teknologi digital dan metode inovatif untuk menghasilkan lulusan yang profesional yang berkeutamaan dan berwawasan kosmopolitan.\",\"\\u25cf\\tMengembangkan penelitian interdisipliner yang berkualitas dan berfokus pada digital humanities, teknologi pembelajaran bahasa, dan kajian budaya kontemporer.\",\"\\u25cf\\tMenerapkan ilmu pengetahuan melalui pengabdian masyarakat yang transformatif, kolaboratif, dan inovatif demi masyarakat yang semakin bermartabat.\",\"\\u25cf\\tMembangun jaringan kerjasama dengan institusi nasional dan internasional  untuk mewujudkan program studi unggulan dalam bahasa, sastra, dan budaya Inggris yang terintegrasi dengan teknologi digital untuk memajukan komunikasi lintas budaya dan kemanusiaan yang berwawasan multikultural dan kosmopolitan.\"]', '[\"\\u25cf\\tMenghasilkan lulusan yang menguasai kompetensi profesional dalam bidang bahasa, sastra, dan budaya Inggris yang dilengkapi dengan literasi teknologi digital, sehingga mampu berkarir dan bersaing ditingkat global di berbagai sektor seperti pendidikan, ekonomi kreatif, diplomasi, dan industri dengan menunjukkan etika dan wawasan kosmopolitan.\",\"\\u25cf\\tMelaksanakan pendidikan berkualitas dengan kurikulum yang menerapkan contextual learning yang berbasis industri dan ASEAN University Network Quality Assurance Framework (AUN-QA Framework)\",\"\\u25cf\\tMengembangkan ilmu pengetahuan melalui penelitian di bidang bahasa dan budaya Inggris yang mencakup digital humanities, teknologi pembelajaran bahasa, dan kajian budaya kontemporer dan yang diwujudnyatakan dalam kegiatan pengabdian masyarakat berbasis keahlian bahasa dan budaya kepada berbagai macam pelaku kepentingan\",\"\\u25cf\\tMenjalin kemitraan dengan perguruan tinggi, perusahaan, dan lembaga di tingkat nasional dan internasional\"]', '[{\"title\":\"English Trainer\",\"desc\":\"Mengajar dan melatih keterampilan bahasa Inggris secara komunikatif dan profesional.\"},{\"title\":\"Translator \\/ Interpreter\",\"desc\":\"Menerjemahkan teks tertulis serta melakukan alih bahasa lisan dalam berbagai situasi komunikasi.\"},{\"title\":\"Content Creator\",\"desc\":\"Membuat konten kreatif dan komunikatif untuk media digital dan global.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Agama (Religious Studies)\",\"sks\":2},{\"code\":\"2\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"3\",\"name\":\"Cross Cultural Understanding\",\"sks\":3},{\"code\":\"4\",\"name\":\"Personal Branding\",\"sks\":2},{\"code\":\"5\",\"name\":\"Introduction to Listening & Speaking\",\"sks\":3},{\"code\":\"6\",\"name\":\"Basic Grammar\",\"sks\":3},{\"code\":\"7\",\"name\":\"Introduction to Reading & Writing\",\"sks\":3},{\"code\":\"8\",\"name\":\"English Phonetics and Phonology\",\"sks\":2}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewarganegaraan (Citizenship)\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Indonesia (Indonesian Language)\",\"sks\":2},{\"code\":\"3\",\"name\":\"Intermediate Listening\",\"sks\":3},{\"code\":\"4\",\"name\":\"Intermediate Speaking\",\"sks\":2},{\"code\":\"5\",\"name\":\"Intermediate Grammar\",\"sks\":3},{\"code\":\"6\",\"name\":\"Intermediate Reading\",\"sks\":3},{\"code\":\"7\",\"name\":\"Intermediate Writing\",\"sks\":3},{\"code\":\"8\",\"name\":\"Pronunciation\",\"sks\":2}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"UPITRA DNA\",\"sks\":3},{\"code\":\"2\",\"name\":\"Creative Writing\",\"sks\":3},{\"code\":\"3\",\"name\":\"English Literature and Culture\",\"sks\":3},{\"code\":\"4\",\"name\":\"English for Specific Purpose\",\"sks\":3},{\"code\":\"5\",\"name\":\"Introduction to Translation Studies\",\"sks\":3},{\"code\":\"6\",\"name\":\"English Lexicology\",\"sks\":2},{\"code\":\"7\",\"name\":\"English for Business Communication\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewirausahaan (Entrepreneurship)\",\"sks\":3},{\"code\":\"2\",\"name\":\"Critical Theory\",\"sks\":3},{\"code\":\"3\",\"name\":\"Play Performance\",\"sks\":3},{\"code\":\"4\",\"name\":\"Academic Writing\",\"sks\":3},{\"code\":\"5\",\"name\":\"Cross-Linguistics Analysis for Translation\",\"sks\":3},{\"code\":\"6\",\"name\":\"Pragmatic and Sociolinguistics\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"English Test Preparation\",\"sks\":3},{\"code\":\"2\",\"name\":\"Public Speaking\",\"sks\":3},{\"code\":\"3\",\"name\":\"Critical Discourse Analysis\",\"sks\":3},{\"code\":\"4\",\"name\":\"Research Method\",\"sks\":3},{\"code\":\"5\",\"name\":\"Etika Profesi (Professional Ethics)\",\"sks\":2},{\"code\":\"6\",\"name\":\"English Trainer Stream\",\"sks\":0},{\"code\":\"7\",\"name\":\"Language Teaching  Methodology and Material Development\",\"sks\":3},{\"code\":\"8\",\"name\":\"Information and Communication Technology in English Teaching\",\"sks\":3},{\"code\":\"9\",\"name\":\"Language Assessment and Evaluation\",\"sks\":3},{\"code\":\"10\",\"name\":\"Translation and Interpreting Stream\",\"sks\":0},{\"code\":\"11\",\"name\":\"Interpreting\",\"sks\":3},{\"code\":\"12\",\"name\":\"Translation Theories and Ideologies\",\"sks\":3},{\"code\":\"13\",\"name\":\"Translation Criticism and Quality Assessment\",\"sks\":3},{\"code\":\"14\",\"name\":\"Content Creation Stream\",\"sks\":0},{\"code\":\"15\",\"name\":\"Digital Communication and Content Creation\",\"sks\":3},{\"code\":\"16\",\"name\":\"Creative Digital Performance\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Sikap I\",\"sks\":5},{\"code\":\"2\",\"name\":\"Pengetahuan I\",\"sks\":5},{\"code\":\"3\",\"name\":\"Keterampilan Umum I\",\"sks\":5},{\"code\":\"4\",\"name\":\"Keterampilan Khusus I\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Sikap II\",\"sks\":5},{\"code\":\"2\",\"name\":\"Pengetahuan II\",\"sks\":5},{\"code\":\"3\",\"name\":\"Ketrampilan Umum II\",\"sks\":5},{\"code\":\"4\",\"name\":\"Ketrampilan Khusus II\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Final Assignment\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"Foundational English Skills\",\"desc\":\"Development of basic competencies in listening, speaking, reading, writing, grammar, and pronunciation.\"},{\"semester\":\"Semester 2\",\"title\":\"Intermediate English Proficiency\",\"desc\":\"Strengthening intermediate language skills and communicative competence.\"},{\"semester\":\"Semester 3\",\"title\":\"Applied English and Cultural Studies\",\"desc\":\"Introduction to literature, culture, translation, and English for professional contexts.\"},{\"semester\":\"Semester 4\",\"title\":\"Language Analysis and Academic Development\",\"desc\":\"Development of analytical skills through linguistics, discourse, and academic writing.\"},{\"semester\":\"Semester 5\",\"title\":\"Professional and Specialized English\",\"desc\":\"Enhancement of professional communication and specialization pathways.\"},{\"semester\":\"Semester 6\",\"title\":\"Immersion Program\",\"desc\":\"Practical experience through industry or community engagement.\"},{\"semester\":\"Semester 7\",\"title\":\"Immersion Program\",\"desc\":\"Practical experience through industry or community engagement.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Thesis or final academic project.\"}]', '[]', 7, '2026-05-27 21:21:25', '2026-10-22 00:50:09'),
(8, 'Keselamatan dan Kesehatan Kerja', NULL, 'Program Studi Keselamatan dan Kesehatan Kerja (K3) UPITRA dirancang untuk menghasilkan lulusan yang mampu mengidentifikasi, menganalisis, dan mengendalikan risiko di lingkungan kerja, serta menerapkan sistem manajemen keselamatan dan kesehatan kerja guna mendukung produktivitas, keberlanjutan, dan kesejahteraan tenaga kerja di berbagai sektor industri.', NULL, 'keselamatan-dan-kesehatan-kerja', 'FK', 'Fakultas Kesehatan', 'Prodi Baru', 'BookOpen', '/keselamatan-dan-kesehatan-kerja', 1, 352, 'Program Studi Keselamatan dan Kesehatan Kerja', 'Mempersiapkan lulusan yang profesional, berintegritas, dan kompeten dalam menciptakan lingkungan kerja yang aman, sehat, serta berstandar nasional dan internasional.', 'Menjadi Program Studi yang Unggul dalam mengembangkan ilmu pengetahuan sehingga Menghasilkan Sarjana Keselamatan dan Kesehatan Kerja (K3) terdepan dalam Kompeten Secara Akademik dan Dunia Kerja, secara Nasional dan Internasional yang berfokus pada Higiene Industri.', '[\"Menyelenggarakan pendidikan bidang ilmu kesehatan dan keselamatan kerja (K3) yang handal dan kompetitif di dunia kerja sesuai standar kompetensi K3 terutama manajemen Higiene Industri\",\"Melaksanakan penelitian di bidang ilmu kesehatan dan keselamatan kerja (K3) terutama Higiene Industri, guna mengembangkan ilmu dan teknologi dengan peningkatan kualitas publikasi yang bereputasi nasional maupun internasional.\",\"Menyelenggarakan pengabdian kepada masyarakat di bidang ilmu kesehatan dan keselamatan kerja (K3) dengan edukatif dan komunikatif.\",\"Menyelenggarakan program studi ilmu kesehatan dan keselamatan kerja (K3) yang. Transformatif dalam pengembangan dan pertumbuhan ilmu dengan membentuk jaringan Kerjasama Bersama institusi dan industri bersekala nasional maupun internasional.\"]', '[\"Menghasilkan lulusan sarjana terapan keselamatan dan kesehatan kerja yang professional dan memiliki karakter budaya kerja tinggi dan berkompeten unggul di bidang K3 terutama Higiene Industri.\",\"Menghasilkan penelitian dan publikasi ilmiah yang berstandar nasional dan internasional di bidang keselamatan dan kesehatan kerja terutama Higiene Industri.\",\".   Menghasilkan kegiatan-kegiatan kemasyarakatan yang berorientasi pada kepentingan masyarakat di bidang keselamatan dan kesehatan kerja.\",\"Tercapainya jejaring dan kerjasama yang berkesinambungan dengan stakeholder dalam dan luar negeri.\"]', '[{\"title\":\"Care Provider\",\"desc\":\"Sebagai penyedia layanan K3, lulusan berperan dalam memastikan lingkungan kerja yang aman dan sehat bagi pekerja. Mereka bertanggung jawab untuk memberikan layanan terkait pencegahan kecelakaan, pengelolaan risiko kesehatan, dan penanganan situasi darurat di tempat kerja.\"},{\"title\":\"Decision Maker\",\"desc\":\"Sebagai pengambil keputusan, lulusan bertanggung jawab untuk merancang dan mengimplementasikan strategi K3 yang efektif di perusahaan. Mereka menggunakan data dan analisis risiko untuk membuat keputusan yang meningkatkan keselamatan dan produktivitas.\"},{\"title\":\"Communicator\",\"desc\":\"Sebagai komunikator, lulusan bertindak sebagai penghubung antara manajemen, pekerja, dan pihak lain terkait dalam menyampaikan informasi tentang keselamatan dan kesehatan kerja. Mereka berperan dalam mendidik, melatih, dan memotivasi pekerja untuk mengadopsi praktik kerja yang aman.\"},{\"title\":\"Community Leader\",\"desc\":\"Sebagai pemimpin komunitas, lulusan berperan dalam mempromosikan budaya keselamatan di dalam dan luar lingkungan kerja. Mereka menginisiasi program-program K3 yang melibatkan seluruh elemen komunitas kerja, serta berpartisipasi dalam kebijakan publik yang mendukung keselamatan kerja.\"},{\"title\":\"Manager\\/Pengelola Sistem K3\",\"desc\":\"Sebagai manajer, lulusan bertanggung jawab atas perencanaan, pengorganisasian, pelaksanaan, dan evaluasi program K3 di tempat kerja. Mereka mengelola sumber daya, anggaran, dan tim K3 untuk mencapai tujuan keselamatan perusahaan.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"3\",\"name\":\"Pengantar K3\",\"sks\":3},{\"code\":\"4\",\"name\":\"Dasar-Dasar Kesehatan Lingkungan\",\"sks\":3},{\"code\":\"5\",\"name\":\"Dasar-Dasar Epidemiologi\",\"sks\":3},{\"code\":\"6\",\"name\":\"Anatomi dan Fisiologi Manusia\",\"sks\":4},{\"code\":\"7\",\"name\":\"Matematika Terapan\",\"sks\":3}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Inggris\",\"sks\":2},{\"code\":\"3\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"4\",\"name\":\"Statistik Deskriptif\",\"sks\":3},{\"code\":\"5\",\"name\":\"Toksikologi Industri\",\"sks\":3},{\"code\":\"6\",\"name\":\"Higiene Industri\",\"sks\":4},{\"code\":\"7\",\"name\":\"Ergonomi\",\"sks\":3}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Keselamatan Kerja\",\"sks\":4},{\"code\":\"2\",\"name\":\"Penyakit Akibat Kerja (PAK)\",\"sks\":3},{\"code\":\"3\",\"name\":\"Psikologi Industri\",\"sks\":2},{\"code\":\"4\",\"name\":\"Komunikasi K3\",\"sks\":2},{\"code\":\"5\",\"name\":\"Kesehatan Kerja\",\"sks\":3},{\"code\":\"6\",\"name\":\"Pencegahan dan Penanggulangan Kebakaran\",\"sks\":3},{\"code\":\"7\",\"name\":\"Analisis Risiko Kuantitatif dan Kualitatif: Metode HAZOP, FMEA, dan JSA\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Manajemen Risiko K3\",\"sks\":4},{\"code\":\"2\",\"name\":\"Peraturan Perundangan K3\",\"sks\":3},{\"code\":\"3\",\"name\":\"Sistem Manajemen K3 (SMK3)\",\"sks\":3},{\"code\":\"4\",\"name\":\"Pertolongan Pertama pada Kecelakaan (P3K)\",\"sks\":3},{\"code\":\"5\",\"name\":\"Sistem Manajemen Lingkungan\",\"sks\":3},{\"code\":\"6\",\"name\":\"Manajemen Penanggulangan Bencana\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Analisis Bahaya dan Pengendalian (HAZOP, JSA)\",\"sks\":4},{\"code\":\"2\",\"name\":\"Audit K3\",\"sks\":3},{\"code\":\"3\",\"name\":\"K3 Konstruksi\",\"sks\":3},{\"code\":\"4\",\"name\":\"Pemadam Kebakaran\",\"sks\":2},{\"code\":\"5\",\"name\":\"Sistem Manajemen Lingkungan\",\"sks\":3},{\"code\":\"6\",\"name\":\"Teknologi Informasi K3\",\"sks\":3},{\"code\":\"7\",\"name\":\"Industri K3\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"K3 Listrik\",\"sks\":3},{\"code\":\"2\",\"name\":\"K3 Kimia\",\"sks\":3},{\"code\":\"3\",\"name\":\"K3 Pertambangan\",\"sks\":3},{\"code\":\"4\",\"name\":\"Kesehatan Kerja di Perusahaan\",\"sks\":2},{\"code\":\"5\",\"name\":\"Teknik Identifikasi\",\"sks\":3},{\"code\":\"6\",\"name\":\"Promosi K3\",\"sks\":3},{\"code\":\"7\",\"name\":\"Standarisasi K3\",\"sks\":3}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"K3 Rumah Sakit\",\"sks\":3},{\"code\":\"2\",\"name\":\"K3 Migas\",\"sks\":3},{\"code\":\"3\",\"name\":\"K3 Transportasi\",\"sks\":3},{\"code\":\"4\",\"name\":\"Analisis Kecelakaan Kerja\",\"sks\":3},{\"code\":\"5\",\"name\":\"Psikologi Industri\",\"sks\":2},{\"code\":\"6\",\"name\":\"Sistem Analisis Resiko\",\"sks\":2},{\"code\":\"7\",\"name\":\"Kewirausahaan Berbasis K3\",\"sks\":2}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Kepemimpinan Dalam K3\",\"sks\":3},{\"code\":\"2\",\"name\":\"Tugas Akhir\\/Skripsi\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 2\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 3\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 4\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 5\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 6\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 7\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 8\",\"title\":null,\"desc\":null}]', '[]', 0, '2026-06-05 00:06:33', '2026-10-21 18:20:13'),
(9, 'Fisioterapi', NULL, 'Program Studi Fisioterapi UPITRA dirancang untuk menghasilkan lulusan yang mampu melakukan promotif, preventif, kuratif, dan rehabilitatif melalui pendekatan fisioterapi berbasis ilmu pengetahuan dan teknologi. Mahasiswa dibekali keterampilan dalam penanganan gangguan gerak dan fungsi tubuh untuk mendukung kesehatan, kemandirian, serta kualitas hidup individu dan masyarakat.', NULL, 'fisioterapi', 'FK', 'Fakultas Kesehatan', 'Prodi Baru', 'Focus', '/fisioterapi', 1, 187, 'Program Studi Fisioterapi', 'Mempersiapkan lulusan yang profesional, berempati, dan kompeten dalam meningkatkan kualitas hidup masyarakat melalui pelayanan fisioterapi yang unggul dan berstandar global.', 'Menjadi program studi terdepan dalam pengembangan ilmu fisioterapi, khususnya fisioterapi anak, serta berkontribusi pada peningkatan kualitas hidup.', '[\"Menyelenggarakan pendidikan tinggi fisioterapi yang berorientasi pada penanganan tumbuh kembang anak.\",\"Menghasilkan lulusan fisioterapis yang kompeten, berintegritas, dan inovatif terutama di bidang fisioterapi anak.\",\"Melaksanakan penelitian di bidang fisioterapi dengan kualitas penelitian berdasarkan standar nasional dan internasional untuk mengembangkan ilmu pengetahuan khususnya fisioterapi anak dan tumbuh kembang yang sesuai kebutuhan masyarakat.\",\"Menyelenggarakan kontribusi social dalam bentuk pengabdian masyarakat di bidang fisioterapi untuk meningkatkan derajat Kesehatan dan kesejahteraan masyarakat.\",\"Pengembangan dan pertumbuhan program studi yang berkesinambungan dengan Melakukan jaringan kerjasama dengan masyarakat pengguna, instansi pelayanan kesehatan, dan lembaga atau instansi terkait.\"]', '[\"Menghasilkan fisioterapis profesional, berkualitas dan profesional yang mampu bekerja di berbagai layanan kesehatan.\",\"Menjadi pusat unggulan dalam penelitian fisioterapi anak dan tumbuh kembang.\",\"Mengembangkan jejaring kerja sama dengan institusi terkait baik dalam maupun luar negeri.\"]', '[{\"title\":\"Care Provider\",\"desc\":\"Sebagai penyedia layanan Fisioterapi, lulusan berperan dalam memberikan layanan fisioterapi secara mandiri dengan memiliki kemampuan dalam berfikir kreatif dan berfikir inovatif serta unggul dalam fisioterapi anak dan tumbuh kembang\"},{\"title\":\"Decision Maker\",\"desc\":\"Sebagai pengambil keputusan, Fisioterapis bertanggung jawab untuk menggunakan prinsip dan metode fisioterapi dalam memberikan layanan fisioterapi terutama anak dan tumbuh kembang\"},{\"title\":\"Communicator\",\"desc\":\"Sebagai komunikator, lulusan bertindak sebagai Fisioterapis yang mampu memberikan edukasi terapi fisik dalam merencanakan, mengimplementasikan dan mengevaluasi program-program yang bersifat preventif dan promotif.\"},{\"title\":\"Community Leader\",\"desc\":\"Fisioterapis yang mampu berperan Sebagai pemimpin komunitas, lulusan memimpin masyarakat dalam upaya peningkatan Kesehatan fisik di bidang fisioterapi anak dan tumbuh kembang. Fisioterapis yang mampu berperan sebagai pemimpin komunitas, lulusan memimpin masyarakat dalam upaya peningkatan Kesehatan fisik di bidang fisioterapi anak dan tumbuh kembang.\"},{\"title\":\"Manager\",\"desc\":\"Sebagai manajer, lulusan mampu menjalin kerjasama dengan individu dan organisasi di dalam dan di luar sistem kesehatan untuk mengelola masalah kesehatan individu, komunitas, serta masyarakat dengan menggunakan data kesehatan dan data pendukung lainnya, dalam mewujudkan keunggulan dibidang fisioterapis anak dan tumbuh kembang.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"3\",\"name\":\"Bahasa Inggris\",\"sks\":2},{\"code\":\"4\",\"name\":\"Anatomi Manusia I\",\"sks\":3},{\"code\":\"5\",\"name\":\"Fisiologi Manusia I\",\"sks\":3},{\"code\":\"6\",\"name\":\"Pengantar Fisioterapi\",\"sks\":2},{\"code\":\"7\",\"name\":\"Biomekanika\",\"sks\":3},{\"code\":\"8\",\"name\":\"Dasar-Dasar Fisioterapi\",\"sks\":2}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"2\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"3\",\"name\":\"Anatomi Manusia II\",\"sks\":3},{\"code\":\"4\",\"name\":\"Fisiologi Manusia II\",\"sks\":3},{\"code\":\"5\",\"name\":\"Kinesiologi\",\"sks\":3},{\"code\":\"6\",\"name\":\"Psikologi Umum\",\"sks\":3},{\"code\":\"7\",\"name\":\"Ilmu Perkembangan Gerak I\",\"sks\":3}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Metodologi Penelitian\",\"sks\":3},{\"code\":\"2\",\"name\":\"Patologi Umum\",\"sks\":3},{\"code\":\"3\",\"name\":\"Teknik Fisioterapi Dasar I\",\"sks\":4},{\"code\":\"4\",\"name\":\"Farmakologi Fisioterapi\",\"sks\":3},{\"code\":\"5\",\"name\":\"Penilaian Fisioterapi I\",\"sks\":3},{\"code\":\"6\",\"name\":\"Fisiologi Latihan\",\"sks\":3}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Neurologi Dasar\",\"sks\":3},{\"code\":\"2\",\"name\":\"Penilaian Fisioterapi II\",\"sks\":3},{\"code\":\"3\",\"name\":\"Teknik Fisioterapi Dasar II\",\"sks\":3},{\"code\":\"4\",\"name\":\"Statistika\",\"sks\":2},{\"code\":\"5\",\"name\":\"Fisioterapi Komunitas\",\"sks\":2},{\"code\":\"6\",\"name\":\"Filsafat Ilmu dan Logika\",\"sks\":2},{\"code\":\"7\",\"name\":\"Pengukuran Fisioterapi\",\"sks\":2},{\"code\":\"8\",\"name\":\"Terapi Latihan\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Fisioterapi Muskuloskeletal I\",\"sks\":4},{\"code\":\"2\",\"name\":\"Ergonomi\",\"sks\":2},{\"code\":\"3\",\"name\":\"Manajemen Fisioterapi\",\"sks\":2},{\"code\":\"4\",\"name\":\"Evidence Based Practice\",\"sks\":2},{\"code\":\"5\",\"name\":\"Magang I\",\"sks\":2},{\"code\":\"6\",\"name\":\"Promosi Kesehatan\",\"sks\":3},{\"code\":\"7\",\"name\":\"Ilmu Perkembangan Gerak II\",\"sks\":3},{\"code\":\"8\",\"name\":\"Elektro Fisika dan Sumber Fisis\",\"sks\":2}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Fisioterapi Neurologi\",\"sks\":4},{\"code\":\"2\",\"name\":\"Fisioterapi Kardiopulmonal\",\"sks\":4},{\"code\":\"3\",\"name\":\"Ortotik Prostetik\",\"sks\":2},{\"code\":\"4\",\"name\":\"Magang II\",\"sks\":2},{\"code\":\"5\",\"name\":\"Fisioterapi Geriatri dan Wellness\",\"sks\":3},{\"code\":\"6\",\"name\":\"Dasar-dasar Fisioterapi Pediatri\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Fisioterapi Pediatri Lanjut\",\"sks\":5},{\"code\":\"2\",\"name\":\"Fisioterapi Olahraga\",\"sks\":3},{\"code\":\"3\",\"name\":\"Fisioterapi Tumbuh Kembang\",\"sks\":4},{\"code\":\"4\",\"name\":\"Manajemen Nyeri\",\"sks\":2},{\"code\":\"5\",\"name\":\"Kewirausahaan\",\"sks\":2},{\"code\":\"6\",\"name\":\"Seminar Proposal Skripsi\",\"sks\":1},{\"code\":\"7\",\"name\":\"Magang Fisioterapi Pediatri\",\"sks\":4}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Keterampilan Fisioterapi Pediatri\",\"sks\":5},{\"code\":\"2\",\"name\":\"Tugas Akhir\\/Skripsi\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 2\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 3\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 4\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 5\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 6\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 7\",\"title\":null,\"desc\":null},{\"semester\":\"Semester 8\",\"title\":null,\"desc\":null}]', '[]', 0, '2026-06-05 00:19:31', '2026-10-22 00:32:37'),
(10, 'Sistem Informasi', NULL, 'Program Studi Sistem Informasi UPITRA dirancang untuk menghasilkan lulusan yang mampu merancang, mengembangkan, dan mengelola sistem informasi berbasis teknologi untuk mendukung kebutuhan bisnis dan organisasi.', NULL, 'sistem-informasi', 'FST', 'Fakultas Sains & Teknologi', 'Baik Sekali', 'Monitor', '/sistem-informasi', 1, 740, 'Program Studi Sistem Informasi', 'Mempersiapkan lulusan yang inovatif, mempunyai jiwa kemandirian dan berdaya saing global.', 'Program studi yang unggul dalam bidang sistem informasi, berorientasi global, menjunjung tinggi nilai-nilai integritas dan bersemangat kebhinekaan.', '[\"Menyelenggarakan program studi Sistem informasi secara efektif dan efisien untuk mendukung terlaksananya Tri Dharma perguruan tinggi.\",\"Menghasilkan sarjana di bidang sistem informasi yang kompeten, solutif, berpola pikir logis dan sistematis, memiliki kedalaman spiritual, menjunjung kemanusiaan, rendah hati, berintegritas dan profesional dalam memanfaatkan ilmu sistem informasi di lingkungan kerja maupun kehidupan bermasyarakat.\",\"Menghasilkan penelitian yang unggul, solutif, inovatif dan transformatif bagi masyarakat di bidang sistem informasi.\",\"Memanfaatkan ilmu sistem informasi yang berdaya guna dan berhasil guna bagi masyarakat.\",\"Membangun kerja sama dan mengelola jejaring berkelanjutan dengan dunia pendidikan, masyarakat, pemerintah dan industri untuk mewujudkan keunggulan transformatif di bidang sistem informasi.\"]', '[\"Berkontribusi dalam memperluas akses pendidikan tinggi yang berkualitas dan terjangkau bagi masyarakat di bidang Sistem informasi.\",\"Menghasilkan sarjana bidang Sistem informasi yang bermoral, berintegritas, profesional, bertanggung jawab, dan mampu berkarya dengan ilmu sistem informasi.\",\"Berkontribusi dalam pengembangan dan penelitian perangkat lunak yang unggul, solutif, inovatif dan transformatif bagi masyarakat dan kehidupan.\",\"Menerapkan ilmu sistem informasi yang berdaya guna dan berhasil guna bagi masyarakat.\",\"Menjalin kerja sama dengan dunia pendidikan, masyarakat, pemerintah dan industri yang berkelanjutan, beretika, dan bermanfaat di bidang sistem informasi.\"]', '[{\"title\":\"Cyber Business Analyst\",\"desc\":\"Menganalisis, memiliki pengetahuan teknologi, dan kemampuan membuat keputusan pada organisasi bisnis.\"},{\"title\":\"Big Data Scientist\",\"desc\":\"Menganalisis, mengelola, dan memiliki kemampuan statistik serta  algoritma untuk mengolah data besar (big data) pada organisasi bisnis.\"},{\"title\":\"Cyber System Architect\",\"desc\":\"Mendesain sistem dan membangun pengetahuan terhadap teknologi maupun  arsitektur sebuah organisasi bisnis.\"},{\"title\":\"Cyber Security Analyst\",\"desc\":\"Bertanggung jawab untuk keamanan sistem dan jaringan, analisis resiko keamanan, dan penanganan insiden keamanan pada organisasi bisnis.\"},{\"title\":\"Cyber System Engineer\",\"desc\":\"Membuat sistem dan jaringan, administrasi sistem operasi, dan kemampuan troubleshooting pada organisasi bisnis.\"},{\"title\":\"Database Administrator\",\"desc\":\"Bertanggung jawab untuk administrasi database, memiliki pengetahuan tentang DBMS, backup dan restore database.\"},{\"title\":\"Cloud Engineering\",\"desc\":\"Bertanggung jawab untuk pengelolaan cloud, memiliki pengetahuan arsitektur cloud, dan keamanan cloud.\"},{\"title\":\"Application And Device Developer\",\"desc\":\"Bertanggung jawab untuk pengembangan perangkat lunak, bahasa pemrograman, dan pengujian perangkat lunak.\"},{\"title\":\"Project Manager\",\"desc\":\"Bertanggung jawab untuk manajemen proyek, perencanaan dan pengorganisasian, komunikasi dan kemampuan mengambil keputusan.\"}]', '[{\"semester\":\"Semester 1\",\"courses\":[{\"code\":\"1\",\"name\":\"Agama\",\"sks\":2},{\"code\":\"2\",\"name\":\"Pancasila\",\"sks\":2},{\"code\":\"3\",\"name\":\"Konsep Sistem Informasi\",\"sks\":3},{\"code\":\"4\",\"name\":\"Pengantar Teknologi Informasi\",\"sks\":3},{\"code\":\"5\",\"name\":\"Dasar Proses Bisnis\",\"sks\":3},{\"code\":\"6\",\"name\":\"Pemrograman Dasar\",\"sks\":3},{\"code\":\"7\",\"name\":\"Basis Data\",\"sks\":3}]},{\"semester\":\"Semester 2\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewarganegaraan\",\"sks\":2},{\"code\":\"2\",\"name\":\"Bahasa Indonesia\",\"sks\":2},{\"code\":\"3\",\"name\":\"Statistika dan Probabilitas\",\"sks\":3},{\"code\":\"4\",\"name\":\"Sistem Informasi Manajemen\",\"sks\":3},{\"code\":\"5\",\"name\":\"Sistem Operasi\",\"sks\":3},{\"code\":\"6\",\"name\":\"Perencanaan Sumber Daya Perusahaan\",\"sks\":3},{\"code\":\"7\",\"name\":\"Analisis dan Perancangan Sistem Informasi\",\"sks\":3}]},{\"semester\":\"Semester 3\",\"courses\":[{\"code\":\"1\",\"name\":\"Pengembangan Kepribadian UPITRA DNA\",\"sks\":3},{\"code\":\"2\",\"name\":\"Jaringan Informasi\",\"sks\":3},{\"code\":\"3\",\"name\":\"Transformasi Digital\",\"sks\":3},{\"code\":\"4\",\"name\":\"Pemrograman Berorientasi Objek\",\"sks\":3},{\"code\":\"5\",\"name\":\"Audit Sistem Informasi\",\"sks\":2},{\"code\":\"6\",\"name\":\"Internet of Things\",\"sks\":3},{\"code\":\"7\",\"name\":\"Komunikasi dan Bisnis\",\"sks\":2}]},{\"semester\":\"Semester 4\",\"courses\":[{\"code\":\"1\",\"name\":\"Kewirausahaan\",\"sks\":3},{\"code\":\"2\",\"name\":\"Pemrograman Berbasis Web\",\"sks\":3},{\"code\":\"3\",\"name\":\"Big Data\",\"sks\":3},{\"code\":\"4\",\"name\":\"Kecerdasan Bisnis\",\"sks\":3},{\"code\":\"5\",\"name\":\"Perencanaan Strategis Sistem Informasi\",\"sks\":3},{\"code\":\"6\",\"name\":\"Konsentrasi Pilihan 1 : Cyber Business\",\"sks\":0},{\"code\":\"7\",\"name\":\"Keamanan Sistem Informasi\",\"sks\":3},{\"code\":\"8\",\"name\":\"Pengambilan Informasi\",\"sks\":3},{\"code\":\"9\",\"name\":\"Konsentrasi Pilihan 2 : Information System Governance\",\"sks\":0},{\"code\":\"10\",\"name\":\"Desain Perancangan Antarmuka\",\"sks\":3},{\"code\":\"11\",\"name\":\"Pengujian Perangkat Lunak\",\"sks\":3}]},{\"semester\":\"Semester 5\",\"courses\":[{\"code\":\"1\",\"name\":\"Etika Profesi\",\"sks\":2},{\"code\":\"2\",\"name\":\"Metodologi Penelitian dan Penulisan Ilmiah\",\"sks\":3},{\"code\":\"3\",\"name\":\"Pemrograman Seluler \\/ Mobile\",\"sks\":3},{\"code\":\"4\",\"name\":\"Proyek Sistem Informasi**\",\"sks\":3},{\"code\":\"5\",\"name\":\"Blockchain\",\"sks\":2},{\"code\":\"6\",\"name\":\"Pembelajaran Mesin\",\"sks\":2},{\"code\":\"7\",\"name\":\"Konsentrasi Pilihan 1 : Cyber Business\",\"sks\":0},{\"code\":\"8\",\"name\":\"Komputasi Awan\",\"sks\":3},{\"code\":\"9\",\"name\":\"Berpikir komputasional\",\"sks\":3},{\"code\":\"10\",\"name\":\"Konsentrasi Pilihan 2 : Information System Governance\",\"sks\":0},{\"code\":\"11\",\"name\":\"Tata Kelola Teknologi Informasi\",\"sks\":3},{\"code\":\"12\",\"name\":\"Manajemen Proses Bisnis\",\"sks\":3}]},{\"semester\":\"Semester 6\",\"courses\":[{\"code\":\"1\",\"name\":\"Dasar-dasar Sistem Informasi*\",\"sks\":5},{\"code\":\"2\",\"name\":\"Analisis dan Solusi untuk Sistem Informasi*\",\"sks\":5},{\"code\":\"3\",\"name\":\"Komunikasi Bisnis dan Profesional*\",\"sks\":5},{\"code\":\"4\",\"name\":\"Manajemen Proyek Sistem Informasi*\",\"sks\":5}]},{\"semester\":\"Semester 7\",\"courses\":[{\"code\":\"1\",\"name\":\"Lingkungan Sistem Informasi*\",\"sks\":5},{\"code\":\"2\",\"name\":\"Desain dan Evaluasi untuk Sistem Informasi*\",\"sks\":5},{\"code\":\"3\",\"name\":\"Etika Bisnis dan Tanggung Jawab Sosial*\",\"sks\":5},{\"code\":\"4\",\"name\":\"Inovasi dan Teknologi dalam Bisnis*\",\"sks\":5}]},{\"semester\":\"Semester 8\",\"courses\":[{\"code\":\"1\",\"name\":\"Final Project\",\"sks\":6}]}]', '[{\"semester\":\"Semester 1\",\"title\":\"IT Foundation\",\"desc\":\"Pengantar sistem informasi dan logika informatika.\"},{\"semester\":\"Semester 2\",\"title\":\"Business & IT\",\"desc\":\"Basis data dan pemrograman dasar.\"},{\"semester\":\"Semester 3\",\"title\":\"Information Systems Core\",\"desc\":\"Analisis sistem dan manajemen proyek TI.\"},{\"semester\":\"Semester 4\",\"title\":\"Enterprise Systems\",\"desc\":\"ERP dan sistem informasi manajemen.\"},{\"semester\":\"Semester 5\",\"title\":\"Data & Digital Business\",\"desc\":\"Business intelligence dan data analytics.\"},{\"semester\":\"Semester 6\",\"title\":\"Digital Transformation\",\"desc\":\"E-business dan IT governance.\"},{\"semester\":\"Semester 7\",\"title\":\"Industry Internship\",\"desc\":\"Magang di perusahaan digital.\"},{\"semester\":\"Semester 8\",\"title\":\"Final Project\",\"desc\":\"Pengembangan sistem informasi.\"}]', '[{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"s\",\"9\":\"i\",\"10\":\"s\",\"11\":\"f\",\"12\":\"o\",\"13\":\"\\/\",\"14\":\"s\",\"15\":\"i\",\"16\":\"s\",\"17\":\"f\",\"18\":\"o\",\"19\":\"-\",\"20\":\"1\",\"21\":\".\",\"22\":\"j\",\"23\":\"p\",\"24\":\"g\",\"image\":\"\\/images\\/sisfo\\/sisfo-1.jpg\",\"title\":\"Mahasiswa Berprestasi Internasional\",\"short_description\":\"Mahasiswa program studi S-1 Sistem Informasi berhasil meraih 2 medali di ajang kompetisi internasional.\"},{\"0\":\"\\/\",\"1\":\"i\",\"2\":\"m\",\"3\":\"a\",\"4\":\"g\",\"5\":\"e\",\"6\":\"s\",\"7\":\"\\/\",\"8\":\"s\",\"9\":\"i\",\"10\":\"s\",\"11\":\"f\",\"12\":\"o\",\"13\":\"\\/\",\"14\":\"s\",\"15\":\"i\",\"16\":\"s\",\"17\":\"f\",\"18\":\"o\",\"19\":\"-\",\"20\":\"2\",\"21\":\".\",\"22\":\"j\",\"23\":\"p\",\"24\":\"g\",\"image\":\"\\/images\\/sisfo\\/sisfo-2.jpg\",\"title\":\"Mahasiswa Sistem Informasi Meraih Medali\",\"short_description\":\"Mahasiswa S-1 Sistem Informasi kembali berprestasi dengan berhasil meraih medali di ajang world Youth Invention And Innovation Award (WYIIA).\"},{\"image\":\"\\/images\\/program-studi\\/1777264440_69eee738e3854.jpeg\",\"title\":\"Youth International Science Fair (YISF) 2026\",\"short_description\":\"Delegasi dari Program Studi (Prodi) Sistem Informasi UPITRA sukses memborong dua medali emas dalam ajang bergengsi Youth International Science Fair (YISF) 2026.\"}]', 1, '2026-04-16 20:16:04', '2026-10-22 04:55:06');

